window.EDMUND_DSE_PRACTICAL_WRITING_SEED = {"dse/paper-3/practical-english-writing/practical-formats/letter-of-enquiry":[{"front":"Letter of Enquiry","meaning":"查詢信","examples":[{"en":"This is a formal letter of enquiry about Product A.","zh":"這是一封關於A產品的正式查詢信。"},{"en":"A letter of enquiry is a formal letter used to ask for information before making a decision.","zh":"查詢信是用來在作決定前索取資料的正式信件。"},{"en":"A customer may write a letter of enquiry to ask about the price of a training course.","zh":"顧客可以寫查詢信，詢問培訓課程的價格。"},{"en":"Writing a clear letter of enquiry helps the receiver understand exactly what information is needed.","zh":"撰寫清晰的查詢信，有助收信人明白你確切需要甚麼資料。"},{"en":"A letter of enquiry should be polite, specific, and organised.","zh":"查詢信應該有禮、具體，而且有條理。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"Dear Sir/Madam","meaning":"敬啟者","examples":[{"en":"Dear Sir/Madam, I am writing to request more information about Product A.","zh":"敬啟者：我寫信是想索取更多關於A產品的資料。"},{"en":"Dear Sir/Madam is a formal greeting used when you do not know the receiver’s name.","zh":"Dear Sir/Madam 是在不知道收信人姓名時使用的正式稱呼。"},{"en":"A student may begin a formal complaint with Dear Sir/Madam if the correct officer’s name is unknown.","zh":"如果不知道負責職員的姓名，學生可以用 Dear Sir/Madam 開始正式投訴信。"},{"en":"Using Dear Sir/Madam helps keep the tone polite in business or official writing.","zh":"使用 Dear Sir/Madam 有助商業或官方寫作保持有禮語氣。"},{"en":"If you know the receiver’s name, it is usually better to write Dear Mr Chan or Dear Ms Lee.","zh":"如果你知道收信人的姓名，通常最好寫 Dear Mr Chan 或 Dear Ms Lee。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"I am writing to request","meaning":"我寫信是想索取……","examples":[{"en":"I am writing to request more information about Product A.","zh":"我寫信是想索取更多關於A產品的資料。"},{"en":"I am writing to request is a formal way to state what you want from the receiver.","zh":"I am writing to request 是正式說明你希望收信人提供甚麼的方式。"},{"en":"I am writing to request a copy of the school application form.","zh":"我寫信是想索取一份學校申請表。"},{"en":"This phrase makes the purpose of the letter clear from the beginning.","zh":"這個短語令信件目的從一開始就清楚。"},{"en":"It is more suitable for formal letters than simply saying I want.","zh":"它比直接說 I want 更適合正式信件。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"more information about","meaning":"更多關於……的資料","examples":[{"en":"I am writing to request more information about Product A.","zh":"我寫信是想索取更多關於A產品的資料。"},{"en":"More information about something means extra details that help someone understand it better.","zh":"more information about something 指有助某人更了解某事物的額外詳情。"},{"en":"Parents may ask for more information about a school trip before giving permission.","zh":"家長在批准前，可能會要求更多關於學校旅行的資料。"},{"en":"If a buyer receives more information about a product, they can make a safer decision.","zh":"如果買家收到更多關於產品的資料，就能作出更穩妥的決定。"},{"en":"This phrase is useful when the existing details are not enough.","zh":"當現有資料不足時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"Product A","meaning":"A產品","examples":[{"en":"Our company would like to request more information about Product A.","zh":"本公司想索取更多關於A產品的資料。"},{"en":"Product A is a placeholder name used when the exact product name is not stated or is being discussed generally.","zh":"Product A 是一個代稱，用於未說明確實產品名稱或作一般討論時。"},{"en":"In a business report, Product A may be compared with Product B to show price differences.","zh":"在商業報告中，A產品可以與B產品比較，以顯示價格差異。"},{"en":"Using Product A keeps the writing simple when the focus is on the enquiry, not the product name.","zh":"當重點是查詢而不是產品名稱時，使用A產品可以令寫作較簡潔。"},{"en":"This label should be replaced by the real product name in an actual business letter.","zh":"在真實商業信件中，這個標籤應改為實際產品名稱。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"provide you with","meaning":"向你提供……","examples":[{"en":"I would also like to provide you with the details of our purchase.","zh":"我也想向你提供我們採購的詳情。"},{"en":"To provide you with something means to give you information, materials, or support.","zh":"provide you with something 指向你提供資料、材料或支援。"},{"en":"The school office can provide you with a copy of your attendance record.","zh":"校務處可以向你提供一份出席紀錄副本。"},{"en":"Providing someone with clear details reduces confusion and follow-up questions.","zh":"向某人提供清晰詳情，可以減少混亂和後續問題。"},{"en":"This phrase is formal and polite, so it is common in business writing.","zh":"這個短語正式而有禮，所以常用於商業寫作。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"the details of our purchase","meaning":"我們採購的詳情","examples":[{"en":"I would also like to provide you with the details of our purchase.","zh":"我也想向你提供我們採購的詳情。"},{"en":"The details of our purchase are the specific information about what, how many, and when a company wants to buy.","zh":"the details of our purchase 指公司想購買甚麼、數量多少和時間安排等具體資料。"},{"en":"The details of our purchase include the product name, quantity, delivery address, and preferred date.","zh":"我們採購的詳情包括產品名稱、數量、送貨地址和首選日期。"},{"en":"Clear purchase details help the seller prepare an accurate quotation and delivery plan.","zh":"清楚的採購詳情有助賣方準備準確報價和送貨計劃。"},{"en":"Without the details of a purchase, the seller may not know how to process the order.","zh":"如果沒有採購詳情，賣方可能不知道如何處理訂單。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"Firstly","meaning":"首先","examples":[{"en":"Firstly, we would like to know the release date of Product A.","zh":"首先，我們想知道A產品的發售日期。"},{"en":"Firstly is used to introduce the first point in a list or sequence.","zh":"Firstly 用來引出清單或次序中的第一點。"},{"en":"Firstly, students should read the question carefully before writing their answer.","zh":"首先，學生應仔細閱讀問題，然後才寫答案。"},{"en":"Using firstly helps organise a letter so the reader can follow the writer’s requests.","zh":"使用 firstly 有助整理信件，令讀者能跟上作者的請求。"},{"en":"After firstly, writers often use secondly, in addition, or finally to continue the structure.","zh":"在 firstly 之後，作者常用 secondly、in addition 或 finally 繼續結構。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"we would like to know","meaning":"我們想知道","examples":[{"en":"We would like to know the release date, expected price and delivery method of Product A.","zh":"我們想知道A產品的發售日期、預計價格和送貨方式。"},{"en":"We would like to know is a polite formal way to ask for information.","zh":"We would like to know 是禮貌而正式地索取資料的說法。"},{"en":"We would like to know whether the meeting room is available next Friday.","zh":"我們想知道會議室下星期五是否可用。"},{"en":"This phrase sounds more respectful than asking directly, What is the price?","zh":"這個短語比直接問「價格是多少？」聽起來更有禮。"},{"en":"It is useful in letters because it clearly introduces the information being requested.","zh":"它在信件中很有用，因為能清楚引出所要求的資料。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"the release date","meaning":"發售日期","examples":[{"en":"We would like to know the release date of Product A.","zh":"我們想知道A產品的發售日期。"},{"en":"The release date is the date when a product, film, book, or service becomes available to the public.","zh":"release date 指產品、電影、書籍或服務正式向公眾推出的日期。"},{"en":"Fans often check the release date of a new game before deciding when to buy it.","zh":"粉絲常在決定何時購買前查看新遊戲的發售日期。"},{"en":"Knowing the release date helps customers plan orders, budgets, and delivery schedules.","zh":"知道發售日期有助顧客規劃訂單、預算和送貨時間。"},{"en":"If the release date is delayed, buyers may need to change their plans.","zh":"如果發售日期延遲，買家可能需要更改計劃。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"expected price","meaning":"預計價格","examples":[{"en":"Please provide the expected price of Product A.","zh":"請提供A產品的預計價格。"},{"en":"The expected price is the price that people think or estimate a product will cost.","zh":"expected price 指人們估計某產品將會售賣的價格。"},{"en":"Before opening registration, a course provider may announce the expected price of the programme.","zh":"在開放報名前，課程機構可能會公布課程的預計價格。"},{"en":"Knowing the expected price helps buyers decide whether the product is within budget.","zh":"知道預計價格有助買家決定產品是否在預算之內。"},{"en":"The expected price may change later if production, shipping, or demand changes.","zh":"如果生產、運輸或需求改變，預計價格之後可能會變。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":1},{"front":"delivery method","meaning":"送貨方式","examples":[{"en":"Please provide details of the delivery method for Product A.","zh":"請提供A產品送貨方式的詳情。"},{"en":"A delivery method is the way goods are transported from the seller to the buyer.","zh":"delivery method 指貨品由賣方運送到買方的方式。"},{"en":"Common delivery methods include courier service, air freight, sea freight, and local pickup.","zh":"常見送貨方式包括速遞、空運、海運和本地自取。"},{"en":"The delivery method affects cost, speed, tracking, and risk of damage.","zh":"送貨方式會影響成本、速度、追蹤和損壞風險。"},{"en":"Buyers should ask about the delivery method before placing a large order.","zh":"買家在下大訂單前應詢問送貨方式。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"I would be grateful if","meaning":"如你能……，我將不勝感激","examples":[{"en":"I would be grateful if you could provide the release date, expected price and delivery method.","zh":"如你能提供發售日期、預計價格和送貨方式，我將不勝感激。"},{"en":"I would be grateful if is a polite formal phrase used to make a request.","zh":"I would be grateful if 是用來提出請求的禮貌正式短語。"},{"en":"I would be grateful if you could send the application form by email.","zh":"如你能以電郵傳送申請表，我將不勝感激。"},{"en":"This phrase makes a request sound respectful rather than demanding.","zh":"這個短語令請求聽起來尊重對方，而不是命令對方。"},{"en":"It is commonly used in formal letters, emails, and enquiries.","zh":"它常用於正式信件、電郵和查詢。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"could provide","meaning":"能夠提供","examples":[{"en":"I would be grateful if you could provide more details about Product A.","zh":"如你能夠提供更多關於A產品的詳情，我將不勝感激。"},{"en":"Could provide is a polite way to ask whether someone can give information, help, or materials.","zh":"could provide 是禮貌詢問某人能否提供資料、協助或材料的說法。"},{"en":"Could you provide a receipt for the payment, please?","zh":"請問你能夠提供付款收據嗎？"},{"en":"Using could provide softens a request and makes it more suitable for formal communication.","zh":"使用 could provide 可以令請求語氣較柔和，更適合正式溝通。"},{"en":"This phrase is useful when asking for documents, prices, dates, or explanations.","zh":"這個短語適合用於索取文件、價格、日期或解釋。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"it would be much appreciated if","meaning":"如能……，我們將十分感激","examples":[{"en":"It would be much appreciated if you could also provide details of the limited edition.","zh":"如能同時提供限量版的詳情，我們將十分感激。"},{"en":"It would be much appreciated if is a very polite way to request help or information.","zh":"It would be much appreciated if 是非常有禮地請求協助或資料的說法。"},{"en":"It would be much appreciated if you could reply before Friday.","zh":"如能在星期五前回覆，我們將十分感激。"},{"en":"This phrase is useful when the writer wants to sound especially respectful.","zh":"當作者想聽起來特別尊重對方時，這個短語很有用。"},{"en":"It is more formal than please send me the details.","zh":"它比 please send me the details 更正式。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"details of the limited edition","meaning":"限量版的詳情","examples":[{"en":"Please provide details of the limited edition of Product A.","zh":"請提供A產品限量版的詳情。"},{"en":"Details of the limited edition are the specific facts about a special version that is available only in limited numbers.","zh":"details of the limited edition 指關於只限少量供應的特別版本的具體資料。"},{"en":"Customers may ask for details of the limited edition, such as colour, packaging, price, and quantity.","zh":"顧客可能會詢問限量版的詳情，例如顏色、包裝、價格和數量。"},{"en":"Clear details of the limited edition help buyers decide whether it is worth ordering early.","zh":"清楚的限量版詳情有助買家決定是否值得提早訂購。"},{"en":"Without these details, customers may confuse the limited edition with the standard version.","zh":"如果沒有這些詳情，顧客可能會把限量版與標準版混淆。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"the limited-edition version","meaning":"限量版","examples":[{"en":"We would also like to purchase the limited-edition version of Product A.","zh":"我們也想購買A產品的限量版。"},{"en":"The limited-edition version is a special version of a product produced in a limited quantity.","zh":"limited-edition version 指以有限數量生產的產品特別版本。"},{"en":"A phone brand may sell a limited-edition version with a special colour and gift box.","zh":"手機品牌可能售賣一款有特別顏色和禮盒的限量版。"},{"en":"Because the limited-edition version is scarce, customers may need to order it early.","zh":"由於限量版數量稀少，顧客可能需要提早訂購。"},{"en":"A limited-edition version often costs more than the regular version.","zh":"限量版通常比普通版價格更高。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"As for","meaning":"至於","examples":[{"en":"As for the details of our purchase, our company would like to order 200 items.","zh":"至於我們採購的詳情，本公司想訂購200件貨品。"},{"en":"As for is used to introduce a new but related topic.","zh":"As for 用來引出一個新的但相關的話題。"},{"en":"As for transport, students can take the school bus or the MTR.","zh":"至於交通，學生可以乘校巴或港鐵。"},{"en":"This phrase helps a letter move smoothly from one point to another.","zh":"這個短語幫助信件自然地從一點轉到另一點。"},{"en":"As for is useful when the writer wants to separate different parts of a discussion.","zh":"當作者想分開討論不同部分時，As for 很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"it is confirmed that","meaning":"現確認","examples":[{"en":"It is confirmed that our company would like to order 200 items.","zh":"現確認本公司想訂購200件貨品。"},{"en":"It is confirmed that means something has been officially stated or made certain.","zh":"it is confirmed that 指某事已被正式說明或確定。"},{"en":"It is confirmed that the meeting will take place next Monday.","zh":"現確認會議將於下星期一舉行。"},{"en":"This phrase removes doubt by showing that a decision is now definite.","zh":"這個短語透過顯示決定已確定來消除疑問。"},{"en":"It is formal and often used in business messages, notices, and reports.","zh":"它較正式，常用於商業訊息、通知和報告。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"place an order for","meaning":"訂購……","examples":[{"en":"Our company would like to place an order for 200 items.","zh":"本公司想訂購200件貨品。"},{"en":"To place an order for something means to formally request to buy it.","zh":"place an order for something 指正式提出購買某物的要求。"},{"en":"A restaurant may place an order for fresh vegetables every morning.","zh":"餐廳可能每天早上訂購新鮮蔬菜。"},{"en":"Once a company places an order, the seller can prepare stock, payment records, and delivery.","zh":"公司一下訂單，賣方就可以準備存貨、付款紀錄和送貨。"},{"en":"This phrase is common in business because it sounds more formal than buy.","zh":"這個短語在商業中常見，因為它比 buy 更正式。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"200 items","meaning":"200件貨品","examples":[{"en":"Our company would like to place an order for 200 items.","zh":"本公司想訂購200件貨品。"},{"en":"200 items means two hundred units or pieces of goods.","zh":"200 items 指二百個單位或二百件貨品。"},{"en":"A school may order 200 items, such as notebooks, for a large student event.","zh":"學校可能為大型學生活動訂購200件貨品，例如筆記簿。"},{"en":"Ordering 200 items may count as a bulk purchase and may justify asking for a discount.","zh":"訂購200件貨品可能算是大批量採購，因此可合理要求折扣。"},{"en":"In a business letter, stating 200 items clearly helps the supplier calculate stock and delivery.","zh":"在商業信件中清楚列明200件貨品，有助供應商計算存貨和送貨。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"will be ordered by","meaning":"將由……訂購","examples":[{"en":"A total of 200 items will be ordered by our company.","zh":"合共200件貨品將由本公司訂購。"},{"en":"Will be ordered by shows who will make the order in a passive sentence.","zh":"will be ordered by 在被動句中顯示誰將會下訂單。"},{"en":"The textbooks will be ordered by the school office before the new term.","zh":"教科書將由校務處在新學期前訂購。"},{"en":"This structure is useful when the writer wants to emphasise the items rather than the buyer.","zh":"當作者想強調貨品而不是買家時，這個結構很有用。"},{"en":"In business writing, passive forms can sound formal and objective.","zh":"在商業寫作中，被動形式可以聽起來正式而客觀。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":2},{"front":"In addition","meaning":"此外","examples":[{"en":"In addition, we would be most grateful if the products could be delivered before August.","zh":"此外，如產品能在八月之前送達，我們將非常感激。"},{"en":"In addition is used to add another point to what has already been said.","zh":"In addition 用來補充前面已經說過的內容。"},{"en":"The hotel is near the station; in addition, it provides free breakfast.","zh":"這間酒店接近車站；此外，它提供免費早餐。"},{"en":"This phrase helps organise several requests in a formal letter.","zh":"這個短語有助在正式信件中整理多項請求。"},{"en":"It is more formal than also, so it is useful in business writing.","zh":"它比 also 更正式，所以在商業寫作中很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"we would be most grateful if","meaning":"如能……，我們將非常感激","examples":[{"en":"We would be most grateful if the products could be delivered to Hong Kong before August.","zh":"如產品能在八月之前送達香港，我們將非常感激。"},{"en":"We would be most grateful if is a highly polite expression used to make an important request.","zh":"We would be most grateful if 是用來提出重要請求的高度禮貌表達。"},{"en":"We would be most grateful if you could confirm the booking by tomorrow.","zh":"如你能在明天前確認預訂，我們將非常感激。"},{"en":"This phrase shows respect and makes the request sound less forceful.","zh":"這個短語顯示尊重，並令請求聽起來較不強硬。"},{"en":"It is suitable when asking for help, speed, flexibility, or special arrangements.","zh":"它適合用於請求協助、加快處理、彈性安排或特別安排。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"could be delivered to","meaning":"能夠送達……","examples":[{"en":"We would be most grateful if the products could be delivered to Hong Kong before August.","zh":"如產品能在八月之前送達香港，我們將非常感激。"},{"en":"Could be delivered to means could be sent or transported to a particular place.","zh":"could be delivered to 指能夠被送往或運送到某個特定地方。"},{"en":"The documents could be delivered to the office by courier.","zh":"文件可以透過速遞送達辦公室。"},{"en":"Asking whether goods could be delivered to a place helps confirm shipping arrangements before ordering.","zh":"詢問貨品能否送達某地，有助在訂購前確認運輸安排。"},{"en":"This phrase is useful when the delivery location matters to the buyer.","zh":"當送貨地點對買家很重要時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"before August","meaning":"八月之前","examples":[{"en":"We would like the products to be delivered before August.","zh":"我們希望產品在八月之前送達。"},{"en":"Before August means earlier than the start of August.","zh":"before August 指早於八月開始的時間。"},{"en":"The school wants the uniforms to arrive before August so students can prepare for the new term.","zh":"學校希望校服在八月之前送達，好讓學生為新學期準備。"},{"en":"If the goods arrive after August begins, the buyer’s schedule may be affected.","zh":"如果貨品在八月開始後才送達，買家的時間表可能會受影響。"},{"en":"This phrase sets a clear deadline without naming an exact day.","zh":"這個短語設定清晰期限，但沒有指定確切日子。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"Regarding","meaning":"關於","examples":[{"en":"Regarding our purchase of the limited-edition version, we would like to ask whether 30 items can be ordered.","zh":"關於我們購買限量版，我們想查詢是否可以訂購30件貨品。"},{"en":"Regarding means about or concerning a particular topic.","zh":"Regarding 指關於或涉及某個特定話題。"},{"en":"Regarding the school trip, parents will receive a notice next week.","zh":"關於學校旅行，家長將於下星期收到通知。"},{"en":"This word helps introduce a new section in a formal letter or email.","zh":"這個字有助在正式信件或電郵中引出新部分。"},{"en":"Regarding is more formal than about and is common in business communication.","zh":"Regarding 比 about 更正式，常見於商業溝通。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"our purchase of","meaning":"我們購買……","examples":[{"en":"Regarding our purchase of the limited-edition version, we have one further question.","zh":"關於我們購買限量版，我們有一個進一步問題。"},{"en":"Our purchase of something means the act or plan of buying that thing by our company or group.","zh":"our purchase of something 指我們公司或團體購買某物的行為或計劃。"},{"en":"Our purchase of new computers will depend on the final quotation.","zh":"我們購買新電腦將取決於最終報價。"},{"en":"Mentioning our purchase of a product helps connect the question to a specific order.","zh":"提及我們購買某產品，有助把問題連繫到具體訂單。"},{"en":"This phrase is formal and useful when discussing buying arrangements.","zh":"這個短語較正式，適合討論採購安排。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"is it possible to","meaning":"是否可以……","examples":[{"en":"Is it possible to order 30 units of the limited-edition version?","zh":"是否可以訂購30件限量版？"},{"en":"Is it possible to is a polite way to ask whether something can be done.","zh":"Is it possible to 是禮貌詢問某事是否能做到的說法。"},{"en":"Is it possible to change the delivery address after placing the order?","zh":"下訂單後是否可以更改送貨地址？"},{"en":"This question is useful when the writer is unsure whether the request is allowed.","zh":"當作者不確定請求是否被允許時，這個問題很有用。"},{"en":"It sounds softer and more polite than Can we do this?","zh":"它比 Can we do this? 聽起來更柔和、更有禮。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"order 30 units of","meaning":"訂購30件……","examples":[{"en":"Is it possible to order 30 units of the limited-edition version?","zh":"是否可以訂購30件限量版？"},{"en":"To order 30 units of something means to formally request to buy thirty pieces or items of it.","zh":"order 30 units of something 指正式要求購買三十件某物。"},{"en":"A shop may order 30 units of a new toy before the holiday season.","zh":"商店可能在假期前訂購30件新玩具。"},{"en":"Ordering 30 units helps the supplier know the exact quantity needed.","zh":"訂購30件貨品有助供應商知道所需的確切數量。"},{"en":"This phrase is useful when the number of products is important.","zh":"當產品數量很重要時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"Finally","meaning":"最後","examples":[{"en":"Finally, we would like to ask whether a discount could be offered.","zh":"最後，我們想詢問可否提供折扣。"},{"en":"Finally is used to introduce the last point in a list or sequence.","zh":"Finally 用來引出清單或次序中的最後一點。"},{"en":"Finally, please check your name and class number before submitting the form.","zh":"最後，提交表格前請檢查你的姓名和班別號碼。"},{"en":"Using finally tells the reader that the writer is reaching the last request.","zh":"使用 finally 告訴讀者作者正提出最後一項請求。"},{"en":"This word helps give a letter a clear beginning, middle, and end.","zh":"這個字有助信件具備清晰的開始、中段和結尾。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"since","meaning":"由於","examples":[{"en":"Since we will be making a bulk purchase, we would like to ask whether a discount could be offered.","zh":"由於我們將會大批量採購，所以想詢問可否提供折扣。"},{"en":"Since means because when it gives the reason for something.","zh":"since 在說明原因時解作 because。"},{"en":"Since the train is delayed, we should call the teacher and explain.","zh":"由於火車延誤，我們應致電老師解釋。"},{"en":"Using since helps connect a request with the reason behind it.","zh":"使用 since 有助把請求與背後原因連繫起來。"},{"en":"In formal writing, since can make a reason sound clear and logical.","zh":"在正式寫作中，since 可以令原因聽起來清晰而合乎邏輯。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"make a bulk purchase","meaning":"大批量採購","examples":[{"en":"Since we will be making a bulk purchase, we would like to ask about a possible discount.","zh":"由於我們將會大批量採購，所以想詢問可能提供的折扣。"},{"en":"To make a bulk purchase means to buy a large quantity of goods at one time.","zh":"make a bulk purchase 指一次購買大量貨品。"},{"en":"A school may make a bulk purchase of tablets for all new students.","zh":"學校可能為所有新生大批量採購平板電腦。"},{"en":"Making a bulk purchase can reduce the price per item if the seller offers a discount.","zh":"如果賣方提供折扣，大批量採購可以降低每件貨品的價格。"},{"en":"Buyers should confirm storage, delivery, and payment before making a bulk purchase.","zh":"買家在大批量採購前應確認儲存、送貨和付款安排。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":3},{"front":"a bulk purchase","meaning":"大批量採購","examples":[{"en":"A discount would be appreciated because this is a bulk purchase.","zh":"由於這是大批量採購，如能提供折扣，我們將十分感激。"},{"en":"A bulk purchase is a large order of many items bought together.","zh":"bulk purchase 指一次過購買大量貨品的大型訂單。"},{"en":"Buying 300 notebooks for a conference is a bulk purchase.","zh":"為會議購買300本筆記簿是一項大批量採購。"},{"en":"A bulk purchase may give the buyer stronger reasons to request a lower price.","zh":"大批量採購可能令買家有更充分理由要求較低價格。"},{"en":"However, a bulk purchase also requires careful planning because storage and delivery may be difficult.","zh":"不過，大批量採購也需要仔細規劃，因為儲存和送貨可能較困難。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"we were wondering if","meaning":"我們想知道是否……","examples":[{"en":"We were wondering if a discount could be offered.","zh":"我們想知道是否可以提供折扣。"},{"en":"We were wondering if is a polite and indirect way to ask a question or make a request.","zh":"We were wondering if 是禮貌而間接地提問或提出請求的說法。"},{"en":"We were wondering if you could extend the payment deadline by one week.","zh":"我們想知道是否可以把付款期限延長一星期。"},{"en":"This phrase makes a request sound less direct and more respectful.","zh":"這個短語令請求聽起來較不直接，而且更尊重對方。"},{"en":"It is useful in business emails when asking for flexibility or special treatment.","zh":"在商業電郵中要求彈性或特別安排時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"a discount could be offered","meaning":"可否提供折扣","examples":[{"en":"We were wondering if a discount could be offered for this bulk purchase.","zh":"我們想知道這次大批量採購可否提供折扣。"},{"en":"A discount could be offered means the seller might reduce the price.","zh":"a discount could be offered 指賣方可能降低價格。"},{"en":"A shop may say a discount could be offered if the customer buys more than fifty units.","zh":"如果顧客購買超過五十件，商店可能表示可提供折扣。"},{"en":"If a discount is offered, the buyer may be more willing to place a larger order.","zh":"如果提供折扣，買家可能更願意下較大的訂單。"},{"en":"This phrase is polite because it asks about a lower price without sounding too demanding.","zh":"這個短語很有禮，因為它詢問較低價格，但不會顯得太強硬。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"Should you have any enquiries","meaning":"如你有任何查詢","examples":[{"en":"Should you have any enquiries concerning our purchase, please do not hesitate to contact us.","zh":"如你有任何關於我們採購的查詢，請隨時與我們聯絡。"},{"en":"Should you have any enquiries means if you have any questions.","zh":"Should you have any enquiries 指如果你有任何問題。"},{"en":"Should you have any enquiries about the timetable, please contact the school office.","zh":"如你有任何關於時間表的查詢，請聯絡校務處。"},{"en":"This phrase makes the writer sound helpful and open to further communication.","zh":"這個短語令作者聽起來樂意幫忙，並願意進一步溝通。"},{"en":"It is formal and commonly used near the end of business letters.","zh":"它較正式，常用於商業信件結尾部分。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"concerning our purchase","meaning":"關於我們的採購","examples":[{"en":"Should you have any enquiries concerning our purchase, please do not hesitate to contact us.","zh":"如你有任何關於我們採購的查詢，請隨時與我們聯絡。"},{"en":"Concerning our purchase means about or related to our order or buying arrangement.","zh":"concerning our purchase 指關於或涉及我們的訂單或購買安排。"},{"en":"The supplier sent an update concerning our purchase of office chairs.","zh":"供應商發送了一項關於我們購買辦公椅的更新。"},{"en":"Using concerning our purchase keeps the focus on the business transaction.","zh":"使用 concerning our purchase 可以把重點集中在商業交易上。"},{"en":"This phrase is formal and useful when discussing details of an order.","zh":"這個短語較正式，適合討論訂單詳情。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"please do not hesitate to contact us","meaning":"請隨時與我們聯絡","examples":[{"en":"Should you have any enquiries, please do not hesitate to contact us.","zh":"如你有任何查詢，請隨時與我們聯絡。"},{"en":"Please do not hesitate to contact us means please feel free to get in touch with us.","zh":"please do not hesitate to contact us 指請放心與我們聯絡。"},{"en":"Please do not hesitate to contact us if you need another copy of the invoice.","zh":"如你需要另一份發票副本，請隨時與我們聯絡。"},{"en":"This phrase encourages the receiver to ask questions without feeling troublesome.","zh":"這個短語鼓勵收信人提問，而不會覺得麻煩。"},{"en":"It is a polite closing phrase in formal emails and business letters.","zh":"它是正式電郵和商業信件中有禮的結尾用語。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"more than happy to","meaning":"非常樂意","examples":[{"en":"We are more than happy to provide you with further information.","zh":"我們非常樂意向你提供進一步資料。"},{"en":"More than happy to means very willing to do something.","zh":"more than happy to 指非常願意做某事。"},{"en":"The staff are more than happy to help visitors find the correct room.","zh":"職員非常樂意幫助訪客找到正確房間。"},{"en":"This phrase creates a friendly tone and shows the writer is willing to cooperate.","zh":"這個短語營造友善語氣，並顯示作者願意合作。"},{"en":"It is useful when offering help after making a request or giving information.","zh":"在提出請求或提供資料後表示願意協助時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"provide further information","meaning":"提供進一步資料","examples":[{"en":"We are more than happy to provide further information.","zh":"我們非常樂意提供進一步資料。"},{"en":"To provide further information means to give extra details beyond what has already been said.","zh":"provide further information 指在已說明的內容以外提供額外詳情。"},{"en":"The teacher can provide further information about the exam format next week.","zh":"老師可以在下星期提供關於考試形式的進一步資料。"},{"en":"Providing further information helps answer questions and prevent misunderstanding.","zh":"提供進一步資料有助回答問題和避免誤解。"},{"en":"This phrase is common when the writer is willing to explain more if needed.","zh":"當作者願意在需要時作更多解釋，這個短語很常見。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"Thank you very much for your attention","meaning":"感謝你的關注","examples":[{"en":"Thank you very much for your attention.","zh":"感謝你的關注。"},{"en":"Thank you very much for your attention is a polite closing sentence that thanks the reader for reading and considering the matter.","zh":"Thank you very much for your attention 是有禮的結尾句，用來感謝讀者閱讀並考慮有關事項。"},{"en":"A speaker may say thank you very much for your attention at the end of a presentation.","zh":"講者可以在簡報結尾說 thank you very much for your attention。"},{"en":"This sentence helps end a formal message respectfully.","zh":"這句話有助以尊重語氣結束正式訊息。"},{"en":"It is especially useful when the writer has made several requests.","zh":"當作者提出了幾項請求時，這句話尤其有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"look forward to","meaning":"期待","examples":[{"en":"I look forward to your favourable reply.","zh":"我期待你的正面回覆。"},{"en":"To look forward to something means to wait for it with interest, hope, or expectation.","zh":"look forward to something 指帶著興趣、希望或期待等待某事。"},{"en":"Students look forward to the results after finishing an important exam.","zh":"學生完成重要考試後，會期待成績。"},{"en":"In formal letters, look forward to is often used to show that the writer expects a reply.","zh":"在正式信件中，look forward to 常用來表示作者期待回覆。"},{"en":"This phrase should be followed by a noun or an -ing verb.","zh":"這個短語後面應接名詞或 -ing 動詞。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"your favourable reply","meaning":"你的正面回覆","examples":[{"en":"I look forward to your favourable reply.","zh":"我期待你的正面回覆。"},{"en":"Your favourable reply means a positive or helpful response from the receiver.","zh":"your favourable reply 指收信人作出的正面或有幫助的回覆。"},{"en":"A job applicant may write that they look forward to a favourable reply after an interview.","zh":"求職者面試後可能會寫，他期待正面回覆。"},{"en":"Asking for a favourable reply shows hope that the receiver will accept or support the request.","zh":"期待正面回覆顯示作者希望收信人接受或支持其請求。"},{"en":"This phrase is formal and often appears near the end of enquiry or application letters.","zh":"這個短語較正式，常出現在查詢信或申請信結尾附近。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":4},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully, Chris Wong.","zh":"Chris Wong 謹啟。"},{"en":"Yours faithfully is a formal closing used when the letter begins with Dear Sir/Madam.","zh":"Yours faithfully 是當信件以 Dear Sir/Madam 開始時使用的正式結尾語。"},{"en":"A business enquiry that starts with Dear Sir/Madam can end with Yours faithfully.","zh":"以 Dear Sir/Madam 開始的商業查詢信可以用 Yours faithfully 結尾。"},{"en":"Using the correct closing makes a formal letter look professional and complete.","zh":"使用正確結尾語能令正式信件看起來專業而完整。"},{"en":"If the letter begins with a named person, Yours sincerely is usually more appropriate.","zh":"如果信件以具名人士作稱呼，通常較適合使用 Yours sincerely。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"staff member of","meaning":"……的職員","examples":[{"en":"Chris Wong is a staff member of TBC Trade Company.","zh":"Chris Wong 是TBC貿易公司的職員。"},{"en":"A staff member of an organisation is a person who works for that organisation.","zh":"staff member of an organisation 指為某機構工作的人。"},{"en":"A staff member of the library helped students find reference books.","zh":"圖書館的職員幫助學生尋找參考書。"},{"en":"Identifying someone as a staff member of a company shows they are connected to that company officially.","zh":"說明某人是公司職員，顯示他們與該公司有正式關係。"},{"en":"This phrase is useful when explaining a person’s role in a formal situation.","zh":"在正式情況中解釋某人的身份時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"TBC Trade Company","meaning":"TBC貿易公司","examples":[{"en":"Chris Wong writes on behalf of TBC Trade Company.","zh":"Chris Wong 代表TBC貿易公司寫信。"},{"en":"TBC Trade Company is the company represented by Chris Wong in the letter.","zh":"TBC Trade Company 是信中由 Chris Wong 代表的公司。"},{"en":"In a formal enquiry, the company name tells the receiver who is making the request.","zh":"在正式查詢中，公司名稱告訴收信人誰正在提出請求。"},{"en":"Naming TBC Trade Company helps the supplier identify the buyer and record the enquiry properly.","zh":"寫明TBC貿易公司有助供應商識別買家並妥善記錄查詢。"},{"en":"A company name should be written clearly in business communication.","zh":"在商業溝通中，公司名稱應清楚寫出。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"write on behalf of","meaning":"代表……寫信","examples":[{"en":"Chris Wong writes on behalf of TBC Trade Company.","zh":"Chris Wong 代表TBC貿易公司寫信。"},{"en":"To write on behalf of someone means to write as their representative.","zh":"write on behalf of someone 指以某人或某機構代表的身份寫信。"},{"en":"A secretary may write on behalf of the principal to invite guests to a ceremony.","zh":"秘書可以代表校長寫信邀請嘉賓出席典禮。"},{"en":"Writing on behalf of a company shows that the message is official, not only personal.","zh":"代表公司寫信顯示訊息是正式的，而不只是個人意見。"},{"en":"This phrase is common when an employee sends a letter for an organisation.","zh":"當員工為機構發信時，這個短語很常見。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"formal enquiry","meaning":"正式查詢","examples":[{"en":"This formal enquiry asks about the price, delivery method and limited-edition version of Product A.","zh":"這項正式查詢詢問A產品的價格、送貨方式和限量版。"},{"en":"A formal enquiry is a polite official request for information.","zh":"formal enquiry 指禮貌而正式地索取資料。"},{"en":"A company may send a formal enquiry before choosing a new supplier.","zh":"公司在選擇新供應商前，可能會發出正式查詢。"},{"en":"A formal enquiry helps both sides keep a written record of questions and replies.","zh":"正式查詢有助雙方保留問題和回覆的書面紀錄。"},{"en":"It should use clear language, proper tone, and specific questions.","zh":"它應使用清晰語言、恰當語氣和具體問題。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"purchase details","meaning":"採購詳情","examples":[{"en":"The letter provides purchase details for Product A.","zh":"這封信提供A產品的採購詳情。"},{"en":"Purchase details are the specific facts about an order, such as quantity, product type, delivery place, and deadline.","zh":"purchase details 指訂單的具體資料，例如數量、產品類型、送貨地點和期限。"},{"en":"A buyer should check the purchase details before confirming payment.","zh":"買家應在確認付款前檢查採購詳情。"},{"en":"Incorrect purchase details can lead to wrong products, late delivery, or payment problems.","zh":"錯誤的採購詳情可能導致產品錯誤、送貨延誤或付款問題。"},{"en":"Clear purchase details help a supplier process an order accurately.","zh":"清楚的採購詳情有助供應商準確處理訂單。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"further details","meaning":"進一步詳情","examples":[{"en":"The company would like to request further details about Product A.","zh":"該公司想索取更多關於A產品的進一步詳情。"},{"en":"Further details are extra pieces of information that explain something more fully.","zh":"further details 指能更完整解釋某事的額外資料。"},{"en":"Parents asked for further details about the camp schedule and safety arrangements.","zh":"家長詢問關於營地時間表和安全安排的進一步詳情。"},{"en":"Further details help people make decisions when basic information is not enough.","zh":"當基本資料不足時，進一步詳情能幫助人作決定。"},{"en":"This phrase is common in formal enquiries, reports, and follow-up emails.","zh":"這個短語常見於正式查詢、報告和跟進電郵。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"delivery to Hong Kong","meaning":"送貨到香港","examples":[{"en":"The company requests delivery to Hong Kong before August.","zh":"該公司要求在八月之前送貨到香港。"},{"en":"Delivery to Hong Kong means the goods are sent or transported to Hong Kong.","zh":"delivery to Hong Kong 指貨品被送往或運送到香港。"},{"en":"An online shop may offer delivery to Hong Kong for international customers.","zh":"網店可能為國際顧客提供送貨到香港的服務。"},{"en":"Confirming delivery to Hong Kong is important because shipping cost and time may differ by location.","zh":"確認是否能送貨到香港很重要，因為運費和時間可能因地點而不同。"},{"en":"If delivery to Hong Kong is not available, the buyer may need another supplier.","zh":"如果不能送貨到香港，買家可能需要尋找另一間供應商。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"limited-edition order","meaning":"限量版訂單","examples":[{"en":"The company asks whether a limited-edition order of 30 units is possible.","zh":"該公司詢問是否可以下30件限量版訂單。"},{"en":"A limited-edition order is an order for a special version of a product produced in limited numbers.","zh":"limited-edition order 指訂購以有限數量生產的產品特別版本。"},{"en":"A shop may place a limited-edition order for special gift boxes before Christmas.","zh":"商店可能在聖誕節前下限量版禮盒訂單。"},{"en":"Limited-edition orders may need early confirmation because stock can run out quickly.","zh":"限量版訂單可能需要提早確認，因為存貨很快售罄。"},{"en":"Buyers should check quantity limits before making a limited-edition order.","zh":"買家在下限量版訂單前應檢查數量限制。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5},{"front":"possible discount","meaning":"可能提供的折扣","examples":[{"en":"The company asks about a possible discount for a bulk purchase.","zh":"該公司詢問大批量採購是否有可能提供的折扣。"},{"en":"A possible discount is a price reduction that may be available but has not yet been confirmed.","zh":"possible discount 指可能可以獲得但尚未確認的減價優惠。"},{"en":"A customer may ask about a possible discount before ordering furniture for a whole office.","zh":"顧客在為整個辦公室訂購家具前，可能會詢問可能提供的折扣。"},{"en":"If a possible discount is confirmed, the final cost may become much lower.","zh":"如果可能提供的折扣獲確認，最終成本可能會低很多。"},{"en":"This phrase is useful when asking politely without assuming the seller must reduce the price.","zh":"這個短語適合禮貌查詢，而不是假設賣方必須減價。"}],"source":"Flash Cards -實用文 - Letter of Enquiry .pdf","sourcePage":5}],"dse/paper-3/practical-english-writing/practical-formats/letter-of-invitation-spokesperson":[{"front":"Letter of Invitation","meaning":"邀請信","examples":[{"en":"This is a formal letter of invitation to Ms Mok.","zh":"這是一封給 Mok 女士的正式邀請信。"},{"en":"A letter of invitation is a message that formally asks someone to attend an event or accept a role.","zh":"邀請信是正式邀請某人出席活動或接受某個角色的訊息。"},{"en":"A school may send a letter of invitation to a guest speaker before the annual prize ceremony.","zh":"學校可以在年度頒獎典禮前向嘉賓講者發出邀請信。"},{"en":"A clear letter of invitation helps the receiver understand why they are invited and what they need to do.","zh":"清晰的邀請信有助收信人明白為何被邀請，以及需要做甚麼。"},{"en":"A formal letter of invitation should include the purpose, date, details, and polite closing.","zh":"正式邀請信應包括目的、日期、詳情和有禮結尾。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"Dear Ms Mok","meaning":"Mok女士鈞鑒","examples":[{"en":"Dear Ms Mok, you are cordially invited to serve as our hotel’s spokesperson.","zh":"Mok 女士鈞鑒：誠邀你擔任我們酒店的代言人。"},{"en":"Dear Ms Mok is a formal greeting used when writing directly to a woman named Ms Mok.","zh":"Dear Ms Mok 是直接寫信給 Mok 女士時使用的正式稱呼。"},{"en":"A business letter may begin with Dear Ms Mok if the writer knows the receiver’s surname and title.","zh":"如果作者知道收信人的姓氏和稱謂，商業信件可以用 Dear Ms Mok 開首。"},{"en":"Using the correct greeting helps the letter sound respectful and professional.","zh":"使用正確稱呼有助信件聽起來尊重而專業。"},{"en":"If the receiver’s name is unknown, the writer may use Dear Sir/Madam instead.","zh":"如果不知道收信人的姓名，作者可以改用 Dear Sir/Madam。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"be cordially invited to","meaning":"誠邀……","examples":[{"en":"You are cordially invited to attend the opening ceremony of GC Hotel.","zh":"誠邀你出席 GC Hotel 的開幕典禮。"},{"en":"Be cordially invited to means be warmly and formally asked to attend or do something.","zh":"be cordially invited to 指被熱情而正式地邀請出席或做某事。"},{"en":"Parents are cordially invited to attend the school’s music performance.","zh":"誠邀家長出席學校音樂表演。"},{"en":"This phrase makes an invitation sound respectful, official, and welcoming.","zh":"這個短語令邀請聽起來尊重、正式而親切。"},{"en":"It is more formal than simply saying you are invited to.","zh":"它比簡單說 you are invited to 更正式。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"serve as","meaning":"擔任","examples":[{"en":"You are cordially invited to serve as our hotel’s spokesperson.","zh":"誠邀你擔任我們酒店的代言人。"},{"en":"To serve as something means to take on a particular role or function.","zh":"serve as something 指承擔某個角色或功能。"},{"en":"A senior student may serve as a mentor for new students during orientation week.","zh":"高年級學生可以在迎新週擔任新生導師。"},{"en":"When someone serves as a representative, their words and actions affect the group’s image.","zh":"當某人擔任代表，他們的言行會影響團體形象。"},{"en":"This phrase is common in formal writing when describing duties or positions.","zh":"這個短語常用於正式寫作中描述職責或職位。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"our hotel’s spokesperson","meaning":"我們酒店的代言人","examples":[{"en":"Ms Mok is invited to serve as our hotel’s spokesperson for the coming year.","zh":"Mok 女士獲邀擔任我們酒店來年的代言人。"},{"en":"Our hotel’s spokesperson is the person who publicly represents the hotel and promotes its image.","zh":"our hotel’s spokesperson 指公開代表酒店並推廣其形象的人。"},{"en":"A hotel’s spokesperson may appear in advertisements, interviews, and public events.","zh":"酒店代言人可能出現在廣告、訪問和公開活動中。"},{"en":"If the spokesperson is respected, guests may trust the hotel’s values more easily.","zh":"如果代言人受人尊重，客人可能更容易相信酒店的價值觀。"},{"en":"Choosing the right spokesperson matters because they become closely linked to the brand.","zh":"選擇合適代言人很重要，因為他們會與品牌緊密連繫。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"for the coming year","meaning":"來年","examples":[{"en":"Ms Mok is invited to serve as the hotel’s spokesperson for the coming year.","zh":"Mok 女士獲邀擔任酒店來年的代言人。"},{"en":"For the coming year means during the next year from now or from the stated starting point.","zh":"for the coming year 指由現在或指定起點開始的下一年期間。"},{"en":"The committee has planned several charity events for the coming year.","zh":"委員會已為來年計劃幾項慈善活動。"},{"en":"If a person accepts a role for the coming year, they should understand the time commitment involved.","zh":"如果某人接受來年的角色，他們應明白所需投入的時間。"},{"en":"This phrase is useful when describing future plans, duties, or appointments.","zh":"這個短語適合描述未來計劃、職責或任命。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"attend the opening ceremony of","meaning":"出席……的開幕典禮","examples":[{"en":"Ms Mok is invited to attend the opening ceremony of GC Hotel.","zh":"Mok 女士獲邀出席 GC Hotel 的開幕典禮。"},{"en":"To attend the opening ceremony of a place means to be present at its formal first public event.","zh":"attend the opening ceremony of a place 指出席某地正式首次公開活動。"},{"en":"Local officials may attend the opening ceremony of a new community centre.","zh":"本地官員可能出席新社區中心的開幕典禮。"},{"en":"Attending an opening ceremony shows support and gives the event a more official feeling.","zh":"出席開幕典禮能顯示支持，並令活動更有正式感。"},{"en":"This phrase is often used in formal invitations and event notices.","zh":"這個短語常用於正式邀請和活動通知。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"the opening ceremony","meaning":"開幕典禮","examples":[{"en":"The opening ceremony will be held on 14 July.","zh":"開幕典禮將於7月14日舉行。"},{"en":"The opening ceremony is a formal event that marks the beginning or launch of something.","zh":"opening ceremony 是標誌某事物開始或推出的正式活動。"},{"en":"A new library may hold an opening ceremony before it welcomes the public.","zh":"新圖書館在開放予公眾前可能會舉行開幕典禮。"},{"en":"An opening ceremony can attract media attention and introduce the project to guests.","zh":"開幕典禮可以吸引媒體注意，並向嘉賓介紹項目。"},{"en":"It usually includes speeches, guests, photos, and sometimes a ribbon-cutting moment.","zh":"它通常包括演講、嘉賓、拍照，有時還有剪綵環節。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"the reasons for inviting you","meaning":"邀請你的原因","examples":[{"en":"The reasons for inviting you are outlined below.","zh":"邀請你的原因概述如下。"},{"en":"The reasons for inviting you are the explanations of why you have been chosen or asked to join.","zh":"the reasons for inviting you 指解釋你為何被選中或被邀請參與的原因。"},{"en":"In a formal invitation, the reasons for inviting a guest may include their experience and reputation.","zh":"在正式邀請中，邀請嘉賓的原因可能包括他們的經驗和聲譽。"},{"en":"Explaining the reasons for inviting someone can make the invitation feel sincere and thoughtful.","zh":"解釋邀請某人的原因可以令邀請顯得真誠而周到。"},{"en":"Without clear reasons, the receiver may not understand why they are the right person.","zh":"如果沒有清楚原因，收信人可能不明白自己為何是合適人選。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"as well as","meaning":"以及","examples":[{"en":"The reasons for inviting you, as well as the details of the ceremony, are outlined below.","zh":"邀請你的原因以及典禮詳情概述如下。"},{"en":"As well as means in addition to or together with another thing.","zh":"as well as 指除此之外，或與另一事物一起。"},{"en":"The school will provide lunch as well as transport for the students.","zh":"學校將為學生提供午餐以及交通安排。"},{"en":"This phrase helps combine two related pieces of information in one sentence.","zh":"這個短語有助把兩項相關資料放在同一句中。"},{"en":"It is useful when the writer wants to add something without starting a new sentence.","zh":"當作者想補充內容而不另開新句時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"the details of the ceremony","meaning":"典禮詳情","examples":[{"en":"The details of the ceremony are outlined below.","zh":"典禮詳情概述如下。"},{"en":"The details of the ceremony are the specific facts about the event, such as time, place, guests, and activities.","zh":"the details of the ceremony 指關於活動的具體資料，例如時間、地點、嘉賓和流程。"},{"en":"Guests should read the details of the ceremony before deciding what time to arrive.","zh":"嘉賓應先閱讀典禮詳情，再決定何時到達。"},{"en":"Clear ceremony details help prevent confusion on the day of the event.","zh":"清晰的典禮詳情有助避免活動當日出現混亂。"},{"en":"If important details are missing, guests may not know what to prepare.","zh":"如果缺少重要詳情，嘉賓可能不知道需要準備甚麼。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":1},{"front":"be held on","meaning":"於……舉行","examples":[{"en":"The opening ceremony will be held on 14 July.","zh":"開幕典禮將於7月14日舉行。"},{"en":"Be held on is used to say the date when an event will take place.","zh":"be held on 用來說明活動將在哪一天舉行。"},{"en":"The parents’ meeting will be held on Friday afternoon.","zh":"家長會將於星期五下午舉行。"},{"en":"Stating when an event will be held helps guests arrange their schedules.","zh":"說明活動何時舉行，有助嘉賓安排時間表。"},{"en":"This phrase is formal and common in notices, invitations, and announcements.","zh":"這個短語較正式，常見於通知、邀請信和公告。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"are outlined below","meaning":"概述如下","examples":[{"en":"The reasons and ceremony details are outlined below.","zh":"原因和典禮詳情概述如下。"},{"en":"Are outlined below means the main points are briefly explained in the following part of the text.","zh":"are outlined below 指主要重點會在下文簡要說明。"},{"en":"The rules for the competition are outlined below for all participants.","zh":"比賽規則概述如下，供所有參賽者參考。"},{"en":"This phrase prepares the reader to look at the information that follows.","zh":"這個短語提醒讀者留意接下來的資料。"},{"en":"It is useful in formal writing when introducing organised details.","zh":"在正式寫作中引出有條理的詳情時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"previously expressed","meaning":"之前表達過","examples":[{"en":"You have previously expressed a strong interest in environmental protection.","zh":"你之前表達過對環境保護有濃厚興趣。"},{"en":"Previously expressed means said or shown earlier, before the present moment.","zh":"previously expressed 指在現在之前曾經說出或顯示。"},{"en":"The student had previously expressed interest in joining the science club.","zh":"那名學生之前表達過有興趣加入科學學會。"},{"en":"Mentioning what someone previously expressed helps explain why they are being contacted now.","zh":"提及某人之前表達過的想法，有助解釋為何現在聯絡他們。"},{"en":"This phrase is useful when linking a past opinion to a current invitation or decision.","zh":"當要把過去意見與現時邀請或決定連繫起來時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"a strong interest in","meaning":"對……有濃厚興趣","examples":[{"en":"Ms Mok has expressed a strong interest in environmental protection.","zh":"Mok 女士表達過對環境保護有濃厚興趣。"},{"en":"A strong interest in something means a deep and serious concern or curiosity about it.","zh":"a strong interest in something 指對某事物有深厚而認真的關注或好奇心。"},{"en":"A student with a strong interest in science may read extra books after class.","zh":"對科學有濃厚興趣的學生可能會在課後閱讀額外書籍。"},{"en":"When someone has a strong interest in a topic, they are more likely to support related activities.","zh":"當某人對某議題有濃厚興趣，他們較可能支持相關活動。"},{"en":"This phrase helps explain why a person is suitable for a role or project.","zh":"這個短語有助解釋某人為何適合某角色或項目。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"environmental protection","meaning":"環境保護","examples":[{"en":"Ms Mok has a strong interest in environmental protection.","zh":"Mok 女士對環境保護有濃厚興趣。"},{"en":"Environmental protection means actions that help protect nature, reduce pollution, and use resources responsibly.","zh":"environmental protection 指保護自然、減少污染和負責任地使用資源的行動。"},{"en":"Recycling paper and saving electricity are simple forms of environmental protection.","zh":"回收紙張和節約用電都是簡單的環境保護方式。"},{"en":"Without environmental protection, air, water, forests, and wildlife may suffer long-term damage.","zh":"如果沒有環境保護，空氣、水、森林和野生動物可能會受到長期破壞。"},{"en":"Businesses can support environmental protection by reducing waste and choosing sustainable materials.","zh":"企業可以透過減少浪費和選擇可持續材料來支持環境保護。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"a desire to","meaning":"渴望……","examples":[{"en":"Ms Mok has expressed a desire to contribute to improving the environment.","zh":"Mok 女士表達過渴望為改善環境作出貢獻。"},{"en":"A desire to do something means a strong wish or hope to do it.","zh":"a desire to do something 指強烈希望或渴望做某事。"},{"en":"A young volunteer may have a desire to help elderly people in the community.","zh":"年輕義工可能渴望幫助社區中的長者。"},{"en":"A desire to improve something can lead people to take real action rather than only talk.","zh":"渴望改善某事可以推動人採取實際行動，而不只是空談。"},{"en":"This phrase is useful when describing motivation behind a person’s choices.","zh":"描述一個人選擇背後的動機時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"contribute to","meaning":"為……作出貢獻","examples":[{"en":"Ms Mok wants to contribute to improving the environment.","zh":"Mok 女士想為改善環境作出貢獻。"},{"en":"To contribute to something means to help bring about or support a result.","zh":"contribute to something 指幫助促成或支持某個結果。"},{"en":"Students can contribute to a cleaner school by picking up rubbish after lunch.","zh":"學生可以在午飯後撿垃圾，為更清潔的校園作出貢獻。"},{"en":"Small actions can contribute to a larger goal when many people take part.","zh":"當很多人參與，小行動可以為更大目標作出貢獻。"},{"en":"This phrase is often used when one person or action forms part of a bigger effort.","zh":"當一個人或一項行動是更大努力的一部分時，這個短語常用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"improving the environment","meaning":"改善環境","examples":[{"en":"Ms Mok hopes to contribute to improving the environment.","zh":"Mok 女士希望為改善環境作出貢獻。"},{"en":"Improving the environment means making the natural or living surroundings cleaner, safer, and healthier.","zh":"improving the environment 指令自然或生活環境更清潔、更安全和更健康。"},{"en":"Planting trees in a neighbourhood can help with improving the environment.","zh":"在社區種樹可以幫助改善環境。"},{"en":"Reducing plastic waste contributes to improving the environment because less rubbish enters landfills and the sea.","zh":"減少塑膠廢物有助改善環境，因為較少垃圾會進入堆填區和海洋。"},{"en":"Improving the environment requires long-term habits, not only one short campaign.","zh":"改善環境需要長期習慣，而不只是一場短期活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"closely align with","meaning":"與……非常一致","examples":[{"en":"Our views closely align with yours.","zh":"我們的看法與你的看法非常一致。"},{"en":"Closely align with means strongly match or agree with something.","zh":"closely align with 指與某事物高度相符或一致。"},{"en":"The charity’s goals closely align with the school’s values of service and kindness.","zh":"該慈善機構的目標與學校重視服務和善良的價值觀非常一致。"},{"en":"When two organisations’ views closely align, cooperation becomes easier and more natural.","zh":"當兩個機構的看法非常一致，合作會更容易和自然。"},{"en":"This phrase is useful when explaining why someone is a good partner or candidate.","zh":"解釋某人為何是合適伙伴或人選時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"firmly believe that","meaning":"堅信","examples":[{"en":"We firmly believe that businesses should adopt sustainable practices.","zh":"我們堅信企業應該採用可持續做法。"},{"en":"Firmly believe that means strongly and confidently think something is true or right.","zh":"firmly believe that 指強烈而有信心地認為某事是真實或正確的。"},{"en":"Many teachers firmly believe that students learn better when they receive useful feedback.","zh":"很多老師堅信學生在得到有用回饋時會學得更好。"},{"en":"When a company firmly believes in a value, it should show that value through real action.","zh":"當公司堅信某個價值觀，就應透過實際行動展示它。"},{"en":"This phrase is stronger than believe and is often used to express principles.","zh":"這個短語比 believe 語氣更強，常用來表達原則。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"businesses should adopt","meaning":"企業應該採用","examples":[{"en":"We believe that businesses should adopt sustainable practices.","zh":"我們相信企業應該採用可持續做法。"},{"en":"Businesses should adopt something means companies should start using a method, policy, or practice.","zh":"businesses should adopt something 指公司應開始使用某種方法、政策或做法。"},{"en":"Businesses should adopt clearer refund policies to protect customers.","zh":"企業應該採用更清晰的退款政策，以保障顧客。"},{"en":"When businesses adopt better practices, they can improve trust and reduce harm.","zh":"當企業採用更好的做法，就能提升信任並減少傷害。"},{"en":"This phrase is useful when giving recommendations about company behaviour.","zh":"就公司行為提出建議時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":2},{"front":"sustainable practices","meaning":"可持續做法","examples":[{"en":"Businesses should adopt sustainable practices.","zh":"企業應該採用可持續做法。"},{"en":"Sustainable practices are ways of working that reduce harm to the environment and can continue over time.","zh":"sustainable practices 指減少對環境傷害並能長期持續的工作方式。"},{"en":"A restaurant uses sustainable practices when it reduces food waste and avoids single-use plastic.","zh":"餐廳減少食物浪費並避免使用即棄塑膠時，就是採用可持續做法。"},{"en":"Sustainable practices can lower long-term costs because less energy and material are wasted.","zh":"可持續做法可以降低長期成本，因為較少能源和材料被浪費。"},{"en":"They are important because businesses affect communities, resources, and future generations.","zh":"它們很重要，因為企業會影響社區、資源和下一代。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"as our spokesperson","meaning":"作為我們的代言人","examples":[{"en":"We hope that, as our spokesperson, you will help us promote these values.","zh":"我們希望你作為我們的代言人，協助我們推廣這些價值觀。"},{"en":"As our spokesperson means in the role of representing us publicly.","zh":"as our spokesperson 指以公開代表我們的角色身份。"},{"en":"As our spokesperson, the athlete will speak about the charity’s health campaign.","zh":"作為我們的代言人，該運動員將談論慈善機構的健康活動。"},{"en":"Someone acting as a spokesperson must understand the organisation’s message clearly.","zh":"擔任代言人的人必須清楚理解機構的訊息。"},{"en":"This phrase explains the position from which a person will speak or act.","zh":"這個短語解釋一個人以甚麼身份發言或行動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"help us promote","meaning":"協助我們推廣","examples":[{"en":"We hope that you will help us promote these values.","zh":"我們希望你會協助我們推廣這些價值觀。"},{"en":"To help us promote something means to support us in making it better known or more widely accepted.","zh":"help us promote something 指支持我們令某事物更廣為人知或更被接受。"},{"en":"Teachers can help us promote reading by recommending books students enjoy.","zh":"老師可以透過推薦學生喜歡的書，協助我們推廣閱讀。"},{"en":"If respected people help promote a campaign, more people may listen and take part.","zh":"如果受尊重的人協助推廣活動，更多人可能會聆聽和參與。"},{"en":"This phrase is often used when asking someone to support a public message.","zh":"當邀請某人支持公共訊息時，這個短語常用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"these values","meaning":"這些價值觀","examples":[{"en":"We hope that Ms Mok will help us promote these values.","zh":"我們希望 Mok 女士會協助我們推廣這些價值觀。"},{"en":"These values are the beliefs or principles already mentioned, such as responsibility and sustainability.","zh":"these values 指前文已提到的信念或原則，例如責任和可持續發展。"},{"en":"A school may ask students to follow values such as respect, honesty, and care.","zh":"學校可能要求學生遵守尊重、誠實和關懷等價值觀。"},{"en":"When a company promotes its values, customers judge whether its actions match its words.","zh":"當公司推廣其價值觀，顧客會判斷它的行動是否與言語一致。"},{"en":"This phrase depends on the previous sentence, so the values must be clear from context.","zh":"這個短語依賴前一句內容，所以價值觀必須從語境中清楚可見。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"pointed out that","meaning":"指出","examples":[{"en":"You have also pointed out that recycling is becoming increasingly important.","zh":"你也指出回收在現代社會變得越來越重要。"},{"en":"Pointed out that means clearly said or drew attention to a fact or opinion.","zh":"pointed out that 指清楚說出或提醒別人注意某個事實或意見。"},{"en":"The teacher pointed out that many students forgot to write their names on the test paper.","zh":"老師指出很多學生忘記在試卷上寫姓名。"},{"en":"Pointing out a problem helps people notice something they may have ignored.","zh":"指出問題有助人們注意到他們可能忽略的事情。"},{"en":"This phrase is useful when referring to someone’s earlier comment or argument.","zh":"提及某人較早前的評論或論點時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"recycling","meaning":"回收","examples":[{"en":"Recycling is becoming increasingly important in modern society.","zh":"回收在現代社會變得越來越重要。"},{"en":"Recycling means collecting and processing used materials so they can be made into new products.","zh":"recycling 指收集和處理已使用材料，使它們可以被製成新產品。"},{"en":"Students practise recycling when they put paper, plastic bottles, and cans into separate bins.","zh":"學生把紙張、膠樽和罐放入分類回收箱時，就是在實踐回收。"},{"en":"Recycling can reduce waste because fewer materials are thrown away after one use.","zh":"回收可以減少廢物，因為較少材料會在使用一次後被丟棄。"},{"en":"It works best when people clean and sort recyclable items properly.","zh":"當人們妥善清潔和分類可回收物品時，回收效果最好。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"become increasingly important","meaning":"變得越來越重要","examples":[{"en":"Recycling is becoming increasingly important in modern society.","zh":"回收在現代社會變得越來越重要。"},{"en":"Become increasingly important means become more and more necessary or valuable over time.","zh":"become increasingly important 指隨時間變得越來越必要或有價值。"},{"en":"Digital skills are becoming increasingly important in many jobs.","zh":"數碼技能在很多工作中變得越來越重要。"},{"en":"When a problem grows, solutions related to it often become increasingly important.","zh":"當問題擴大，與之相關的解決方法通常會變得越來越重要。"},{"en":"This phrase is useful for describing trends and changes in society.","zh":"描述社會趨勢和變化時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"in modern society","meaning":"在現代社會","examples":[{"en":"Recycling is becoming increasingly important in modern society.","zh":"回收在現代社會變得越來越重要。"},{"en":"In modern society means in today’s world, with current lifestyles, technology, and social needs.","zh":"in modern society 指在今天的世界中，包括現時生活方式、科技和社會需要。"},{"en":"In modern society, people often rely on phones for work, study, and transport.","zh":"在現代社會，人們常依賴手機工作、學習和乘搭交通工具。"},{"en":"Problems in modern society can spread quickly because people and systems are closely connected.","zh":"現代社會的問題可能迅速擴散，因為人和系統緊密相連。"},{"en":"This phrase is useful when discussing present-day issues and habits.","zh":"討論當代議題和習慣時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"a view we fully share","meaning":"我們完全認同的觀點","examples":[{"en":"Recycling is important, a view we fully share.","zh":"回收很重要，這是我們完全認同的觀點。"},{"en":"A view we fully share means an opinion that we completely agree with.","zh":"a view we fully share 指我們完全同意的意見。"},{"en":"You believe students need enough rest, a view we fully share.","zh":"你認為學生需要足夠休息，這是我們完全認同的觀點。"},{"en":"Saying a view is fully shared helps show agreement before presenting related actions.","zh":"說明完全認同某個觀點，有助在提出相關行動前展示共識。"},{"en":"This phrase is formal and useful in letters when building a connection with the receiver.","zh":"這個短語較正式，在信件中建立與收信人的連繫時很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"In fact","meaning":"事實上","examples":[{"en":"In fact, GC Hotel uses recycled fabrics as wallpaper.","zh":"事實上，GC Hotel 使用回收布料作為牆紙。"},{"en":"In fact is used to add a true detail that supports, explains, or strengthens the previous point.","zh":"In fact 用來加入真實細節，以支持、解釋或加強前一點。"},{"en":"The shop says it is eco-friendly; in fact, it uses solar power and recycled bags.","zh":"這間商店說自己環保；事實上，它使用太陽能和回收袋。"},{"en":"This phrase helps move from a general claim to a specific fact.","zh":"這個短語幫助從一般說法轉到具體事實。"},{"en":"It is useful when the writer wants to prove that a statement is not just empty words.","zh":"當作者想證明某說法不是空話時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"recycled fabrics","meaning":"回收布料","examples":[{"en":"GC Hotel uses recycled fabrics as wallpaper.","zh":"GC Hotel 使用回收布料作為牆紙。"},{"en":"Recycled fabrics are cloth materials made from used or recovered textiles instead of completely new resources.","zh":"recycled fabrics 指由已使用或回收紡織品製成，而非完全使用新資源的布料。"},{"en":"A fashion brand may use recycled fabrics to make bags, jackets, or curtains.","zh":"時裝品牌可能使用回收布料製作袋、外套或窗簾。"},{"en":"Using recycled fabrics can reduce waste because old materials are given a new purpose.","zh":"使用回收布料可以減少浪費，因為舊材料被賦予新用途。"},{"en":"This phrase is often used when discussing sustainable design and production.","zh":"討論可持續設計和生產時，這個短語常用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":3},{"front":"as wallpaper","meaning":"作為牆紙","examples":[{"en":"GC Hotel uses recycled fabrics as wallpaper.","zh":"GC Hotel 使用回收布料作為牆紙。"},{"en":"As wallpaper means used to cover or decorate walls.","zh":"as wallpaper 指用來覆蓋或裝飾牆壁。"},{"en":"A café may use old newspaper pages as wallpaper to create a vintage style.","zh":"咖啡店可能使用舊報紙頁作為牆紙，營造復古風格。"},{"en":"Using recycled material as wallpaper can make decoration both attractive and environmentally friendly.","zh":"使用回收材料作為牆紙，可以令裝飾既吸引又環保。"},{"en":"This phrase explains the function or purpose of the material.","zh":"這個短語解釋材料的功能或用途。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"we would be most grateful if","meaning":"如你能……，我們將非常感激","examples":[{"en":"We would be most grateful if you could help promote this initiative.","zh":"如你能協助推廣這項措施，我們將非常感激。"},{"en":"We would be most grateful if is a very polite way to make an important request.","zh":"We would be most grateful if 是非常有禮地提出重要請求的說法。"},{"en":"We would be most grateful if you could confirm your attendance by Friday.","zh":"如你能在星期五前確認出席，我們將非常感激。"},{"en":"This phrase shows respect and makes the request sound less forceful.","zh":"這個短語顯示尊重，並令請求聽起來較不強硬。"},{"en":"It is common in formal letters when asking for help, cooperation, or a reply.","zh":"在正式信件中請求協助、合作或回覆時，它很常見。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"help promote this initiative","meaning":"協助推廣這項措施","examples":[{"en":"We would be most grateful if you could help promote this initiative.","zh":"如你能協助推廣這項措施，我們將非常感激。"},{"en":"To help promote this initiative means to support and publicise this planned action or project.","zh":"help promote this initiative 指支持並宣傳這項計劃或行動。"},{"en":"Students can help promote a recycling initiative by making posters and explaining the rules.","zh":"學生可以透過製作海報和解釋規則，協助推廣回收措施。"},{"en":"If a well-known person helps promote an initiative, more people may notice and support it.","zh":"如果知名人士協助推廣一項措施，更多人可能會注意並支持它。"},{"en":"This phrase is useful when asking someone to help spread a message.","zh":"當請求某人幫助傳播訊息時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"this initiative","meaning":"這項措施","examples":[{"en":"GC Hotel would like Ms Mok to promote this initiative.","zh":"GC Hotel 希望 Mok 女士推廣這項措施。"},{"en":"This initiative means the specific plan, project, or action already mentioned.","zh":"this initiative 指前文已提到的具體計劃、項目或行動。"},{"en":"A school’s healthy lunch initiative may encourage students to eat more fruit and vegetables.","zh":"學校的健康午餐措施可能鼓勵學生多吃水果和蔬菜。"},{"en":"An initiative becomes more effective when people understand its purpose and know how to take part.","zh":"當人們理解措施目的並知道如何參與，措施會更有效。"},{"en":"This phrase depends on context, so the writer should make clear which initiative is meant.","zh":"這個短語依賴語境，所以作者應清楚說明指哪項措施。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"emphasised that","meaning":"強調","examples":[{"en":"You have emphasised that businesses should take greater responsibility.","zh":"你強調企業應該承擔更大責任。"},{"en":"Emphasised that means strongly stated or gave special importance to a point.","zh":"emphasised that 指強烈指出或特別重視某一點。"},{"en":"The coach emphasised that teamwork was more important than individual scores.","zh":"教練強調團隊合作比個人分數更重要。"},{"en":"When someone emphasises an issue, they want others to pay serious attention to it.","zh":"當某人強調某議題，他們希望其他人認真注意它。"},{"en":"This phrase is useful when referring to a point someone has highlighted before.","zh":"提及某人之前特別突出的重點時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"across different sectors","meaning":"跨不同行業","examples":[{"en":"Businesses across different sectors should take greater responsibility.","zh":"跨不同行業的企業應該承擔更大責任。"},{"en":"Across different sectors means in many different industries or areas of work.","zh":"across different sectors 指在許多不同產業或工作範疇中。"},{"en":"Companies across different sectors, from transport to retail, are using digital payment systems.","zh":"從交通到零售，跨不同行業的公司都在使用電子支付系統。"},{"en":"If businesses across different sectors act together, social change can happen more quickly.","zh":"如果跨不同行業的企業一起行動，社會改變可以更快發生。"},{"en":"This phrase is useful when a point applies beyond one single industry.","zh":"當某一點不只適用於單一行業時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"take greater responsibility in","meaning":"在……方面承擔更大責任","examples":[{"en":"Businesses should take greater responsibility in addressing deforestation.","zh":"企業應該在應對森林砍伐問題方面承擔更大責任。"},{"en":"To take greater responsibility in something means to accept a bigger duty to help solve or manage it.","zh":"take greater responsibility in something 指接受更大責任去協助解決或管理某事。"},{"en":"Schools should take greater responsibility in protecting students’ mental health.","zh":"學校應在保護學生心理健康方面承擔更大責任。"},{"en":"When organisations take greater responsibility, they stop treating problems as someone else’s job.","zh":"當機構承擔更大責任，它們就不再把問題視為別人的工作。"},{"en":"This phrase is useful when asking powerful groups to do more.","zh":"當要求有權力的群體做更多時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"addressing deforestation","meaning":"應對森林砍伐問題","examples":[{"en":"Businesses should take greater responsibility in addressing deforestation.","zh":"企業應該在應對森林砍伐問題方面承擔更大責任。"},{"en":"Addressing deforestation means dealing with the problem of forests being cut down or destroyed.","zh":"addressing deforestation 指處理森林被砍伐或破壞的問題。"},{"en":"Companies can help address deforestation by buying paper from responsible sources.","zh":"公司可以透過購買來自負責任來源的紙張，協助應對森林砍伐問題。"},{"en":"If deforestation is not addressed, wildlife habitats and climate stability may be harmed.","zh":"如果森林砍伐問題沒有被應對，野生動物棲息地和氣候穩定可能受害。"},{"en":"This phrase focuses on solving the problem, not only describing it.","zh":"這個短語聚焦於解決問題，而不只是描述問題。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"deforestation","meaning":"森林砍伐","examples":[{"en":"GC Hotel wants to help address deforestation.","zh":"GC Hotel 想協助應對森林砍伐問題。"},{"en":"Deforestation is the cutting down or clearing of forests, often for farming, building, or business use.","zh":"deforestation 指砍伐或清除森林，通常是為了農業、建築或商業用途。"},{"en":"Deforestation can happen when land is cleared to produce palm oil, beef, or timber.","zh":"當土地被清理用作生產棕櫚油、牛肉或木材時，可能出現森林砍伐。"},{"en":"Large-scale deforestation can destroy habitats and reduce the planet’s ability to absorb carbon dioxide.","zh":"大規模森林砍伐會破壞棲息地，並降低地球吸收二氧化碳的能力。"},{"en":"Reducing deforestation requires responsible buying, stronger rules, and forest protection.","zh":"減少森林砍伐需要負責任採購、更嚴格規則和森林保護。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"agree with your perspective","meaning":"認同你的觀點","examples":[{"en":"We agree with your perspective on forest conservation.","zh":"我們認同你對森林保育的觀點。"},{"en":"To agree with your perspective means to share your way of seeing or understanding an issue.","zh":"agree with your perspective 指認同你看待或理解某議題的方式。"},{"en":"The committee agrees with your perspective that student safety should come first.","zh":"委員會認同你認為學生安全應優先的觀點。"},{"en":"When people agree with someone’s perspective, cooperation becomes easier because they share the same basic view.","zh":"當人們認同某人的觀點，合作會更容易，因為他們有相同基本看法。"},{"en":"This phrase is more thoughtful than simply saying we agree with you.","zh":"這個短語比簡單說 we agree with you 更有思考感。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"be currently collaborating with","meaning":"目前正與……合作","examples":[{"en":"GC Hotel is currently collaborating with five celebrities.","zh":"GC Hotel 目前正與五位名人合作。"},{"en":"Be currently collaborating with means be working together with someone at the present time.","zh":"be currently collaborating with 指現在正與某人合作。"},{"en":"The school is currently collaborating with a local museum on a history project.","zh":"學校目前正與本地博物館合作進行歷史項目。"},{"en":"When organisations collaborate, they can share resources, ideas, and public attention.","zh":"當機構合作，它們可以共享資源、想法和公眾關注。"},{"en":"This phrase is useful when describing an active partnership.","zh":"描述正在進行的伙伴關係時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":4},{"front":"five celebrities","meaning":"五位名人","examples":[{"en":"GC Hotel is collaborating with five celebrities to promote forest conservation.","zh":"GC Hotel 正與五位名人合作推廣森林保育。"},{"en":"Five celebrities means five famous public figures, such as actors, singers, athletes, or media personalities.","zh":"five celebrities 指五位著名公眾人物，例如演員、歌手、運動員或媒體人物。"},{"en":"A charity may invite five celebrities to attract more attention to a fundraising event.","zh":"慈善機構可能邀請五位名人，為籌款活動吸引更多注意。"},{"en":"When celebrities support a cause, their followers may become more aware of the issue.","zh":"當名人支持某個議題，他們的追隨者可能更關注該問題。"},{"en":"However, celebrity support works best when the message is sincere and well explained.","zh":"不過，名人支持在訊息真誠而解釋清楚時效果最好。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"promote forest conservation","meaning":"推廣森林保育","examples":[{"en":"The hotel is working with celebrities to promote forest conservation.","zh":"酒店正與名人合作推廣森林保育。"},{"en":"To promote forest conservation means to encourage people to protect forests and use forest resources responsibly.","zh":"promote forest conservation 指鼓勵人們保護森林並負責任地使用森林資源。"},{"en":"Schools can promote forest conservation by teaching students why trees and habitats matter.","zh":"學校可以透過教學生樹木和棲息地的重要性來推廣森林保育。"},{"en":"Promoting forest conservation can reduce public support for products linked to deforestation.","zh":"推廣森林保育可以減少公眾對與森林砍伐有關產品的支持。"},{"en":"This phrase is often used in environmental campaigns.","zh":"這個短語常用於環保活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"forest conservation","meaning":"森林保育","examples":[{"en":"GC Hotel supports forest conservation.","zh":"GC Hotel 支持森林保育。"},{"en":"Forest conservation means protecting forests so trees, animals, water systems, and local communities can survive.","zh":"forest conservation 指保護森林，使樹木、動物、水系統和本地社區能夠存續。"},{"en":"Forest conservation may include planting trees, stopping illegal logging, and protecting wildlife habitats.","zh":"森林保育可以包括種樹、阻止非法伐木和保護野生動物棲息地。"},{"en":"Without forest conservation, soil, rivers, climate, and biodiversity can be damaged.","zh":"如果沒有森林保育，土壤、河流、氣候和生物多樣性都可能受損。"},{"en":"It is important because forests support both nature and human life.","zh":"它很重要，因為森林支撐自然和人類生活。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"Regarding","meaning":"關於","examples":[{"en":"Regarding the opening ceremony, you will be invited to deliver a speech.","zh":"關於開幕典禮，你將獲邀發表演講。"},{"en":"Regarding means about or concerning a particular topic.","zh":"Regarding 指關於或涉及某個特定話題。"},{"en":"Regarding the school trip, parents will receive the final details tomorrow.","zh":"關於學校旅行，家長明天會收到最終詳情。"},{"en":"This word helps introduce a new section in a formal letter or email.","zh":"這個字有助在正式信件或電郵中引出新部分。"},{"en":"It is more formal than about and is common in business communication.","zh":"它比 about 更正式，常見於商業溝通。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"be invited to deliver a speech","meaning":"獲邀發表演講","examples":[{"en":"You will be invited to deliver a speech at the opening ceremony.","zh":"你將獲邀在開幕典禮上發表演講。"},{"en":"Be invited to deliver a speech means be formally asked to give a talk at an event.","zh":"be invited to deliver a speech 指被正式邀請在活動中演講。"},{"en":"A graduate may be invited to deliver a speech at the school’s careers day.","zh":"畢業生可能獲邀在學校職業日發表演講。"},{"en":"Being invited to speak shows that the organiser respects the speaker’s experience or public image.","zh":"獲邀演講顯示主辦方尊重講者的經驗或公眾形象。"},{"en":"This phrase is suitable for formal invitations and event arrangements.","zh":"這個短語適合用於正式邀請和活動安排。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"deliver a speech on","meaning":"就……發表演講","examples":[{"en":"Ms Mok will deliver a speech on the company’s values.","zh":"Mok 女士將就公司的價值觀發表演講。"},{"en":"To deliver a speech on a topic means to give a formal talk about that topic.","zh":"deliver a speech on a topic 指就某個題目作正式演講。"},{"en":"The student leader will deliver a speech on school service and responsibility.","zh":"學生領袖將就學校服務和責任發表演講。"},{"en":"A speech on a clear topic helps the audience know what to listen for.","zh":"有清晰主題的演講能幫助觀眾知道要聆聽甚麼。"},{"en":"This phrase is more formal than talk about.","zh":"這個短語比 talk about 更正式。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"our company’s values","meaning":"我們公司的價值觀","examples":[{"en":"You will be invited to deliver a speech on our company’s values.","zh":"你將獲邀就我們公司的價值觀發表演講。"},{"en":"Our company’s values are the beliefs and principles that guide how the company behaves.","zh":"our company’s values 指引導公司行為的信念和原則。"},{"en":"A company’s values may include honesty, sustainability, service, and respect for customers.","zh":"公司的價值觀可能包括誠信、可持續發展、服務和尊重顧客。"},{"en":"If a company’s actions do not match its values, people may lose trust in it.","zh":"如果公司的行動與其價值觀不一致，人們可能會失去信任。"},{"en":"This phrase is useful when explaining what a business stands for.","zh":"解釋企業代表甚麼時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"advocacy work","meaning":"倡議工作","examples":[{"en":"Ms Mok will speak about her advocacy work.","zh":"Mok 女士將談及她的倡議工作。"},{"en":"Advocacy work means activities that support, speak up for, or campaign for a cause or group.","zh":"advocacy work 指支持、發聲或推動某個議題或群體的活動。"},{"en":"A social worker may do advocacy work for children who need better protection.","zh":"社工可以為需要更好保護的兒童進行倡議工作。"},{"en":"Advocacy work can change public attitudes because it gives a voice to important issues.","zh":"倡議工作可以改變公眾態度，因為它為重要議題發聲。"},{"en":"This phrase is often used for human rights, health, education, and environmental campaigns.","zh":"這個短語常用於人權、健康、教育和環保活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"as a token of our appreciation","meaning":"為表謝意","examples":[{"en":"As a token of our appreciation, you are welcome to enjoy a complimentary dinner.","zh":"為表謝意，歡迎你享用免費晚餐。"},{"en":"As a token of our appreciation means as a small sign showing our thanks.","zh":"as a token of our appreciation 指作為表達謝意的小小表示。"},{"en":"The school gave volunteers a certificate as a token of its appreciation.","zh":"學校向義工頒發證書，以表謝意。"},{"en":"A token of appreciation does not repay everything, but it shows gratitude politely.","zh":"謝意表示不能完全回報一切，但能有禮地表達感激。"},{"en":"This phrase is formal and often used before offering a gift, meal, or benefit.","zh":"這個短語較正式，常用於提供禮物、餐膳或福利之前。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"be welcome to","meaning":"歡迎……","examples":[{"en":"You are welcome to enjoy a complimentary dinner with other guests.","zh":"歡迎你與其他嘉賓一起享用免費晚餐。"},{"en":"Be welcome to means be invited or allowed to do something freely and politely.","zh":"be welcome to 指被禮貌邀請或允許自由做某事。"},{"en":"Visitors are welcome to ask staff for help at any time.","zh":"歡迎訪客隨時向職員求助。"},{"en":"This phrase makes the receiver feel comfortable about accepting an offer.","zh":"這個短語令收信人覺得接受提議是自然和舒服的。"},{"en":"It is useful when offering hospitality, assistance, or permission.","zh":"提供款待、協助或許可時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"enjoy a complimentary dinner","meaning":"享用免費晚餐","examples":[{"en":"You are welcome to enjoy a complimentary dinner with other guests.","zh":"歡迎你與其他嘉賓一起享用免費晚餐。"},{"en":"To enjoy a complimentary dinner means to have a free meal provided by the organiser or host.","zh":"enjoy a complimentary dinner 指享用由主辦方或主人提供的免費餐膳。"},{"en":"Speakers at the conference were invited to enjoy a complimentary dinner after the event.","zh":"會議講者獲邀在活動後享用免費晚餐。"},{"en":"Offering a complimentary dinner can make guests feel respected and appreciated.","zh":"提供免費晚餐可以令嘉賓感到受尊重和被感謝。"},{"en":"This phrase is common in formal invitations to events, hotels, and ceremonies.","zh":"這個短語常見於活動、酒店和典禮的正式邀請。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":5},{"front":"complimentary dinner","meaning":"免費晚餐","examples":[{"en":"A complimentary dinner will be offered to Ms Mok.","zh":"Mok 女士將獲提供免費晚餐。"},{"en":"A complimentary dinner is a dinner provided free of charge, usually as a courtesy or thank-you gesture.","zh":"complimentary dinner 指免費提供的晚餐，通常作為禮貌或謝意表示。"},{"en":"The hotel offered a complimentary dinner to guests whose rooms were delayed.","zh":"酒店向房間延遲入住的客人提供免費晚餐。"},{"en":"A complimentary dinner can help create a positive impression of hospitality.","zh":"免費晚餐有助營造款待周到的正面印象。"},{"en":"Complimentary means free in this context, not full of compliments.","zh":"complimentary 在此語境中解作免費，不是充滿讚美。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"with other guests","meaning":"與其他嘉賓一起","examples":[{"en":"Ms Mok may enjoy a complimentary dinner with other guests.","zh":"Mok 女士可以與其他嘉賓一起享用免費晚餐。"},{"en":"With other guests means together with other invited people at the event.","zh":"with other guests 指與活動中的其他受邀人士一起。"},{"en":"The speaker sat with other guests during the school banquet.","zh":"講者在學校宴會中與其他嘉賓一起就座。"},{"en":"Sharing a meal with other guests can create chances for conversation and networking.","zh":"與其他嘉賓一起用餐可以創造交談和建立聯繫的機會。"},{"en":"This phrase clarifies that the person will not be dining alone.","zh":"這個短語說明該人不會獨自用餐。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"In addition","meaning":"此外","examples":[{"en":"In addition, a limousine service will be provided upon request.","zh":"此外，豪華轎車接送服務可按要求提供。"},{"en":"In addition is used to add another point to what has already been said.","zh":"In addition 用來補充前面已經說過的內容。"},{"en":"The event provides lunch; in addition, transport will be arranged for guests.","zh":"活動提供午餐；此外，也會為嘉賓安排交通。"},{"en":"This phrase helps organise several details in a formal letter.","zh":"這個短語有助在正式信件中整理多項詳情。"},{"en":"It is more formal than also and is useful in business writing.","zh":"它比 also 更正式，適合商業寫作。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"limousine service","meaning":"豪華轎車接送服務","examples":[{"en":"A limousine service will be provided upon request.","zh":"豪華轎車接送服務可按要求提供。"},{"en":"Limousine service means transport in a luxury car, usually arranged for special guests or formal occasions.","zh":"limousine service 指豪華轎車交通服務，通常為特別嘉賓或正式場合安排。"},{"en":"The hotel offers limousine service for VIP guests arriving from the airport.","zh":"酒店為從機場抵達的貴賓提供豪華轎車接送服務。"},{"en":"A limousine service can make travel more comfortable and convenient for important guests.","zh":"豪華轎車接送服務可以令重要嘉賓的交通更舒適方便。"},{"en":"This phrase is often used in hotels, corporate events, and formal ceremonies.","zh":"這個短語常用於酒店、企業活動和正式典禮。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"be provided upon request","meaning":"可按要求提供","examples":[{"en":"A limousine service will be provided upon request.","zh":"豪華轎車接送服務可按要求提供。"},{"en":"Be provided upon request means it will be given or arranged if someone asks for it.","zh":"be provided upon request 指如果有人提出要求，便會提供或安排。"},{"en":"Extra copies of the report can be provided upon request.","zh":"額外報告副本可按要求提供。"},{"en":"This phrase lets people know a service is available, but not automatic.","zh":"這個短語讓人知道服務可用，但不是自動提供。"},{"en":"It is common in formal notices, hotel services, and business communication.","zh":"它常見於正式通知、酒店服務和商業溝通。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"for your convenience","meaning":"方便你","examples":[{"en":"A limousine service will be provided for your convenience.","zh":"為方便你，我們將提供豪華轎車接送服務。"},{"en":"For your convenience means to make something easier, more comfortable, or less troublesome for you.","zh":"for your convenience 指為了令你更容易、更舒服或更少麻煩。"},{"en":"For your convenience, the application form is available online.","zh":"為方便你，申請表可在網上下載。"},{"en":"Providing transport for guests can reduce stress and make arrival easier.","zh":"為嘉賓提供交通可以減少壓力，令抵達更容易。"},{"en":"This phrase is polite and often used when offering helpful arrangements.","zh":"這個短語有禮，常用於提供便利安排時。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"sincerely believe that","meaning":"我們真誠相信","examples":[{"en":"We sincerely believe that you are the most suitable candidate.","zh":"我們真誠相信你是最合適的人選。"},{"en":"Sincerely believe that means honestly and genuinely think something is true.","zh":"sincerely believe that 指真心而誠懇地認為某事是真實的。"},{"en":"The teachers sincerely believe that every student can improve with the right support.","zh":"老師們真誠相信，每個學生在適當支援下都可以進步。"},{"en":"This phrase makes an opinion sound warm, serious, and honest.","zh":"這個短語令意見聽起來溫和、認真而真誠。"},{"en":"It is useful in formal letters when praising someone or explaining a decision.","zh":"在正式信件中稱讚某人或解釋決定時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"the most suitable candidate","meaning":"最合適的人選","examples":[{"en":"Ms Mok is the most suitable candidate for the role.","zh":"Mok 女士是擔任該角色的最合適人選。"},{"en":"The most suitable candidate is the person who best fits the requirements of a role or task.","zh":"the most suitable candidate 指最符合某角色或任務要求的人。"},{"en":"A student with strong leadership and speaking skills may be the most suitable candidate for class representative.","zh":"具備強領導能力和演說技巧的學生，可能是班代表的最合適人選。"},{"en":"Choosing the most suitable candidate helps an organisation avoid mismatch and poor performance.","zh":"選擇最合適的人選，有助機構避免人選不配和表現欠佳。"},{"en":"This phrase is often used in recruitment, nominations, and formal invitations.","zh":"這個短語常用於招聘、提名和正式邀請。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"for the role of","meaning":"擔任……一職","examples":[{"en":"Ms Mok is the most suitable candidate for the role of spokesperson.","zh":"Mok 女士是擔任代言人一職的最合適人選。"},{"en":"For the role of means for the position or duty of being a particular person in an organisation or event.","zh":"for the role of 指擔任某個組織或活動中的職位或職責。"},{"en":"The school chose Anna for the role of student ambassador.","zh":"學校選擇 Anna 擔任學生大使一職。"},{"en":"When selecting someone for a role, organisers consider skills, image, and responsibility.","zh":"選擇某人擔任一職時，籌辦者會考慮技能、形象和責任。"},{"en":"This phrase is formal and often appears in job, event, and invitation contexts.","zh":"這個短語較正式，常出現在工作、活動和邀請語境中。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"spokesperson for","meaning":"……的代言人","examples":[{"en":"Ms Mok is invited to be the spokesperson for GC Hotel.","zh":"Mok 女士獲邀成為 GC Hotel 的代言人。"},{"en":"A spokesperson for an organisation is a person who speaks publicly on its behalf.","zh":"spokesperson for an organisation 指代表某機構公開發言的人。"},{"en":"A doctor may become the spokesperson for a public health campaign.","zh":"醫生可以成為公共健康活動的代言人。"},{"en":"A spokesperson affects how the public understands and trusts an organisation.","zh":"代言人會影響公眾如何理解和信任一個機構。"},{"en":"This phrase is useful when describing a representative role.","zh":"描述代表角色時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"Should you have any enquiries","meaning":"如你有任何查詢","examples":[{"en":"Should you have any enquiries, please do not hesitate to contact us.","zh":"如你有任何查詢，請隨時與我們聯絡。"},{"en":"Should you have any enquiries means if you have any questions.","zh":"Should you have any enquiries 指如果你有任何問題。"},{"en":"Should you have any enquiries about the event schedule, please contact the organiser.","zh":"如你有任何關於活動時間表的查詢，請聯絡主辦方。"},{"en":"This phrase makes the writer sound helpful and open to further communication.","zh":"這個短語令作者聽起來樂意幫忙，並願意進一步溝通。"},{"en":"It is formal and commonly used near the end of business letters.","zh":"它較正式，常用於商業信件結尾部分。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":6},{"front":"please do not hesitate to contact us","meaning":"請隨時與我們聯絡","examples":[{"en":"Should you have any enquiries, please do not hesitate to contact us.","zh":"如你有任何查詢，請隨時與我們聯絡。"},{"en":"Please do not hesitate to contact us means please feel free to get in touch with us.","zh":"please do not hesitate to contact us 指請放心與我們聯絡。"},{"en":"Please do not hesitate to contact us if you need another copy of the programme.","zh":"如你需要另一份場刊副本，請隨時與我們聯絡。"},{"en":"This phrase encourages the receiver to ask questions without feeling troublesome.","zh":"這個短語鼓勵收信人提問，而不會覺得麻煩。"},{"en":"It is a polite closing phrase in formal emails and business letters.","zh":"它是正式電郵和商業信件中有禮的結尾用語。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"more than happy to","meaning":"非常樂意","examples":[{"en":"We would be more than happy to provide further information.","zh":"我們非常樂意提供進一步資料。"},{"en":"More than happy to means very willing to do something.","zh":"more than happy to 指非常願意做某事。"},{"en":"The hotel staff are more than happy to help guests arrange transport.","zh":"酒店職員非常樂意協助客人安排交通。"},{"en":"This phrase creates a friendly tone and shows the writer is willing to cooperate.","zh":"這個短語營造友善語氣，並顯示作者願意合作。"},{"en":"It is useful when offering help after giving an invitation or request.","zh":"在發出邀請或請求後表示願意協助時，它很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"provide further information","meaning":"提供進一步資料","examples":[{"en":"We would be more than happy to provide further information.","zh":"我們非常樂意提供進一步資料。"},{"en":"To provide further information means to give extra details beyond what has already been said.","zh":"provide further information 指在已說明的內容以外提供額外詳情。"},{"en":"The organiser can provide further information about the dress code and parking arrangements.","zh":"主辦方可以提供關於服裝要求和泊車安排的進一步資料。"},{"en":"Providing further information helps answer questions and prevent misunderstanding.","zh":"提供進一步資料有助回答問題和避免誤解。"},{"en":"This phrase is common when the writer is willing to explain more if needed.","zh":"當作者願意在需要時作更多解釋，這個短語很常見。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"Thank you very much for your attention","meaning":"感謝你的關注","examples":[{"en":"Thank you very much for your attention.","zh":"感謝你的關注。"},{"en":"Thank you very much for your attention is a polite closing sentence that thanks the reader for reading and considering the matter.","zh":"Thank you very much for your attention 是有禮的結尾句，用來感謝讀者閱讀並考慮有關事項。"},{"en":"A speaker may say thank you very much for your attention at the end of a presentation.","zh":"講者可以在簡報結尾說 thank you very much for your attention。"},{"en":"This sentence helps end a formal message respectfully.","zh":"這句話有助以尊重語氣結束正式訊息。"},{"en":"It is especially useful when the writer has made an invitation or request.","zh":"當作者提出邀請或請求時，這句話尤其有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"look forward to","meaning":"期待","examples":[{"en":"We look forward to your favourable reply.","zh":"我們期待你的正面回覆。"},{"en":"To look forward to something means to wait for it with interest, hope, or expectation.","zh":"look forward to something 指帶著興趣、希望或期待等待某事。"},{"en":"Students look forward to the school picnic after finishing their exams.","zh":"學生完成考試後，期待學校旅行。"},{"en":"In formal letters, look forward to is often used to show that the writer expects a reply.","zh":"在正式信件中，look forward to 常用來表示作者期待回覆。"},{"en":"This phrase should be followed by a noun or an -ing verb.","zh":"這個短語後面應接名詞或 -ing 動詞。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"your favourable reply","meaning":"你的正面回覆","examples":[{"en":"We look forward to your favourable reply.","zh":"我們期待你的正面回覆。"},{"en":"Your favourable reply means a positive or helpful response from the receiver.","zh":"your favourable reply 指收信人作出的正面或有幫助的回覆。"},{"en":"An organisation may write that it looks forward to a favourable reply after inviting a guest speaker.","zh":"機構邀請嘉賓講者後，可能會寫期待對方的正面回覆。"},{"en":"Asking for a favourable reply shows hope that the receiver will accept or support the request.","zh":"期待正面回覆顯示作者希望收信人接受或支持其請求。"},{"en":"This phrase is formal and often appears near the end of invitation or application letters.","zh":"這個短語較正式，常出現在邀請信或申請信結尾附近。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"Yours sincerely, Jannie Tang.","zh":"Jannie Tang 謹啟。"},{"en":"Yours sincerely is a formal closing used when the writer knows the receiver’s name.","zh":"Yours sincerely 是當作者知道收信人姓名時使用的正式結尾語。"},{"en":"A letter that begins with Dear Ms Mok can end with Yours sincerely.","zh":"以 Dear Ms Mok 開始的信件可以用 Yours sincerely 結尾。"},{"en":"Using the correct closing makes a formal letter look professional and complete.","zh":"使用正確結尾語能令正式信件看起來專業而完整。"},{"en":"If the letter begins with Dear Sir/Madam, Yours faithfully is usually more appropriate.","zh":"如果信件以 Dear Sir/Madam 開首，通常較適合使用 Yours faithfully。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"Marketing Department","meaning":"市場部","examples":[{"en":"Jannie Tang writes from the Marketing Department of GC Hotel.","zh":"Jannie Tang 來自 GC Hotel 市場部寫信。"},{"en":"A Marketing Department is the part of a company responsible for promotion, branding, advertising, and public communication.","zh":"Marketing Department 指公司中負責推廣、品牌、廣告和公共溝通的部門。"},{"en":"The Marketing Department may design posters, manage social media, and contact the press.","zh":"市場部可能設計海報、管理社交媒體和聯絡傳媒。"},{"en":"A strong Marketing Department can help a hotel reach more customers and build a better image.","zh":"強大的市場部可以幫助酒店接觸更多顧客並建立更好形象。"},{"en":"This phrase is useful when identifying the sender’s role or office.","zh":"說明寄件人的角色或部門時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"write from","meaning":"來自……寫信","examples":[{"en":"Jannie Tang writes from the Marketing Department of GC Hotel.","zh":"Jannie Tang 來自 GC Hotel 市場部寫信。"},{"en":"Write from means send a letter or message as a person connected to a particular place, department, or organisation.","zh":"write from 指以與某地方、部門或機構有關的人士身份發出信件或訊息。"},{"en":"The teacher writes from the English Department to invite parents to a reading workshop.","zh":"老師來自英文科寫信，邀請家長參加閱讀工作坊。"},{"en":"Writing from a department shows the message is official and related to that office’s work.","zh":"來自某部門寫信顯示訊息是正式的，並與該部門工作有關。"},{"en":"This phrase is useful when the sender’s organisational position matters.","zh":"當寄件人在機構中的身份很重要時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"formal invitation","meaning":"正式邀請","examples":[{"en":"The letter is a formal invitation to serve as a spokesperson.","zh":"這封信是邀請擔任代言人的正式邀請。"},{"en":"A formal invitation is a polite official request asking someone to attend an event or accept a role.","zh":"formal invitation 指禮貌而正式地邀請某人出席活動或接受角色。"},{"en":"A university may send a formal invitation to a professor to speak at a ceremony.","zh":"大學可能向教授發出正式邀請，邀請其在典禮上演講。"},{"en":"A formal invitation should clearly state the role, event details, and reason for inviting the person.","zh":"正式邀請應清楚說明角色、活動詳情和邀請原因。"},{"en":"It uses respectful language because the receiver is being treated as an important guest or partner.","zh":"它使用尊重語氣，因為收信人被視為重要嘉賓或伙伴。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"company values","meaning":"公司價值觀","examples":[{"en":"The speech will focus on the hotel’s company values.","zh":"演講將集中於酒店的公司價值觀。"},{"en":"Company values are the beliefs and principles that guide how a company makes decisions and treats people.","zh":"company values 指引導公司如何決策和待人的信念與原則。"},{"en":"A company’s values may include honesty, service, environmental care, and respect for staff.","zh":"公司的價值觀可能包括誠信、服務、環境關懷和尊重員工。"},{"en":"If company values are real, customers should be able to see them in daily business actions.","zh":"如果公司價值觀是真實的，顧客應能在日常商業行動中看見它們。"},{"en":"This phrase is useful when discussing brand identity and organisational behaviour.","zh":"討論品牌身份和機構行為時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":7},{"front":"environmental values","meaning":"環保價值觀","examples":[{"en":"GC Hotel hopes Ms Mok will promote its environmental values.","zh":"GC Hotel 希望 Mok 女士推廣其環保價值觀。"},{"en":"Environmental values are beliefs about protecting nature, reducing waste, and using resources responsibly.","zh":"environmental values 指關於保護自然、減少浪費和負責任使用資源的信念。"},{"en":"A school shows environmental values when it saves energy and teaches students to recycle.","zh":"學校節約能源並教學生回收時，就是展示環保價值觀。"},{"en":"If a company promotes environmental values but wastes resources, people may doubt its honesty.","zh":"如果公司推廣環保價值觀卻浪費資源，人們可能會懷疑其誠信。"},{"en":"This phrase is useful when linking public image with environmental responsibility.","zh":"把公眾形象與環境責任連繫起來時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":8},{"front":"public image","meaning":"公眾形象","examples":[{"en":"A spokesperson can help promote the hotel’s public image.","zh":"代言人可以協助推廣酒店的公眾形象。"},{"en":"Public image is the way the public sees and judges a person, company, or organisation.","zh":"public image 指公眾如何看待和評價某人、公司或機構。"},{"en":"A company’s public image can improve when it treats customers fairly and responds to problems quickly.","zh":"當公司公平對待顧客並快速回應問題，其公眾形象可以改善。"},{"en":"Bad service can damage public image because people share negative experiences with others.","zh":"差劣服務會損害公眾形象，因為人們會把負面經驗告訴他人。"},{"en":"This phrase is common in marketing, branding, and public relations.","zh":"這個短語常見於市場推廣、品牌和公關。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":8},{"front":"opening-ceremony details","meaning":"開幕典禮詳情","examples":[{"en":"The letter provides the opening-ceremony details.","zh":"這封信提供開幕典禮詳情。"},{"en":"Opening-ceremony details are the specific facts about an opening event, such as date, time, venue, programme, and guest arrangements.","zh":"opening-ceremony details 指關於開幕活動的具體資料，例如日期、時間、地點、流程和嘉賓安排。"},{"en":"Guests should check the opening-ceremony details before deciding when to arrive.","zh":"嘉賓應在決定何時到達前查看開幕典禮詳情。"},{"en":"Clear opening-ceremony details help the event run smoothly because everyone knows the plan.","zh":"清晰的開幕典禮詳情有助活動順利進行，因為每個人都知道安排。"},{"en":"If these details are unclear, guests may miss important moments or arrive unprepared.","zh":"如果這些詳情不清楚，嘉賓可能會錯過重要時刻或準備不足。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Spokesperson).pdf","sourcePage":8}],"dse/paper-3/practical-english-writing/practical-formats/letter-of-invitation-to-winners":[{"front":"Letter of Invitation","meaning":"邀請信","examples":[{"en":"This is a letter of invitation to the winners.","zh":"這是一封寫給得獎者的邀請信。"},{"en":"A letter of invitation is a formal letter that asks someone to attend an event.","zh":"letter of invitation 指正式邀請某人出席活動的信件。"},{"en":"A school may send a letter of invitation to parents before an open day.","zh":"學校可能在開放日前向家長發出邀請信。"},{"en":"If a letter of invitation is clear, guests will know the date, place, time, and purpose of the event.","zh":"如果邀請信清楚，賓客就會知道活動的日期、地點、時間和目的。"},{"en":"A good letter of invitation should sound polite and give enough details for guests to respond.","zh":"好的邀請信應有禮，並提供足夠詳情讓賓客回覆。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"winners of","meaning":"……的得獎者","examples":[{"en":"The winners of the “Daily Drawer” game are invited to the tour.","zh":"“Daily Drawer” 遊戲的得獎者獲邀參加導賞團。"},{"en":"The winners of a game, contest, or prize draw are the people who have won it.","zh":"winners of 某遊戲、比賽或抽獎，指贏得該活動的人。"},{"en":"The winners of the writing competition received certificates at assembly.","zh":"寫作比賽的得獎者在早會上獲頒證書。"},{"en":"If the winners of a lucky draw are announced late, participants may become impatient.","zh":"如果幸運抽獎的得獎者太遲公布，參加者可能會變得不耐煩。"},{"en":"This phrase is useful when identifying exactly which competition the winners belong to.","zh":"這個短語適合用來清楚指出得獎者來自哪一項比賽。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"congratulations on","meaning":"恭喜……","examples":[{"en":"Congratulations on winning the “Daily Drawer” game.","zh":"恭喜你贏得 “Daily Drawer” 遊戲。"},{"en":"Congratulations on is used to praise someone for an achievement or happy event.","zh":"congratulations on 用來祝賀某人的成就或喜事。"},{"en":"Congratulations on passing your driving test after months of practice.","zh":"恭喜你經過數月練習後通過駕駛考試。"},{"en":"If someone wins a prize, saying congratulations on their success sounds polite and warm.","zh":"如果某人得獎，說 congratulations on their success 會顯得有禮而親切。"},{"en":"This phrase is followed by a noun or -ing form, such as “your promotion” or “winning the game.”","zh":"這個短語後面接名詞或 -ing 形式，例如 “your promotion” 或 “winning the game”。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"win the game","meaning":"贏得遊戲","examples":[{"en":"You have won the “Daily Drawer” game organised by our company.","zh":"你已贏得由本公司舉辦的 “Daily Drawer” 遊戲。"},{"en":"To win the game means to finish first or be chosen as the successful player.","zh":"win the game 指在遊戲中勝出，或被選為成功玩家。"},{"en":"A child may win the game by collecting the most points before time runs out.","zh":"小朋友可能透過在限時前取得最多分數來贏得遊戲。"},{"en":"If players understand the rules well, they have a better chance to win the game.","zh":"如果玩家很清楚規則，他們贏得遊戲的機會會較高。"},{"en":"Winning the game may bring a prize, a certificate, or simply a feeling of success.","zh":"贏得遊戲可能帶來獎品、證書，或單純的成功感。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"organised by","meaning":"由……舉辦","examples":[{"en":"You have won the game organised by our company.","zh":"你已贏得由本公司舉辦的遊戲。"},{"en":"Organised by means planned, arranged, and managed by a person or group.","zh":"organised by 指由某人或某團體計劃、安排和管理。"},{"en":"A charity walk organised by students can raise money for the community.","zh":"由學生舉辦的慈善步行可以為社區籌款。"},{"en":"If an event is organised by a trusted company, guests may feel more confident joining it.","zh":"如果活動由可信的公司舉辦，賓客可能會更放心參加。"},{"en":"This phrase tells readers who is responsible for running the activity.","zh":"這個短語告訴讀者誰負責舉辦該活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"be cordially invited to","meaning":"誠邀……","examples":[{"en":"You are cordially invited to attend a full-day tour.","zh":"誠邀你參加全日導賞團。"},{"en":"Be cordially invited to means be warmly and formally invited to do something.","zh":"be cordially invited to 指受到熱誠而正式的邀請去做某事。"},{"en":"Parents are cordially invited to attend the school concert on Friday evening.","zh":"誠邀家長出席星期五晚的學校音樂會。"},{"en":"This phrase makes an invitation sound polite, respectful, and official.","zh":"這個短語令邀請聽起來有禮、尊重而正式。"},{"en":"It is often used in formal letters, ceremonies, company events, and school functions.","zh":"它常用於正式信件、典禮、公司活動和學校活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"attend a full-day tour","meaning":"參加全日導賞團","examples":[{"en":"You are invited to attend a full-day tour of our film studio.","zh":"你獲邀參加我們電影製作室的全日導賞團。"},{"en":"To attend a full-day tour means to join a guided visit that lasts for most of the day.","zh":"attend a full-day tour 指參加一個持續大半天的導賞參觀活動。"},{"en":"Students may attend a full-day tour of a museum to learn outside the classroom.","zh":"學生可能參加博物館全日導賞團，在課室以外學習。"},{"en":"If guests attend a full-day tour, they should prepare enough time and comfortable shoes.","zh":"如果賓客參加全日導賞團，他們應預留足夠時間並穿舒適鞋子。"},{"en":"This phrase is useful when the activity is longer and more structured than a short visit.","zh":"當活動比短暫參觀更長、更有安排時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"full-day tour","meaning":"全日導賞團","examples":[{"en":"The winners are invited to a full-day tour of the film studio.","zh":"得獎者獲邀參加電影製作室的全日導賞團。"},{"en":"A full-day tour is a guided visit that takes place across most of one day.","zh":"full-day tour 指一個持續大半天的導賞參觀活動。"},{"en":"A full-day tour may include transport, meals, talks, and visits to several places.","zh":"全日導賞團可能包括交通、膳食、講解和參觀多個地方。"},{"en":"If a full-day tour starts early, guests should arrive on time and follow the schedule.","zh":"如果全日導賞團很早開始，賓客應準時到達並跟隨日程。"},{"en":"A full-day tour gives visitors more time to understand a place than a short visit.","zh":"全日導賞團比短暫參觀給訪客更多時間了解一個地方。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"film studio","meaning":"電影製作室；片場","examples":[{"en":"The winners will visit our film studio on 25 February.","zh":"得獎者將於2月25日參觀我們的電影製作室。"},{"en":"A film studio is a place where films, television shows, or scenes are made.","zh":"film studio 指製作電影、電視節目或場景的地方。"},{"en":"Students may visit a film studio to see cameras, lights, costumes, and sets.","zh":"學生可能參觀電影製作室，看看攝影機、燈光、服裝和場景。"},{"en":"If a film studio is busy, visitors may need to follow safety rules carefully.","zh":"如果片場很忙，訪客可能需要小心遵守安全規則。"},{"en":"A film studio can show guests how stories are turned into moving images.","zh":"電影製作室可以向賓客展示故事如何變成影像。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"be awarded","meaning":"獲頒；獲得","examples":[{"en":"You will be awarded two business-class tickets to Bali.","zh":"你將獲頒兩張前往峇里的商務客位機票。"},{"en":"To be awarded something means to receive it officially as a prize or honour.","zh":"be awarded something 指正式獲得某物作為獎項或榮譽。"},{"en":"A student may be awarded a scholarship for excellent academic results.","zh":"學生可能因優秀學業成績而獲頒獎學金。"},{"en":"If someone is awarded a medal, it usually recognises effort, talent, or service.","zh":"如果某人獲頒獎章，通常是為了表揚努力、才能或服務。"},{"en":"This phrase sounds more formal than “get” and is common in prize letters.","zh":"這個短語比 “get” 更正式，常見於得獎通知信。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"business-class tickets","meaning":"商務客位機票","examples":[{"en":"The winners will receive two business-class tickets to Bali.","zh":"得獎者將收到兩張前往峇里的商務客位機票。"},{"en":"Business-class tickets are travel tickets for a more comfortable class of airline service.","zh":"business-class tickets 指航空公司較舒適艙等的機票。"},{"en":"Business-class tickets usually offer wider seats, better meals, and more space than economy tickets.","zh":"商務客位機票通常比經濟客位機票提供較寬座位、較好餐膳和更多空間。"},{"en":"If a prize includes business-class tickets, the winners may enjoy a more comfortable journey.","zh":"如果獎品包括商務客位機票，得獎者可能會享受更舒適的旅程。"},{"en":"These tickets are often more expensive, so they can make a prize feel more valuable.","zh":"這些機票通常較昂貴，所以可以令獎品感覺更有價值。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":1},{"front":"the details are as follows","meaning":"詳情如下","examples":[{"en":"The details of the tour are as follows.","zh":"導賞團詳情如下。"},{"en":"The details are as follows is a formal phrase used before listing information.","zh":"the details are as follows 是正式短語，用於列出資料之前。"},{"en":"The details of the interview are as follows: date, time, place, and required documents.","zh":"面試詳情如下：日期、時間、地點和所需文件。"},{"en":"If an email says the details are as follows, readers expect clear points underneath.","zh":"如果電郵寫道 the details are as follows，讀者會預期下方有清楚要點。"},{"en":"This phrase helps organise information in notices, letters, and formal emails.","zh":"這個短語有助在告示、信件和正式電郵中整理資料。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"gather at","meaning":"在……集合","examples":[{"en":"All 30 winners will gather at the entrance of the Marriott Hotel.","zh":"全部30名得獎者將在 Marriott Hotel 入口集合。"},{"en":"To gather at a place means to meet together there before an activity begins.","zh":"gather at a place 指在某地集合，然後開始活動。"},{"en":"Students may gather at the school gate before leaving for a trip.","zh":"學生可能在出發旅行前於校門集合。"},{"en":"If participants gather at the wrong place, the coach may be delayed.","zh":"如果參加者在錯誤地方集合，旅遊巴可能會延誤。"},{"en":"This phrase is useful when giving clear meeting instructions for a group.","zh":"這個短語適合用來向團體提供清楚集合指示。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"entrance of","meaning":"……的入口","examples":[{"en":"The winners will gather at the entrance of the Marriott Hotel in Central.","zh":"得獎者將在中環 Marriott Hotel 的入口集合。"},{"en":"The entrance of a place is the door or area where people go in.","zh":"entrance of a place 指某地方讓人進入的門口或區域。"},{"en":"Visitors should wait at the entrance of the museum before the guide arrives.","zh":"訪客應在導賞員到達前於博物館入口等候。"},{"en":"If a large group blocks the entrance of a building, other people may find it hard to enter.","zh":"如果一大群人堵住大樓入口，其他人可能很難進入。"},{"en":"This phrase helps people find the exact meeting point more easily.","zh":"這個短語有助人們更容易找到確實集合地點。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"Marriott Hotel in Central","meaning":"中環 Marriott Hotel","examples":[{"en":"The winners will gather at the Marriott Hotel in Central.","zh":"得獎者將在中環 Marriott Hotel 集合。"},{"en":"Marriott Hotel in Central names the hotel and its district so guests know the exact location.","zh":"Marriott Hotel in Central 同時列出酒店名稱和地區，讓賓客知道確實位置。"},{"en":"A meeting notice may say “the library in Kowloon Tong” to avoid confusion with other branches.","zh":"會議通知可能寫「九龍塘的圖書館」，以免與其他分館混淆。"},{"en":"If the location is not specific, guests may go to the wrong hotel.","zh":"如果地點不夠具體，賓客可能會去錯酒店。"},{"en":"Including both the venue name and area makes travel planning easier.","zh":"同時寫出場地名稱和地區，可以令交通安排更容易。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"complimentary buffet breakfast","meaning":"免費自助早餐","examples":[{"en":"A complimentary buffet breakfast will be provided.","zh":"將會提供免費自助早餐。"},{"en":"A complimentary buffet breakfast is a free breakfast where guests can choose food from different dishes.","zh":"complimentary buffet breakfast 指免費提供、讓賓客從不同食物中自選的早餐。"},{"en":"A hotel may offer a complimentary buffet breakfast to guests staying overnight.","zh":"酒店可能為留宿賓客提供免費自助早餐。"},{"en":"If breakfast is complimentary, guests do not need to pay extra for it.","zh":"如果早餐是 complimentary，賓客不需要額外付款。"},{"en":"This phrase is common in hotels, tours, and formal event arrangements.","zh":"這個短語常見於酒店、導賞團和正式活動安排。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"be provided","meaning":"將會提供","examples":[{"en":"A complimentary buffet breakfast will be provided.","zh":"將會提供免費自助早餐。"},{"en":"Be provided means be supplied or made available for people to use or enjoy.","zh":"be provided 指某物會被供應或安排給人使用或享用。"},{"en":"Drinking water may be provided at a sports event on a hot day.","zh":"在炎熱日子的體育活動中，可能會提供飲用水。"},{"en":"If clear instructions are provided, participants are less likely to feel confused.","zh":"如果提供清晰指示，參加者較不容易感到混亂。"},{"en":"This phrase is useful when saying what services, food, materials, or support will be available.","zh":"這個短語適合用來說明將會提供甚麼服務、食物、物資或支援。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"be picked up by","meaning":"由……接載","examples":[{"en":"You will be picked up by our studio coach.","zh":"你將由我們的片場旅遊巴接載。"},{"en":"To be picked up by a vehicle means that the vehicle will collect you from a place.","zh":"be picked up by a vehicle 指某交通工具會到某地接載你。"},{"en":"Students may be picked up by a school bus outside their building.","zh":"學生可能由校巴在大廈外接載。"},{"en":"If guests are picked up late, the whole tour schedule may be affected.","zh":"如果賓客被延遲接載，整個導賞團日程可能受影響。"},{"en":"This phrase is useful when explaining transport arrangements.","zh":"這個短語適合用來解釋交通安排。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"studio coach","meaning":"片場旅遊巴","examples":[{"en":"You will be picked up by our studio coach.","zh":"你將由我們的片場旅遊巴接載。"},{"en":"A studio coach is a coach arranged by a film studio to transport guests or staff.","zh":"studio coach 指由片場安排、用來接送賓客或員工的旅遊巴。"},{"en":"Visitors may take a studio coach from the hotel to the filming location.","zh":"訪客可能乘坐片場旅遊巴從酒店前往拍攝地點。"},{"en":"If the studio coach leaves on time, the tour can start smoothly.","zh":"如果片場旅遊巴準時開出，導賞團可以順利開始。"},{"en":"A studio coach helps keep a large group together during a visit.","zh":"片場旅遊巴有助在參觀期間讓大型團體一起行動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"be taken to","meaning":"被帶到；被接載到","examples":[{"en":"You will be taken to our film studio.","zh":"你將被接載到我們的電影製作室。"},{"en":"Be taken to a place means be brought or transported there by someone or something.","zh":"be taken to a place 指由某人或某交通工具帶到某地。"},{"en":"Patients may be taken to hospital by ambulance after an accident.","zh":"意外後，病人可能由救護車送到醫院。"},{"en":"If guests are taken to the wrong entrance, the organiser may need to guide them again.","zh":"如果賓客被帶到錯誤入口，組織者可能需要再次帶路。"},{"en":"This phrase often appears in tour schedules and transport notices.","zh":"這個短語常出現在導賞團日程和交通通知中。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"briefing about","meaning":"關於……的簡介","examples":[{"en":"A briefing about the tour will be given by our staff.","zh":"我們的職員將講解關於導賞團的簡介。"},{"en":"A briefing about something is a short explanation that gives important information before it begins.","zh":"briefing about something 指在某事開始前提供重要資料的簡短講解。"},{"en":"A teacher may give a briefing about safety rules before a science experiment.","zh":"老師可能在科學實驗前講解關於安全規則的簡介。"},{"en":"If guests miss the briefing about the tour, they may not know the schedule or rules.","zh":"如果賓客錯過關於導賞團的簡介，他們可能不知道日程或規則。"},{"en":"A good briefing helps people understand what to expect and what to do.","zh":"好的簡介幫助人們明白將會發生甚麼以及應該怎樣做。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"be given by","meaning":"由……講解","examples":[{"en":"A briefing about the tour will be given by our staff.","zh":"導賞團簡介將由我們的職員講解。"},{"en":"Be given by means be delivered, explained, or presented by a particular person or group.","zh":"be given by 指由某人或某團體提供、講解或展示。"},{"en":"The safety talk will be given by the school nurse.","zh":"安全講解將由學校護士負責。"},{"en":"If instructions are given by experienced staff, visitors may feel more confident.","zh":"如果指示由有經驗的職員講解，訪客可能會更安心。"},{"en":"This phrase tells readers who will provide the information or service.","zh":"這個短語告訴讀者誰會提供資料或服務。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":2},{"front":"during the journey","meaning":"在車程期間","examples":[{"en":"A briefing will be given during the journey.","zh":"簡介將在車程期間講解。"},{"en":"During the journey means while people are travelling from one place to another.","zh":"during the journey 指人們從一地前往另一地的途中。"},{"en":"Students may listen to safety instructions during the journey to the campsite.","zh":"學生可能在前往營地的車程期間聆聽安全指示。"},{"en":"If guests receive information during the journey, they can use travel time productively.","zh":"如果賓客在車程期間收到資料，他們可以善用交通時間。"},{"en":"This phrase is useful when an activity happens on the coach, train, plane, or ferry.","zh":"這個短語適合用於活動在旅遊巴、火車、飛機或渡輪上進行的情況。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"upon arrival at","meaning":"抵達……後","examples":[{"en":"Upon arrival at the film studio, you will be guided through different film sets.","zh":"抵達電影製作室後，你將獲帶領參觀不同電影場景。"},{"en":"Upon arrival at means immediately after reaching a place.","zh":"upon arrival at 指一抵達某地之後。"},{"en":"Upon arrival at the hotel, guests should check in at the front desk.","zh":"抵達酒店後，賓客應到前台辦理入住手續。"},{"en":"If visitors receive badges upon arrival at the school, security can identify them easily.","zh":"如果訪客抵達學校後獲發名牌，保安就能容易識別他們。"},{"en":"This phrase is formal and useful in schedules, notices, and travel instructions.","zh":"這個短語較正式，適合用於日程、告示和旅遊指示。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"film studio","meaning":"片場；電影製作室","examples":[{"en":"Upon arrival at the film studio, you will meet the actors.","zh":"抵達片場後，你將與演員見面。"},{"en":"A film studio is a place prepared for filming scenes, building sets, and working with actors.","zh":"film studio 指為拍攝場景、搭建佈景和與演員工作而準備的地方。"},{"en":"A film studio may have sound stages, costumes, cameras, and lighting equipment.","zh":"片場可能有錄影廠、服裝、攝影機和燈光設備。"},{"en":"If visitors enter a film studio, they may need to stay quiet during filming.","zh":"如果訪客進入片場，他們可能需要在拍攝期間保持安靜。"},{"en":"This phrase can refer to both the physical filming place and the company space used for production.","zh":"這個短語可以指實際拍攝地點，也可以指用於製作的公司空間。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"be guided through","meaning":"獲帶領參觀","examples":[{"en":"You will be guided through different film sets.","zh":"你將獲帶領參觀不同電影場景。"},{"en":"To be guided through a place means to be led around it while someone explains what you see.","zh":"be guided through a place 指由某人帶領參觀某地，並講解所見內容。"},{"en":"Visitors may be guided through a museum by a staff member.","zh":"訪客可能由職員帶領參觀博物館。"},{"en":"If guests are guided through a large building, they are less likely to get lost.","zh":"如果賓客獲帶領參觀一座大型建築，他們較不容易迷路。"},{"en":"This phrase suggests organised movement, explanation, and help from a guide.","zh":"這個短語表示有組織的移動、講解和導賞協助。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"film sets","meaning":"電影場景","examples":[{"en":"You will be guided through different film sets.","zh":"你將獲帶領參觀不同電影場景。"},{"en":"Film sets are built places or arranged spaces where scenes are filmed.","zh":"film sets 指為拍攝場面而搭建或佈置的地方。"},{"en":"A film set may look like a hospital, a palace, a street, or a forest.","zh":"電影場景可能看起來像醫院、宮殿、街道或森林。"},{"en":"If a film set is realistic, viewers may believe the story more easily.","zh":"如果電影場景逼真，觀眾可能更容易相信故事。"},{"en":"Visitors to film sets can see how ordinary spaces are changed for filming.","zh":"參觀電影場景的訪客可以看到普通空間如何為拍攝而改變。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"have the opportunity to","meaning":"有機會去……","examples":[{"en":"You will have the opportunity to meet actors there.","zh":"你將有機會在那裡與演員見面。"},{"en":"To have the opportunity to do something means to have a chance to do it.","zh":"have the opportunity to do something 指有機會做某事。"},{"en":"Students may have the opportunity to ask questions after a guest talk.","zh":"學生可能在嘉賓講座後有機會提問。"},{"en":"If visitors have the opportunity to meet experts, they may learn more than from reading only.","zh":"如果訪客有機會與專家見面，他們可能學到比只閱讀更多的東西。"},{"en":"This phrase sounds positive and is often used when describing a special benefit.","zh":"這個短語聽起來正面，常用於描述特別待遇或好處。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"meet actors","meaning":"與演員見面","examples":[{"en":"You will have the opportunity to meet actors at the studio.","zh":"你將有機會在片場與演員見面。"},{"en":"To meet actors means to see and speak with people who perform in films, dramas, or television shows.","zh":"meet actors 指見到並與電影、戲劇或電視節目中的演員交談。"},{"en":"Students may meet actors after a theatre performance and ask about their training.","zh":"學生可能在劇場演出後與演員見面，並詢問他們的訓練。"},{"en":"If fans meet actors in person, the event may become more memorable.","zh":"如果粉絲親身與演員見面，活動可能會更難忘。"},{"en":"Meeting actors can help visitors understand the human work behind a production.","zh":"與演員見面可以幫助訪客了解製作背後的人力工作。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"major themes include","meaning":"主要主題包括","examples":[{"en":"Major themes include an ancient Chinese palace and a sci-fi studio.","zh":"主要主題包括中國古代宮殿和科幻片場。"},{"en":"Major themes include is used to introduce the main topics, styles, or features of something.","zh":"major themes include 用來介紹某事的主要題目、風格或特色。"},{"en":"Major themes in a school exhibition may include health, technology, and environmental protection.","zh":"學校展覽的主要主題可能包括健康、科技和環境保護。"},{"en":"If major themes are listed clearly, visitors can understand the focus of an event quickly.","zh":"如果主要主題列得清楚，訪客可以很快理解活動重點。"},{"en":"This phrase helps organise several important ideas in one sentence.","zh":"這個短語有助在一句句子中整理幾個重要概念。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"ancient Chinese palace","meaning":"中國古代宮殿","examples":[{"en":"One of the film sets is an ancient Chinese palace.","zh":"其中一個電影場景是中國古代宮殿。"},{"en":"An ancient Chinese palace is a grand building designed to look like a palace from old China.","zh":"ancient Chinese palace 指設計成中國古代皇宮樣子的宏偉建築。"},{"en":"A historical drama may use an ancient Chinese palace to show royal life.","zh":"歷史劇可能使用中國古代宮殿來展示皇室生活。"},{"en":"If the ancient Chinese palace set has detailed costumes and furniture, the scene feels more believable.","zh":"如果中國古代宮殿場景有細緻服裝和家具，畫面會更可信。"},{"en":"This phrase describes both the time period and the cultural style of the setting.","zh":"這個短語同時描述場景的年代和文化風格。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"artificial forest","meaning":"人造森林","examples":[{"en":"The tour includes an artificial forest.","zh":"導賞團包括一個人造森林。"},{"en":"An artificial forest is a man-made forest setting, not a natural one.","zh":"artificial forest 指人造的森林場景，而不是天然森林。"},{"en":"A film crew may use an artificial forest when filming indoors or controlling the weather.","zh":"電影團隊在室內拍攝或控制天氣時，可能會使用人造森林。"},{"en":"If an artificial forest is well designed, viewers may not realise it is fake.","zh":"如果人造森林設計得好，觀眾可能不會察覺它是假的。"},{"en":"This phrase is useful when describing a set that looks natural but has been built by people.","zh":"這個短語適合描述看起來天然、但由人建造的場景。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"sci-fi studio","meaning":"科幻片場","examples":[{"en":"The tour includes a sci-fi studio.","zh":"導賞團包括一個科幻片場。"},{"en":"A sci-fi studio is a filming space designed for science-fiction scenes.","zh":"sci-fi studio 指為拍攝科幻場面而設計的片場。"},{"en":"A sci-fi studio may contain spaceships, control rooms, robots, or futuristic lights.","zh":"科幻片場可能有太空船、控制室、機械人或未來感燈光。"},{"en":"If a sci-fi studio uses strong visual effects, ordinary rooms can look like another planet.","zh":"如果科幻片場使用強烈視覺效果，普通房間也可以看起來像另一個星球。"},{"en":"This phrase is useful when describing film settings connected to future technology or space stories.","zh":"這個短語適合描述與未來科技或太空故事有關的電影場景。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":3},{"front":"prize-giving ceremony","meaning":"頒獎典禮","examples":[{"en":"The prize-giving ceremony will commence at 3:15 p.m.","zh":"頒獎典禮將於下午3時15分開始。"},{"en":"A prize-giving ceremony is a formal event where awards or prizes are presented.","zh":"prize-giving ceremony 指頒發獎項或獎品的正式活動。"},{"en":"A school may hold a prize-giving ceremony to honour students with excellent results.","zh":"學校可能舉行頒獎典禮，表揚成績優異的學生。"},{"en":"If a prize-giving ceremony is well organised, winners know when to go on stage.","zh":"如果頒獎典禮安排得好，得獎者會知道何時上台。"},{"en":"This phrase is often used in schools, competitions, companies, and public events.","zh":"這個短語常用於學校、比賽、公司和公開活動。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"commence","meaning":"開始","examples":[{"en":"The prize-giving ceremony will commence at 3:15 p.m.","zh":"頒獎典禮將於下午3時15分開始。"},{"en":"Commence means begin or start, and it sounds formal.","zh":"commence 指開始，語氣較正式。"},{"en":"The meeting will commence once all committee members have arrived.","zh":"會議將在所有委員到達後開始。"},{"en":"If a ceremony commences late, the following activities may also be delayed.","zh":"如果典禮遲了開始，之後的活動也可能延誤。"},{"en":"This word is common in formal notices, schedules, and announcements.","zh":"這個字常見於正式告示、日程和公告。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"must be used within","meaning":"必須在……內使用","examples":[{"en":"The tickets must be used within two years.","zh":"機票必須在兩年內使用。"},{"en":"Must be used within means something has to be used before a set period ends.","zh":"must be used within 指某物必須在指定期限完結前使用。"},{"en":"A discount coupon must be used within one month of purchase.","zh":"折扣券必須在購買後一個月內使用。"},{"en":"If a gift card must be used within six months, customers should check the expiry date.","zh":"如果禮品卡必須在六個月內使用，顧客應查看到期日。"},{"en":"This phrase tells people the time limit for using a ticket, offer, or prize.","zh":"這個短語告訴人們使用門票、優惠或獎品的時限。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"within two years","meaning":"兩年內","examples":[{"en":"The business-class tickets must be used within two years.","zh":"商務客位機票必須在兩年內使用。"},{"en":"Within two years means before two years have passed.","zh":"within two years 指在兩年過去之前。"},{"en":"A new employee may need to complete training within two years.","zh":"新員工可能需要在兩年內完成培訓。"},{"en":"If a prize must be claimed within two years, the winner should not wait too long.","zh":"如果獎品必須在兩年內領取，得獎者不應等太久。"},{"en":"This phrase sets a clear time limit without giving one exact date.","zh":"這個短語設定清楚時限，但不一定給出單一確實日期。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"during the ceremony","meaning":"在典禮期間","examples":[{"en":"During the ceremony, Tony Mak will attend as our guest of honour.","zh":"在典禮期間，Tony Mak 將以主禮嘉賓身份出席。"},{"en":"During the ceremony means while the formal event is taking place.","zh":"during the ceremony 指正式活動進行期間。"},{"en":"During the ceremony, guests should remain seated and listen respectfully.","zh":"在典禮期間，賓客應保持就座並尊重地聆聽。"},{"en":"If photos are taken during the ceremony, the photographer should not block the stage.","zh":"如果在典禮期間拍照，攝影師不應阻擋舞台。"},{"en":"This phrase helps show when something will happen in the event schedule.","zh":"這個短語有助說明某事會在活動日程中何時發生。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"renowned movie star","meaning":"著名電影明星","examples":[{"en":"The renowned movie star Tony Mak will attend the ceremony.","zh":"著名電影明星 Tony Mak 將出席典禮。"},{"en":"A renowned movie star is a famous actor known by many people for film work.","zh":"renowned movie star 指因電影作品而被很多人認識的著名演員。"},{"en":"A charity event may invite a renowned movie star to attract public attention.","zh":"慈善活動可能邀請著名電影明星來吸引公眾注意。"},{"en":"If a renowned movie star attends an event, more fans and reporters may come.","zh":"如果著名電影明星出席活動，更多粉絲和記者可能會到場。"},{"en":"Renowned sounds more formal than famous and is suitable for invitations or announcements.","zh":"renowned 比 famous 更正式，適合用於邀請信或公告。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"attend as","meaning":"以……身份出席","examples":[{"en":"Tony Mak will attend as our guest of honour.","zh":"Tony Mak 將以我們的主禮嘉賓身份出席。"},{"en":"Attend as means take part in an event in a particular role or position.","zh":"attend as 指以某個角色或身份參與活動。"},{"en":"A doctor may attend a school talk as a health expert.","zh":"醫生可能以健康專家身份出席學校講座。"},{"en":"If someone attends as a judge, they are expected to evaluate the competition fairly.","zh":"如果某人以評判身份出席，他應公平評審比賽。"},{"en":"This phrase explains not only that a person will attend, but also why they are there.","zh":"這個短語不只說明某人會出席，也說明他出席的身份。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"guest of honour","meaning":"主禮嘉賓","examples":[{"en":"Tony Mak will attend as our guest of honour.","zh":"Tony Mak 將以我們的主禮嘉賓身份出席。"},{"en":"A guest of honour is a special guest given an important role at an event.","zh":"guest of honour 指在活動中擔任重要角色的特別嘉賓。"},{"en":"A school may invite a former student as the guest of honour at graduation.","zh":"學校可能邀請舊生擔任畢業禮主禮嘉賓。"},{"en":"If a guest of honour gives a speech, the organiser should include it in the schedule.","zh":"如果主禮嘉賓會致辭，主辦方應把它列入日程。"},{"en":"This phrase shows respect and tells guests who the most important invited person is.","zh":"這個短語表示尊重，並告訴賓客誰是最重要的受邀人士。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"be welcome to","meaning":"歡迎……","examples":[{"en":"You are welcome to take photos with him.","zh":"歡迎你與他合照。"},{"en":"Be welcome to do something means you are allowed and encouraged to do it.","zh":"be welcome to do something 指你可以並受到鼓勵去做某事。"},{"en":"Visitors are welcome to ask questions after the guided tour.","zh":"歡迎訪客在導賞團後提問。"},{"en":"If guests are welcome to take snacks, they do not need to ask permission each time.","zh":"如果歡迎賓客取用小食，他們不需要每次都詢問許可。"},{"en":"This phrase sounds friendly because it gives permission politely.","zh":"這個短語聽起來友善，因為它有禮地給予許可。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"take photos with","meaning":"與……合照","examples":[{"en":"You are welcome to take photos with Tony Mak.","zh":"歡迎你與 Tony Mak 合照。"},{"en":"To take photos with someone means to be photographed together with that person.","zh":"take photos with someone 指與某人一起拍照。"},{"en":"Children may take photos with their teacher after a school performance.","zh":"孩子可能在學校演出後與老師合照。"},{"en":"If many people want to take photos with a guest, organisers should manage the queue.","zh":"如果很多人想與嘉賓合照，組織者應管理隊伍。"},{"en":"This phrase is common when guests meet celebrities, speakers, or award winners.","zh":"這個短語常用於賓客與名人、講者或得獎者見面的情況。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"at the end of","meaning":"在……結束時","examples":[{"en":"At the end of the tour, guests may take the coach to the nearest MTR station.","zh":"在導賞團結束時，賓客可乘坐旅遊巴前往最近的港鐵站。"},{"en":"At the end of means when something is finishing or has just finished.","zh":"at the end of 指某事即將結束或剛結束時。"},{"en":"At the end of the lesson, the teacher collected the worksheets.","zh":"在課堂結束時，老師收集了工作紙。"},{"en":"If transport is arranged at the end of an event, guests can leave more easily.","zh":"如果活動結束時安排交通，賓客可以更容易離開。"},{"en":"This phrase helps show the final stage of an activity.","zh":"這個短語有助說明活動的最後階段。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":4},{"front":"the tour will end","meaning":"活動將於……結束","examples":[{"en":"The tour will end at 4:15 p.m.","zh":"導賞團將於下午4時15分結束。"},{"en":"The tour will end means the guided visit will finish at a particular time.","zh":"the tour will end 指導賞參觀會在某個時間結束。"},{"en":"The museum tour will end after the final exhibition room.","zh":"博物館導賞團將在最後一個展覽室後結束。"},{"en":"If the tour ends late, guests may miss their next appointment.","zh":"如果導賞團太遲結束，賓客可能會錯過下一個約會。"},{"en":"This phrase gives guests a clear idea of when the activity finishes.","zh":"這個短語讓賓客清楚知道活動何時完結。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"be available upon request","meaning":"可按要求提供","examples":[{"en":"Studio coaches will be available upon request.","zh":"片場旅遊巴可按要求提供。"},{"en":"Be available upon request means something can be provided if people ask for it.","zh":"be available upon request 指某物或服務在有人提出要求時可以提供。"},{"en":"Extra chairs are available upon request for elderly guests.","zh":"額外椅子可按要求提供給年長賓客。"},{"en":"If translation support is available upon request, visitors should tell the organiser early.","zh":"如果翻譯支援可按要求提供，訪客應及早通知主辦方。"},{"en":"This phrase is useful when a service is not automatic but can be arranged.","zh":"這個短語適合用於服務不是自動提供、但可以安排的情況。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"upon request","meaning":"按要求","examples":[{"en":"Studio coaches will be available upon request.","zh":"片場旅遊巴可按要求提供。"},{"en":"Upon request means when someone asks for something formally or clearly.","zh":"upon request 指在有人正式或清楚提出要求時。"},{"en":"A restaurant may provide a vegetarian menu upon request.","zh":"餐廳可按要求提供素食餐牌。"},{"en":"If documents are available upon request, people must ask before receiving them.","zh":"如果文件可按要求提供，人們必須先提出要求才會收到。"},{"en":"This phrase often appears in formal notices about optional services or information.","zh":"這個短語常見於關於可選服務或資料的正式告示。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"nearest MTR station","meaning":"最近的港鐵站","examples":[{"en":"The coach can take guests to the nearest MTR station.","zh":"旅遊巴可以把賓客送到最近的港鐵站。"},{"en":"The nearest MTR station is the closest railway station in Hong Kong’s MTR system.","zh":"nearest MTR station 指香港港鐵系統中距離最近的鐵路站。"},{"en":"Visitors may ask staff how to walk to the nearest MTR station after an event.","zh":"訪客可能在活動後詢問職員如何步行到最近的港鐵站。"},{"en":"If guests are taken to the nearest MTR station, they can continue their journey more easily.","zh":"如果賓客被送到最近的港鐵站，他們可以更容易繼續行程。"},{"en":"This phrase is useful in Hong Kong travel instructions because many people use the MTR.","zh":"這個短語在香港交通指示中很有用，因為很多人使用港鐵。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"once again","meaning":"再次","examples":[{"en":"Once again, congratulations on winning the game.","zh":"再次恭喜你贏得遊戲。"},{"en":"Once again means one more time, often used to repeat thanks, congratulations, or a reminder.","zh":"once again 指再一次，常用來重複感謝、祝賀或提醒。"},{"en":"Once again, thank you for helping with the charity sale.","zh":"再次感謝你協助慈善義賣。"},{"en":"If a letter ends with once again, the writer is emphasising an important message politely.","zh":"如果信件結尾使用 once again，作者是在有禮地強調重要訊息。"},{"en":"This phrase is useful for repeating a warm point before closing a formal message.","zh":"這個短語適合在正式訊息結尾前重複一個親切重點。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"should you have any enquiries","meaning":"如有任何查詢","examples":[{"en":"Should you have any enquiries, please contact us.","zh":"如有任何查詢，請聯絡我們。"},{"en":"Should you have any enquiries is a formal way of saying “if you have any questions.”","zh":"should you have any enquiries 是 “if you have any questions” 的正式說法。"},{"en":"Should you have any enquiries about the application, please call the school office.","zh":"如對申請有任何查詢，請致電學校辦公室。"},{"en":"This phrase is often used near the end of formal letters to offer help.","zh":"這個短語常用於正式信件結尾附近，用來提供協助。"},{"en":"It sounds more polite and formal than “If you have questions, ask us.”","zh":"它比 “If you have questions, ask us.” 聽起來更有禮和正式。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"enquiries","meaning":"查詢","examples":[{"en":"Should you have any enquiries, please contact us.","zh":"如有任何查詢，請聯絡我們。"},{"en":"Enquiries are questions or requests for information.","zh":"enquiries 指問題或索取資料的要求。"},{"en":"Parents may send enquiries to the school office about uniform rules.","zh":"家長可能向學校辦公室發出關於校服規則的查詢。"},{"en":"If a company receives many enquiries about an event, it should prepare clear answers.","zh":"如果公司收到很多關於活動的查詢，就應準備清楚答案。"},{"en":"This word is common in formal British English and is often used in letters and notices.","zh":"這個字常見於正式英式英語，常用於信件和告示。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"please do not hesitate to","meaning":"請隨時……","examples":[{"en":"Please do not hesitate to contact us.","zh":"請隨時聯絡我們。"},{"en":"Please do not hesitate to means please feel free to do something without worry.","zh":"please do not hesitate to 指請放心去做某事，不用猶豫。"},{"en":"Please do not hesitate to ask the teacher if you do not understand the homework.","zh":"如果你不明白功課，請隨時詢問老師。"},{"en":"This phrase makes an offer of help sound polite and welcoming.","zh":"這個短語令提供協助的語氣顯得有禮而親切。"},{"en":"It is often used before verbs like contact, ask, call, or email.","zh":"它常用於 contact、ask、call 或 email 等動詞之前。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"contact us","meaning":"聯絡我們","examples":[{"en":"Please do not hesitate to contact us.","zh":"請隨時聯絡我們。"},{"en":"To contact us means to get in touch with our organisation by phone, email, message, or another method.","zh":"contact us 指透過電話、電郵、訊息或其他方法與我們的機構聯絡。"},{"en":"Customers may contact us if they need help with a booking.","zh":"顧客如需要預訂協助，可以聯絡我們。"},{"en":"If guests cannot find the meeting point, they should contact us immediately.","zh":"如果賓客找不到集合地點，應立即聯絡我們。"},{"en":"This phrase tells readers who they can reach when they need help or information.","zh":"這個短語告訴讀者在需要協助或資料時可以找誰。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"be more than happy to","meaning":"非常樂意……","examples":[{"en":"We would be more than happy to provide further assistance.","zh":"我們非常樂意提供進一步協助。"},{"en":"Be more than happy to means be very willing to do something.","zh":"be more than happy to 指非常願意做某事。"},{"en":"The school office would be more than happy to help parents complete the form.","zh":"學校辦公室非常樂意協助家長填寫表格。"},{"en":"This phrase makes the speaker sound helpful, polite, and positive.","zh":"這個短語令講者聽起來樂於助人、有禮而正面。"},{"en":"It is common in customer service emails and formal letters that offer support.","zh":"它常見於提供支援的客戶服務電郵和正式信件。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"provide further assistance","meaning":"提供進一步協助","examples":[{"en":"We would be more than happy to provide further assistance.","zh":"我們非常樂意提供進一步協助。"},{"en":"To provide further assistance means to give more help if it is needed.","zh":"provide further assistance 指在有需要時給予更多幫助。"},{"en":"A receptionist may provide further assistance if a guest cannot find the meeting room.","zh":"如果賓客找不到會議室，接待員可能會提供進一步協助。"},{"en":"If instructions are still unclear, staff should provide further assistance before the event begins.","zh":"如果指示仍不清楚，職員應在活動開始前提供進一步協助。"},{"en":"This phrase is formal and useful when ending an email politely.","zh":"這個短語較正式，適合用於有禮地結束電郵。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":5},{"front":"thank you for your attention","meaning":"多謝垂注","examples":[{"en":"Thank you for your attention.","zh":"多謝垂注。"},{"en":"Thank you for your attention is a formal way to thank readers for reading or listening carefully.","zh":"thank you for your attention 是正式感謝讀者閱讀或聽眾留心聆聽的說法。"},{"en":"A speaker may end a presentation by saying, “Thank you for your attention.”","zh":"講者可能以 “Thank you for your attention.” 結束匯報。"},{"en":"If a notice contains important details, this phrase politely thanks people for considering them.","zh":"如果告示包含重要詳情，這個短語會有禮地感謝人們留意。"},{"en":"It is more formal than simply saying “thanks for reading.”","zh":"它比簡單說 “thanks for reading” 更正式。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":6},{"front":"look forward to seeing you","meaning":"期待見到你","examples":[{"en":"We look forward to seeing you at our film studio.","zh":"我們期待在電影製作室見到你。"},{"en":"Look forward to seeing you means we are pleased about meeting you in the future.","zh":"look forward to seeing you 指我們期待將來與你見面。"},{"en":"A teacher may write, “I look forward to seeing you at the parents’ meeting.”","zh":"老師可能寫道：「我期待在家長會見到你。」"},{"en":"This phrase helps end an invitation letter in a warm and positive way.","zh":"這個短語有助以溫暖而正面的方式結束邀請信。"},{"en":"It is followed by the -ing form “seeing,” not “see.”","zh":"它後面接 -ing 形式 “seeing”，不是 “see”。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":6},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully, Jackie Man.","zh":"Jackie Man 謹啟。"},{"en":"Yours faithfully is a formal closing used at the end of a letter when the writer may not know the reader personally.","zh":"Yours faithfully 是正式信件結尾用語，常用於作者未必私人認識讀者的情況。"},{"en":"A company may end a formal invitation with “Yours faithfully” before the sender’s name.","zh":"公司可能在正式邀請信中，以 “Yours faithfully” 加寄件人姓名作結。"},{"en":"Using Yours faithfully helps the letter sound respectful and complete.","zh":"使用 Yours faithfully 可以令信件顯得尊重而完整。"},{"en":"This closing is common in formal British-style business letters.","zh":"這個結語常見於英式正式商業信件。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":6},{"front":"Communication Department","meaning":"傳訊部","examples":[{"en":"Jackie Man works in the Communication Department.","zh":"Jackie Man 在傳訊部工作。"},{"en":"A Communication Department is the part of an organisation that handles public messages, announcements, and media contact.","zh":"Communication Department 指機構中負責公開訊息、公告和媒體聯絡的部門。"},{"en":"The Communication Department may prepare emails, press releases, posters, and event notices.","zh":"傳訊部可能準備電郵、新聞稿、海報和活動通知。"},{"en":"If a company gives unclear information, the Communication Department may need to explain it again.","zh":"如果公司提供的資料不清楚，傳訊部可能需要再次解釋。"},{"en":"This department helps an organisation speak clearly to customers, guests, and the public.","zh":"這個部門幫助機構清楚地向顧客、賓客和公眾溝通。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":6},{"front":"QB Television Company","meaning":"QB Television Company","examples":[{"en":"Jackie Man works for QB Television Company.","zh":"Jackie Man 任職於 QB Television Company。"},{"en":"QB Television Company is the organisation that sends the invitation and runs the related event.","zh":"QB Television Company 是發出邀請並舉辦相關活動的機構。"},{"en":"A television company may organise studio tours to let visitors see how programmes are made.","zh":"電視公司可能舉辦片場導賞團，讓訪客了解節目如何製作。"},{"en":"If QB Television Company invites winners to its studio, it should provide clear transport and safety details.","zh":"如果 QB Television Company 邀請得獎者到片場，應提供清楚交通和安全詳情。"},{"en":"Naming the company helps readers know who is responsible for the invitation.","zh":"寫出公司名稱有助讀者知道誰負責這封邀請信。"}],"source":"Flash Cards -實用文 - Letter of Invitation (Winner).pdf","sourcePage":6}],"dse/paper-3/practical-english-writing/practical-formats/letter-of-reply":[{"front":"provide someone with more information about","meaning":"向某人提供更多關於……的資料","examples":[{"en":"I am writing to provide you with more information about Mumbo Jumbo Pet-Friendly Park.","zh":"我寫信是為了向你提供更多關於 Mumbo Jumbo Pet-Friendly Park 的資料。"},{"en":"To provide someone with more information about something means to give extra details so they understand it better.","zh":"provide someone with more information about something 指向某人提供額外資料，讓他們更了解某事。"},{"en":"A teacher may provide parents with more information about a school trip before they sign the consent form.","zh":"老師可能會在家長簽同意書前，向他們提供更多關於學校旅行的資料。"},{"en":"Providing customers with more information about a product can help them make a safer choice.","zh":"向顧客提供更多關於產品的資料，可以幫助他們作出更安全的選擇。"},{"en":"If people are still confused, a clear email can provide them with more information about the next steps.","zh":"如果人們仍然感到困惑，一封清楚的電郵可以向他們提供更多關於下一步的資料。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"pet-friendly park","meaning":"寵物友善公園","examples":[{"en":"Mumbo Jumbo Pet-Friendly Park welcomes visitors and their pets.","zh":"Mumbo Jumbo Pet-Friendly Park 歡迎訪客和他們的寵物。"},{"en":"A pet-friendly park is a park where people are allowed to bring their pets.","zh":"寵物友善公園是容許人們攜帶寵物進入的公園。"},{"en":"A pet-friendly park may provide water bowls, open space, and bins for pet waste.","zh":"寵物友善公園可能會提供水碗、開放空間和寵物糞便垃圾桶。"},{"en":"Pet-friendly parks can help pet owners exercise their animals safely.","zh":"寵物友善公園可以幫助寵物主人安全地讓動物活動。"},{"en":"A park is not truly pet-friendly if pets are allowed but there are no clear safety rules.","zh":"如果公園容許寵物進入，但沒有清楚安全規則，就不算真正寵物友善。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"regarding","meaning":"關於","examples":[{"en":"Regarding the size of our pet-friendly park, I would like to provide more details.","zh":"關於我們寵物友善公園的大小，我想提供更多詳情。"},{"en":"Regarding means about or concerning a particular topic.","zh":"regarding 指關於某個特定主題。"},{"en":"Regarding your homework, please submit it before Friday.","zh":"關於你的功課，請在星期五前提交。"},{"en":"A manager may use “regarding” to introduce the main topic of an email.","zh":"經理可能會用 regarding 來引入電郵的主要主題。"},{"en":"Regarding is more formal than simply saying “about”.","zh":"regarding 比簡單說 “about” 更正式。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"standard-sized","meaning":"標準大小的","examples":[{"en":"The park is as large as two standard-sized basketball courts.","zh":"該公園與兩個標準大小的籃球場一樣大。"},{"en":"Standard-sized means having the usual or officially accepted size.","zh":"standard-sized 指具有一般或正式認可大小的。"},{"en":"A standard-sized classroom can usually fit about thirty students.","zh":"一間標準大小的課室通常可以容納約三十名學生。"},{"en":"If a table is not standard-sized, it may not fit normal chairs properly.","zh":"如果桌子不是標準大小，可能無法配合普通椅子使用。"},{"en":"Using standard-sized equipment makes it easier to compare space and cost.","zh":"使用標準大小的設備，能更容易比較空間和成本。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"as large as","meaning":"與……一樣大","examples":[{"en":"The park is as large as two standard-sized basketball courts.","zh":"該公園與兩個標準大小的籃球場一樣大。"},{"en":"As large as is used to compare size and means equal in size to something else.","zh":"as large as 用來比較大小，意思是與另一事物大小相同。"},{"en":"The new library is as large as three classrooms.","zh":"新圖書館與三間課室一樣大。"},{"en":"Saying a room is as large as a tennis court helps people imagine its size more clearly.","zh":"說一個房間與一個網球場一樣大，可以幫助人們更清楚想像其大小。"},{"en":"As large as compares size, while as tall as compares height.","zh":"as large as 比較大小，而 as tall as 則比較高度。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"standard-sized basketball courts","meaning":"標準籃球場","examples":[{"en":"The park is as large as two standard-sized basketball courts.","zh":"該公園與兩個標準籃球場一樣大。"},{"en":"Standard-sized basketball courts are basketball courts built to a normal recognised size.","zh":"standard-sized basketball courts 指按一般認可大小建造的籃球場。"},{"en":"A school may compare a playground with standard-sized basketball courts to show its area clearly.","zh":"學校可能會用標準籃球場來比較操場大小，使面積更清楚。"},{"en":"If an indoor hall can fit two standard-sized basketball courts, it is quite spacious.","zh":"如果室內禮堂能容納兩個標準籃球場，空間就相當寬敞。"},{"en":"This phrase helps readers imagine size by using a familiar sports space.","zh":"這個片語透過熟悉的運動場地，幫助讀者想像大小。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"bathrooms installed within","meaning":"在……內設有洗手間","examples":[{"en":"There are two bathrooms installed within the park.","zh":"公園內設有兩個洗手間。"},{"en":"Bathrooms installed within a place are toilets or washrooms built inside that area.","zh":"bathrooms installed within a place 指在某地方內建有洗手間。"},{"en":"A campsite with bathrooms installed within the site is more convenient for families.","zh":"如果營地內設有洗手間，對家庭會更方便。"},{"en":"Having bathrooms installed within a park can reduce the need for visitors to leave and return.","zh":"公園內設有洗手間，可以減少訪客需要離開再回來的情況。"},{"en":"If bathrooms are not installed within the venue, visitors may have to use nearby public toilets.","zh":"如果場地內沒有設洗手間，訪客可能需要使用附近的公眾洗手間。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"within the park","meaning":"在公園內","examples":[{"en":"There are two bathrooms within the park.","zh":"公園內有兩個洗手間。"},{"en":"Within the park means inside the area or boundary of the park.","zh":"within the park 指在公園範圍或邊界之內。"},{"en":"Visitors should keep dogs on a leash within the park.","zh":"訪客在公園內應為狗隻繫上牽繩。"},{"en":"If food stalls are located within the park, visitors do not need to walk outside to buy snacks.","zh":"如果小食攤位設於公園內，訪客就不需要走到外面買小食。"},{"en":"Within the park is more specific than simply saying “near the park”.","zh":"within the park 比簡單說 “near the park” 更具體。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"visitors are allowed to","meaning":"訪客可獲准……","examples":[{"en":"Visitors are allowed to bring pet food into the park.","zh":"訪客可獲准把寵物食物帶進公園。"},{"en":"Visitors are allowed to means visitors have permission to do something.","zh":"visitors are allowed to 指訪客有權或獲准做某事。"},{"en":"Visitors are allowed to take photos in the garden, but not inside the museum.","zh":"訪客可獲准在花園拍照，但不可在博物館內拍照。"},{"en":"If visitors are allowed to enter early, queues may be shorter later.","zh":"如果訪客可獲准提早入場，之後排隊人龍可能會較短。"},{"en":"This phrase usually appears in rules, notices, or information letters.","zh":"這個片語通常出現在規則、告示或資料信件中。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"bring pet food into","meaning":"把寵物食物帶進……","examples":[{"en":"Visitors are allowed to bring pet food into the park.","zh":"訪客可獲准把寵物食物帶進公園。"},{"en":"To bring pet food into a place means to carry food for animals inside that place.","zh":"bring pet food into a place 指把動物食物帶入某地方。"},{"en":"Pet owners may bring pet food into a dog café if the café permits it.","zh":"如果狗狗咖啡店容許，寵物主人可以把寵物食物帶進店內。"},{"en":"Allowing people to bring pet food into a park can help pets stay comfortable during long visits.","zh":"容許人們把寵物食物帶進公園，可以讓寵物在長時間逗留時更舒適。"},{"en":"Visitors should not bring pet food into an area if it may attract wild animals.","zh":"如果寵物食物可能吸引野生動物，訪客就不應把它帶進該區域。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"however","meaning":"然而","examples":[{"en":"However, visitors themselves are not permitted to eat inside.","zh":"然而，訪客本人不獲准在園內進食。"},{"en":"However introduces a contrast or a different point from what was just said.","zh":"however 用來引入與前文不同或相反的重點。"},{"en":"Dogs are welcome in the park; however, they must be kept on a leash.","zh":"狗隻歡迎進入公園；然而，牠們必須繫上牽繩。"},{"en":"A sentence with “however” often shows that there is a limit or exception.","zh":"含有 however 的句子通常表示有限制或例外。"},{"en":"However is more formal than “but” and is common in written notices.","zh":"however 比 “but” 較正式，常見於書面告示。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":1},{"front":"we regret to inform you that","meaning":"我們很遺憾通知你……","examples":[{"en":"We regret to inform you that visitors are not permitted to eat inside.","zh":"我們很遺憾通知你，訪客不獲准在園內進食。"},{"en":"We regret to inform you that is a formal way to give disappointing or negative news.","zh":"we regret to inform you that 是正式表達令人失望或負面消息的說法。"},{"en":"We regret to inform you that the event has been cancelled due to bad weather.","zh":"我們很遺憾通知你，活動因惡劣天氣而取消。"},{"en":"This phrase softens bad news and sounds more polite in official writing.","zh":"這個片語能緩和壞消息，在正式寫作中較有禮貌。"},{"en":"It is usually followed by information the reader may not want to hear.","zh":"它後面通常接着讀者可能不想聽到的資料。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"visitors themselves","meaning":"訪客本人","examples":[{"en":"Visitors themselves are not permitted to eat inside the park.","zh":"訪客本人不獲准在公園內進食。"},{"en":"Visitors themselves emphasises the visitors personally, not their pets or other people.","zh":"visitors themselves 強調訪客本人，而不是他們的寵物或其他人。"},{"en":"Pets may eat snacks in the park, but visitors themselves must not eat there.","zh":"寵物可以在公園內吃小食，但訪客本人不得在那裡進食。"},{"en":"This phrase is useful when a rule applies to people directly and not to animals or objects.","zh":"當規則直接適用於人，而不是動物或物件時，這個片語很有用。"},{"en":"Adding “themselves” makes the contrast clearer.","zh":"加上 “themselves” 會令對比更清楚。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"be permitted to","meaning":"獲准……","examples":[{"en":"Visitors are not permitted to eat inside the park.","zh":"訪客不獲准在公園內進食。"},{"en":"To be permitted to do something means to be officially allowed to do it.","zh":"be permitted to do something 指正式獲准做某事。"},{"en":"Students are permitted to use calculators in this part of the exam.","zh":"學生在考試這部分獲准使用計算機。"},{"en":"If visitors are not permitted to enter an area, they may be asked to leave.","zh":"如果訪客不獲准進入某區域，他們可能會被要求離開。"},{"en":"Be permitted to is more formal than “can” or “may”.","zh":"be permitted to 比 “can” 或 “may” 更正式。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"eat inside","meaning":"在室內／園內進食","examples":[{"en":"Visitors are not permitted to eat inside the park.","zh":"訪客不獲准在公園內進食。"},{"en":"To eat inside means to have food indoors or within a particular area.","zh":"eat inside 指在室內或某個特定範圍內進食。"},{"en":"Students may eat outside the classroom, but they should not eat inside.","zh":"學生可以在課室外進食，但不應在室內進食。"},{"en":"Banning people from eating inside can help keep a place clean and safe.","zh":"禁止人們在室內進食，可以幫助保持地方清潔和安全。"},{"en":"Eat inside can refer to eating inside a building or inside a restricted venue.","zh":"eat inside 可以指在建築物內進食，也可以指在受限制場地內進食。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"opening ceremony","meaning":"開幕典禮","examples":[{"en":"The opening ceremony of the park will be held on 15 March.","zh":"該公園的開幕典禮將於 3 月 15 日舉行。"},{"en":"An opening ceremony is a formal event that marks the start or official launch of a place or project.","zh":"opening ceremony 指標誌某地方或項目正式開始的正式活動。"},{"en":"A school may invite parents to the opening ceremony of a new library.","zh":"學校可能會邀請家長出席新圖書館的開幕典禮。"},{"en":"An opening ceremony can attract guests, media attention, and public interest.","zh":"開幕典禮可以吸引嘉賓、傳媒關注和公眾興趣。"},{"en":"Unlike a normal visit, an opening ceremony usually includes speeches or special activities.","zh":"與普通參觀不同，開幕典禮通常包括演講或特別活動。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"be held on","meaning":"將於……舉行","examples":[{"en":"The opening ceremony will be held on 15 March.","zh":"開幕典禮將於 3 月 15 日舉行。"},{"en":"Be held on is used to say the date when an event will take place.","zh":"be held on 用來說明活動舉行的日期。"},{"en":"The school picnic will be held on 8 May.","zh":"學校野餐將於 5 月 8 日舉行。"},{"en":"If an event is held on a public holiday, more people may be able to attend.","zh":"如果活動於公眾假期舉行，可能有更多人能出席。"},{"en":"This phrase is common in notices, invitations, and formal announcements.","zh":"這個片語常見於告示、邀請信和正式公告。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"last for two hours","meaning":"歷時兩小時","examples":[{"en":"The opening ceremony will last for two hours.","zh":"開幕典禮將歷時兩小時。"},{"en":"To last for two hours means to continue for a period of two hours.","zh":"last for two hours 指持續兩小時。"},{"en":"The workshop will last for two hours, from 10 a.m. to noon.","zh":"工作坊將歷時兩小時，由上午十時至中午十二時。"},{"en":"If a talk lasts for two hours, organisers should include a short break.","zh":"如果講座歷時兩小時，主辦方應安排短暫休息。"},{"en":"This phrase tells visitors how much time they need to reserve.","zh":"這個片語告訴訪客需要預留多少時間。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"all visitors are welcome to","meaning":"歡迎所有訪客……","examples":[{"en":"All visitors are welcome to bring their pets to the ceremony.","zh":"歡迎所有訪客攜帶寵物出席典禮。"},{"en":"All visitors are welcome to means everyone is invited or allowed to do something.","zh":"all visitors are welcome to 指所有人都受邀或獲准做某事。"},{"en":"All visitors are welcome to take photos in the garden.","zh":"歡迎所有訪客在花園拍照。"},{"en":"Saying this can make an invitation sound friendly and open.","zh":"這種說法可以令邀請聽起來友善和開放。"},{"en":"However, visitors may still need to follow rules even if they are welcome to join.","zh":"然而，即使歡迎訪客參與，他們仍可能需要遵守規則。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"participate in","meaning":"參加","examples":[{"en":"Visitors are welcome to participate in the opening ceremony.","zh":"歡迎訪客參加開幕典禮。"},{"en":"To participate in something means to take part in an activity or event.","zh":"participate in something 指參加某活動或事件。"},{"en":"Students can participate in the school concert as singers, helpers, or audience members.","zh":"學生可以作為歌手、幫手或觀眾參加學校音樂會。"},{"en":"Participating in community events can help people feel more connected.","zh":"參加社區活動可以幫助人們感到更有連繫。"},{"en":"Participate in is more formal than “join in”.","zh":"participate in 比 “join in” 更正式。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"as for","meaning":"至於","examples":[{"en":"As for the activities, there will be several special programmes.","zh":"至於活動方面，將會有幾個特別節目。"},{"en":"As for is used to introduce a new topic or return to a particular point.","zh":"as for 用來引入新話題或回到某個特定重點。"},{"en":"As for transport, visitors can take the shuttle bus from the station.","zh":"至於交通，訪客可從車站乘搭穿梭巴士。"},{"en":"This phrase helps organise information in a letter or speech.","zh":"這個片語有助在信件或演講中組織資料。"},{"en":"As for is useful when answering several questions one by one.","zh":"當逐一回答幾個問題時，as for 很有用。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"there will be","meaning":"將會有……","examples":[{"en":"There will be a talk and several other activities.","zh":"將會有一場講座和幾項其他活動。"},{"en":"There will be is used to say that something is planned to happen or exist in the future.","zh":"there will be 用來表示將來計劃會發生或存在某事。"},{"en":"There will be free drinks after the workshop.","zh":"工作坊後將會有免費飲品。"},{"en":"If there will be many visitors, organisers should prepare enough staff.","zh":"如果將會有很多訪客，主辦方應準備足夠職員。"},{"en":"This phrase is common when introducing events, facilities, or arrangements.","zh":"這個片語常用於介紹活動、設施或安排。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":2},{"front":"a talk given by","meaning":"由……主講的講座","examples":[{"en":"There will be a talk given by our guest, Steven Choi.","zh":"將會有一場由我們的嘉賓 Steven Choi 主講的講座。"},{"en":"A talk given by someone is a speech or presentation delivered by that person.","zh":"a talk given by someone 指由某人發表的演講或講座。"},{"en":"Students attended a talk given by a doctor about healthy eating.","zh":"學生出席了一場由醫生主講的健康飲食講座。"},{"en":"A talk given by an expert can make an event more educational.","zh":"由專家主講的講座可以令活動更具教育意義。"},{"en":"This phrase is useful when naming the speaker of a talk.","zh":"這個片語在說明講座講者時很有用。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"guest speaker","meaning":"嘉賓講者","examples":[{"en":"Steven Choi will attend the ceremony as the guest speaker.","zh":"Steven Choi 將以嘉賓講者身份出席典禮。"},{"en":"A guest speaker is an invited person who gives a talk at an event.","zh":"guest speaker 指受邀在活動中發表演講的人。"},{"en":"The school invited a firefighter as the guest speaker for Safety Day.","zh":"學校邀請了一位消防員擔任安全日的嘉賓講者。"},{"en":"A good guest speaker can share real experience that ordinary organisers may not have.","zh":"優秀的嘉賓講者可以分享普通主辦方未必有的真實經驗。"},{"en":"A guest speaker is different from a host because the speaker usually gives a talk, not manages the whole event.","zh":"嘉賓講者與主持人不同，因為講者通常負責演講，而不是管理整個活動。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"dog-walking tips","meaning":"遛狗技巧","examples":[{"en":"A famous pet trainer will share dog-walking tips.","zh":"一位著名寵物訓練師將分享遛狗技巧。"},{"en":"Dog-walking tips are pieces of advice about how to walk a dog safely and properly.","zh":"dog-walking tips 指關於如何安全而適當地遛狗的建議。"},{"en":"Dog-walking tips may include using a leash, bringing water, and avoiding very hot ground.","zh":"遛狗技巧可能包括使用牽繩、帶水和避開很熱的地面。"},{"en":"Good dog-walking tips can prevent accidents between dogs, owners, and other visitors.","zh":"良好的遛狗技巧可以防止狗隻、主人和其他訪客之間發生意外。"},{"en":"New dog owners often need dog-walking tips because small mistakes can become habits.","zh":"新手狗主常需要遛狗技巧，因為小錯誤可能變成習慣。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"shared by","meaning":"由……分享","examples":[{"en":"Dog-walking tips will be shared by a famous pet trainer.","zh":"遛狗技巧將由一位著名寵物訓練師分享。"},{"en":"Shared by means given, explained, or presented by a particular person.","zh":"shared by 指由某個特定人士提供、解釋或介紹。"},{"en":"Study advice shared by older students can help younger students prepare for exams.","zh":"由高年級學生分享的溫習建議，可以幫助低年級學生準備考試。"},{"en":"Information shared by experts is often more trusted than rumours.","zh":"由專家分享的資料通常比傳言更可信。"},{"en":"This phrase is useful in passive sentences when the focus is on the information, not only the speaker.","zh":"當重點放在資料而不只是講者時，這個片語在被動句中很有用。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"famous pet trainer","meaning":"著名寵物訓練師","examples":[{"en":"Kevin Lin is a famous pet trainer.","zh":"Kevin Lin 是一位著名寵物訓練師。"},{"en":"A famous pet trainer is a well-known person who teaches animals and owners better behaviour.","zh":"famous pet trainer 指知名並教導動物和主人改善行為的人。"},{"en":"A famous pet trainer may appear on television to show how to train dogs safely.","zh":"著名寵物訓練師可能會上電視展示如何安全地訓練狗隻。"},{"en":"Inviting a famous pet trainer can attract pet owners to an event.","zh":"邀請著名寵物訓練師可以吸引寵物主人參加活動。"},{"en":"Fame alone is not enough; a pet trainer should also use kind and safe methods.","zh":"名氣本身並不足夠；寵物訓練師也應使用溫和而安全的方法。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, there will also be a prize-drawing game.","zh":"此外，亦將會有抽獎遊戲。"},{"en":"In addition is used to add another point or extra piece of information.","zh":"in addition 用來加入另一個重點或額外資料。"},{"en":"The library has new books; in addition, it now opens on Sundays.","zh":"圖書館有新書；此外，現在星期日也開放。"},{"en":"Using “in addition” helps a writer connect extra details smoothly.","zh":"使用 “in addition” 可以幫助作者順暢地連接額外細節。"},{"en":"In addition is more formal than “also” or “besides”.","zh":"in addition 比 “also” 或 “besides” 更正式。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"prize-drawing game","meaning":"抽獎遊戲","examples":[{"en":"The opening ceremony will include a prize-drawing game.","zh":"開幕典禮將包括抽獎遊戲。"},{"en":"A prize-drawing game is an activity where winners are chosen by chance to receive prizes.","zh":"prize-drawing game 指以隨機方式選出得獎者並頒發獎品的活動。"},{"en":"A school fair may hold a prize-drawing game to attract more visitors.","zh":"學校嘉年華可能會舉行抽獎遊戲來吸引更多訪客。"},{"en":"Prize-drawing games can make an event more exciting because people hope to win something.","zh":"抽獎遊戲可以令活動更刺激，因為人們希望贏得獎品。"},{"en":"Clear rules are needed so the prize-drawing game feels fair.","zh":"抽獎遊戲需要清楚規則，才會令人覺得公平。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"thank you very much for your interest in","meaning":"非常感謝你對……的關注","examples":[{"en":"Thank you very much for your interest in Mumbo Jumbo Pet-Friendly Park.","zh":"非常感謝你對 Mumbo Jumbo Pet-Friendly Park 的關注。"},{"en":"Thank you very much for your interest in something is a polite way to thank someone for wanting to know about it.","zh":"thank you very much for your interest in something 是禮貌感謝某人想了解某事的說法。"},{"en":"Thank you very much for your interest in our summer course.","zh":"非常感謝你對我們暑期課程的關注。"},{"en":"This phrase makes a reply sound warm and professional.","zh":"這個片語令回覆聽起來親切而專業。"},{"en":"It is often used at the beginning or end of an information letter.","zh":"它常用於資料信件的開首或結尾。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"should you have any further enquiries","meaning":"如你有任何進一步查詢","examples":[{"en":"Should you have any further enquiries, please contact us.","zh":"如你有任何進一步查詢，請聯絡我們。"},{"en":"Should you have any further enquiries means if you have any more questions.","zh":"should you have any further enquiries 指如果你有更多問題。"},{"en":"Should you have any further enquiries about the timetable, please email the school office.","zh":"如你對時間表有任何進一步查詢，請電郵校務處。"},{"en":"This phrase is formal and common in customer service replies.","zh":"這個片語較正式，常見於客戶服務回覆。"},{"en":"It invites the reader to ask more questions politely.","zh":"它禮貌地邀請讀者提出更多問題。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"do not hesitate to","meaning":"請不要猶豫……","examples":[{"en":"Please do not hesitate to contact us.","zh":"請不要猶豫聯絡我們。"},{"en":"Do not hesitate to means please feel free to do something without worry.","zh":"do not hesitate to 指請放心做某事，不用擔心。"},{"en":"If you need help with the form, do not hesitate to ask a staff member.","zh":"如果你填寫表格時需要幫助，請不要猶豫向職員查詢。"},{"en":"This phrase makes an offer of help sound polite and welcoming.","zh":"這個片語令提供幫助的語氣顯得有禮而親切。"},{"en":"It is often used in formal emails when the writer wants to sound helpful.","zh":"它常用於正式電郵中，表達作者願意提供協助。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"contact us","meaning":"聯絡我們","examples":[{"en":"Please contact us if you need more information.","zh":"如你需要更多資料，請聯絡我們。"},{"en":"To contact us means to get in touch with our organisation by phone, email, message, or another method.","zh":"contact us 指透過電話、電郵、訊息或其他方式與我們的機構取得聯繫。"},{"en":"Parents can contact us if their child loses something during the trip.","zh":"如果孩子在旅行期間遺失物品，家長可以聯絡我們。"},{"en":"Clear contact details help people contact us quickly when problems happen.","zh":"清楚的聯絡資料能幫助人們在問題發生時迅速聯絡我們。"},{"en":"“Contact us” is common on websites, notices, and formal letters.","zh":"“contact us” 常見於網站、告示和正式信件。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":3},{"front":"would be more than happy to","meaning":"非常樂意……","examples":[{"en":"We would be more than happy to provide further information.","zh":"我們非常樂意提供進一步資料。"},{"en":"Would be more than happy to means would be very willing and pleased to do something.","zh":"would be more than happy to 指非常願意並樂於做某事。"},{"en":"Our staff would be more than happy to show you around the centre.","zh":"我們的職員非常樂意帶你參觀中心。"},{"en":"This phrase sounds polite, warm, and helpful in customer service writing.","zh":"這個片語在客戶服務寫作中顯得有禮、親切和樂於幫忙。"},{"en":"It is stronger and friendlier than simply saying “we can”.","zh":"它比簡單說 “we can” 更強烈和友善。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":4},{"front":"provide further information","meaning":"提供進一步資料","examples":[{"en":"We would be more than happy to provide further information.","zh":"我們非常樂意提供進一步資料。"},{"en":"To provide further information means to give more details beyond what has already been given.","zh":"provide further information 指在已提供資料之外，再給予更多詳情。"},{"en":"The school can provide further information about fees after parents complete the form.","zh":"家長填妥表格後，學校可以提供關於費用的進一步資料。"},{"en":"Providing further information can prevent misunderstanding before people make a decision.","zh":"提供進一步資料可以在人們作決定前避免誤會。"},{"en":"This phrase is common when a letter cannot include every detail at once.","zh":"當信件無法一次過包括所有細節時，這個片語很常用。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":4},{"front":"thank you very much for your attention","meaning":"非常感謝你的關注","examples":[{"en":"Thank you very much for your attention.","zh":"非常感謝你的關注。"},{"en":"Thank you very much for your attention is a polite closing used to thank the reader for reading or listening.","zh":"thank you very much for your attention 是禮貌結語，用來感謝讀者閱讀或聽眾聆聽。"},{"en":"A speaker may end a presentation by saying, “Thank you very much for your attention.”","zh":"講者可能會以「非常感謝你的關注」結束簡報。"},{"en":"This phrase helps end a formal message respectfully.","zh":"這個片語有助以尊重語氣結束正式訊息。"},{"en":"It is suitable for letters, speeches, and notices, but may sound too formal in casual texts.","zh":"它適合用於信件、演講和告示，但在 casual 訊息中可能顯得太正式。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":4},{"front":"Yours sincerely","meaning":"謹啟（正式信件結尾）","examples":[{"en":"Yours sincerely, Debby Wong.","zh":"Debby Wong 謹啟。"},{"en":"Yours sincerely is a formal closing used before the writer’s name in a letter.","zh":"Yours sincerely 是正式信件中放在署名前的結尾用語。"},{"en":"In a formal letter to a named person, you can end with “Yours sincerely”.","zh":"在寫給具名收信人的正式信件中，可以用 “Yours sincerely” 作結。"},{"en":"Using the correct closing makes a letter look more professional.","zh":"使用正確結尾能令信件看起來更專業。"},{"en":"Yours sincerely is not usually used in messages to close friends.","zh":"Yours sincerely 通常不會用於寫給親密朋友的訊息。"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":4},{"front":"staff member","meaning":"職員","examples":[{"en":"Debby Wong is a staff member of Mumbo Jumbo Pet-Friendly Park.","zh":"Debby Wong 是 Mumbo Jumbo Pet-Friendly Park 的職員。"},{"en":"A staff member is a person who works for an organisation, company, school, or venue.","zh":"staff member 指在組織、公司、學校或場地工作的人。"},{"en":"If visitors are lost, they can ask a staff member for directions.","zh":"如果訪客迷路，可以向職員詢問方向。"},{"en":"Staff members help keep a place safe, organised, and welcoming.","zh":"職員幫助保持地方安全、有秩序和親切。"},{"en":"A staff member may answer questions, handle bookings, or explain rules to visitors.","zh":"職員可能會回答問題、處理預約或向訪客解釋規則"}],"source":"Flash Cards -實用文 - Letter of Reply.pdf","sourcePage":4}],"dse/paper-3/practical-english-writing/practical-formats/letter-of-request":[{"front":"I am writing to","meaning":"我寫信是為了……","examples":[{"en":"I am writing to discuss and request several new arrangements for the annual party.","zh":"我寫信是為了討論並請求年度聚會的幾項新安排。"},{"en":"“I am writing to” is used at the beginning of a formal email or letter to explain its purpose.","zh":"“I am writing to” 用於正式電郵或信件開首，用來解釋寫信目的。"},{"en":"I am writing to ask whether the school trip can be postponed because of the bad weather.","zh":"我寫信是為了查詢學校旅行可否因惡劣天氣而延期。"},{"en":"Using “I am writing to” makes the reason for the message clear from the first sentence.","zh":"使用 “I am writing to” 可以令訊息的目的在第一句已清楚表達。"},{"en":"In formal writing, “I am writing to” sounds more polite than starting directly with a demand.","zh":"在正式寫作中，“I am writing to” 比直接提出要求更有禮貌。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"discuss and request","meaning":"討論並請求","examples":[{"en":"I am writing to discuss and request several new arrangements.","zh":"我寫信是為了討論並請求幾項新安排。"},{"en":"To discuss and request something means to talk about an issue and formally ask for a change or action.","zh":"討論並請求某事意思是談論一個問題，並正式要求作出改動或行動。"},{"en":"A student may email a teacher to discuss and request extra time for an assignment.","zh":"學生可能會發電郵給老師，討論並請求延長功課期限。"},{"en":"If a plan has problems, staff may discuss and request new arrangements before the event.","zh":"如果計劃有問題，職員可能會在活動前討論並請求新安排。"},{"en":"This phrase is useful when you want to sound polite but still make a clear request.","zh":"當你想保持禮貌但又清楚提出要求時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"several new arrangements","meaning":"幾項新安排","examples":[{"en":"I am writing to request several new arrangements for the annual party.","zh":"我寫信是為了請求年度聚會的幾項新安排。"},{"en":"Several new arrangements means more than two new plans, changes or practical details.","zh":"幾項新安排意思是超過兩項新的計劃、改動或實際細節。"},{"en":"The school made several new arrangements after the sports day was moved indoors.","zh":"運動會改為室內舉行後，學校作出了幾項新安排。"},{"en":"Several new arrangements may be needed if the date, venue and guest list all change.","zh":"如果日期、場地和賓客名單都改變，可能需要幾項新安排。"},{"en":"This phrase is useful when the changes are not just one small adjustment.","zh":"當改動不只是一個小調整時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"annual party","meaning":"年度聚會","examples":[{"en":"The annual party will be held next month.","zh":"年度聚會將於下月舉行。"},{"en":"An annual party is a party that happens once every year.","zh":"年度聚會是每年舉行一次的聚會。"},{"en":"A company may hold an annual party to thank staff for their work during the year.","zh":"公司可能會舉行年度聚會，感謝員工一年來的工作。"},{"en":"Because an annual party happens only once a year, organisers often plan it carefully.","zh":"因為年度聚會一年只有一次，主辦方通常會仔細策劃。"},{"en":"An annual party can help classmates, colleagues or members celebrate together.","zh":"年度聚會可以幫助同學、同事或會員一起慶祝。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"to be held next month","meaning":"將於下月舉行","examples":[{"en":"The annual party is to be held next month.","zh":"年度聚會將於下月舉行。"},{"en":"To be held next month means an event is planned or scheduled to happen in the coming month.","zh":"將於下月舉行意思是活動已計劃或安排在下個月發生。"},{"en":"The school concert is to be held next month, so rehearsals have already started.","zh":"學校音樂會將於下月舉行，所以排練已經開始。"},{"en":"If an event is to be held next month, the organiser should confirm the venue soon.","zh":"如果活動將於下月舉行，主辦方應盡快確認場地。"},{"en":"This phrase is formal and is often used in notices, emails and announcements.","zh":"這個短語較正式，常用於通告、電郵和公告中。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"Firstly","meaning":"首先","examples":[{"en":"Firstly, I would like to enquire whether the date could be changed.","zh":"首先，我想查詢聚會日期可否更改。"},{"en":"Firstly is used to introduce the first point in a list or argument.","zh":"首先用來引入清單或論點中的第一點。"},{"en":"Firstly, the school should improve the lighting near the entrance.","zh":"首先，學校應改善入口附近的照明。"},{"en":"Using “Firstly” helps readers follow the order of your ideas more easily.","zh":"使用 “Firstly” 有助讀者更容易跟隨你的想法次序。"},{"en":"After “Firstly”, writers often continue with “Secondly” and “Finally”.","zh":"在 “Firstly” 之後，作者通常會接着使用 “Secondly” 和 “Finally”。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"I would like to enquire whether","meaning":"我想查詢是否……","examples":[{"en":"I would like to enquire whether the date of the party could be changed.","zh":"我想查詢聚會日期可否更改。"},{"en":"“I would like to enquire whether” is a polite formal way to ask if something is possible or true.","zh":"“I would like to enquire whether” 是一種有禮而正式的說法，用來詢問某事是否可能或真實。"},{"en":"I would like to enquire whether the meeting room is available next Friday.","zh":"我想查詢下星期五會議室是否可供使用。"},{"en":"This phrase is useful when you do not want your question to sound too direct or demanding.","zh":"當你不想問題聽起來太直接或像命令時，這個短語很有用。"},{"en":"In formal emails, it is softer than simply asking, “Can you change it?”","zh":"在正式電郵中，它比直接問「你可否更改？」更委婉。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"the date of the party","meaning":"聚會日期","examples":[{"en":"The date of the party may need to be changed.","zh":"聚會日期可能需要更改。"},{"en":"The date of the party means the day on which the party is planned to take place.","zh":"聚會日期意思是該聚會計劃舉行的日子。"},{"en":"Please check the date of the party before booking your flight.","zh":"預訂機票前，請先查看聚會日期。"},{"en":"If the date of the party clashes with exams, many students may not attend.","zh":"如果聚會日期與考試撞期，很多學生可能無法出席。"},{"en":"Confirming the date of the party early helps guests arrange their schedules.","zh":"及早確認聚會日期有助賓客安排日程。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"could be changed","meaning":"可否更改","examples":[{"en":"I would like to enquire whether the date could be changed.","zh":"我想查詢日期可否更改。"},{"en":"Could be changed means it might be possible to alter something, but permission or agreement is needed.","zh":"可否更改意思是某事可能可以改動，但需要許可或同意。"},{"en":"The lesson time could be changed if most students are unavailable.","zh":"如果大多數學生沒有空，課堂時間可否更改。"},{"en":"If the venue is too far away, the location could be changed to somewhere more convenient.","zh":"如果場地太遠，地點可否更改至更方便的地方。"},{"en":"This phrase sounds polite because it does not demand that the change must happen.","zh":"這個短語聽起來有禮貌，因為它不是強硬要求必須更改。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"unable to attend","meaning":"未能出席","examples":[{"en":"Most of the guests are unable to attend on the current date.","zh":"大部分賓客未能在現定日期出席。"},{"en":"Unable to attend means not able to go to an event, meeting or appointment.","zh":"未能出席意思是不能參加活動、會議或預約。"},{"en":"A student may be unable to attend a lesson because of illness.","zh":"學生可能因病未能出席課堂。"},{"en":"If many guests are unable to attend, the organiser may need to choose another date.","zh":"如果很多賓客未能出席，主辦方可能需要選擇另一個日期。"},{"en":"This phrase is more formal than saying someone “cannot come”.","zh":"這個短語比說某人 “cannot come” 更正式。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"on the current date","meaning":"在現定日期","examples":[{"en":"Most of the guests are unable to attend on the current date.","zh":"大部分賓客未能在現定日期出席。"},{"en":"On the current date means on the date that has already been chosen or arranged.","zh":"在現定日期意思是在已經選定或安排好的日期。"},{"en":"The interview cannot take place on the current date because the manager will be overseas.","zh":"面試不能在現定日期進行，因為經理將會在海外。"},{"en":"If too many people are busy on the current date, changing the date may improve attendance.","zh":"如果太多人在現定日期很忙，改期可能會提升出席率。"},{"en":"This phrase helps contrast the existing date with a possible new one.","zh":"這個短語有助把現有日期與可能的新日期作對比。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":1},{"front":"Secondly","meaning":"其次","examples":[{"en":"Secondly, would it be possible to replace the host?","zh":"其次，可否更換主持？"},{"en":"Secondly is used to introduce the second point in a list or argument.","zh":"其次用來引入清單或論點中的第二點。"},{"en":"Secondly, the company should choose a venue that is easier to reach.","zh":"其次，公司應選擇一個更容易到達的場地。"},{"en":"Using “Secondly” shows that the writer is moving to another related point.","zh":"使用 “Secondly” 顯示作者正轉到另一個相關重點。"},{"en":"This word helps organise formal writing so the reader does not feel lost.","zh":"這個詞有助整理正式寫作，令讀者不會迷失。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"the current host","meaning":"現任主持","examples":[{"en":"The current host has recently been involved in several scandals.","zh":"現任主持最近牽涉於幾宗醜聞。"},{"en":"The current host means the person who is presently chosen to lead or present the event.","zh":"現任主持意思是目前被選中負責主持或帶領活動的人。"},{"en":"The current host of the school ceremony is confident but sometimes speaks too quickly.","zh":"學校典禮的現任主持很有信心，但有時說話太快。"},{"en":"If the current host has a poor public image, the organiser may consider replacing him.","zh":"如果現任主持的公眾形象不佳，主辦方可能會考慮更換他。"},{"en":"This phrase contrasts the existing host with a possible new host.","zh":"這個短語把現有主持與可能的新主持作對比。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"has recently been involved in","meaning":"最近牽涉於……","examples":[{"en":"The current host has recently been involved in several scandals.","zh":"現任主持最近牽涉於幾宗醜聞。"},{"en":"Has recently been involved in means someone has taken part in or been connected with something not long ago.","zh":"最近牽涉於某事意思是某人在不久前參與或與某事有關。"},{"en":"The manager has recently been involved in a dispute about unfair working hours.","zh":"經理最近牽涉於一場關於不公平工時的爭議。"},{"en":"If a public figure has recently been involved in a scandal, the event may receive negative attention.","zh":"如果公眾人物最近牽涉於醜聞，活動可能會受到負面關注。"},{"en":"This phrase does not always mean the person is guilty, but it shows a connection to the matter.","zh":"這個短語不一定表示該人有罪，但顯示他與事件有關。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"several scandals","meaning":"幾宗醜聞","examples":[{"en":"The current host has recently been involved in several scandals.","zh":"現任主持最近牽涉於幾宗醜聞。"},{"en":"Several scandals means more than two public events that damage someone’s reputation.","zh":"幾宗醜聞意思是超過兩宗會損害某人聲譽的公開事件。"},{"en":"A company may lose customers after several scandals about product safety.","zh":"公司在幾宗產品安全醜聞後可能會失去顧客。"},{"en":"Several scandals can make people doubt whether a public figure is suitable for an event.","zh":"幾宗醜聞可以令人懷疑公眾人物是否適合出席活動。"},{"en":"This phrase suggests repeated reputation problems, not just one small mistake.","zh":"這個短語暗示反覆出現聲譽問題，而不只是一個小錯誤。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"would it be possible to","meaning":"可否……","examples":[{"en":"Would it be possible to replace him with a more suitable host?","zh":"可否以更合適的主持取代他？"},{"en":"“Would it be possible to” is a polite way to ask whether someone can do something.","zh":"“Would it be possible to” 是有禮地詢問某人是否可以做某事的說法。"},{"en":"Would it be possible to move the meeting to Friday afternoon?","zh":"可否把會議改到星期五下午？"},{"en":"This phrase is useful when the request may require effort or approval from another person.","zh":"當要求可能需要另一個人付出努力或批准時，這個短語很有用。"},{"en":"It sounds more respectful than saying, “Please do this now.”","zh":"它比說「請現在這樣做」更尊重對方。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"replace someone with","meaning":"以……取代某人","examples":[{"en":"Would it be possible to replace him with a more suitable host?","zh":"可否以更合適的主持取代他？"},{"en":"To replace someone with another person means to remove the first person from a role and choose another person instead.","zh":"以另一人取代某人意思是把原來的人從某個角色中移除，並選另一人代替。"},{"en":"The school may replace the absent speaker with a teacher who knows the topic well.","zh":"學校可能會以一位熟悉主題的老師取代缺席講者。"},{"en":"If a staff member leaves suddenly, the company must replace them with someone reliable.","zh":"如果員工突然離職，公司必須以可靠的人取代他。"},{"en":"This phrase is useful when discussing changes in roles, jobs or event arrangements.","zh":"這個短語適合用於討論角色、工作或活動安排的改動。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"a more suitable host","meaning":"更合適的主持","examples":[{"en":"The organiser hopes to replace him with a more suitable host.","zh":"主辦方希望以更合適的主持取代他。"},{"en":"A more suitable host is a person who fits the event better than the current host.","zh":"更合適的主持是比現任主持更配合活動的人。"},{"en":"A children’s party needs a more suitable host if the original host is not good with children.","zh":"如果原本主持不擅長與兒童互動，兒童派對就需要更合適的主持。"},{"en":"Choosing a more suitable host can make guests feel more comfortable and interested.","zh":"選擇更合適的主持可以令賓客感到更舒服和更有興趣。"},{"en":"Suitability may depend on image, speaking skills, experience and audience expectations.","zh":"是否合適可能取決於形象、說話技巧、經驗和觀眾期望。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"Finally","meaning":"最後","examples":[{"en":"Finally, it would be greatly appreciated if the venue could also be changed.","zh":"最後，如場地也能更改，將不勝感激。"},{"en":"Finally is used to introduce the last point in a list or argument.","zh":"最後用來引入清單或論點中的最後一點。"},{"en":"Finally, please send the updated schedule to all participants before Monday.","zh":"最後，請在星期一前把更新後的時間表發給所有參加者。"},{"en":"Using “Finally” tells the reader that the writer is reaching the last main request.","zh":"使用 “Finally” 告訴讀者，作者正提出最後一個主要要求。"},{"en":"This word helps a formal email end its list of points clearly.","zh":"這個詞有助正式電郵清楚結束重點清單。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"it would be greatly appreciated if","meaning":"如能……將不勝感激","examples":[{"en":"It would be greatly appreciated if the venue could also be changed.","zh":"如場地也能更改，將不勝感激。"},{"en":"“It would be greatly appreciated if” is a very polite way to make a request.","zh":"“It would be greatly appreciated if” 是一種非常有禮貌地提出要求的說法。"},{"en":"It would be greatly appreciated if the report could be submitted by Friday.","zh":"如能在星期五前提交報告，將不勝感激。"},{"en":"This phrase softens the request and shows respect for the reader’s effort.","zh":"這個短語令請求較委婉，並表示尊重讀者的付出。"},{"en":"It is often used in formal emails when asking someone to do something helpful.","zh":"它常用於正式電郵中，向別人請求協助。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"the venue","meaning":"場地","examples":[{"en":"The venue could also be changed.","zh":"場地也可以更改。"},{"en":"The venue is the place where an event, meeting or performance happens.","zh":"場地是活動、會議或表演舉行的地方。"},{"en":"The school hall is a suitable venue for the graduation ceremony.","zh":"學校禮堂是畢業典禮的合適場地。"},{"en":"If the venue is too small, guests may feel crowded and uncomfortable.","zh":"如果場地太小，賓客可能會覺得擠迫和不舒服。"},{"en":"Choosing the right venue can affect transport, cost and the overall atmosphere.","zh":"選擇合適場地會影響交通、成本和整體氣氛。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"considered inconvenient","meaning":"被認為不方便","examples":[{"en":"The current venue is considered inconvenient by many guests.","zh":"現有場地被很多賓客認為不方便。"},{"en":"Considered inconvenient means people think something is difficult to use, reach or arrange.","zh":"被認為不方便意思是人們覺得某事難以使用、到達或安排。"},{"en":"A meeting time may be considered inconvenient if it clashes with most workers’ lunch break.","zh":"如果會議時間與大多數員工的午飯時間撞期，它可能被認為不方便。"},{"en":"If a venue is considered inconvenient, fewer guests may attend the event.","zh":"如果場地被認為不方便，出席活動的賓客可能會較少。"},{"en":"This phrase is often used politely instead of directly saying something is badly chosen.","zh":"這個短語常用作較有禮貌的說法，而不是直接說某事安排得差。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":2},{"front":"by many guests","meaning":"被很多賓客","examples":[{"en":"The current venue is considered inconvenient by many guests.","zh":"現有場地被很多賓客認為不方便。"},{"en":"By many guests means according to the opinions or experiences of a large number of invited people.","zh":"被很多賓客意思是根據大量受邀人士的意見或經驗。"},{"en":"The hotel was praised by many guests because the staff were helpful.","zh":"酒店被很多賓客稱讚，因為職員很樂於助人。"},{"en":"If a problem is mentioned by many guests, the organiser should take it seriously.","zh":"如果問題被很多賓客提及，主辦方應認真看待。"},{"en":"This phrase shows that the opinion is shared by more than just one person.","zh":"這個短語顯示該意見不只是由一個人提出。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"Please note that","meaning":"請注意","examples":[{"en":"Please note that the revised arrangements should be forwarded to the boss.","zh":"請注意，修訂後的安排應轉交給老闆。"},{"en":"Please note that is used to draw attention to important information.","zh":"請注意用來提醒讀者留意重要資料。"},{"en":"Please note that the library will close early this Friday.","zh":"請注意，圖書館本星期五將提早關閉。"},{"en":"This phrase helps make sure readers do not miss an instruction, warning or deadline.","zh":"這個短語有助確保讀者不會錯過指示、警告或期限。"},{"en":"It is common in formal emails, notices and announcements.","zh":"它常見於正式電郵、通告和公告。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"revised arrangements","meaning":"修訂後的安排","examples":[{"en":"The revised arrangements should be forwarded to the boss.","zh":"修訂後的安排應轉交給老闆。"},{"en":"Revised arrangements are plans or details that have been changed after review.","zh":"修訂後的安排是經檢討後已作改動的計劃或細節。"},{"en":"The revised arrangements for the picnic include a new meeting time and indoor backup plan.","zh":"野餐的修訂後安排包括新的集合時間和室內後備方案。"},{"en":"If revised arrangements are not shared clearly, people may follow the old plan by mistake.","zh":"如果修訂後的安排沒有清楚分享，人們可能會錯誤跟從舊計劃。"},{"en":"This phrase is useful when an event has already been planned but needs updates.","zh":"當活動已經計劃好但需要更新時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"forwarded to","meaning":"轉交給……","examples":[{"en":"The revised arrangements should be forwarded to the boss.","zh":"修訂後的安排應轉交給老闆。"},{"en":"Forwarded to someone means sent on to that person, usually after receiving it from someone else.","zh":"轉交給某人意思是把資料傳送給那個人，通常是在自己收到後再傳給對方。"},{"en":"The teacher forwarded the parent’s email to the school office.","zh":"老師把家長的電郵轉交給校務處。"},{"en":"If the document is forwarded to the wrong person, private information may be exposed.","zh":"如果文件被轉交給錯誤的人，私人資料可能會外洩。"},{"en":"This phrase is common in workplace emails when information needs to be passed along.","zh":"當資料需要傳遞時，這個短語常見於工作電郵中。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"informed of","meaning":"獲告知……","examples":[{"en":"The boss should be informed of the changes.","zh":"老闆應獲告知相關改動。"},{"en":"To be informed of something means to be told about important news, facts or updates.","zh":"獲告知某事意思是被通知重要消息、事實或更新。"},{"en":"Parents should be informed of any changes to the school bus schedule.","zh":"家長應獲告知校車時間表的任何改動。"},{"en":"If staff are not informed of new rules, they may continue using old procedures.","zh":"如果職員沒有獲告知新規則，他們可能會繼續使用舊程序。"},{"en":"This phrase sounds formal and is often used in office communication.","zh":"這個短語聽起來較正式，常用於辦公室溝通。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"the changes","meaning":"相關改動","examples":[{"en":"The boss should be informed of the changes.","zh":"老闆應獲告知相關改動。"},{"en":"The changes are the parts of a plan, rule or arrangement that have been altered.","zh":"相關改動是計劃、規則或安排中已被修改的部分。"},{"en":"Students need to know the changes to the exam timetable before they start revising.","zh":"學生在開始溫習前需要知道考試時間表的相關改動。"},{"en":"If the changes are not explained clearly, people may become confused or make mistakes.","zh":"如果相關改動沒有清楚解釋，人們可能會感到困惑或犯錯。"},{"en":"This phrase usually refers to updates that are already known in the context.","zh":"這個短語通常指上下文中已知的更新內容。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"In addition","meaning":"此外","examples":[{"en":"In addition, the above-mentioned arrangements will be reported to all senior managers.","zh":"此外，上述安排將向全體高級經理匯報。"},{"en":"In addition is used to add another point or piece of information.","zh":"此外用來加入另一個重點或一項資料。"},{"en":"The library will extend its opening hours; in addition, more study rooms will be available.","zh":"圖書館將延長開放時間；此外，將有更多自修室可供使用。"},{"en":"Using “In addition” helps connect related ideas smoothly.","zh":"使用 “In addition” 有助順暢連接相關想法。"},{"en":"This phrase is more formal than simply saying “also”.","zh":"這個短語比單純說 “also” 更正式。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"above-mentioned arrangements","meaning":"上述安排","examples":[{"en":"The above-mentioned arrangements will be reported to all senior managers.","zh":"上述安排將向全體高級經理匯報。"},{"en":"Above-mentioned arrangements are the plans or changes already mentioned earlier in the letter or document.","zh":"上述安排是信件或文件較早前已提及的計劃或改動。"},{"en":"The above-mentioned arrangements include the new venue, new date and updated guest list.","zh":"上述安排包括新場地、新日期和更新後的賓客名單。"},{"en":"Referring to above-mentioned arrangements avoids repeating the same long details again.","zh":"提及上述安排可以避免再次重複同一串長細節。"},{"en":"This phrase is formal and is usually used in written communication.","zh":"這個短語較正式，通常用於書面溝通。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"reported to","meaning":"向……匯報","examples":[{"en":"The arrangements will be reported to all senior managers.","zh":"相關安排將向全體高級經理匯報。"},{"en":"Reported to someone means formally told or presented to that person or group.","zh":"向某人匯報意思是正式告知或向該人或群體呈報。"},{"en":"The accident must be reported to the school office immediately.","zh":"意外必須立即向校務處匯報。"},{"en":"If a serious problem is reported to managers early, they can act before it gets worse.","zh":"如果嚴重問題及早向經理匯報，他們就能在情況惡化前採取行動。"},{"en":"This phrase is common when information needs to reach people with responsibility.","zh":"當資料需要傳達給有責任的人時，這個短語很常用。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"all senior managers","meaning":"全體高級經理","examples":[{"en":"The arrangements will be reported to all senior managers at the next meeting.","zh":"相關安排將在下次會議上向全體高級經理匯報。"},{"en":"All senior managers means every manager at a high level in an organisation.","zh":"全體高級經理意思是機構中每一位高層管理人員。"},{"en":"All senior managers should be informed before a major company policy changes.","zh":"在重大公司政策改變前，全體高級經理都應獲告知。"},{"en":"If all senior managers agree on a plan, it may be easier to carry it out smoothly.","zh":"如果全體高級經理同意一項計劃，執行起來可能會更順利。"},{"en":"This phrase suggests the matter is important enough for top management to know.","zh":"這個短語暗示事情重要到需要讓高層管理人員知道。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"at the next meeting","meaning":"在下次會議上","examples":[{"en":"The arrangements will be reported at the next meeting.","zh":"相關安排將在下次會議上匯報。"},{"en":"At the next meeting means during the next scheduled discussion or formal gathering.","zh":"在下次會議上意思是在下一次已安排的討論或正式聚會期間。"},{"en":"The teacher will explain the new exam rules at the next meeting.","zh":"老師將在下次會議上解釋新的考試規則。"},{"en":"If a decision is delayed until the next meeting, staff may have to wait for approval.","zh":"如果決定延至下次會議，職員可能要等待批准。"},{"en":"This phrase gives a clear time for when information will be discussed.","zh":"這個短語清楚交代資料會在甚麼時候討論。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":3},{"front":"express my deepest gratitude","meaning":"表達最深切謝意","examples":[{"en":"I would like to express my deepest gratitude for your hard work.","zh":"我想為你的辛勤工作表達最深切謝意。"},{"en":"To express my deepest gratitude means to say that I am extremely thankful.","zh":"表達最深切謝意意思是說明自己非常感激。"},{"en":"I would like to express my deepest gratitude to the volunteers who stayed late to help.","zh":"我想向留下來幫忙到很晚的義工表達最深切謝意。"},{"en":"This phrase is used when someone’s effort has been very valuable or meaningful.","zh":"當某人的付出非常有價值或有意義時，會使用這個短語。"},{"en":"It is more formal and emotional than simply saying “thank you”.","zh":"它比單純說「謝謝」更正式，也更有情感。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"deepest gratitude","meaning":"最深切的謝意","examples":[{"en":"I would like to express my deepest gratitude for your hard work.","zh":"我想為你的辛勤工作表達最深切的謝意。"},{"en":"Deepest gratitude means very strong and sincere thanks.","zh":"最深切的謝意意思是非常強烈而真誠的感謝。"},{"en":"The family expressed their deepest gratitude to the doctors who saved their child.","zh":"那個家庭向拯救孩子的醫生表達最深切的謝意。"},{"en":"Deepest gratitude is suitable when ordinary thanks may not feel enough.","zh":"當普通感謝似乎不足夠時，最深切的謝意就很合適。"},{"en":"This phrase is formal, so it fits speeches, letters and serious messages.","zh":"這個短語較正式，適合演講、信件和嚴肅訊息。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"hard work","meaning":"辛勤工作；努力","examples":[{"en":"Thank you for your hard work on the new arrangements.","zh":"感謝你在新安排上的辛勤工作。"},{"en":"Hard work means serious effort, time and energy spent on a task.","zh":"辛勤工作意思是在任務上付出認真的努力、時間和精力。"},{"en":"Students need hard work and regular practice to improve their writing.","zh":"學生需要努力和定期練習才能改善寫作。"},{"en":"Hard work can lead to better results when it is guided by clear goals.","zh":"當努力由清楚目標引導時，可以帶來更好成果。"},{"en":"Thanking people for their hard work shows that their effort has been noticed.","zh":"感謝別人的努力，表示你注意到他們的付出。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"should you have any questions","meaning":"如你有任何疑問","examples":[{"en":"Should you have any questions, please do not hesitate to contact me.","zh":"如你有任何疑問，請不要猶豫聯絡我。"},{"en":"Should you have any questions means if you have any questions.","zh":"如你有任何疑問意思是如果你有任何問題。"},{"en":"Should you have any questions about the timetable, please ask the class teacher.","zh":"如你對時間表有任何疑問，請詢問班主任。"},{"en":"This phrase sounds formal and polite, so it is common in business emails.","zh":"這個短語聽起來正式而有禮，所以常見於商業電郵。"},{"en":"It reassures the reader that questions are welcome, not troublesome.","zh":"它令讀者放心，知道提出問題是受歡迎的，而不是麻煩。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"please do not hesitate to","meaning":"請不要猶豫去……","examples":[{"en":"Please do not hesitate to contact me.","zh":"請不要猶豫聯絡我。"},{"en":"Please do not hesitate to means please feel free to do something without worry or delay.","zh":"請不要猶豫去做某事意思是請放心並不用延誤地去做。"},{"en":"Please do not hesitate to ask for help if you do not understand the instructions.","zh":"如果你不明白指示，請不要猶豫尋求幫助。"},{"en":"This phrase encourages the reader to take action when they need support.","zh":"這個短語鼓勵讀者在需要支援時採取行動。"},{"en":"It is a polite closing phrase often used in formal letters and emails.","zh":"它是正式信件和電郵中常用的有禮結尾語。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"contact me","meaning":"聯絡我","examples":[{"en":"Please do not hesitate to contact me.","zh":"請不要猶豫聯絡我。"},{"en":"To contact me means to get in touch with me by phone, email, message or another method.","zh":"聯絡我意思是透過電話、電郵、訊息或其他方式與我取得聯繫。"},{"en":"If your address changes, please contact me before Friday.","zh":"如果你的地址有變，請在星期五前聯絡我。"},{"en":"Contacting me early can help solve small problems before they become serious.","zh":"及早聯絡我可以幫助在小問題變嚴重前解決它。"},{"en":"This phrase is useful when you want readers to know you are available for follow-up.","zh":"當你想讓讀者知道可以跟進找你時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"I would be more than happy to","meaning":"我非常樂意……","examples":[{"en":"I would be more than happy to provide you with further information.","zh":"我非常樂意向你提供進一步資料。"},{"en":"I would be more than happy to means I would gladly do something.","zh":"我非常樂意做某事意思是我很願意並高興地做該事。"},{"en":"I would be more than happy to explain the application process after class.","zh":"我非常樂意在課後解釋申請程序。"},{"en":"This phrase sounds warm and helpful, especially in formal customer service or work emails.","zh":"這個短語聽起來溫暖而樂於助人，尤其適合正式客戶服務或工作電郵。"},{"en":"It shows that the writer is willing to help, not just doing the minimum.","zh":"它顯示作者願意幫忙，而不只是做最低限度。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"provide someone with","meaning":"向某人提供……","examples":[{"en":"I would be more than happy to provide you with further information.","zh":"我非常樂意向你提供進一步資料。"},{"en":"To provide someone with something means to give that person what they need or ask for.","zh":"向某人提供某物意思是給那個人所需或所要求的東西。"},{"en":"The school provides students with textbooks at the start of the term.","zh":"學校在學期開始時向學生提供課本。"},{"en":"Providing staff with clear instructions can prevent mistakes during an event.","zh":"向職員提供清楚指示可以防止活動中出錯。"},{"en":"This phrase is common in formal writing when talking about giving help, materials or information.","zh":"這個短語常見於正式寫作中，用來談及提供幫助、材料或資料。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"further information","meaning":"進一步資料","examples":[{"en":"I would be more than happy to provide you with further information.","zh":"我非常樂意向你提供進一步資料。"},{"en":"Further information means extra details that help someone understand something more clearly.","zh":"進一步資料意思是能幫助某人更清楚理解某事的額外細節。"},{"en":"Please visit the school office if you need further information about the exchange programme.","zh":"如果你需要交流計劃的進一步資料，請到校務處查詢。"},{"en":"Further information can help people make better decisions before joining an event.","zh":"進一步資料可以幫助人們在參加活動前作出更好決定。"},{"en":"This phrase is often used at the end of formal emails to offer more details if needed.","zh":"這個短語常用於正式電郵結尾，表示如有需要可提供更多細節。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"I look forward to","meaning":"我期待……","examples":[{"en":"I look forward to seeing you at the upcoming annual party.","zh":"我期待在即將舉行的年度聚會上見到你。"},{"en":"I look forward to means I am pleased or excited about something that will happen later.","zh":"我期待某事意思是我對稍後會發生的事感到高興或期待。"},{"en":"I look forward to meeting the new team members next Monday.","zh":"我期待下星期一見到新的團隊成員。"},{"en":"This phrase is often used in formal endings to sound positive and polite.","zh":"這個短語常用於正式結尾，令語氣正面而有禮。"},{"en":"After “look forward to”, use a noun or a verb ending in -ing, such as “meeting” or “seeing”.","zh":"在 “look forward to” 之後，應使用名詞或 -ing 形式動詞，例如 “meeting” 或 “seeing”。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"upcoming annual party","meaning":"即將舉行的年度聚會","examples":[{"en":"I look forward to seeing you at the upcoming annual party.","zh":"我期待在即將舉行的年度聚會上見到你。"},{"en":"The upcoming annual party is the yearly party that will happen soon.","zh":"即將舉行的年度聚會是很快會發生的一年一度聚會。"},{"en":"Staff are preparing decorations for the upcoming annual party.","zh":"職員正在為即將舉行的年度聚會準備裝飾。"},{"en":"If the upcoming annual party is important, guests should receive the final details early.","zh":"如果即將舉行的年度聚會很重要，賓客應及早收到最終細節。"},{"en":"This phrase reminds readers that the event is near and happens once a year.","zh":"這個短語提醒讀者活動快將舉行，而且一年一次。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":4},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"The letter ends with “Yours sincerely”.","zh":"這封信以 “Yours sincerely” 作結。"},{"en":"Yours sincerely is a formal closing used at the end of a letter or email when the writer knows the recipient’s name.","zh":"“Yours sincerely” 是在寫信人知道收信人姓名時，用於信件或電郵結尾的正式結語。"},{"en":"A job application letter may end with “Yours sincerely” before the writer’s name.","zh":"求職信可能會在寫信人姓名前以 “Yours sincerely” 作結。"},{"en":"Using the right closing helps a formal letter sound polite and complete.","zh":"使用合適結語有助正式信件顯得有禮而完整。"},{"en":"“Yours sincerely” is more formal than “Best” or “Cheers”.","zh":"“Yours sincerely” 比 “Best” 或 “Cheers” 更正式。"}],"source":"Flash Cards -實用文 - Letter Of Request.pdf","sourcePage":5}],"dse/paper-3/practical-english-writing/practical-formats/letter-of-request-informal":[{"front":"informal / encouraging and positive","meaning":"非正式、鼓勵而正面的語氣","examples":[{"en":"The letter is written in an informal, encouraging and positive tone.","zh":"這封信以非正式、鼓勵而正面的語氣撰寫。"},{"en":"An informal, encouraging and positive tone sounds friendly, supportive, and hopeful rather than strict or cold.","zh":"informal, encouraging and positive tone 指語氣友善、支持和充滿希望，而不是嚴厲或冷淡。"},{"en":"A teacher may use an informal, encouraging and positive tone when giving feedback to a nervous student.","zh":"老師向緊張的學生提供回饋時，可能會使用非正式、鼓勵而正面的語氣。"},{"en":"This tone can make the reader feel more confident, even when changes are needed.","zh":"這種語氣可以令讀者更有信心，即使需要作出修改。"},{"en":"It is suitable for friendly advice, but not for very serious warnings or legal notices.","zh":"它適合用於友善建議，但不適合非常嚴肅的警告或法律告示。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"How are you doing?","meaning":"你最近怎樣？","examples":[{"en":"Hey Angie, how are you doing?","zh":"嘿，Angie，你最近怎樣？"},{"en":"How are you doing? is a friendly way to ask someone how they are or how things are going.","zh":"How are you doing? 是友善地詢問對方近況或事情進展的說法。"},{"en":"A friend may ask, “How are you doing?” after not seeing you for a few weeks.","zh":"朋友幾星期沒見你後，可能會問：「你最近怎樣？」"},{"en":"This question can make a message sound warm before discussing work or problems.","zh":"這個問題可以令訊息在討論工作或問題前顯得親切。"},{"en":"It is more casual than “How do you do?” and is common in everyday conversation.","zh":"它比 “How do you do?” 較隨意，常見於日常對話。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"first of all","meaning":"首先","examples":[{"en":"First of all, thank you very much for your hard work.","zh":"首先，非常感謝你付出的努力。"},{"en":"First of all is used to introduce the first point in a message or speech.","zh":"first of all 用來引入訊息或演說中的第一個重點。"},{"en":"First of all, please check your name on the form before answering the questions.","zh":"首先，請在回答問題前檢查表格上的姓名。"},{"en":"Using “first of all” helps readers follow the order of your ideas.","zh":"使用 “first of all” 可幫助讀者跟上你的思路次序。"},{"en":"It is useful when you want to begin with the most important or polite point.","zh":"當你想以最重要或最有禮貌的重點開始時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"thank you very much for","meaning":"非常感謝你……","examples":[{"en":"Thank you very much for your hard work on the video.","zh":"非常感謝你在影片方面付出的努力。"},{"en":"Thank you very much for is a polite way to show strong gratitude for something someone has done.","zh":"thank you very much for 是禮貌地對某人所做的事表達深切感謝的說法。"},{"en":"Thank you very much for helping me prepare for the interview.","zh":"非常感謝你幫我準備面試。"},{"en":"This phrase can make the other person feel appreciated before you give suggestions.","zh":"這個片語可以在你提出建議前，令對方感到被欣賞。"},{"en":"It is more formal and warmer than simply saying “thanks”.","zh":"它比簡單說 “thanks” 更正式和溫暖。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"hard work on","meaning":"在……方面付出的努力","examples":[{"en":"Thank you very much for your hard work on the video.","zh":"非常感謝你在影片方面付出的努力。"},{"en":"Hard work on something means the time, effort, and care someone has put into that task.","zh":"hard work on something 指某人在某項任務中投入的時間、努力和心思。"},{"en":"The class thanked the monitor for her hard work on the charity sale.","zh":"全班感謝班長在慈善義賣方面付出的努力。"},{"en":"Hard work on a project often leads to better results, even if revisions are still needed.","zh":"在項目方面付出的努力通常會帶來更好成果，即使仍需要修改。"},{"en":"Praising someone’s hard work on a task can encourage them to keep improving.","zh":"稱讚某人在任務方面付出的努力，可以鼓勵他繼續進步。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"short video competition","meaning":"短片比賽","examples":[{"en":"Angie made a video for the short video competition.","zh":"Angie 為短片比賽製作了一段影片。"},{"en":"A short video competition is a contest where people submit brief videos to be judged.","zh":"short video competition 指參賽者提交短影片讓評判評審的比賽。"},{"en":"A school may hold a short video competition to promote reading or environmental protection.","zh":"學校可能會舉辦短片比賽來推廣閱讀或環保。"},{"en":"Rules for a short video competition often include a time limit and a theme.","zh":"短片比賽的規則通常包括時間限制和主題。"},{"en":"A good short video competition rewards clear messages, creativity, and technical quality.","zh":"好的短片比賽會獎勵清晰訊息、創意和技術質素。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"I am writing to","meaning":"我寫信是為了……","examples":[{"en":"I am writing to update you on a few changes.","zh":"我寫信是為了向你交代幾項修改。"},{"en":"I am writing to is a formal or semi-formal way to explain the purpose of a letter or email.","zh":"I am writing to 是正式或半正式地說明信件或電郵目的的說法。"},{"en":"I am writing to ask about the application deadline.","zh":"我寫信是為了查詢申請截止日期。"},{"en":"This phrase helps the reader understand the reason for the message immediately.","zh":"這個片語幫助讀者立刻理解訊息的原因。"},{"en":"It is useful in letters, but it may sound too formal in casual texting.","zh":"它適合用於信件，但在 casual 短訊中可能顯得太正式。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"update someone on","meaning":"向某人交代／更新……","examples":[{"en":"I am writing to update you on a few changes to the poster.","zh":"我寫信是為了向你交代海報的幾項修改。"},{"en":"To update someone on something means to tell them the latest information about it.","zh":"update someone on something 指向某人提供某事的最新資料。"},{"en":"The class teacher updated parents on the school trip arrangements.","zh":"班主任向家長更新學校旅行安排。"},{"en":"Updating team members on changes prevents confusion and repeated questions.","zh":"向團隊成員交代變更，可以避免混亂和重複提問。"},{"en":"A short email can update someone on progress without needing a meeting.","zh":"一封簡短電郵可以向某人更新進度，而不需要開會。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"a few changes to","meaning":"對……作出的幾項修改","examples":[{"en":"There are a few changes to the poster you designed.","zh":"你設計的海報有幾項修改。"},{"en":"A few changes to something means a small number of modifications made to it.","zh":"a few changes to something 指對某物作出少量修改。"},{"en":"There are a few changes to the timetable because one teacher is absent.","zh":"由於有一位老師缺席，時間表有幾項修改。"},{"en":"A few changes to a design can make it clearer and easier to read.","zh":"對設計作出幾項修改，可以令它更清楚和更易閱讀。"},{"en":"This phrase suggests the work is not completely wrong, but some parts need adjustment.","zh":"這個片語暗示作品並非完全錯誤，只是有些部分需要調整。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"as well as","meaning":"以及","examples":[{"en":"The letter discusses the poster as well as the video.","zh":"這封信討論海報以及影片。"},{"en":"As well as means in addition to another thing already mentioned.","zh":"as well as 指除了已提及的事物之外，還包括另一事物。"},{"en":"The course teaches speaking as well as writing.","zh":"這個課程教授說話以及寫作。"},{"en":"Using “as well as” helps connect two related items in one sentence.","zh":"使用 “as well as” 可以在一句中連接兩個相關項目。"},{"en":"It is often used when both things are important, not only the first one.","zh":"當兩件事都重要，而不只是第一件事重要時，這個片語常會使用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"details regarding","meaning":"關於……的詳情","examples":[{"en":"The letter includes details regarding Angie’s submitted video.","zh":"這封信包括關於 Angie 已提交影片的詳情。"},{"en":"Details regarding something are specific pieces of information about that topic.","zh":"details regarding something 指關於某主題的具體資料。"},{"en":"The notice gives details regarding the exam venue and starting time.","zh":"告示提供關於考試場地和開始時間的詳情。"},{"en":"Clear details regarding a task help people avoid mistakes.","zh":"關於任務的清楚詳情可以幫助人們避免錯誤。"},{"en":"This phrase is common in formal messages when the writer introduces information about a subject.","zh":"這個片語常見於正式訊息中，用來引入關於某主題的資料。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":1},{"front":"submitted video","meaning":"已提交的影片","examples":[{"en":"Simon mentions some details regarding Angie’s submitted video.","zh":"Simon 提及一些關於 Angie 已提交影片的詳情。"},{"en":"A submitted video is a video that has already been sent in for checking, judging, or approval.","zh":"submitted video 指已經提交作檢查、評審或審批的影片。"},{"en":"A student cannot edit a submitted video unless the teacher allows changes.","zh":"除非老師容許修改，否則學生不能編輯已提交的影片。"},{"en":"If a submitted video breaks the rules, the participant may need to revise it.","zh":"如果已提交的影片違反規則，參賽者可能需要修改它。"},{"en":"This phrase is often used in competitions, assignments, and online applications.","zh":"這個片語常用於比賽、功課和網上申請。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"regarding","meaning":"關於","examples":[{"en":"Regarding the poster, Simon suggests changing the image.","zh":"關於海報，Simon 建議更改圖片。"},{"en":"Regarding means about or concerning a particular matter.","zh":"regarding 指關於某個特定事項。"},{"en":"Regarding your application, we need one more document.","zh":"關於你的申請，我們需要多一份文件。"},{"en":"This word helps organise a message by clearly naming the topic.","zh":"這個字透過清楚指出主題，幫助組織訊息。"},{"en":"Regarding is more formal than “about” and is common in emails.","zh":"regarding 比 “about” 更正式，常見於電郵。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"would it be possible to","meaning":"可否……？","examples":[{"en":"Would it be possible to change the image in the centre?","zh":"可否更改中央的圖片？"},{"en":"Would it be possible to is a polite way to ask whether someone can do something.","zh":"would it be possible to 是禮貌詢問對方能否做某事的說法。"},{"en":"Would it be possible to meet after school instead of during lunch?","zh":"可否改為放學後見面，而不是午飯時間？"},{"en":"This phrase softens a request and makes it sound less demanding.","zh":"這個片語能緩和請求，令語氣不那麼像命令。"},{"en":"It is useful when asking someone to make a change or do extra work.","zh":"當請對方作出修改或做額外工作時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"change the image in the centre","meaning":"更改中央的圖片","examples":[{"en":"Simon asks Angie to change the image in the centre.","zh":"Simon 要求 Angie 更改中央的圖片。"},{"en":"To change the image in the centre means to replace or alter the picture placed in the middle.","zh":"change the image in the centre 指替換或修改放在中間的圖片。"},{"en":"A designer may change the image in the centre if it does not match the theme.","zh":"如果圖片不符合主題，設計師可能會更改中央的圖片。"},{"en":"Changing the central image can affect the whole look of a poster.","zh":"更改中央的圖片可能影響整張海報的外觀。"},{"en":"This instruction is specific because it tells the designer exactly which image needs attention.","zh":"這項指示很具體，因為它清楚告訴設計師哪張圖片需要處理。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"use the same image","meaning":"使用同一張圖片","examples":[{"en":"TKC Secondary School has used the same image as well.","zh":"TKC Secondary School 也使用了同一張圖片。"},{"en":"To use the same image means to choose an identical picture instead of a different one.","zh":"use the same image 指選用完全相同的圖片，而不是另一張不同圖片。"},{"en":"Two groups may accidentally use the same image from a free website.","zh":"兩組人可能會不小心從免費網站使用同一張圖片。"},{"en":"If several posters use the same image, they may look less original.","zh":"如果幾張海報使用同一張圖片，它們可能顯得較不原創。"},{"en":"Changing the image can help a design stand out from others.","zh":"更改圖片可以幫助設計從其他作品中突圍而出。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"as well","meaning":"也；同樣","examples":[{"en":"TKC Secondary School has used the same image as well.","zh":"TKC Secondary School 也使用了同一張圖片。"},{"en":"As well means also or in addition.","zh":"as well 指也、同樣或此外。"},{"en":"I will bring the tickets, and I can bring the map as well.","zh":"我會帶門票，也可以帶地圖。"},{"en":"This phrase shows that the same action or situation applies to another person or thing.","zh":"這個片語表示同一行動或情況也適用於另一人或事物。"},{"en":"As well usually comes near the end of a sentence in everyday English.","zh":"在日常英語中，as well 通常放在句子接近結尾的位置。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"I would be most grateful if","meaning":"如能……我將非常感激","examples":[{"en":"I would be most grateful if the title could be revised.","zh":"如能修改標題，我將非常感激。"},{"en":"I would be most grateful if is a very polite way to ask someone to do something.","zh":"I would be most grateful if 是非常有禮地請求某人做某事的說法。"},{"en":"I would be most grateful if you could send the form by Friday.","zh":"如你能在星期五前寄出表格，我將非常感激。"},{"en":"This phrase is useful when the request may take effort or cause inconvenience.","zh":"當請求可能需要對方付出努力或造成不便時，這個片語很有用。"},{"en":"It sounds formal, respectful, and softer than a direct command.","zh":"它聽起來正式、尊重，而且比直接命令更溫和。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"could be revised","meaning":"可被修改","examples":[{"en":"The title could be revised because it is too long.","zh":"標題因太長而可被修改。"},{"en":"Could be revised means could be changed or improved after review.","zh":"could be revised 指經檢視後可以被更改或改善。"},{"en":"The timetable could be revised if many students cannot attend the activity.","zh":"如果很多學生不能參加活動，時間表可被修改。"},{"en":"A paragraph could be revised to make the meaning clearer.","zh":"段落可被修改，以令意思更清楚。"},{"en":"This phrase sounds more polite than saying something must be changed.","zh":"這個片語比說某事必須更改更有禮貌。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"too long and difficult to read","meaning":"太長而難以閱讀","examples":[{"en":"The title may be too long and difficult to read.","zh":"標題可能太長而難以閱讀。"},{"en":"Too long and difficult to read means the wording is so lengthy that readers may struggle to understand it.","zh":"too long and difficult to read 指文字過長，以致讀者可能難以理解。"},{"en":"A poster title that is too long and difficult to read may fail to attract attention.","zh":"如果海報標題太長而難以閱讀，可能無法吸引注意。"},{"en":"If instructions are too long and difficult to read, people may skip important steps.","zh":"如果指示太長而難以閱讀，人們可能會略過重要步驟。"},{"en":"Shorter wording can make a message clearer and easier to remember.","zh":"較短的措辭可以令訊息更清晰和更容易記住。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"introduction to the story","meaning":"故事簡介","examples":[{"en":"Simon asks Angie to include an introduction to the story.","zh":"Simon 要求 Angie 加入故事簡介。"},{"en":"An introduction to the story gives basic background so readers or viewers understand what is happening.","zh":"introduction to the story 提供基本背景，讓讀者或觀眾明白正在發生甚麼。"},{"en":"A short introduction to the story can explain the main character, setting, and problem.","zh":"簡短的故事簡介可以說明主角、背景和問題。"},{"en":"Without an introduction to the story, judges may feel confused at the beginning.","zh":"沒有故事簡介，評判一開始可能會感到困惑。"},{"en":"A good introduction should be clear and brief, not a full summary of every event.","zh":"好的簡介應清楚而簡短，不是完整概述每件事。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"be included","meaning":"被加入","examples":[{"en":"An introduction to the story could be included.","zh":"故事簡介可以被加入。"},{"en":"To be included means to be added as part of something.","zh":"be included 指被加入成為某事物的一部分。"},{"en":"A map could be included in the leaflet to help visitors find the venue.","zh":"小冊子可加入地圖，以幫助訪客找到場地。"},{"en":"If important details are not included, readers may misunderstand the message.","zh":"如果重要細節沒有被加入，讀者可能會誤解訊息。"},{"en":"This phrase is often used when suggesting extra information or features.","zh":"這個片語常用於建議加入額外資料或功能。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":2},{"front":"help someone better understand","meaning":"幫助某人更清楚了解","examples":[{"en":"This would help the judges better understand the background.","zh":"這會幫助評判更清楚了解背景。"},{"en":"To help someone better understand means to make information clearer for that person.","zh":"help someone better understand 指令資料對某人更清楚易明。"},{"en":"Diagrams can help students better understand how the heart works.","zh":"圖表可以幫助學生更清楚了解心臟如何運作。"},{"en":"Clear examples help readers better understand difficult vocabulary.","zh":"清楚例子能幫助讀者更清楚了解困難詞彙。"},{"en":"When people understand the background better, they can judge the work more fairly.","zh":"當人們更清楚了解背景時，他們可以更公平地評審作品。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"the judges","meaning":"評判","examples":[{"en":"The introduction would help the judges understand the story.","zh":"簡介會幫助評判理解故事。"},{"en":"The judges are the people who assess entries and decide the results of a competition.","zh":"the judges 指評審參賽作品並決定比賽結果的人。"},{"en":"The judges listened carefully before choosing the winner of the speech contest.","zh":"評判仔細聆聽後，選出演講比賽的勝出者。"},{"en":"If the judges cannot understand the message, even a creative video may lose marks.","zh":"如果評判無法理解訊息，即使影片有創意也可能失分。"},{"en":"Competitors should read the rules because the judges will use them when giving scores.","zh":"參賽者應閱讀規則，因為評判評分時會使用這些規則。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"the background","meaning":"背景","examples":[{"en":"The introduction would help the judges understand the background.","zh":"簡介會幫助評判了解背景。"},{"en":"The background is the information needed to understand the situation, story, or reason behind something.","zh":"the background 指理解某個情況、故事或原因所需的資料。"},{"en":"Before reading the article, students learned the background of the historical event.","zh":"閱讀文章前，學生先了解該歷史事件的背景。"},{"en":"Without enough background, people may misunderstand a character’s actions.","zh":"沒有足夠背景，人們可能會誤解角色的行動。"},{"en":"Background information should explain the context without taking over the whole story.","zh":"背景資料應解釋語境，但不應佔據整個故事。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"as for","meaning":"至於","examples":[{"en":"As for the video, the rules state that it should be shorter.","zh":"至於影片，規則列明它應該更短。"},{"en":"As for is used to introduce a new topic or return to a specific point.","zh":"as for 用來引入新話題或回到某個特定重點。"},{"en":"As for the poster, we only need to change the title.","zh":"至於海報，我們只需要更改標題。"},{"en":"This phrase helps organise comments when several items are being discussed.","zh":"當討論幾個項目時，這個片語有助整理意見。"},{"en":"It is useful when moving from one part of feedback to another.","zh":"當從一部分回饋轉到另一部分時，它很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"plan to submit","meaning":"計劃提交","examples":[{"en":"Simon refers to the video Angie plans to submit.","zh":"Simon 提到 Angie 計劃提交的影片。"},{"en":"To plan to submit something means to intend to send it in for approval, marking, or a competition.","zh":"plan to submit something 指打算把某物提交作審批、評分或參賽。"},{"en":"The student plans to submit her essay before the deadline.","zh":"那名學生計劃在截止日期前提交文章。"},{"en":"If you plan to submit a video, you should check the rules first.","zh":"如果你計劃提交影片，應先檢查規則。"},{"en":"Planning to submit is not the same as submitting; changes can still be made before sending it.","zh":"計劃提交不等於已經提交；在送出前仍可修改。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"the rules state that","meaning":"規則列明……","examples":[{"en":"The rules state that the video should be no longer than five minutes.","zh":"規則列明影片不應超過五分鐘。"},{"en":"The rules state that means the official instructions clearly say something.","zh":"the rules state that 指正式指引清楚說明某事。"},{"en":"The rules state that all students must wear sports shoes during the activity.","zh":"規則列明所有學生在活動期間必須穿運動鞋。"},{"en":"If the rules state that late entries are not accepted, participants must submit on time.","zh":"如果規則列明逾期作品不獲接納，參賽者就必須準時提交。"},{"en":"This phrase is useful when explaining a requirement rather than giving a personal opinion.","zh":"當解釋要求而不是表達個人意見時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"no longer than","meaning":"不超過","examples":[{"en":"The video should be no longer than five minutes.","zh":"影片不應超過五分鐘。"},{"en":"No longer than means not exceeding a particular length, time, or amount.","zh":"no longer than 指不超過某個長度、時間或數量。"},{"en":"The answer should be no longer than 100 words.","zh":"答案不應超過 100 字。"},{"en":"If a video is no longer than five minutes, judges can watch every entry more easily.","zh":"如果影片不超過五分鐘，評判可以更容易觀看每份參賽作品。"},{"en":"This phrase sets an upper limit, so shorter is acceptable but longer is not.","zh":"這個片語設定上限，所以較短可以，但較長不可以。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"current version","meaning":"目前版本","examples":[{"en":"Angie’s current version is about ten minutes long.","zh":"Angie 的目前版本長約十分鐘。"},{"en":"The current version is the form of a piece of work as it exists now.","zh":"current version 指作品目前存在的版本。"},{"en":"The current version of the essay still has spelling mistakes.","zh":"這篇文章的目前版本仍有串字錯誤。"},{"en":"A current version can be improved before the final version is submitted.","zh":"目前版本可以在提交最終版本前改善。"},{"en":"This phrase is useful when comparing the present draft with a later revised version.","zh":"當比較現有草稿和之後的修訂版時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"about ten minutes long","meaning":"長約十分鐘","examples":[{"en":"The current version is about ten minutes long.","zh":"目前版本長約十分鐘。"},{"en":"About ten minutes long means approximately ten minutes in length.","zh":"about ten minutes long 指長度大約是十分鐘。"},{"en":"The interview was about ten minutes long, so it was easy to watch during lunch.","zh":"訪問長約十分鐘，所以很容易在午飯時間觀看。"},{"en":"If a video is about ten minutes long but the limit is five minutes, it must be shortened.","zh":"如果影片長約十分鐘，但限制是五分鐘，就必須縮短。"},{"en":"“About” shows that the length is approximate, not exact.","zh":"“About” 表示長度是大約，而不是精確數字。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"Don’t worry","meaning":"不用擔心","examples":[{"en":"Simon says, “Don’t worry—we still have time to make adjustments.”","zh":"Simon 說：「不用擔心——我們仍然有時間作出調整。」"},{"en":"Don’t worry is used to comfort someone and tell them the situation is not too serious.","zh":"Don’t worry 用來安慰某人，告訴對方情況並不太嚴重。"},{"en":"Don’t worry; we can still print another copy before class starts.","zh":"不用擔心；上課前我們仍可以再列印一份。"},{"en":"Saying “Don’t worry” can reduce pressure before giving advice or instructions.","zh":"說 “Don’t worry” 可以在給予建議或指示前減輕壓力。"},{"en":"It sounds friendly, but it should be followed by a real solution if the problem is serious.","zh":"它聽起來友善，但如果問題嚴重，後面應有真正解決方法。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"still have time to","meaning":"仍然有時間……","examples":[{"en":"They still have time to make adjustments.","zh":"他們仍然有時間作出調整。"},{"en":"Still have time to means there is enough time left to do something before a deadline or event.","zh":"still have time to 指在限期或活動前仍有足夠時間做某事。"},{"en":"We still have time to revise the report before the meeting.","zh":"我們在會議前仍然有時間修改報告。"},{"en":"If students still have time to check their answers, they can catch small mistakes.","zh":"如果學生仍然有時間檢查答案，他們可以發現小錯誤。"},{"en":"This phrase reassures people that the situation can still be improved.","zh":"這個片語令人放心，表示情況仍可改善。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":3},{"front":"make adjustments","meaning":"作出調整","examples":[{"en":"They still have time to make adjustments to the video.","zh":"他們仍然有時間對影片作出調整。"},{"en":"To make adjustments means to make small changes so something works better or fits the requirement.","zh":"make adjustments 指作出小修改，使某事運作得更好或符合要求。"},{"en":"The coach made adjustments to the training plan after several players got injured.","zh":"幾名球員受傷後，教練對訓練計劃作出調整。"},{"en":"Making adjustments can prevent a project from failing because of small problems.","zh":"作出調整可以防止項目因小問題而失敗。"},{"en":"Adjustments are usually smaller than a complete redesign.","zh":"調整通常比完全重新設計幅度小。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, the theme should focus on people with disabilities.","zh":"此外，主題應聚焦於殘疾人士。"},{"en":"In addition is used to add another point or extra piece of information.","zh":"in addition 用來加入另一個重點或額外資料。"},{"en":"The poster needs a clearer title; in addition, the font should be larger.","zh":"海報需要更清楚的標題；此外，字體應更大。"},{"en":"This phrase helps connect extra comments smoothly in a letter.","zh":"這個片語有助在信件中順暢連接額外意見。"},{"en":"In addition is more formal than “also” and works well in written feedback.","zh":"in addition 比 “also” 更正式，適合書面回饋。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"be supposed to","meaning":"應該；按規定要","examples":[{"en":"The theme is supposed to focus on people with disabilities.","zh":"主題應該聚焦於殘疾人士。"},{"en":"Be supposed to means something is expected or required according to rules, plans, or common understanding.","zh":"be supposed to 指根據規則、計劃或一般理解，某事應該或按規定要做到。"},{"en":"Students are supposed to arrive ten minutes before the exam starts.","zh":"學生應該在考試開始前十分鐘到達。"},{"en":"If a video is supposed to follow a theme, unrelated content may lose marks.","zh":"如果影片按規定要跟隨主題，不相關內容可能會失分。"},{"en":"This phrase often shows that reality may not match the expected rule.","zh":"這個片語常顯示現實可能與預期規則不一致。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"focus on","meaning":"集中於；聚焦於","examples":[{"en":"The theme is supposed to focus on people with disabilities.","zh":"主題應該聚焦於殘疾人士。"},{"en":"To focus on something means to give most attention to that subject.","zh":"focus on something 指把大部分注意力放在某主題上。"},{"en":"A study plan should focus on the topics the student finds most difficult.","zh":"學習計劃應集中於學生覺得最困難的題目。"},{"en":"If a video focuses on too many ideas, the main message may become unclear.","zh":"如果影片聚焦於太多想法，主要訊息可能變得不清楚。"},{"en":"Focusing on one clear theme helps the audience understand the purpose.","zh":"聚焦於一個清晰主題，有助觀眾理解目的。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"people with disabilities","meaning":"殘疾人士","examples":[{"en":"The video should focus on people with disabilities.","zh":"影片應聚焦於殘疾人士。"},{"en":"People with disabilities are people who have physical, sensory, intellectual, or mental conditions that may affect daily life.","zh":"people with disabilities 指有身體、感官、智力或精神狀況，並可能影響日常生活的人。"},{"en":"Public buildings should support people with disabilities through ramps, lifts, and clear signs.","zh":"公共建築應透過斜道、升降機和清楚標誌支援殘疾人士。"},{"en":"If society ignores people with disabilities, they may face unfair barriers at school, work, and in public spaces.","zh":"如果社會忽視殘疾人士，他們可能在學校、工作和公共空間面對不公平障礙。"},{"en":"Respectful language focuses on people first, not only their disability.","zh":"尊重的語言會先着重人本身，而不只是其殘疾。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"whereas","meaning":"然而；相比之下","examples":[{"en":"The theme is about people with disabilities, whereas the video is about disabled pets.","zh":"主題是關於殘疾人士，然而影片是關於殘疾寵物。"},{"en":"Whereas is used to show a contrast between two facts, ideas, or situations.","zh":"whereas 用來顯示兩個事實、想法或情況之間的對比。"},{"en":"My brother likes action films, whereas I prefer quiet documentaries.","zh":"我哥哥喜歡動作片，相比之下，我較喜歡安靜的紀錄片。"},{"en":"Using “whereas” makes the difference between two points clear.","zh":"使用 “whereas” 可以清楚顯示兩點之間的差異。"},{"en":"It is more formal than “but” and is useful in comparisons.","zh":"它比 “but” 更正式，適合用於比較。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"disabled pets","meaning":"殘疾寵物","examples":[{"en":"Angie’s video is about disabled pets.","zh":"Angie 的影片是關於殘疾寵物。"},{"en":"Disabled pets are animals with physical or medical conditions that affect how they move, see, hear, or live.","zh":"disabled pets 指有身體或醫療狀況，影響牠們活動、視力、聽力或生活的動物。"},{"en":"A disabled pet may need a wheelchair, special food, or extra care at home.","zh":"殘疾寵物可能需要輪椅、特別食物或家中額外照顧。"},{"en":"Videos about disabled pets can be touching, but they may not match a theme about people with disabilities.","zh":"關於殘疾寵物的影片可以很感人，但未必符合關於殘疾人士的主題。"},{"en":"Caring for disabled pets requires patience, planning, and understanding.","zh":"照顧殘疾寵物需要耐性、規劃和理解。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"I was wondering if","meaning":"我想知道可否……","examples":[{"en":"I was wondering if the content could be modified accordingly.","zh":"我想知道內容可否作相應修改。"},{"en":"I was wondering if is a polite and indirect way to make a request or suggestion.","zh":"I was wondering if 是禮貌而間接地提出請求或建議的說法。"},{"en":"I was wondering if you could send me the notes after class.","zh":"我想知道你可否在課後把筆記發給我。"},{"en":"This phrase makes a request sound gentle rather than demanding.","zh":"這個片語令請求聽起來溫和，而不是強硬。"},{"en":"It is useful when asking someone to change work they have already done.","zh":"當請某人修改已完成的作品時，它很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"could be modified accordingly","meaning":"可作相應修改","examples":[{"en":"The content could be modified accordingly to match the theme.","zh":"內容可作相應修改，以配合主題。"},{"en":"Could be modified accordingly means could be changed in a way that fits the new requirement or situation.","zh":"could be modified accordingly 指可以按新的要求或情況作出配合的修改。"},{"en":"The lesson plan could be modified accordingly if the class finishes the first task early.","zh":"如果全班提早完成第一項任務，課堂計劃可作相應修改。"},{"en":"If rules change, the application form should be modified accordingly.","zh":"如果規則改變，申請表應作相應修改。"},{"en":"This phrase shows that the change should match a specific reason, not be random.","zh":"這個片語顯示修改應配合特定原因，而不是隨意更改。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"lastly","meaning":"最後","examples":[{"en":"Lastly, a post-credits scene is required.","zh":"最後，片尾彩蛋是必須的。"},{"en":"Lastly is used to introduce the final point in a list or message.","zh":"lastly 用來引入清單或訊息中的最後一點。"},{"en":"Lastly, please remember to save your work before closing the computer.","zh":"最後，請記得在關閉電腦前儲存作品。"},{"en":"Using “lastly” helps the reader know that the final item is coming.","zh":"使用 “lastly” 可讓讀者知道最後一項即將出現。"},{"en":"It is useful in feedback letters when several suggestions are given one by one.","zh":"當回饋信逐一提出幾項建議時，這個字很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"as mentioned in","meaning":"正如……所提及","examples":[{"en":"As mentioned in the rules, a post-credits scene is required.","zh":"正如規則所提及，片尾彩蛋是必須的。"},{"en":"As mentioned in means as already stated or explained in a particular source.","zh":"as mentioned in 指正如某個來源早前已說明或解釋。"},{"en":"As mentioned in the email, the meeting will start at 9 a.m.","zh":"正如電郵所提及，會議將於上午九時開始。"},{"en":"This phrase reminds readers that the information comes from an earlier document or message.","zh":"這個片語提醒讀者，資料來自較早前的文件或訊息。"},{"en":"It is useful when you want to support your point with a rule or previous statement.","zh":"當你想用規則或先前陳述支持自己的重點時，它很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":4},{"front":"post-credits scene","meaning":"片尾彩蛋","examples":[{"en":"A post-credits scene is required for all participants.","zh":"所有參賽者都必須加入片尾彩蛋。"},{"en":"A post-credits scene is an extra short scene shown after the main ending credits of a video or film.","zh":"post-credits scene 指影片或電影主要片尾字幕後播放的額外短片段。"},{"en":"A comedy video may include a post-credits scene showing one final joke.","zh":"喜劇影片可能加入片尾彩蛋，展示最後一個笑位。"},{"en":"If a competition requires a post-credits scene, videos without one may lose marks.","zh":"如果比賽要求片尾彩蛋，沒有加入的影片可能會失分。"},{"en":"A good post-credits scene should add interest without making the video too long.","zh":"好的片尾彩蛋應增加趣味，但不應令影片太長。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"be required for","meaning":"對……而言是必須的","examples":[{"en":"A post-credits scene is required for all participants.","zh":"片尾彩蛋對所有參賽者而言是必須的。"},{"en":"Be required for means be necessary for a particular person, group, event, or purpose.","zh":"be required for 指對某人、群體、活動或目的而言是必要的。"},{"en":"A student card is required for entry to the library after school.","zh":"放學後進入圖書館必須使用學生證。"},{"en":"If safety training is required for volunteers, they must complete it before helping.","zh":"如果安全培訓對義工而言是必須的，他們必須在幫忙前完成。"},{"en":"This phrase shows that something is not optional.","zh":"這個片語顯示某事不是可選項。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"all participants","meaning":"所有參賽者","examples":[{"en":"The rule applies to all participants.","zh":"該規則適用於所有參賽者。"},{"en":"All participants means every person who takes part in an activity, event, or competition.","zh":"all participants 指參與活動、事件或比賽的每一個人。"},{"en":"All participants must arrive fifteen minutes before the workshop begins.","zh":"所有參賽者必須在工作坊開始前十五分鐘到達。"},{"en":"If a rule applies to all participants, no one should be treated as an exception without a reason.","zh":"如果規則適用於所有參賽者，沒有人應在沒有理由下被視為例外。"},{"en":"This phrase is useful when giving instructions fairly to everyone involved.","zh":"當公平地向所有相關人士提供指示時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"it might be a good idea to","meaning":"……可能是個好主意","examples":[{"en":"It might be a good idea to include a post-credits scene.","zh":"加入片尾彩蛋可能是個好主意。"},{"en":"It might be a good idea to is a gentle way to suggest that someone should do something.","zh":"it might be a good idea to 是溫和建議某人應做某事的說法。"},{"en":"It might be a good idea to save a copy before you edit the file.","zh":"在編輯檔案前先儲存副本可能是個好主意。"},{"en":"This phrase gives advice without sounding too forceful.","zh":"這個片語能給予建議，而不顯得太強硬。"},{"en":"It is useful when you want to encourage a change politely.","zh":"當你想禮貌地鼓勵作出改變時，它很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"include one as well","meaning":"也加入一個","examples":[{"en":"Simon suggests including a post-credits scene as well.","zh":"Simon 建議也加入一個片尾彩蛋。"},{"en":"Include one as well means add one too, in addition to the other parts already mentioned.","zh":"include one as well 指除了已提及的部分外，也加入一個。"},{"en":"If the poster has a title and image, you should include a slogan as well.","zh":"如果海報已有標題和圖片，你也應加入一個口號。"},{"en":"Including one as well can help the work meet all the requirements.","zh":"也加入一個可以幫助作品符合所有要求。"},{"en":"This phrase is often used when an extra item should not be forgotten.","zh":"當提醒不要忘記額外項目時，這個片語常會使用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"keep up the great work","meaning":"繼續保持出色表現","examples":[{"en":"Please keep up the great work!","zh":"請繼續保持出色表現！"},{"en":"Keep up the great work means continue doing very well.","zh":"keep up the great work 指繼續做得很好。"},{"en":"A coach may say “keep up the great work” after a player improves in training.","zh":"球員在訓練中進步後，教練可能會說「繼續保持出色表現」。"},{"en":"This phrase encourages someone to continue their effort and confidence.","zh":"這個片語鼓勵某人繼續努力和保持信心。"},{"en":"It is positive and friendly, so it works well at the end of supportive feedback.","zh":"它正面而友善，所以適合用於支持性回饋的結尾。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"truly appreciate","meaning":"真心感謝","examples":[{"en":"I truly appreciate all your effort.","zh":"我真心感謝你所有的努力。"},{"en":"Truly appreciate means sincerely value or feel thankful for something.","zh":"truly appreciate 指真誠重視或感謝某事。"},{"en":"I truly appreciate your help during this difficult week.","zh":"我真心感謝你在這個困難星期中的幫助。"},{"en":"Saying this can make thanks sound more heartfelt than a quick “thank you”.","zh":"說這句可以令感謝比簡短的 “thank you” 更真誠。"},{"en":"It is useful when someone has spent real time or energy helping you.","zh":"當某人花了真正時間或精力幫助你時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"all your effort","meaning":"你所有的努力","examples":[{"en":"Simon appreciates all Angie’s effort.","zh":"Simon 感謝 Angie 所有的努力。"},{"en":"All your effort means all the time, energy, and care you have put into something.","zh":"all your effort 指你在某事中投入的所有時間、精力和心思。"},{"en":"Thank you for all your effort in preparing the class performance.","zh":"感謝你為準備班級表演付出的所有努力。"},{"en":"When people notice all your effort, you may feel more motivated to continue.","zh":"當人們看見你所有的努力，你可能更有動力繼續。"},{"en":"This phrase values the process, not only the final result.","zh":"這個片語重視過程，而不只是最終結果。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"look forward to seeing","meaning":"期待看到","examples":[{"en":"I look forward to seeing the revised version.","zh":"我期待看到修訂版。"},{"en":"To look forward to seeing something means to feel happy or interested about seeing it in the future.","zh":"look forward to seeing something 指對將來看到某事感到期待或有興趣。"},{"en":"I look forward to seeing your presentation next week.","zh":"我期待下星期看到你的簡報。"},{"en":"This phrase ends a message in a positive and hopeful way.","zh":"這個片語能以正面和有希望的方式結束訊息。"},{"en":"It is common in emails when waiting for a draft, reply, or finished product.","zh":"當等待草稿、回覆或完成品時，它常見於電郵中。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"revised version","meaning":"修訂版","examples":[{"en":"Simon looks forward to seeing the revised version of the poster and video.","zh":"Simon 期待看到海報和影片的修訂版。"},{"en":"A revised version is a new form of a piece of work after changes have been made.","zh":"revised version 指作出修改後的新版本。"},{"en":"The revised version of the essay has clearer examples and fewer grammar mistakes.","zh":"文章的修訂版有更清楚的例子和較少文法錯誤。"},{"en":"A revised version should respond to feedback, not repeat the same problems.","zh":"修訂版應回應回饋，而不是重複同樣問題。"},{"en":"This phrase is useful when a first draft has been improved.","zh":"當初稿已被改善時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"both A and B","meaning":"A 和 B 兩者","examples":[{"en":"Simon wants to see the revised version of both the poster and the video.","zh":"Simon 想看到海報和影片兩者的修訂版。"},{"en":"Both A and B means the two things mentioned are included together.","zh":"both A and B 指所提及的兩件事都包括在內。"},{"en":"The school needs both the consent form and the payment before the trip.","zh":"學校在旅行前需要同意書和付款兩者。"},{"en":"If both A and B are required, submitting only one of them is not enough.","zh":"如果 A 和 B 兩者都是必須的，只提交其中一項並不足夠。"},{"en":"This structure is useful when you want to make two items equally clear.","zh":"當你想同樣清楚地指出兩個項目時，這個結構很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":5},{"front":"I am sure you can do it","meaning":"我相信你一定做到","examples":[{"en":"Simon encourages Angie by saying, “I am sure you can do it.”","zh":"Simon 說「我相信你一定做到」來鼓勵 Angie。"},{"en":"I am sure you can do it is used to express confidence in someone’s ability.","zh":"I am sure you can do it 用來表達對某人能力的信心。"},{"en":"A teacher may say this to a student who feels nervous before a speech.","zh":"老師可能會對演講前緊張的學生說這句話。"},{"en":"This sentence can encourage someone when a task feels difficult but possible.","zh":"當任務感覺困難但仍可完成時，這句話可以鼓勵對方。"},{"en":"It is positive and supportive, especially after giving suggestions for improvement.","zh":"它正面而支持，尤其適合在提出改善建議後使用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6},{"front":"if you have any questions","meaning":"如果你有任何問題","examples":[{"en":"If Angie has any questions, she can contact Simon.","zh":"如果 Angie 有任何問題，她可以聯絡 Simon。"},{"en":"If you have any questions means if there is anything you do not understand or want to ask about.","zh":"if you have any questions 指如果你有任何不明白或想查詢的事情。"},{"en":"If you have any questions about the homework, please ask before Friday.","zh":"如果你對功課有任何問題，請在星期五前提問。"},{"en":"This phrase invites the reader to seek help instead of guessing alone.","zh":"這個片語邀請讀者尋求幫助，而不是自己猜測。"},{"en":"It is common at the end of instructions, notices, and emails.","zh":"它常見於指示、告示和電郵的結尾。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6},{"front":"feel free to","meaning":"隨時……","examples":[{"en":"Feel free to contact me if you have any questions.","zh":"如果你有任何問題，隨時聯絡我。"},{"en":"Feel free to means you are welcome to do something without feeling worried or shy.","zh":"feel free to 指歡迎你放心做某事，不用擔心或害羞。"},{"en":"Feel free to ask for help if you do not understand the task.","zh":"如果你不明白任務，隨時尋求幫助。"},{"en":"This phrase makes an offer sound friendly and open.","zh":"這個片語令提供協助的語氣顯得友善和開放。"},{"en":"It is useful when you want the other person to know that asking is acceptable.","zh":"當你想讓對方知道提問是可以的，這個片語很有用。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6},{"front":"contact me","meaning":"聯絡我","examples":[{"en":"Angie can contact Simon if she has questions.","zh":"如果 Angie 有問題，她可以聯絡 Simon。"},{"en":"To contact me means to get in touch with me by phone, email, message, or another method.","zh":"contact me 指透過電話、電郵、訊息或其他方式與我取得聯繫。"},{"en":"Please contact me before Thursday if you cannot attend the meeting.","zh":"如果你不能出席會議，請在星期四前聯絡我。"},{"en":"Clear contact details make it easier for people to contact you quickly.","zh":"清楚的聯絡資料可以令人更容易快速聯絡你。"},{"en":"This phrase is common in emails when the writer is offering help or asking for a reply.","zh":"當作者提供協助或要求回覆時，這個片語常見於電郵中。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6},{"front":"I would be more than happy to","meaning":"我非常樂意……","examples":[{"en":"I would be more than happy to help.","zh":"我非常樂意幫忙。"},{"en":"I would be more than happy to means I would be very willing and pleased to do something.","zh":"I would be more than happy to 指我非常願意並樂於做某事。"},{"en":"I would be more than happy to explain the instructions again after class.","zh":"我非常樂意在課後再次解釋指示。"},{"en":"This phrase makes help sound warm, polite, and sincere.","zh":"這個片語令提供幫助聽起來溫暖、有禮和真誠。"},{"en":"It is stronger and friendlier than simply saying “I can”.","zh":"它比簡單說 “I can” 更強烈和友善。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6},{"front":"more than happy to help","meaning":"非常樂意幫忙","examples":[{"en":"Simon would be more than happy to help Angie.","zh":"Simon 非常樂意幫助 Angie。"},{"en":"More than happy to help means very willing to give support or assistance.","zh":"more than happy to help 指非常願意提供支援或協助。"},{"en":"The librarian is more than happy to help students find suitable books.","zh":"圖書館管理員非常樂意幫助學生尋找合適書籍。"},{"en":"Saying you are more than happy to help can make others feel comfortable asking questions.","zh":"說你非常樂意幫忙，可以令他人更放心提問。"},{"en":"This phrase is often used to end a message in a supportive and positive way.","zh":"這個片語常用來以支持而正面的方式結束訊息。"}],"source":"Flash Cards -實用文 - Informal letter of request.pdf","sourcePage":6}],"dse/paper-3/practical-english-writing/practical-formats/negative-emails":[{"front":"regret to inform you that","meaning":"很遺憾通知你","examples":[{"en":"I regret to inform you that I will be absent from today’s lesson.","zh":"很遺憾通知你，我將會缺席今天的課堂。"},{"en":"“I regret to inform you that” is a formal way to give someone bad or disappointing news politely.","zh":"“I regret to inform you that” 是一種正式而有禮地告知對方壞消息或令人失望消息的說法。"},{"en":"A student may write, “I regret to inform you that I cannot attend the school trip.”","zh":"學生可能寫道：「很遺憾通知你，我不能參加學校旅行。」"},{"en":"People use this phrase when they want to sound respectful before explaining a problem.","zh":"人們使用這個短語，是因為他們想在解釋問題前顯得尊重對方。"},{"en":"“I regret to inform you that” is more formal than simply saying “Sorry, but...”","zh":"“I regret to inform you that” 比簡單說 “Sorry, but...” 更正式。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"be absent from","meaning":"缺席……","examples":[{"en":"I will be absent from today’s lesson.","zh":"我將會缺席今天的課堂。"},{"en":"To be absent from a class, meeting, or event means not to attend it.","zh":"be absent from 某課堂、會議或活動，指沒有出席。"},{"en":"A student may be absent from school because of illness.","zh":"學生可能因病缺席上課。"},{"en":"If an employee is absent from work without notice, the manager may need to ask why.","zh":"如果員工沒有通知便缺席工作，經理可能需要詢問原因。"},{"en":"Being absent from an important lesson may make it harder to follow the next one.","zh":"缺席重要課堂可能會令下一課更難跟上。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"today’s lesson","meaning":"今天的課堂","examples":[{"en":"I will be absent from today’s lesson.","zh":"我將會缺席今天的課堂。"},{"en":"Today’s lesson means the class that takes place today.","zh":"today’s lesson 指今天進行的課堂。"},{"en":"A teacher may upload the notes from today’s lesson after school.","zh":"老師可能在放學後上載今天的課堂筆記。"},{"en":"If students miss today’s lesson, they should ask classmates what was taught.","zh":"如果學生錯過今天的課堂，應該詢問同學教了甚麼。"},{"en":"Today’s lesson may be important if it introduces a new topic or assignment.","zh":"如果今天的課堂介紹新題目或功課，它可能很重要。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"assignment","meaning":"功課；作業","examples":[{"en":"My assignment will be sent to you via email instead.","zh":"我的功課將改為透過電郵發送給你。"},{"en":"An assignment is a piece of schoolwork or coursework that a student must complete.","zh":"assignment 指學生必須完成的功課或作業。"},{"en":"Students may write an essay, finish a worksheet, or prepare a presentation as an assignment.","zh":"學生可能要寫文章、完成工作紙或準備匯報作為作業。"},{"en":"If an assignment is submitted late, marks may be deducted.","zh":"如果功課遲交，可能會被扣分。"},{"en":"A clear assignment should include the task, deadline, format, and marking criteria.","zh":"清晰的作業應包括任務、截止日期、格式和評分準則。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"be sent to you via email","meaning":"透過電郵發送給你","examples":[{"en":"My assignment will be sent to you via email instead.","zh":"我的功課將改為透過電郵發送給你。"},{"en":"If something is sent to you via email, it is delivered to your email inbox instead of being given by hand.","zh":"如果某物 is sent to you via email，即表示它會送到你的電郵收件箱，而不是親手交給你。"},{"en":"A receipt can be sent to you via email after an online purchase.","zh":"網上購物後，收據可以透過電郵發送給你。"},{"en":"If a document is sent to you via email, you can download and keep a digital copy.","zh":"如果文件透過電郵發送給你，你可以下載並保存電子版本。"},{"en":"This phrase is useful when explaining how a file, form, or assignment will be delivered.","zh":"這個短語適合用來解釋檔案、表格或功課會如何送達。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"via email","meaning":"透過電郵","examples":[{"en":"The assignment will be sent to you via email.","zh":"功課將透過電郵發送給你。"},{"en":"Via email means by using email as the method of communication or delivery.","zh":"via email 指以電郵作為溝通或傳送的方法。"},{"en":"A teacher may send lesson notes via email to students who are sick.","zh":"老師可能透過電郵把課堂筆記發給生病的學生。"},{"en":"If a form is sent via email, it can arrive faster than a printed copy.","zh":"如果表格透過電郵發送，它可以比印刷本更快到達。"},{"en":"Via email is more formal than saying “by email” in some school or office messages.","zh":"在一些學校或辦公室訊息中，via email 比 “by email” 聽起來較正式。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"instead","meaning":"改為；反而","examples":[{"en":"My assignment will be sent to you via email instead.","zh":"我的功課將改為透過電郵發送給你。"},{"en":"Instead means that one action replaces another action.","zh":"instead 指一個行動取代另一個行動。"},{"en":"If the library is closed, students may study at home instead.","zh":"如果圖書館關門，學生可能改為在家溫習。"},{"en":"A sick student may submit homework online instead of handing it in personally.","zh":"生病的學生可能改為網上提交功課，而不是親手遞交。"},{"en":"Instead is useful when explaining a change from the original plan.","zh":"instead 適合用來解釋原本計劃有所改變。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"unfortunately","meaning":"不幸地；很抱歉","examples":[{"en":"Unfortunately, I am unable to attend the lecture today due to a fever.","zh":"很抱歉，我因發燒未能出席今天的講課。"},{"en":"Unfortunately is used to introduce bad news, a problem, or an unwanted situation.","zh":"unfortunately 用來引出壞消息、問題或不理想的情況。"},{"en":"Unfortunately, the bus was delayed, so many students arrived late.","zh":"很抱歉，巴士延誤了，所以很多學生遲到。"},{"en":"If something unfortunate happens, this word helps the speaker sound polite and regretful.","zh":"如果發生不幸或不理想的事情，這個字可以令講者聽起來有禮並帶歉意。"},{"en":"Unfortunately is often used before explaining why something cannot happen.","zh":"unfortunately 常用於解釋某事為何不能發生之前。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"be unable to","meaning":"未能；不能","examples":[{"en":"I am unable to attend the lecture today due to a fever.","zh":"我因發燒未能出席今天的講課。"},{"en":"To be unable to do something means not to be able to do it.","zh":"be unable to do something 指不能做某事。"},{"en":"A student may be unable to finish homework if they are very ill.","zh":"如果學生病得很嚴重，可能未能完成功課。"},{"en":"If a speaker is unable to attend an event, the organiser may need to find a replacement.","zh":"如果講者未能出席活動，主辦方可能需要找替代人選。"},{"en":"Be unable to is more formal than “can’t” and is common in emails.","zh":"be unable to 比 “can’t” 更正式，常見於電郵。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"attend the lecture","meaning":"出席講課","examples":[{"en":"I am unable to attend the lecture today.","zh":"我未能出席今天的講課。"},{"en":"To attend the lecture means to be present at a formal class or talk.","zh":"attend the lecture 指出席正式課堂或講課。"},{"en":"University students often attend lectures before joining smaller tutorial discussions.","zh":"大學生通常先出席講課，然後再參加較小組的導修討論。"},{"en":"If you do not attend the lecture, you may miss important explanations.","zh":"如果你沒有出席講課，可能會錯過重要解釋。"},{"en":"Students should inform the teacher early if they cannot attend the lecture.","zh":"如果學生不能出席講課，應及早通知老師。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"due to a fever","meaning":"由於發燒","examples":[{"en":"I am unable to attend the lecture today due to a fever.","zh":"我由於發燒，未能出席今天的講課。"},{"en":"Due to a fever means because someone has a high body temperature and is unwell.","zh":"due to a fever 指因為某人發燒、體溫偏高並感到不適。"},{"en":"A child may stay home from school due to a fever.","zh":"小朋友可能由於發燒而留在家中不上學。"},{"en":"If a worker is absent due to a fever, they should rest and avoid spreading illness.","zh":"如果員工由於發燒而缺席，他應休息並避免傳播疾病。"},{"en":"Due to a fever gives a clear health reason for missing a class or event.","zh":"due to a fever 為缺席課堂或活動提供清楚的健康原因。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":1},{"front":"therefore","meaning":"因此","examples":[{"en":"Therefore, I cannot submit the assignment to you in person.","zh":"因此，我不能親身把功課遞交給你。"},{"en":"Therefore means as a result, so it is used to show a conclusion or consequence.","zh":"therefore 指「因此；所以」，用來表示結論或結果。"},{"en":"The library is closed today; therefore, students must return books tomorrow.","zh":"圖書館今天關門；因此，學生必須明天還書。"},{"en":"If a student is sick, they may be unable to travel; therefore, they may submit work online.","zh":"如果學生生病，可能無法外出；因此，他可能會在網上提交功課。"},{"en":"Therefore is more formal than “so” and is often used in writing.","zh":"therefore 比 “so” 更正式，常用於寫作。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"submit the assignment","meaning":"遞交功課","examples":[{"en":"I cannot submit the assignment to you in person.","zh":"我不能親身把功課遞交給你。"},{"en":"To submit the assignment means to hand in or send completed schoolwork for checking.","zh":"submit the assignment 指把完成的功課交出或發送給老師檢查。"},{"en":"Students may submit the assignment on paper, through email, or on an online platform.","zh":"學生可以以紙本、電郵或網上平台遞交功課。"},{"en":"If students forget to submit the assignment, the teacher may mark it as missing.","zh":"如果學生忘記遞交功課，老師可能會把它記為欠交。"},{"en":"Before submitting the assignment, students should check their name, class, and answers.","zh":"遞交功課前，學生應檢查姓名、班別和答案。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"in person","meaning":"親身","examples":[{"en":"I cannot submit the assignment to you in person.","zh":"我不能親身把功課遞交給你。"},{"en":"In person means physically present, not online, by phone, or through another person.","zh":"in person 指親身在場，而不是網上、電話或透過別人。"},{"en":"Some interviews must be done in person because the company wants to meet applicants directly.","zh":"有些面試必須親身進行，因為公司想直接見申請人。"},{"en":"If a student is ill, they may not be able to hand in homework in person.","zh":"如果學生生病，可能不能親身交功課。"},{"en":"Meeting in person can make communication clearer than exchanging messages only.","zh":"親身見面可以比只交換訊息更清楚地溝通。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"scan the assignment","meaning":"掃描功課","examples":[{"en":"The assignment will be scanned and sent to you as a soft copy.","zh":"功課將會被掃描，並以電子版本發送給你。"},{"en":"To scan the assignment means to use a scanner or phone to turn the paper homework into a digital file.","zh":"scan the assignment 指使用掃描器或手機把紙本功課變成電子檔案。"},{"en":"A student may scan the assignment at home before emailing it to the teacher.","zh":"學生可能在家掃描功課，然後電郵給老師。"},{"en":"If the scanned pages are unclear, the teacher may not be able to read the answers.","zh":"如果掃描頁面不清楚，老師可能無法閱讀答案。"},{"en":"Students should scan the assignment carefully so every page is complete and straight.","zh":"學生應仔細掃描功課，確保每一頁完整而端正。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"soft copy","meaning":"電子版本","examples":[{"en":"The assignment will be sent to you as a soft copy.","zh":"功課將會以電子版本發送給你。"},{"en":"A soft copy is a digital version of a document, not a printed paper copy.","zh":"soft copy 指文件的電子版本，而不是印刷紙本。"},{"en":"Teachers may accept a soft copy of an essay through email.","zh":"老師可能接受學生透過電郵提交文章的電子版本。"},{"en":"If students lose the printed worksheet, a soft copy can help them print another one.","zh":"如果學生遺失印刷工作紙，電子版本可以幫助他們再列印一份。"},{"en":"A soft copy is easy to store and send, but it should still be clearly named.","zh":"電子版本方便儲存和傳送，但仍應清楚命名。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"immediately","meaning":"立即","examples":[{"en":"The assignment will be sent to you immediately.","zh":"功課將會立即發送給你。"},{"en":"Immediately means at once, without delay.","zh":"immediately 指立刻、沒有延誤。"},{"en":"If there is a fire alarm, students should leave the building immediately.","zh":"如果火警鐘響起，學生應立即離開大樓。"},{"en":"Sending the assignment immediately helps show that the student is responsible.","zh":"立即發送功課有助顯示學生有責任感。"},{"en":"Immediately is stronger than “soon” because it means no waiting.","zh":"immediately 比 “soon” 更強，因為它表示不用等待。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"express my sincere apology","meaning":"表達誠摯歉意","examples":[{"en":"I would like to express my sincere apology for any inconvenience caused.","zh":"我想就造成的任何不便表達誠摯歉意。"},{"en":"To express my sincere apology means to formally say that I am truly sorry.","zh":"express my sincere apology 指正式表示自己真的感到抱歉。"},{"en":"A student may express a sincere apology after missing an important deadline.","zh":"學生錯過重要截止日期後，可能會表達誠摯歉意。"},{"en":"If a mistake causes extra work for others, expressing a sincere apology shows respect.","zh":"如果錯誤令別人要做額外工作，表達誠摯歉意能顯示尊重。"},{"en":"This phrase is formal and suitable for emails to teachers, clients, or supervisors.","zh":"這個短語較正式，適合用於寫給老師、客戶或上司的電郵。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"sincere apology","meaning":"誠摯歉意","examples":[{"en":"I would like to express my sincere apology.","zh":"我想表達誠摯歉意。"},{"en":"A sincere apology is an apology that sounds honest and truly regretful.","zh":"sincere apology 指聽起來真誠並真正帶有歉意的道歉。"},{"en":"A student may offer a sincere apology after speaking rudely to a classmate.","zh":"學生對同學說話無禮後，可能會表達誠摯歉意。"},{"en":"A sincere apology can help repair trust when someone has caused trouble.","zh":"當某人造成麻煩時，誠摯歉意可以幫助修補信任。"},{"en":"A sincere apology should be followed by responsible action, not just polite words.","zh":"誠摯歉意應配合負責任的行動，而不只是禮貌說話。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"inconvenience caused","meaning":"造成的不便","examples":[{"en":"I apologise for any inconvenience caused.","zh":"我就造成的任何不便道歉。"},{"en":"Inconvenience caused means trouble, difficulty, or extra work created for someone.","zh":"inconvenience caused 指為某人帶來的麻煩、困難或額外工作。"},{"en":"A delayed train announcement may say sorry for the inconvenience caused.","zh":"火車延誤公告可能會為造成的不便致歉。"},{"en":"If a student changes a meeting time suddenly, there may be inconvenience caused to the teacher.","zh":"如果學生突然更改會面時間，可能會對老師造成不便。"},{"en":"This phrase is formal and often appears in apology emails or public notices.","zh":"這個短語較正式，常見於道歉電郵或公共告示。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"thank you very much for","meaning":"非常感謝你……","examples":[{"en":"I thank you very much for your understanding.","zh":"我非常感謝你的諒解。"},{"en":"Thank you very much for is a polite way to show strong gratitude for something.","zh":"thank you very much for 是一種有禮地表達強烈感謝的說法。"},{"en":"A student may write, “Thank you very much for your help with my project.”","zh":"學生可能寫道：「非常感謝你幫助我的項目。」"},{"en":"People use this phrase when they want their thanks to sound warm and respectful.","zh":"人們使用這個短語，是因為他們想令謝意聽起來溫暖而尊重。"},{"en":"It is often followed by a noun or -ing form, such as “your patience” or “helping me.”","zh":"它後面常接名詞或 -ing 形式，例如 “your patience” 或 “helping me”。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"your understanding","meaning":"你的諒解","examples":[{"en":"Thank you very much for your understanding.","zh":"非常感謝你的諒解。"},{"en":"Your understanding means your patience and acceptance of a difficult situation.","zh":"your understanding 指你對困難情況的耐心和接受。"},{"en":"A teacher may show understanding when a sick student submits work late.","zh":"當生病學生遲交功課時，老師可能會表示諒解。"},{"en":"If someone changes a plan because of illness, they may thank others for their understanding.","zh":"如果某人因病改變計劃，他可能會感謝別人的諒解。"},{"en":"This phrase is polite because it recognises that the other person may be inconvenienced.","zh":"這個短語有禮，因為它承認對方可能受到不便。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":2},{"front":"look forward to","meaning":"期待……","examples":[{"en":"I look forward to seeing you in person again at the next lecture.","zh":"我期待在下一堂講課再次親身見到你。"},{"en":"To look forward to something means to feel pleased or excited about something that will happen later.","zh":"look forward to something 指對將來會發生的事情感到高興或期待。"},{"en":"Students may look forward to the school picnic after exams.","zh":"學生可能在考試後期待學校旅行。"},{"en":"If someone looks forward to a meeting, it means they expect it positively.","zh":"如果某人期待一場會面，即表示他以正面心情等待它。"},{"en":"Look forward to is followed by a noun or -ing form, such as “the lesson” or “seeing you.”","zh":"look forward to 後面接名詞或 -ing 形式，例如 “the lesson” 或 “seeing you”。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":3},{"front":"see you in person","meaning":"親身見到你","examples":[{"en":"I look forward to seeing you in person again.","zh":"我期待再次親身見到你。"},{"en":"To see you in person means to meet you face to face rather than online or through messages.","zh":"see you in person 指面對面見到你，而不是透過網上或訊息。"},{"en":"After several online lessons, students may be happy to see their teacher in person.","zh":"上了幾堂網課後，學生可能很高興能親身見到老師。"},{"en":"Seeing someone in person can make it easier to ask questions and explain problems.","zh":"親身見到某人可以令提問和解釋問題更容易。"},{"en":"This phrase is useful when contrasting face-to-face meetings with email or video calls.","zh":"這個短語適合用來對比面對面會面與電郵或視像通話。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":3},{"front":"at the next lecture","meaning":"在下一堂講課","examples":[{"en":"I look forward to seeing you again at the next lecture.","zh":"我期待在下一堂講課再次見到你。"},{"en":"At the next lecture means during the following formal class or talk.","zh":"at the next lecture 指在下一次正式課堂或講課期間。"},{"en":"The teacher may explain the homework requirements at the next lecture.","zh":"老師可能會在下一堂講課解釋功課要求。"},{"en":"If students miss today’s class, they should return prepared at the next lecture.","zh":"如果學生錯過今天的課堂，他們應在下一堂講課準備好回來。"},{"en":"This phrase points to a future class and helps make the time clear.","zh":"這個短語指向未來的課堂，有助清楚說明時間。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":3},{"front":"Yours sincerely","meaning":"謹啟；此致","examples":[{"en":"Yours sincerely, Samuel Chan.","zh":"Samuel Chan 謹啟。"},{"en":"Yours sincerely is a formal closing used at the end of a letter or email.","zh":"Yours sincerely 是信件或電郵結尾使用的正式結語。"},{"en":"A student may write “Yours sincerely” before signing their name in a formal message to a teacher.","zh":"學生在寫給老師的正式訊息中，可能會在簽名前寫 “Yours sincerely”。"},{"en":"Using Yours sincerely helps the email end politely and respectfully.","zh":"使用 Yours sincerely 可以令電郵以有禮和尊重的方式結束。"},{"en":"This closing is suitable for serious school, work, or official communication.","zh":"這個結語適合用於嚴肅的學校、工作或正式溝通。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":3},{"front":"Student UID","meaning":"學生編號","examples":[{"en":"Student UID: 373 171 383.","zh":"學生編號：373 171 383。"},{"en":"A Student UID is a unique identification number used to identify a student.","zh":"Student UID 指用來識別學生身份的唯一學生編號。"},{"en":"A university may ask students to write their Student UID on forms and assignments.","zh":"大學可能要求學生在表格和功課上寫上學生編號。"},{"en":"If two students have similar names, the Student UID helps the school identify the correct person.","zh":"如果兩名學生姓名相似，學生編號可以幫助學校識別正確的人。"},{"en":"Students should check their Student UID carefully because a wrong number may cause record problems.","zh":"學生應仔細檢查自己的學生編號，因為錯誤號碼可能造成紀錄問題。"}],"source":"Flash Cards -實用文 - Negative Letter.pdf","sourcePage":3}],"dse/paper-3/practical-english-writing/practical-formats/outline":[{"front":"Outline of","meaning":"……的綱要","examples":[{"en":"This is an outline of car accidents in Santa Flora City.","zh":"這是 Santa Flora City 交通意外的綱要。"},{"en":"An outline of something gives the main points without including every small detail.","zh":"某事的綱要會列出主要重點，而不包括每個細節。"},{"en":"A teacher may give students an outline of the lesson before explaining each part.","zh":"老師可能會在解釋每個部分前，給學生課堂綱要。"},{"en":"An outline of a report helps readers understand the structure quickly.","zh":"報告綱要有助讀者快速理解結構。"},{"en":"If an outline of a topic is clear, students can predict what details will come next.","zh":"如果某主題的綱要清楚，學生就能預計接下來會有甚麼細節。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"car accidents in the city","meaning":"城市內的交通意外","examples":[{"en":"The article discusses car accidents in the city.","zh":"文章討論城市內的交通意外。"},{"en":"Car accidents in the city are crashes or road incidents that happen within an urban area.","zh":"城市內的交通意外是在市區發生的撞車或道路事故。"},{"en":"Heavy traffic can increase the number of car accidents in the city during rush hour.","zh":"繁忙交通可能會在繁忙時間增加城市內的交通意外數目。"},{"en":"Car accidents in the city can delay buses, block roads and injure pedestrians.","zh":"城市內的交通意外可以令巴士延誤、道路受阻，並令行人受傷。"},{"en":"Reducing car accidents in the city requires safer roads, careful drivers and clear rules.","zh":"減少城市內的交通意外需要更安全的道路、小心的司機和清楚規則。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"effects of car accidents","meaning":"交通意外的影響","examples":[{"en":"The first section focuses on the effects of car accidents.","zh":"第一部分集中討論交通意外的影響。"},{"en":"The effects of car accidents are the results or problems caused by road crashes.","zh":"交通意外的影響是道路事故造成的結果或問題。"},{"en":"The effects of car accidents can include injuries, traffic jams and expensive repairs.","zh":"交通意外的影響可以包括受傷、交通擠塞和昂貴維修費。"},{"en":"Serious car accidents may affect families because victims need long-term care.","zh":"嚴重交通意外可能影響家庭，因為傷者需要長期照顧。"},{"en":"Understanding the effects of car accidents helps governments decide which safety measures are needed.","zh":"了解交通意外的影響有助政府決定需要哪些安全措施。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"every year","meaning":"每年","examples":[{"en":"Every year, there are more than 800 car accidents in Santa Flora City.","zh":"每年，Santa Flora City 有超過 800 宗交通意外。"},{"en":"Every year means once in each year or during each year.","zh":"每年意思是在每一年之中或每一年一次。"},{"en":"Every year, students prepare for final exams before the summer holiday.","zh":"每年，學生都會在暑假前準備期末考試。"},{"en":"If a problem happens every year, people should not treat it as a surprise.","zh":"如果問題每年都發生，人們就不應把它當成意外。"},{"en":"Keeping records every year helps a city see whether the situation is improving.","zh":"每年保存紀錄有助城市了解情況是否正在改善。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"more than 800 cases of","meaning":"超過800宗……個案","examples":[{"en":"There are more than 800 cases of car accidents in Santa Flora City every year.","zh":"Santa Flora City 每年有超過 800 宗交通意外個案。"},{"en":"More than 800 cases of something means over 800 reported examples or incidents of it.","zh":"超過 800 宗某事個案意思是有 800 宗以上已記錄的例子或事件。"},{"en":"A hospital may receive more than 800 cases of flu during a severe winter.","zh":"在嚴重冬季，醫院可能會收到超過 800 宗流感個案。"},{"en":"More than 800 cases of the same problem can show that the issue is widespread.","zh":"超過 800 宗同一問題個案可以顯示該問題很普遍。"},{"en":"When there are more than 800 cases of an incident, officials usually need a long-term solution.","zh":"當某事件有超過 800 宗個案，官員通常需要長遠解決方案。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"car accidents","meaning":"交通意外","examples":[{"en":"Car accidents are a serious problem in Santa Flora City.","zh":"交通意外是 Santa Flora City 的嚴重問題。"},{"en":"Car accidents are crashes involving cars, often causing damage, injuries or delays.","zh":"交通意外是涉及汽車的撞車事故，通常造成損毀、受傷或延誤。"},{"en":"Car accidents may happen when drivers speed, ignore signals or use phones while driving.","zh":"當司機超速、無視燈號或駕駛時使用手機，可能會發生交通意外。"},{"en":"Car accidents can make roads dangerous for drivers, passengers and pedestrians.","zh":"交通意外會令道路對司機、乘客和行人變得危險。"},{"en":"Careful driving and good road design can reduce car accidents.","zh":"小心駕駛和良好道路設計可以減少交通意外。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"It is estimated that","meaning":"據估計","examples":[{"en":"It is estimated that damage costs can top $300 million a year.","zh":"據估計，損失金額每年可高達 3 億美元。"},{"en":"It is estimated that means experts or officials have made an approximate calculation.","zh":"據估計意思是專家或官員作出了大概計算。"},{"en":"It is estimated that the new library will cost two million dollars to build.","zh":"據估計，新圖書館將耗資二百萬美元興建。"},{"en":"If exact figures are not available, people may say it is estimated that a number is likely.","zh":"如果沒有準確數字，人們可能會用「據估計」來表示某個數字很可能如此。"},{"en":"This phrase is useful when giving a careful figure instead of a completely certain one.","zh":"當給出謹慎數字而不是完全確定數字時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"damage costs","meaning":"損失金額；損毀成本","examples":[{"en":"Damage costs from car accidents can top $300 million a year.","zh":"交通意外造成的損失金額每年可高達 3 億美元。"},{"en":"Damage costs are the money needed to repair or replace things after harm is done.","zh":"損失金額是損害發生後用來維修或更換物件所需的金錢。"},{"en":"After a storm, damage costs may include fixing windows, roofs and flooded shops.","zh":"風暴過後，損失金額可能包括修理窗戶、屋頂和被水浸的店舖。"},{"en":"High damage costs can put pressure on families, businesses and insurance companies.","zh":"高昂損失金額會為家庭、企業和保險公司帶來壓力。"},{"en":"Reducing accidents can lower damage costs because fewer vehicles and buildings are destroyed.","zh":"減少意外可以降低損失金額，因為被毀壞的車輛和建築物會較少。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"can top $300 million","meaning":"可高達3億美元","examples":[{"en":"The damage costs can top $300 million a year.","zh":"損失金額每年可高達 3 億美元。"},{"en":"Can top $300 million means can reach or exceed 300 million dollars.","zh":"可高達 3 億美元意思是可以達到或超過 3 億美元。"},{"en":"The cost of building a new railway can top $300 million if land prices rise.","zh":"如果土地價格上升，興建新鐵路的成本可高達 3 億美元。"},{"en":"If accidents are frequent, repair bills can top $300 million very quickly.","zh":"如果意外頻繁，維修帳單可能很快可高達 3 億美元。"},{"en":"This phrase is used to show that a figure may become extremely high.","zh":"這個短語用來表示某個數字可能變得極高。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"a year","meaning":"每年","examples":[{"en":"The damage costs can top $300 million a year.","zh":"損失金額每年可高達 3 億美元。"},{"en":"A year means in one year or during each year.","zh":"每年意思是在一年之內或每一年。"},{"en":"A family may spend several thousand dollars a year on transport.","zh":"一個家庭每年可能在交通上花費數千美元。"},{"en":"If a city loses millions of dollars a year, the problem is financially serious.","zh":"如果一個城市每年損失數百萬美元，問題在財政上很嚴重。"},{"en":"Saying “a year” helps readers understand the time period of the cost or number.","zh":"說「每年」有助讀者理解成本或數字所屬的時間範圍。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"reported cases of","meaning":"已呈報的……個案","examples":[{"en":"Of all the reported cases of car accidents in 2017, there were 400 casualties.","zh":"在 2017 年所有已呈報的交通意外個案中，有 400 名傷亡者。"},{"en":"Reported cases of something are incidents that have been officially recorded or told to authorities.","zh":"已呈報的某事個案是已被正式記錄或告知當局的事件。"},{"en":"Reported cases of food poisoning may increase after a restaurant fails a hygiene inspection.","zh":"如果餐廳未能通過衛生檢查，已呈報的食物中毒個案可能會增加。"},{"en":"If many cases are not reported, the official number may look smaller than the real problem.","zh":"如果許多個案沒有呈報，官方數字可能看起來比真實問題小。"},{"en":"Reported cases of accidents help officials study patterns and improve safety.","zh":"已呈報的意外個案有助官員研究模式並改善安全。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":1},{"front":"casualties","meaning":"傷亡人數","examples":[{"en":"There were 400 casualties in the reported car accidents in 2017.","zh":"2017 年已呈報的交通意外中有 400 名傷亡者。"},{"en":"Casualties are people who are injured or killed in an accident, attack or disaster.","zh":"傷亡者是在意外、襲擊或災難中受傷或死亡的人。"},{"en":"A serious bus crash may cause many casualties if passengers are not wearing seatbelts.","zh":"如果乘客沒有繫安全帶，嚴重巴士事故可能造成大量傷亡。"},{"en":"Emergency services must act quickly when there are many casualties.","zh":"當傷亡人數很多時，緊急服務必須迅速行動。"},{"en":"Counting casualties helps people understand the human cost of an accident.","zh":"統計傷亡人數有助人們理解意外的人命代價。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"driving regulations","meaning":"駕駛規例","examples":[{"en":"The second section discusses driving regulations in Santa Flora City.","zh":"第二部分討論 Santa Flora City 的駕駛規例。"},{"en":"Driving regulations are rules that tell drivers what they can and cannot do on the road.","zh":"駕駛規例是告訴司機在道路上可以和不可以做甚麼的規則。"},{"en":"Speed limits, seatbelt rules and drink-driving laws are driving regulations.","zh":"車速限制、安全帶規則和酒後駕駛法例都是駕駛規例。"},{"en":"Clear driving regulations can reduce confusion and prevent dangerous behaviour.","zh":"清楚的駕駛規例可以減少混亂並防止危險行為。"},{"en":"Drivers who ignore driving regulations may face fines, licence suspension or accidents.","zh":"無視駕駛規例的司機可能面臨罰款、暫停駕照或意外。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"an NGO that focuses on","meaning":"一個專注於……的非政府組織","examples":[{"en":"SAFE Driving is an NGO that focuses on reducing traffic accidents.","zh":"SAFE Driving 是一個專注於減少交通意外的非政府組織。"},{"en":"An NGO that focuses on a problem is a non-governmental organisation that works mainly on that issue.","zh":"一個專注於某問題的非政府組織，是主要處理該議題的非政府機構。"},{"en":"An NGO that focuses on children’s health may provide free check-ups and education.","zh":"一個專注於兒童健康的非政府組織可能會提供免費檢查和教育。"},{"en":"When an NGO focuses on one clear goal, it can use its resources more effectively.","zh":"當非政府組織專注於一個清楚目標，它就能更有效地運用資源。"},{"en":"This phrase helps explain what an organisation mainly tries to improve.","zh":"這個短語有助解釋一個機構主要想改善甚麼。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"reducing traffic accidents","meaning":"減少交通意外","examples":[{"en":"SAFE Driving focuses on reducing traffic accidents.","zh":"SAFE Driving 專注於減少交通意外。"},{"en":"Reducing traffic accidents means making road crashes happen less often.","zh":"減少交通意外意思是令道路事故較少發生。"},{"en":"Installing clearer road signs can help with reducing traffic accidents near schools.","zh":"安裝更清楚的路牌可以幫助減少學校附近的交通意外。"},{"en":"Reducing traffic accidents can save lives, lower costs and improve public confidence.","zh":"減少交通意外可以拯救生命、降低成本並提升公眾信心。"},{"en":"A city can work on reducing traffic accidents through education, enforcement and better road design.","zh":"城市可以透過教育、執法和改善道路設計來減少交通意外。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"propose a bill","meaning":"提出法案","examples":[{"en":"SAFE Driving proposed a bill in 2018.","zh":"SAFE Driving 在 2018 年提出一項法案。"},{"en":"To propose a bill means to formally suggest a new law for discussion and possible approval.","zh":"提出法案意思是正式建議一項新法律，供討論和可能批准。"},{"en":"A politician may propose a bill to make public transport safer.","zh":"政治人物可能會提出法案，使公共交通更安全。"},{"en":"When a group proposes a bill, lawmakers must study its aims and possible effects.","zh":"當一個組織提出法案，立法者必須研究其目標和可能影響。"},{"en":"Proposing a bill does not mean it has already become law.","zh":"提出法案不代表它已經成為法律。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"increase the fine for","meaning":"提高……的罰款","examples":[{"en":"The bill aimed to increase the fine for drink-driving offences.","zh":"該法案旨在提高酒後駕駛罪行的罰款。"},{"en":"To increase the fine for something means to make the punishment payment higher.","zh":"提高某事的罰款意思是把懲罰性款項加高。"},{"en":"The government may increase the fine for illegal parking near hospitals.","zh":"政府可能會提高醫院附近違例泊車的罰款。"},{"en":"Increasing the fine for dangerous behaviour may discourage people from doing it.","zh":"提高危險行為的罰款可能會阻止人們這樣做。"},{"en":"A higher fine works best when people believe the rule will be enforced.","zh":"當人們相信規則會被執行時，較高罰款效果最好。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"drink-driving offences","meaning":"酒後駕駛罪行","examples":[{"en":"The bill aimed to increase the fine for drink-driving offences.","zh":"該法案旨在提高酒後駕駛罪行的罰款。"},{"en":"Drink-driving offences are illegal acts of driving after drinking too much alcohol.","zh":"酒後駕駛罪行是飲用過量酒精後駕駛的違法行為。"},{"en":"Police roadblocks can catch drivers who commit drink-driving offences.","zh":"警方路障可以截查干犯酒後駕駛罪行的司機。"},{"en":"Drink-driving offences are dangerous because alcohol slows reaction time and judgement.","zh":"酒後駕駛罪行很危險，因為酒精會減慢反應時間和判斷力。"},{"en":"Strong penalties for drink-driving offences can protect passengers, pedestrians and other drivers.","zh":"對酒後駕駛罪行施以嚴厲懲罰，可以保護乘客、行人和其他司機。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"people who drink and drive","meaning":"酒後駕駛的人","examples":[{"en":"The bill targeted people who drink and drive.","zh":"該法案針對酒後駕駛的人。"},{"en":"People who drink and drive are drivers who operate vehicles after drinking alcohol.","zh":"酒後駕駛的人是在飲酒後駕駛車輛的司機。"},{"en":"People who drink and drive may believe they are in control, but their reactions are slower.","zh":"酒後駕駛的人可能以為自己能控制情況，但反應會較慢。"},{"en":"Targeting people who drink and drive can reduce serious night-time accidents.","zh":"針對酒後駕駛的人可以減少嚴重夜間意外。"},{"en":"A safer choice is to take a taxi instead of becoming one of the people who drink and drive.","zh":"更安全的選擇是乘搭的士，而不是成為酒後駕駛的人。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"a survey was conducted by","meaning":"一項調查由……進行","examples":[{"en":"A survey was conducted by SAFE Driving.","zh":"一項調查由 SAFE Driving 進行。"},{"en":"A survey was conducted by someone means that person or organisation collected opinions or information from people.","zh":"一項調查由某人進行，意思是該人或機構向人們收集意見或資料。"},{"en":"A survey was conducted by the school to find out whether students wanted longer lunch breaks.","zh":"學校進行了一項調查，以了解學生是否想要更長午膳時間。"},{"en":"When a survey is conducted properly, the results can show what people really think.","zh":"當調查妥善進行，結果可以顯示人們真正想法。"},{"en":"This passive phrase is often used in reports to focus on the research, not the researchers.","zh":"這個被動短語常用於報告中，把重點放在研究，而不是研究者。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"response from the community","meaning":"社區反應","examples":[{"en":"The response from the community was quite positive.","zh":"社區反應相當正面。"},{"en":"The response from the community means how local people reacted to an idea, policy or event.","zh":"社區反應意思是本地居民對某個想法、政策或事件的反應。"},{"en":"The response from the community was strong after the school proposed a new library.","zh":"學校提出興建新圖書館後，社區反應很強烈。"},{"en":"A positive community response can help a project gain support and funding.","zh":"正面的社區反應可以幫助項目獲得支持和資金。"},{"en":"If the response from the community is negative, leaders may need to explain the plan better.","zh":"如果社區反應負面，領導者可能需要更好地解釋計劃。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"quite positive","meaning":"相當正面","examples":[{"en":"The response from the community was quite positive.","zh":"社區反應相當正面。"},{"en":"Quite positive means generally good or favourable, though not necessarily perfect.","zh":"相當正面意思是大致良好或支持，但不一定完美。"},{"en":"The feedback on the new bus route was quite positive because many people found it convenient.","zh":"新巴士路線的意見相當正面，因為很多人覺得方便。"},{"en":"If public reaction is quite positive, officials may continue with the plan.","zh":"如果公眾反應相當正面，官員可能會繼續推行計劃。"},{"en":"This phrase is useful when the result is encouraging but not completely enthusiastic.","zh":"當結果令人鼓舞但不是完全熱烈時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":2},{"front":"a quarter of","meaning":"四分之一的……","examples":[{"en":"A quarter of the respondents showed absolute support for the bill.","zh":"四分之一的受訪者對該法案表示絕對支持。"},{"en":"A quarter of something means one out of four equal parts, or 25%.","zh":"四分之一的某物意思是四等份中的一份，即 25%。"},{"en":"A quarter of the class arrived early for the school trip.","zh":"四分之一的班級學生提早到達參加學校旅行。"},{"en":"If a quarter of customers complain, the company should take the problem seriously.","zh":"如果四分之一的顧客投訴，公司應認真看待問題。"},{"en":"This phrase is useful for describing survey results and proportions.","zh":"這個短語適合用來描述調查結果和比例。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"absolute support for","meaning":"對……表示絕對支持","examples":[{"en":"A quarter of the respondents showed absolute support for the bill.","zh":"四分之一的受訪者對該法案表示絕對支持。"},{"en":"Absolute support for something means complete and strong approval of it.","zh":"對某事表示絕對支持意思是完全並強烈地贊成它。"},{"en":"Parents showed absolute support for the school’s plan to improve road safety.","zh":"家長對學校改善道路安全的計劃表示絕對支持。"},{"en":"Absolute support for a policy can make it easier for leaders to pass it.","zh":"對政策表示絕對支持可以令領導者更容易通過該政策。"},{"en":"This phrase is stronger than simple support because it leaves little doubt.","zh":"這個短語比一般支持更強，因為它幾乎沒有保留。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"more than 30%","meaning":"超過30%","examples":[{"en":"More than 30% of the respondents supported the bill.","zh":"超過 30% 的受訪者支持該法案。"},{"en":"More than 30% means a proportion greater than thirty out of one hundred.","zh":"超過 30% 意思是比例多於一百人中的三十人。"},{"en":"More than 30% of students chose cycling as their favourite form of exercise.","zh":"超過 30% 的學生選擇踏單車作為最喜愛的運動。"},{"en":"If more than 30% of residents support a plan, officials may see it as meaningful support.","zh":"如果超過 30% 的居民支持一項計劃，官員可能會視之為有意義的支持。"},{"en":"Percentages like more than 30% help readers compare survey results clearly.","zh":"像超過 30% 這樣的百分比有助讀者清楚比較調查結果。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"show support for","meaning":"表示支持……","examples":[{"en":"More than 30% of the respondents showed support for the bill.","zh":"超過 30% 的受訪者表示支持該法案。"},{"en":"To show support for something means to express approval or encouragement for it.","zh":"表示支持某事意思是表達對它的贊成或鼓勵。"},{"en":"Students showed support for the charity event by volunteering after school.","zh":"學生透過放學後做義工表示支持慈善活動。"},{"en":"When many people show support for a policy, decision-makers may feel more confident.","zh":"當很多人表示支持某政策，決策者可能會更有信心。"},{"en":"People can show support for an idea through votes, comments, donations or attendance.","zh":"人們可以透過投票、留言、捐款或出席來表示支持某個想法。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"disapproval of","meaning":"對……表示不支持","examples":[{"en":"Only 5% of the respondents showed disapproval of the bill.","zh":"只有 5% 的受訪者對該法案表示不支持。"},{"en":"Disapproval of something means a negative opinion or lack of support for it.","zh":"對某事表示不支持意思是對它持負面意見或不贊成。"},{"en":"Parents showed disapproval of the school’s plan to shorten lunch time.","zh":"家長對學校縮短午膳時間的計劃表示不支持。"},{"en":"Strong disapproval of a policy can force leaders to explain or change it.","zh":"對政策表示強烈不支持可能迫使領導者解釋或修改它。"},{"en":"Disapproval of an idea does not always mean people reject its goal; they may dislike its method.","zh":"對某想法表示不支持不一定代表人們反對其目標；他們可能是不喜歡方法。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"approve of","meaning":"贊成；認同","examples":[{"en":"In addition, 20 politicians approved of the bill.","zh":"此外，20 名政治人物贊成該法案。"},{"en":"To approve of something means to think it is good, acceptable or right.","zh":"贊成某事意思是認為它良好、可接受或正確。"},{"en":"Many parents approve of extra road safety lessons for children.","zh":"許多家長贊成為兒童增加道路安全課程。"},{"en":"If politicians approve of a bill, it may have a better chance of passing.","zh":"如果政治人物贊成某法案，它通過的機會可能較高。"},{"en":"Approving of an idea is not the same as actually voting it into law.","zh":"贊成某個想法不等於已經真正投票使它成為法律。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"politicians","meaning":"政治人物","examples":[{"en":"Twenty politicians approved of the bill.","zh":"二十名政治人物贊成該法案。"},{"en":"Politicians are people who work in politics and help make public decisions or laws.","zh":"政治人物是在政治界工作，並協助作出公共決定或制定法律的人。"},{"en":"Politicians may debate transport rules before changing road safety laws.","zh":"政治人物可能會在修改道路安全法前辯論交通規則。"},{"en":"When politicians support a proposal, the public may pay more attention to it.","zh":"當政治人物支持一項建議，公眾可能會更注意它。"},{"en":"Good politicians should listen to evidence, experts and citizens before making decisions.","zh":"好的政治人物在作決定前應聆聽證據、專家和市民意見。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"prevent car accidents","meaning":"預防交通意外","examples":[{"en":"Many car accidents can be prevented with different car gadgets.","zh":"許多交通意外可以透過不同汽車裝置預防。"},{"en":"To prevent car accidents means to stop road crashes from happening.","zh":"預防交通意外意思是阻止道路事故發生。"},{"en":"Speed cameras can help prevent car accidents by discouraging dangerous driving.","zh":"測速相機可以透過阻止危險駕駛來預防交通意外。"},{"en":"Preventing car accidents saves lives and reduces damage costs.","zh":"預防交通意外可以拯救生命並減少損失金額。"},{"en":"Drivers can prevent car accidents by staying alert, obeying signs and avoiding alcohol.","zh":"司機可以透過保持警覺、遵守路牌和避免飲酒來預防交通意外。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"different gadgets for cars","meaning":"不同的汽車裝置","examples":[{"en":"Many car accidents can be prevented with different gadgets for cars.","zh":"許多交通意外可以透過不同的汽車裝置預防。"},{"en":"Different gadgets for cars are devices designed to make driving safer, easier or more convenient.","zh":"不同的汽車裝置是為令駕駛更安全、更容易或更方便而設計的設備。"},{"en":"Parking sensors and dash cameras are different gadgets for cars that help drivers notice danger.","zh":"泊車感應器和行車記錄儀是不同的汽車裝置，可以幫助司機察覺危險。"},{"en":"Different gadgets for cars can reduce mistakes, but drivers must still pay attention.","zh":"不同的汽車裝置可以減少錯誤，但司機仍必須專心。"},{"en":"Choosing useful gadgets for cars is better than buying devices that only look impressive.","zh":"選擇實用的汽車裝置，比購買只看起來厲害的設備更好。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"rapidly expandable airbags","meaning":"快速膨脹安全氣袋","examples":[{"en":"Rapidly expandable airbags can help save passengers’ lives.","zh":"快速膨脹安全氣袋可以幫助拯救乘客生命。"},{"en":"Rapidly expandable airbags are safety bags that open very quickly during a crash.","zh":"快速膨脹安全氣袋是在撞車時非常迅速打開的安全氣袋。"},{"en":"When a car hits another vehicle, rapidly expandable airbags can protect the head and chest.","zh":"當汽車撞上另一輛車時，快速膨脹安全氣袋可以保護頭部和胸部。"},{"en":"Rapidly expandable airbags reduce injury by softening the impact during an accident.","zh":"快速膨脹安全氣袋透過減輕意外中的撞擊來減少受傷。"},{"en":"Airbags are helpful, but passengers should still wear seatbelts.","zh":"安全氣袋很有幫助，但乘客仍應繫上安全帶。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"save passengers’ lives","meaning":"拯救乘客生命","examples":[{"en":"Rapidly expandable airbags can save passengers’ lives.","zh":"快速膨脹安全氣袋可以拯救乘客生命。"},{"en":"To save passengers’ lives means to prevent people travelling in a vehicle from dying.","zh":"拯救乘客生命意思是防止車上乘客死亡。"},{"en":"Seatbelts can save passengers’ lives by holding them in place during a crash.","zh":"安全帶可以在撞車時固定乘客，從而拯救乘客生命。"},{"en":"Safety devices save passengers’ lives when they reduce the force of an accident.","zh":"當安全裝置減輕意外衝擊力時，就可以拯救乘客生命。"},{"en":"Drivers also help save passengers’ lives by driving slowly in dangerous weather.","zh":"司機在危險天氣中慢駛，也有助拯救乘客生命。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":3},{"front":"GPS systems","meaning":"全球定位系統","examples":[{"en":"GPS systems can call the police immediately after an accident.","zh":"全球定位系統可以在意外後立即報警。"},{"en":"GPS systems use satellite signals to find a vehicle’s location.","zh":"全球定位系統使用衛星訊號來找出車輛位置。"},{"en":"A GPS system can help drivers choose a faster route when roads are blocked.","zh":"當道路受阻時，全球定位系統可以幫助司機選擇更快路線。"},{"en":"In an emergency, GPS systems can help rescuers find the accident location quickly.","zh":"在緊急情況中，全球定位系統可以幫助救援人員快速找到意外地點。"},{"en":"GPS systems are useful, but drivers should not stare at the screen while driving.","zh":"全球定位系統很有用，但司機駕駛時不應盯著螢幕。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"call the police immediately","meaning":"立即報警","examples":[{"en":"GPS systems can call the police immediately.","zh":"全球定位系統可以立即報警。"},{"en":"To call the police immediately means to contact the police at once, without delay.","zh":"立即報警意思是毫不延誤地聯絡警方。"},{"en":"If someone is injured in a crash, witnesses should call the police immediately.","zh":"如果有人在撞車中受傷，目擊者應立即報警。"},{"en":"Calling the police immediately can help emergency services arrive sooner.","zh":"立即報警可以幫助緊急服務更快到達。"},{"en":"In a serious road accident, waiting too long to call the police can make the situation worse.","zh":"在嚴重交通意外中，太遲報警可能令情況惡化。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"firm-grip seatbelts","meaning":"強力固定安全帶","examples":[{"en":"Firm-grip seatbelts are available on the market.","zh":"強力固定安全帶在市面有售。"},{"en":"Firm-grip seatbelts are safety belts designed to hold passengers securely in their seats.","zh":"強力固定安全帶是設計用來把乘客穩固固定在座位上的安全帶。"},{"en":"Firm-grip seatbelts can stop passengers from being thrown forward during sudden braking.","zh":"強力固定安全帶可以防止乘客在突然煞車時向前拋出。"},{"en":"If seatbelts hold the body firmly, injuries may be reduced in a crash.","zh":"如果安全帶能牢牢固定身體，撞車時受傷可能會減少。"},{"en":"Even with firm-grip seatbelts, passengers must wear them correctly.","zh":"即使有強力固定安全帶，乘客也必須正確佩戴。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"on the market","meaning":"市面有售","examples":[{"en":"Rapidly expandable airbags and firm-grip seatbelts are on the market.","zh":"快速膨脹安全氣袋和強力固定安全帶在市面有售。"},{"en":"On the market means available for people to buy.","zh":"市面有售意思是人們可以購買得到。"},{"en":"Many new electric cars are now on the market.","zh":"許多新款電動車現在在市面有售。"},{"en":"When safer products are on the market, consumers have more choices.","zh":"當更安全的產品在市面有售，消費者會有更多選擇。"},{"en":"A device being on the market does not always mean every driver can afford it.","zh":"某裝置在市面有售，不一定代表每名司機都負擔得起。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"It is reported that","meaning":"據報道","examples":[{"en":"It is reported that these gadgets can reduce car accidents by 50%.","zh":"據報道，這些裝置可以令交通意外減少 50%。"},{"en":"It is reported that means information has been stated in a report, news source or official account.","zh":"據報道意思是資料已在報告、新聞來源或官方說法中被提出。"},{"en":"It is reported that the new traffic lights have reduced accidents near the school.","zh":"據報道，新的交通燈已減少學校附近的意外。"},{"en":"This phrase is often used when the writer is sharing information from another source.","zh":"當作者分享來自另一來源的資料時，常使用這個短語。"},{"en":"If it is reported that a policy works, readers may still want to know who reported it and how.","zh":"如果據報道某政策有效，讀者可能仍想知道是誰報道以及如何得出結果。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"with these gadgets","meaning":"有了這些裝置","examples":[{"en":"With these gadgets, car accidents can be reduced by 50%.","zh":"有了這些裝置，交通意外可以減少 50%。"},{"en":"With these gadgets means by using these devices or because these devices are available.","zh":"有了這些裝置意思是透過使用這些設備，或因為這些設備可以使用。"},{"en":"With these gadgets, drivers can receive warnings before they get too close to another car.","zh":"有了這些裝置，司機可以在太接近另一輛車前收到警告。"},{"en":"With these gadgets, a city may reduce accident damage and emergency response time.","zh":"有了這些裝置，城市可能減少意外損害和緊急應變時間。"},{"en":"Gadgets can help, but with these gadgets alone, unsafe drivers may still cause accidents.","zh":"裝置可以幫助人，但單靠這些裝置，不安全司機仍可能造成意外。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"be reduced by 50%","meaning":"減少50%","examples":[{"en":"Car accidents can be reduced by 50% with these gadgets.","zh":"有了這些裝置，交通意外可以減少 50%。"},{"en":"To be reduced by 50% means to become half as much as before.","zh":"減少 50% 意思是變成原來的一半。"},{"en":"If waiting time is reduced by 50%, a thirty-minute wait becomes fifteen minutes.","zh":"如果等候時間減少 50%，三十分鐘的等待就變成十五分鐘。"},{"en":"Accident numbers may be reduced by 50% if safety measures are effective.","zh":"如果安全措施有效，意外數字可能減少 50%。"},{"en":"Saying something is reduced by 50% shows a large and measurable decrease.","zh":"說某事減少 50%，表示有大幅而可量度的下降。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"In fact","meaning":"事實上","examples":[{"en":"In fact, the car gadget market grew by 70% from 2019 to 2020.","zh":"事實上，汽車裝置市場由 2019 年至 2020 年增長了 70%。"},{"en":"In fact is used to add true information that supports, corrects or strengthens a previous point.","zh":"事實上用來補充真實資料，以支持、糾正或加強前面的重點。"},{"en":"Many people think the shop is new; in fact, it has been open for ten years.","zh":"很多人以為那間店是新的；事實上，它已經開了十年。"},{"en":"A city may seem safer; in fact, accident numbers have fallen for five years.","zh":"一個城市可能看起來更安全；事實上，意外數字已連續五年下降。"},{"en":"This phrase helps the writer introduce a stronger or more exact fact.","zh":"這個短語幫助作者引入更有力或更準確的事實。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"the gadget market","meaning":"裝置市場","examples":[{"en":"The car gadget market grew by 70% from 2019 to 2020.","zh":"汽車裝置市場由 2019 年至 2020 年增長了 70%。"},{"en":"The gadget market is the business area involving the buying and selling of electronic devices or useful tools.","zh":"裝置市場是買賣電子設備或實用工具的商業領域。"},{"en":"The gadget market for smart watches grew when people became more interested in health tracking.","zh":"當人們更重視健康追蹤，智能手錶裝置市場就增長了。"},{"en":"If safety gadgets become popular, the gadget market may expand quickly.","zh":"如果安全裝置變得受歡迎，裝置市場可能會迅速擴大。"},{"en":"A growing gadget market can attract new companies, new products and stronger competition.","zh":"增長中的裝置市場可以吸引新公司、新產品和更強競爭。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"grow by 70%","meaning":"增長70%","examples":[{"en":"The car gadget market grew by 70% from 2019 to 2020.","zh":"汽車裝置市場由 2019 年至 2020 年增長了 70%。"},{"en":"To grow by 70% means to increase by seventy percent compared with an earlier amount.","zh":"增長 70% 意思是與較早數量相比增加七成。"},{"en":"A school club may grow by 70% if many new students join.","zh":"如果很多新學生加入，學校學會可能增長 70%。"},{"en":"When demand grows by 70%, companies may need to produce more goods quickly.","zh":"當需求增長 70%，公司可能需要迅速生產更多貨品。"},{"en":"This phrase describes the size of an increase, not the final total number.","zh":"這個短語描述增幅大小，而不是最終總數。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4},{"front":"from 2019 to 2020","meaning":"由2019年至2020年","examples":[{"en":"The gadget market grew by 70% from 2019 to 2020.","zh":"裝置市場由 2019 年至 2020 年增長了 70%。"},{"en":"From 2019 to 2020 means during the period starting in 2019 and ending in 2020.","zh":"由 2019 年至 2020 年意思是從 2019 年開始，到 2020 年結束的期間。"},{"en":"From 2019 to 2020, many schools began using more online learning tools.","zh":"由 2019 年至 2020 年，許多學校開始使用更多網上學習工具。"},{"en":"Comparing data from 2019 to 2020 helps people see how quickly a situation changed.","zh":"比較由 2019 年至 2020 年的數據，有助人們看出情況變化得有多快。"},{"en":"This phrase gives a clear time period for a trend, increase or decrease.","zh":"這個短語為趨勢、增長或下降提供清楚時間範圍。"}],"source":"Flash Cards -實用文 - Outline : Summary.pdf","sourcePage":4}],"dse/paper-3/practical-english-writing/practical-formats/press-release":[{"front":"press release","meaning":"新聞稿","examples":[{"en":"This is a press release concerning the accusations against the company’s XZ Laptop.","zh":"這是一篇關於針對該公司 XZ Laptop 指控的新聞稿。"},{"en":"A press release is an official written statement sent to the public or the media.","zh":"press release 指發給公眾或媒體的正式書面聲明。"},{"en":"A school may issue a press release to announce a new scholarship programme.","zh":"學校可能會發出新聞稿，公布新的獎學金計劃。"},{"en":"A clear press release can help prevent rumours because it gives the organisation’s official position.","zh":"清晰的新聞稿可以幫助防止謠言，因為它提供機構的官方立場。"},{"en":"Companies often use a press release when they need to respond quickly to public concerns.","zh":"公司需要迅速回應公眾關注時，常會使用新聞稿。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"false accusations","meaning":"失實指控","examples":[{"en":"The company issued a press release against false accusations.","zh":"該公司發出新聞稿反駁失實指控。"},{"en":"False accusations are claims that blame someone for something they did not do or that is not true.","zh":"false accusations 指把某人沒有做過或並非真實的事情歸咎於他的指控。"},{"en":"A student may feel hurt if false accusations are made about cheating.","zh":"如果有人對學生作弊作出失實指控，該學生可能會感到受傷。"},{"en":"False accusations can damage trust, reputation, and relationships even after they are corrected.","zh":"失實指控即使被糾正後，也可能損害信任、聲譽和關係。"},{"en":"Before repeating accusations, people should check evidence to avoid spreading false accusations.","zh":"在重複指控前，人們應查證證據，以免散播失實指控。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"accusations against","meaning":"針對……的指控","examples":[{"en":"The press release concerns the accusations against the company’s XZ Laptop.","zh":"新聞稿是關於針對該公司 XZ Laptop 的指控。"},{"en":"Accusations against someone or something are claims saying that person, product, or organisation has done something wrong.","zh":"accusations against someone or something 指聲稱某人、產品或機構做錯事的指控。"},{"en":"The manager responded to accusations against the restaurant’s hygiene standards.","zh":"經理回應了針對餐廳衛生標準的指控。"},{"en":"Accusations against a product can reduce sales if customers begin to lose trust.","zh":"如果顧客開始失去信任，針對產品的指控可能會令銷售下跌。"},{"en":"Serious accusations against an organisation should be answered with evidence, not emotion.","zh":"針對機構的嚴重指控應以證據回應，而不是以情緒回應。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"concerning","meaning":"關於","examples":[{"en":"The press release concerning the accusations was issued by LMB Tech Buddies.","zh":"關於這些指控的新聞稿由 LMB Tech Buddies 發出。"},{"en":"Concerning means about or related to a particular subject.","zh":"concerning 指關於或與某特定主題有關。"},{"en":"The school sent parents a letter concerning the new lunch arrangements.","zh":"學校向家長發出一封關於新午膳安排的信。"},{"en":"If a notice concerning safety is unclear, people may not know what action to take.","zh":"如果關於安全的告示不清楚，人們可能不知道應採取甚麼行動。"},{"en":"This word is common in formal writing when introducing the topic of a message or document.","zh":"這個詞常見於正式寫作，用來引入訊息或文件的主題。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"lately","meaning":"近日","examples":[{"en":"Lately, several accusations have been made against the product.","zh":"近日，該產品受到數項指控。"},{"en":"Lately means recently or during the past short period of time.","zh":"lately 指最近或在過去一小段時間內。"},{"en":"Lately, many students have been using online notes to revise for exams.","zh":"近日，許多學生一直使用網上筆記溫習考試。"},{"en":"If a machine has been making strange noises lately, it may need checking.","zh":"如果機器近日一直發出奇怪聲音，可能需要檢查。"},{"en":"This word is useful when talking about a recent change, pattern, or problem.","zh":"這個詞適合用來談近期變化、模式或問題。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"come to our attention","meaning":"我們注意到","examples":[{"en":"It has come to our attention that there have been multiple accusations against our product.","zh":"我們注意到，我們的產品受到多項指控。"},{"en":"When something has come to our attention, it means we have noticed it or been informed about it.","zh":"come to our attention 指我們注意到某事，或有人告知我們某事。"},{"en":"It has come to our attention that some students have been entering the library after closing time.","zh":"我們注意到，有些學生在圖書館關閉後仍進入。"},{"en":"When a problem comes to a company’s attention, it should respond before the issue grows.","zh":"當公司注意到某個問題，應在問題擴大前作出回應。"},{"en":"This phrase sounds formal and is often used in announcements or official statements.","zh":"這個短語語氣正式，常用於公告或官方聲明。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"multiple accusations","meaning":"多項指控","examples":[{"en":"There have been multiple accusations against the XZ Laptop.","zh":"XZ Laptop 受到多項指控。"},{"en":"Multiple accusations means more than one claim blaming someone or something for wrongdoing.","zh":"multiple accusations 指不止一項指稱某人或某物有錯的指控。"},{"en":"The school investigated multiple accusations about unfair marking.","zh":"學校調查了多項關於評分不公的指控。"},{"en":"Multiple accusations can make a situation more serious because they suggest repeated concern.","zh":"多項指控可能令情況更嚴重，因為它們顯示反覆出現的關注。"},{"en":"However, multiple accusations are still not proof unless evidence supports them.","zh":"然而，多項指控仍不等於證據，除非有證據支持。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"our product","meaning":"我們的產品","examples":[{"en":"The accusations were made against our product, the XZ Laptop.","zh":"這些指控是針對我們的產品 XZ Laptop 作出的。"},{"en":"Our product means the item made, sold, or provided by our company.","zh":"our product 指我們公司製造、銷售或提供的物品。"},{"en":"We improved our product after customers said the old design was too heavy.","zh":"顧客表示舊設計太重後，我們改善了我們的產品。"},{"en":"If our product has a real problem, the company should repair it or explain the solution clearly.","zh":"如果我們的產品有真正問題，公司應維修它或清楚解釋解決方案。"},{"en":"In business writing, “our product” helps a company refer directly to what it sells.","zh":"在商業寫作中，our product 幫助公司直接指稱自己銷售的東西。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"in fact","meaning":"事實上","examples":[{"en":"These accusations are, in fact, completely misleading.","zh":"這些指控事實上完全誤導。"},{"en":"In fact is used to introduce the truth, especially when it corrects or strengthens a previous idea.","zh":"in fact 用來引出事實，尤其是在糾正或加強前文意思時。"},{"en":"Many people think the shop is expensive; in fact, its lunch sets are cheaper than nearby restaurants.","zh":"很多人以為這間店很貴；事實上，它的午餐套餐比附近餐廳便宜。"},{"en":"In fact can help a writer contrast public belief with actual evidence.","zh":"in fact 可以幫助作者把公眾看法與實際證據作對比。"},{"en":"This phrase is useful when you want to sound clear, firm, and factual.","zh":"當你想表達得清楚、堅定和基於事實時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"completely misleading","meaning":"完全誤導","examples":[{"en":"The company states that the accusations are completely misleading.","zh":"公司表示這些指控完全誤導。"},{"en":"Completely misleading means giving people a totally wrong impression or understanding.","zh":"completely misleading 指令 人產生完全錯誤的印象或理解。"},{"en":"A photo taken from one angle can be completely misleading if it hides the full situation.","zh":"如果一張相片隱藏了完整情況，單從一個角度拍攝可以完全誤導。"},{"en":"Completely misleading information can make customers make decisions based on false beliefs.","zh":"完全誤導的資訊可能令顧客根據錯誤信念作決定。"},{"en":"This phrase is strong because it says the information is not just unclear, but seriously wrong.","zh":"這個短語語氣強烈，因為它表示資訊不只是含糊，而是嚴重錯誤。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"aim to","meaning":"旨在；目的是","examples":[{"en":"In this press release, we aim to clarify the allegations.","zh":"在這篇新聞稿中，我們旨在澄清指控。"},{"en":"Aim to means intend to do something or have a particular purpose.","zh":"aim to 指打算做某事，或有某個特定目的。"},{"en":"This course aims to help beginners speak English more confidently.","zh":"這個課程旨在幫助初學者更有信心地說英語。"},{"en":"If a policy aims to reduce waste, it should include clear recycling rules.","zh":"如果政策旨在減少浪費，就應包括清晰的回收規則。"},{"en":"This phrase is useful when explaining the purpose of a report, letter, plan, or announcement.","zh":"這個短語適合用來解釋報告、信件、計劃或公告的目的。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":1},{"front":"clarify the allegations","meaning":"澄清指控","examples":[{"en":"The company aims to clarify the allegations made against its product.","zh":"公司旨在澄清針對其產品的指控。"},{"en":"To clarify the allegations means to explain the accusations clearly and show what is true or false.","zh":"clarify the allegations 指清楚解釋指控，並說明甚麼是真、甚麼是假。"},{"en":"The principal held a meeting to clarify the allegations about unfair treatment.","zh":"校長召開會議，澄清關於不公平對待的指控。"},{"en":"Clarifying the allegations can reduce confusion because people hear the official explanation.","zh":"澄清指控可以減少混亂，因為人們能聽到官方解釋。"},{"en":"This phrase is often used when an organisation responds to serious public claims.","zh":"當機構回應嚴重公眾聲稱時，這個短語常會使用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"it has been claimed that","meaning":"有人聲稱","examples":[{"en":"It has been claimed that the XZ Laptop has a low battery capacity.","zh":"有人聲稱 XZ Laptop 電池容量低。"},{"en":"It has been claimed that means some people have said something, but the writer may not accept it as true.","zh":"it has been claimed that 指有人說某事，但作者不一定接受它為真。"},{"en":"It has been claimed that the new timetable is unfair to junior students.","zh":"有人聲稱新時間表對低年級學生不公平。"},{"en":"This phrase lets a writer mention an accusation without agreeing with it.","zh":"這個短語讓作者提及一項指控，而不表示同意它。"},{"en":"It is useful in formal writing when the source of a claim is unclear or disputed.","zh":"當聲稱來源不清或有爭議時，這個短語適合用於正式寫作。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"low battery capacity","meaning":"電池容量低","examples":[{"en":"Some people claimed that the XZ Laptop has a low battery capacity.","zh":"有些人聲稱 XZ Laptop 電池容量低。"},{"en":"Low battery capacity means a device cannot store much power and may run out of energy quickly.","zh":"low battery capacity 指裝置不能儲存很多電力，可能很快耗電。"},{"en":"A phone with low battery capacity may need charging several times a day.","zh":"電池容量低的手機可能一天要充電幾次。"},{"en":"Low battery capacity can frustrate users because they cannot work or study for long without a charger.","zh":"電池容量低可能令使用者感到沮喪，因為他們不能長時間不帶充電器工作或學習。"},{"en":"This phrase is usually used when comparing how long electronic devices can operate.","zh":"這個短語通常用於比較電子裝置可以運作多久。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"can only last up to","meaning":"最多只能維持","examples":[{"en":"It was claimed that the laptop can only last up to two hours.","zh":"有人聲稱該手提電腦最多只能維持兩小時。"},{"en":"Can only last up to means the maximum time something can continue is limited to that amount.","zh":"can only last up to 指某物可以持續的最長時間只限於該數量。"},{"en":"This old phone can only last up to three hours if the screen is always on.","zh":"如果螢幕一直開著，這部舊手機最多只能維持三小時。"},{"en":"If a battery can only last up to one hour, users may find the device inconvenient.","zh":"如果電池最多只能維持一小時，使用者可能會覺得裝置不方便。"},{"en":"The word “only” makes the limitation sound disappointing or insufficient.","zh":"only 一詞令限制聽起來令人失望或不足。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"simply not true","meaning":"根本不是真的","examples":[{"en":"The company says this claim is simply not true.","zh":"公司表示這項聲稱根本不是真的。"},{"en":"Simply not true means completely false, with no need for a complicated explanation.","zh":"simply not true 指完全錯誤，無需複雜解釋。"},{"en":"The rumour that the school will close next week is simply not true.","zh":"學校下星期會關閉的傳聞根本不是真的。"},{"en":"Saying something is simply not true is a direct way to reject false information.","zh":"說某事 simply not true 是直接否定虛假資訊的方法。"},{"en":"This phrase sounds firm, so it is often used when correcting a clear mistake.","zh":"這個短語語氣堅定，因此常用於糾正明顯錯誤。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"as a matter of fact","meaning":"事實上","examples":[{"en":"As a matter of fact, the XZ Laptop is equipped with a newly designed lithium battery.","zh":"事實上，XZ Laptop 配備有全新設計的鋰電池。"},{"en":"As a matter of fact is used to introduce a factual correction or stronger evidence.","zh":"as a matter of fact 用來引入事實性的糾正或更有力的證據。"},{"en":"As a matter of fact, the library is open on Sundays, not closed.","zh":"事實上，圖書館星期日開放，並非關閉。"},{"en":"This phrase can correct a misunderstanding by giving the real situation.","zh":"這個短語可以透過提供真實情況來糾正誤解。"},{"en":"It is more formal than “actually” and is useful in reports or public statements.","zh":"它比 actually 更正式，適合用於報告或公開聲明。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"be equipped with","meaning":"配備有","examples":[{"en":"The XZ Laptop is equipped with a newly designed lithium battery.","zh":"XZ Laptop 配備有全新設計的鋰電池。"},{"en":"To be equipped with something means to have a particular tool, part, or feature included.","zh":"be equipped with something 指配有某種工具、部件或功能。"},{"en":"The classroom is equipped with a projector and a sound system.","zh":"課室配備有投影機和音響系統。"},{"en":"A car equipped with safety cameras can help drivers avoid accidents.","zh":"配備安全鏡頭的汽車可以幫助司機避免意外。"},{"en":"This phrase is common when describing the features of machines, rooms, vehicles, or devices.","zh":"這個短語常用於描述機器、房間、車輛或裝置的功能。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"newly designed","meaning":"全新設計的","examples":[{"en":"The laptop uses a newly designed lithium battery.","zh":"該手提電腦使用全新設計的鋰電池。"},{"en":"Newly designed means recently created or improved with a new design.","zh":"newly designed 指最近創造或以新設計改善的。"},{"en":"The school introduced newly designed desks that give students more space.","zh":"學校引入了全新設計的書桌，讓學生有更多空間。"},{"en":"A newly designed product may solve problems found in older versions.","zh":"全新設計的產品可能解決舊版本中發現的問題。"},{"en":"This phrase suggests the design is recent and may include improvements.","zh":"這個短語暗示設計是新的，而且可能包含改善。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"lithium battery","meaning":"鋰電池","examples":[{"en":"The XZ Laptop is equipped with a lithium battery.","zh":"XZ Laptop 配備有鋰電池。"},{"en":"A lithium battery is a rechargeable battery commonly used in phones, laptops, cameras, and other electronic devices.","zh":"lithium battery 指常用於手機、手提電腦、相機和其他電子裝置的可充電電池。"},{"en":"Most modern mobile phones use lithium batteries because they are light and store energy well.","zh":"大多數現代手機使用鋰電池，因為它們較輕且能有效儲存電力。"},{"en":"If a lithium battery is damaged or overheated, it should be checked carefully for safety.","zh":"如果鋰電池受損或過熱，應仔細檢查以確保安全。"},{"en":"This term is often used when discussing battery life, charging, and electronic product performance.","zh":"這個詞常用於討論電池續航、充電和電子產品表現。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"typically lasts for","meaning":"一般可維持","examples":[{"en":"The battery typically lasts for five hours.","zh":"電池一般可維持五小時。"},{"en":"Typically lasts for means usually continues or works for a certain period of time.","zh":"typically lasts for 指通常能持續或運作某段時間。"},{"en":"A fully charged wireless mouse typically lasts for several weeks.","zh":"充滿電的無線滑鼠一般可維持數星期。"},{"en":"If a lesson typically lasts for one hour, students can plan their schedule around it.","zh":"如果一堂課一般可維持一小時，學生便可按此安排時間表。"},{"en":"This phrase describes the normal situation, not the best or worst possible result.","zh":"這個短語描述正常情況，而不是最好或最差結果。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"fully charged","meaning":"充滿電後","examples":[{"en":"When fully charged, the laptop can last up to ten hours.","zh":"充滿電後，該手提電腦最多可維持十小時。"},{"en":"Fully charged means a battery has been charged to its maximum power level.","zh":"fully charged 指電池已充至最高電量。"},{"en":"A fully charged phone is useful when you need to travel for a whole day.","zh":"當你需要整天外出時，充滿電的手機很有用。"},{"en":"If a device is not fully charged, it may run out of power during an important meeting.","zh":"如果裝置未充滿電，可能會在重要會議期間沒電。"},{"en":"This phrase is often used when explaining how long electronic devices can be used.","zh":"這個短語常用於解釋電子裝置可使用多久。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":2},{"front":"last up to ten hours","meaning":"最多可維持十小時","examples":[{"en":"The laptop can last up to ten hours when fully charged.","zh":"該手提電腦充滿電後最多可維持十小時。"},{"en":"Last up to ten hours means continue working for a maximum of ten hours.","zh":"last up to ten hours 指最多可以運作十小時。"},{"en":"These headphones can last up to ten hours, so they are suitable for long journeys.","zh":"這副耳機最多可維持十小時，因此適合長途旅程。"},{"en":"If a tablet can last up to ten hours, students can use it for several lessons without charging.","zh":"如果平板電腦最多可維持十小時，學生可以上幾堂課都不用充電。"},{"en":"“Up to” means ten hours is the possible maximum, not always the guaranteed result.","zh":"up to 表示十小時是可能的最高值，不一定每次都保證達到。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"entirely groundless","meaning":"完全沒有根據","examples":[{"en":"It is entirely groundless to claim that the XZ Laptop has a low battery capacity.","zh":"聲稱 XZ Laptop 電池容量低是完全沒有根據的。"},{"en":"Entirely groundless means having no evidence, basis, or reasonable support at all.","zh":"entirely groundless 指完全沒有證據、基礎或合理支持。"},{"en":"The rumour about the teacher leaving was entirely groundless because no resignation had been submitted.","zh":"關於那位老師離職的傳聞完全沒有根據，因為沒有提交辭職信。"},{"en":"Entirely groundless claims can unfairly damage a person’s reputation.","zh":"完全沒有根據的聲稱可能不公平地損害一個人的聲譽。"},{"en":"This phrase is very strong and is used to reject accusations firmly.","zh":"這個短語語氣很強，用來堅定否定指控。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"claim that","meaning":"聲稱","examples":[{"en":"It is groundless to claim that the laptop has a low battery capacity.","zh":"聲稱該手提電腦電池容量低是沒有根據的。"},{"en":"To claim that something is true means to say it is true, especially when others may question it.","zh":"claim that something is true 指聲稱某事屬實，尤其是當別人可能質疑時。"},{"en":"A shop may claim that its shoes are waterproof, but customers will expect proof.","zh":"商店可能聲稱其鞋子防水，但顧客會期望有證明。"},{"en":"If people claim that a product is unsafe without evidence, the company may respond publicly.","zh":"如果人們在沒有證據下聲稱產品不安全，公司可能會公開回應。"},{"en":"This phrase is useful when reporting what someone says without fully accepting it.","zh":"這個短語適合用來報告別人的說法，而不表示完全接受。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"furthermore","meaning":"此外","examples":[{"en":"Furthermore, the product has also been accused of overheating easily.","zh":"此外，該產品亦被指容易過熱。"},{"en":"Furthermore means in addition or more importantly, and it adds another point to the discussion.","zh":"furthermore 指此外或更進一步，用來在討論中加入另一點。"},{"en":"The hotel is close to the station; furthermore, its rooms are reasonably priced.","zh":"這間酒店靠近車站；此外，房價也合理。"},{"en":"In a report, furthermore helps connect one point to another in a formal way.","zh":"在報告中，furthermore 能以正式方式把一個要點連接到另一個要點。"},{"en":"This word is useful when the writer wants to build a stronger argument with extra information.","zh":"當作者想加入額外資料以建立更強論點時，這個詞很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"be accused of","meaning":"被指控","examples":[{"en":"The product has been accused of overheating easily.","zh":"該產品被指控容易過熱。"},{"en":"To be accused of something means to be blamed or said to have done something wrong.","zh":"be accused of something 指被責怪或被指稱做了錯事。"},{"en":"A student may be accused of copying homework if two answers are exactly the same.","zh":"如果兩份答案完全相同，學生可能會被指控抄功課。"},{"en":"If a restaurant is accused of poor hygiene, it may need to show inspection records.","zh":"如果餐廳被指控衛生差，可能需要展示檢查紀錄。"},{"en":"Being accused of something does not prove guilt; evidence is still needed.","zh":"被指控某事並不證明有罪；仍然需要證據。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"overheat easily","meaning":"容易過熱","examples":[{"en":"Some users claimed that the laptop overheats easily.","zh":"有些使用者聲稱該手提電腦容易過熱。"},{"en":"To overheat easily means to become too hot quickly or often during use.","zh":"overheat easily 指在使用時很快或經常變得過熱。"},{"en":"An old phone may overheat easily when several apps are open at the same time.","zh":"當同時開啟幾個應用程式，舊手機可能容易過熱。"},{"en":"If a laptop overheats easily, users may worry about safety and performance.","zh":"如果手提電腦容易過熱，使用者可能會擔心安全和效能。"},{"en":"This phrase is usually used for machines or electronic devices that produce too much heat.","zh":"這個短語通常用於會產生過多熱力的機器或電子裝置。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"after three hours of use","meaning":"使用三小時後","examples":[{"en":"It was claimed that the laptop overheats after three hours of use.","zh":"有人聲稱該手提電腦使用三小時後會過熱。"},{"en":"After three hours of use means once the device or item has been used continuously for three hours.","zh":"after three hours of use 指裝置或物品連續使用三小時後。"},{"en":"The tablet may need charging after three hours of use if the screen brightness is high.","zh":"如果螢幕亮度很高，平板電腦使用三小時後可能需要充電。"},{"en":"If a chair becomes uncomfortable after three hours of use, it may not be suitable for office workers.","zh":"如果椅子使用三小時後令人不舒服，可能不適合辦公室員工。"},{"en":"This phrase helps describe when a problem appears during a period of use.","zh":"這個短語幫助描述問題在使用期間何時出現。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"false accusation","meaning":"失實指控","examples":[{"en":"The company states that this is a false accusation.","zh":"公司表示這是一項失實指控。"},{"en":"A false accusation is one untrue claim that wrongly blames someone or something.","zh":"false accusation 指一項不真實、錯誤責怪某人或某物的指控。"},{"en":"A false accusation of stealing can seriously upset an innocent student.","zh":"一項偷竊的失實指控可以嚴重傷害無辜學生。"},{"en":"A false accusation can spread quickly online before the truth is checked.","zh":"失實指控可能在真相被查清前已在網上迅速傳播。"},{"en":"This phrase focuses on one specific untrue accusation, while “false accusations” refers to more than one.","zh":"這個短語聚焦一項特定的不實指控，而 false accusations 則指多於一項。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"under normal room temperature conditions","meaning":"在正常室溫環境下","examples":[{"en":"Under normal room temperature conditions, the laptop will not overheat.","zh":"在正常室溫環境下，該手提電腦不會過熱。"},{"en":"Under normal room temperature conditions means in an ordinary indoor environment that is neither very hot nor very cold.","zh":"under normal room temperature conditions 指在普通室內環境下，不是極熱也不是極冷。"},{"en":"Medicine may need to be stored under normal room temperature conditions unless the label says otherwise.","zh":"除非標籤另有說明，藥物可能需要在正常室溫環境下存放。"},{"en":"If a device works well under normal room temperature conditions, extreme heat may still affect it differently.","zh":"如果裝置在正常室溫環境下運作良好，極端高溫仍可能對它有不同影響。"},{"en":"This phrase is often used in testing to explain the environment in which results apply.","zh":"這個短語常用於測試中，說明結果適用的環境。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"room temperature","meaning":"室溫","examples":[{"en":"The laptop was tested under normal room temperature conditions.","zh":"該手提電腦在正常室溫環境下接受測試。"},{"en":"Room temperature means the ordinary temperature inside a room, usually comfortable for people.","zh":"room temperature 指房間內的普通溫度，通常是人感到舒適的溫度。"},{"en":"Butter becomes softer at room temperature, so it is easier to spread on bread.","zh":"牛油在室溫下會變軟，因此較容易塗在麵包上。"},{"en":"Some products must be tested at room temperature before being tested in hotter or colder conditions.","zh":"有些產品必須先在室溫下測試，再於較熱或較冷環境下測試。"},{"en":"This phrase is common in science, cooking, storage instructions, and product testing.","zh":"這個短語常見於科學、烹飪、儲存指示和產品測試。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"will not overheat","meaning":"不會過熱","examples":[{"en":"The laptop will not overheat under normal room temperature conditions.","zh":"該手提電腦在正常室溫環境下不會過熱。"},{"en":"Will not overheat means will not become dangerously or unusually hot during normal use.","zh":"will not overheat 指在正常使用時不會變得危險地或異常地熱。"},{"en":"This fan will not overheat if it is cleaned regularly and used properly.","zh":"如果定期清潔並正確使用，這把風扇不會過熱。"},{"en":"If a device will not overheat, users can feel more confident using it for long periods.","zh":"如果裝置不會過熱，使用者長時間使用時會更有信心。"},{"en":"This phrase is often used to reassure customers about safety and performance.","zh":"這個短語常用來讓顧客對安全和效能放心。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":3},{"front":"be supported by","meaning":"得到……支持","examples":[{"en":"This is supported by the company’s laboratory report.","zh":"這得到公司的實驗室報告支持。"},{"en":"To be supported by something means to be backed up by evidence, data, or reliable information.","zh":"be supported by something 指得到證據、數據或可靠資料支持。"},{"en":"The school’s decision was supported by survey results from parents and students.","zh":"學校的決定得到家長和學生的問卷結果支持。"},{"en":"A claim supported by clear evidence is more convincing than a claim based only on opinion.","zh":"由清晰證據支持的聲稱，比只基於意見的聲稱更有說服力。"},{"en":"This phrase is useful when showing why readers should trust a statement.","zh":"當要說明讀者為何應相信某說法時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"laboratory report","meaning":"實驗室報告","examples":[{"en":"The laboratory report is available on the company’s website.","zh":"實驗室報告可於公司網站查閱。"},{"en":"A laboratory report is a written record of tests, methods, results, and conclusions from a lab.","zh":"laboratory report 指實驗室測試、方法、結果和結論的書面紀錄。"},{"en":"Students write laboratory reports after science experiments to explain what they found.","zh":"學生在科學實驗後撰寫實驗室報告，解釋他們發現了甚麼。"},{"en":"A laboratory report can support a product claim if the test conditions and results are clear.","zh":"如果測試條件和結果清楚，實驗室報告可以支持產品聲稱。"},{"en":"This phrase is common when discussing scientific testing or technical evidence.","zh":"這個短語常用於討論科學測試或技術證據。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"available on our website","meaning":"可於我們網站查閱","examples":[{"en":"The laboratory report is available on our website.","zh":"實驗室報告可於我們網站查閱。"},{"en":"Available on our website means people can find, read, or download the information from our online site.","zh":"available on our website 指人們可以在我們的網站找到、閱讀或下載資料。"},{"en":"The application form is available on our website for all parents.","zh":"申請表可於我們網站供所有家長查閱。"},{"en":"If safety information is available on our website, customers can check it before buying.","zh":"如果安全資料可於我們網站查閱，顧客購買前便能查看。"},{"en":"This phrase is often used in formal notices to direct people to further information.","zh":"這個短語常用於正式告示，引導人們查看進一步資料。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"it has also been reported that","meaning":"亦有報道指","examples":[{"en":"It has also been reported that the XZ Laptop has a faulty keyboard.","zh":"亦有報道指 XZ Laptop 有故障鍵盤。"},{"en":"It has also been reported that means another report or claim says something, but the writer may not confirm it as true.","zh":"it has also been reported that 指另有報道或聲稱指出某事，但作者不一定確認其為真。"},{"en":"It has also been reported that the lift stopped several times last week.","zh":"亦有報道指升降機上星期停頓了數次。"},{"en":"This phrase lets a writer introduce an additional claim in a formal and cautious way.","zh":"這個短語讓作者以正式而謹慎的方式引入另一項聲稱。"},{"en":"It is useful when responding to media reports, complaints, or public statements.","zh":"當回應媒體報道、投訴或公開聲明時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"faulty keyboard","meaning":"有問題的鍵盤；故障鍵盤","examples":[{"en":"Some reports claimed that the XZ Laptop has a faulty keyboard.","zh":"有些報道聲稱 XZ Laptop 有故障鍵盤。"},{"en":"A faulty keyboard is a keyboard that does not work properly or gives incorrect input.","zh":"faulty keyboard 指不能正常運作或輸入錯誤的鍵盤。"},{"en":"A faulty keyboard may type the wrong letters or fail to respond when keys are pressed.","zh":"故障鍵盤可能會打出錯誤字母，或按鍵時沒有反應。"},{"en":"If a laptop has a faulty keyboard, users may lose time correcting typing mistakes.","zh":"如果手提電腦有故障鍵盤，使用者可能要花時間更正輸入錯誤。"},{"en":"This phrase describes a technical problem with one of the main input parts of a computer.","zh":"這個短語描述電腦主要輸入部件之一的技術問題。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"accurately registered","meaning":"被準確記錄","examples":[{"en":"It was claimed that typing is sometimes not accurately registered.","zh":"有人聲稱打字有時未能被準確記錄。"},{"en":"Accurately registered means correctly detected, recorded, or recognised by a system.","zh":"accurately registered 指被系統正確偵測、記錄或辨認。"},{"en":"If a student’s attendance is not accurately registered, the school may think the student is absent.","zh":"如果學生出席紀錄沒有被準確記錄，學校可能以為該學生缺席。"},{"en":"A touchscreen must accurately register each tap so users can control the device properly.","zh":"觸控屏必須準確記錄每次點按，使用者才能正確控制裝置。"},{"en":"This phrase is common when discussing electronic input, records, or data systems.","zh":"這個短語常用於討論電子輸入、紀錄或數據系統。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"this is not the case","meaning":"事實並非如此","examples":[{"en":"However, this is not the case.","zh":"然而，事實並非如此。"},{"en":"This is not the case means the situation described is not true or does not apply.","zh":"this is not the case 指所描述的情況並不真實或並不適用。"},{"en":"Some people think the library closes at five; this is not the case, as it closes at seven.","zh":"有些人以為圖書館五時關門；事實並非如此，因為它七時才關門。"},{"en":"This phrase helps a writer politely correct a wrong belief.","zh":"這個短語幫助作者禮貌地糾正錯誤看法。"},{"en":"It is useful when the writer wants to reject a claim without sounding too emotional.","zh":"當作者想否定某項聲稱而不顯得太情緒化時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"electrically conductive touchscreen system","meaning":"導電式觸控屏系統","examples":[{"en":"The keyboard uses an electrically conductive touchscreen system.","zh":"該鍵盤使用導電式觸控屏系統。"},{"en":"An electrically conductive touchscreen system is a touch system that detects input through electrical signals.","zh":"electrically conductive touchscreen system 指透過電訊號偵測輸入的觸控系統。"},{"en":"A phone screen uses a similar system when it responds to a finger tap.","zh":"手機螢幕回應手指點按時，使用的就是類似系統。"},{"en":"If an electrically conductive touchscreen system works properly, it can register touches without moving mechanical keys.","zh":"如果導電式觸控屏系統運作正常，它可以在沒有活動機械按鍵的情況下記錄觸控。"},{"en":"This phrase is technical, so it is often explained when a company discusses product design.","zh":"這個短語較技術性，因此公司討論產品設計時通常會加以解釋。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"mechanical issues","meaning":"機械問題","examples":[{"en":"No mechanical issues should occur with this keyboard system.","zh":"這個鍵盤系統不應出現機械問題。"},{"en":"Mechanical issues are problems with physical moving parts, such as keys, hinges, buttons, or gears.","zh":"mechanical issues 指實體活動部件的問題，例如按鍵、鉸鏈、按鈕或齒輪。"},{"en":"A printer may have mechanical issues if paper keeps getting stuck inside it.","zh":"如果紙張一直卡在打印機內，打印機可能有機械問題。"},{"en":"Mechanical issues can stop a device from working even when its software is fine.","zh":"即使軟件正常，機械問題仍可能令裝置不能運作。"},{"en":"This phrase is useful when distinguishing physical hardware problems from electronic or software problems.","zh":"當需要把實體硬件問題與電子或軟件問題區分時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"should occur","meaning":"應該會發生","examples":[{"en":"No mechanical issues should occur during normal use.","zh":"正常使用期間不應該會發生機械問題。"},{"en":"Should occur means is expected to happen, usually under certain conditions.","zh":"should occur 指在某些條件下預期會發生。"},{"en":"No delay should occur if all students submit their forms on time.","zh":"如果所有學生準時提交表格，應該不會發生延誤。"},{"en":"If the system is set up correctly, no serious errors should occur.","zh":"如果系統設定正確，應該不會發生嚴重錯誤。"},{"en":"In negative sentences, “should occur” often means a problem is not expected to happen.","zh":"在否定句中，should occur 常表示預期某問題不會發生。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"hence","meaning":"因此","examples":[{"en":"Hence, this allegation is also misleading.","zh":"因此，這項指控亦具誤導性。"},{"en":"Hence means therefore or for this reason.","zh":"hence 指因此或基於這個原因。"},{"en":"The road is flooded; hence, the school bus will take another route.","zh":"道路水浸；因此，校巴會改行另一條路線。"},{"en":"In formal writing, hence connects evidence with a conclusion.","zh":"在正式寫作中，hence 把證據與結論連接起來。"},{"en":"This word should be used when the second idea clearly follows from the first.","zh":"當第二個意思明顯由第一個意思引出時，才應使用這個詞。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":4},{"front":"this allegation","meaning":"這項指控","examples":[{"en":"This allegation is also misleading.","zh":"這項指控亦具誤導性。"},{"en":"This allegation means this particular accusation or claim of wrongdoing.","zh":"this allegation 指這一項特定的錯誤行為指控或聲稱。"},{"en":"This allegation about unfair marking should be investigated before anyone is blamed.","zh":"這項關於評分不公的指控應先被調查，才可責怪任何人。"},{"en":"If this allegation is false, the person accused deserves a clear correction.","zh":"如果這項指控是假的，被指控的人應得到清楚更正。"},{"en":"The phrase is useful when referring back to one specific claim already mentioned.","zh":"這個短語適合用來回指前文已提及的一項特定聲稱。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"spare no effort in","meaning":"不遺餘力","examples":[{"en":"Our company spares no effort in providing customers with excellent products.","zh":"本公司不遺餘力為顧客提供優秀產品。"},{"en":"To spare no effort in doing something means to try as hard as possible to achieve it.","zh":"spare no effort in doing something 指盡最大努力去做某事。"},{"en":"Teachers spare no effort in helping students prepare for important exams.","zh":"老師不遺餘力幫助學生準備重要考試。"},{"en":"A company that spares no effort in improving safety may invest in testing, training, and quality checks.","zh":"一間不遺餘力改善安全的公司，可能會投資於測試、培訓和品質檢查。"},{"en":"This phrase sounds formal and positive, often showing commitment and responsibility.","zh":"這個短語語氣正式而正面，常用來顯示承諾和責任感。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"provide customers with","meaning":"為顧客提供","examples":[{"en":"The company spares no effort in providing customers with high-quality products.","zh":"該公司不遺餘力為顧客提供優質產品。"},{"en":"To provide customers with something means to give, offer, or supply it to customers.","zh":"provide customers with something 指給予、提供或供應某物給顧客。"},{"en":"A café provides customers with free water and comfortable seats.","zh":"咖啡店為顧客提供免費清水和舒適座位。"},{"en":"Providing customers with clear instructions can reduce complaints and returns.","zh":"為顧客提供清晰指示可以減少投訴和退貨。"},{"en":"This phrase is common in business writing because it focuses on what customers receive.","zh":"這個短語常見於商業寫作，因為它聚焦顧客所獲得的東西。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"products of excellent quality","meaning":"優質產品","examples":[{"en":"The company aims to provide products of excellent quality.","zh":"公司旨在提供優質產品。"},{"en":"Products of excellent quality are goods that are well made, reliable, and able to meet high standards.","zh":"products of excellent quality 指製作良好、可靠並能達到高標準的貨品。"},{"en":"A shop selling products of excellent quality may gain loyal customers over time.","zh":"銷售優質產品的商店，長遠可能會獲得忠實顧客。"},{"en":"Products of excellent quality can reduce repair costs because they break less often.","zh":"優質產品因較少損壞，可以減少維修成本。"},{"en":"This phrase is useful in formal business writing when describing a company’s standards.","zh":"這個短語適合用於正式商業寫作，描述公司的標準。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"would like to stress","meaning":"想再次強調","examples":[{"en":"We would like to stress once again that the accusations are not factually based.","zh":"我們想再次強調，這些指控並非有事實根據。"},{"en":"Would like to stress means want to emphasise something clearly and politely.","zh":"would like to stress 指想清楚而禮貌地強調某事。"},{"en":"The school would like to stress that students must arrive before the exam starts.","zh":"學校想強調，學生必須在考試開始前到達。"},{"en":"A company may use this phrase when it wants readers to remember an important point.","zh":"公司希望讀者記住重要要點時，可能會使用這個短語。"},{"en":"It sounds formal and respectful, but it still makes the message firm.","zh":"它聽起來正式而有禮，但訊息仍然堅定。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"once again","meaning":"再次","examples":[{"en":"The company would like to stress once again that the claims are false.","zh":"公司想再次強調，這些聲稱是錯誤的。"},{"en":"Once again means one more time, especially when repeating an important point.","zh":"once again 指再一次，尤其是重複重要要點時。"},{"en":"Once again, please remember to bring your student card to the exam hall.","zh":"再次提醒，請記得帶學生證到試場。"},{"en":"A speaker may say once again when the audience needs to remember a warning or conclusion.","zh":"當聽眾需要記住警告或結論時，講者可能會說 once again。"},{"en":"This phrase is useful for emphasis, but using it too often can sound repetitive.","zh":"這個短語適合用於強調，但使用過多會顯得重複。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"factually based","meaning":"有事實根據的","examples":[{"en":"The company states that the accusations are not factually based.","zh":"公司表示這些指控並非有事實根據。"},{"en":"Factually based means supported by real facts, evidence, or accurate information.","zh":"factually based 指受到真實事實、證據或準確資料支持。"},{"en":"A report should be factually based rather than built on rumours.","zh":"報告應有事實根據，而不是建立在傳聞之上。"},{"en":"If a complaint is not factually based, the organisation may reject it after investigation.","zh":"如果投訴並非有事實根據，機構調查後可能會拒絕它。"},{"en":"This phrase is useful when distinguishing evidence from opinion or misunderstanding.","zh":"當需要區分證據與意見或誤解時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"reserve the right to","meaning":"保留……的權利","examples":[{"en":"The company reserves the right to take legal action if necessary.","zh":"公司保留如有需要時採取法律行動的權利。"},{"en":"To reserve the right to do something means to keep the legal or official power to do it later.","zh":"reserve the right to do something 指保留日後做某事的法律或正式權力。"},{"en":"The school reserves the right to cancel the event if the weather becomes dangerous.","zh":"如天氣變得危險，學校保留取消活動的權利。"},{"en":"A company may reserve the right to refuse service when customers break safety rules.","zh":"當顧客違反安全規則，公司可能保留拒絕服務的權利。"},{"en":"This phrase is formal and is often used in notices, contracts, and public statements.","zh":"這個短語較正式，常用於告示、合約和公開聲明。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"take legal action","meaning":"採取法律行動","examples":[{"en":"The company may take legal action if necessary.","zh":"如有需要，公司可能會採取法律行動。"},{"en":"To take legal action means to use the law, such as through lawyers or court, to deal with a problem.","zh":"take legal action 指使用法律途徑，例如透過律師或法院處理問題。"},{"en":"A landlord may take legal action if rent is not paid for several months.","zh":"如果租金數月未付，業主可能會採取法律行動。"},{"en":"Companies may take legal action when false claims seriously damage their reputation.","zh":"當失實聲稱嚴重損害公司聲譽時，公司可能採取法律行動。"},{"en":"This phrase sounds serious because it means the issue may move beyond ordinary discussion.","zh":"這個短語語氣嚴重，因為它表示事情可能超出普通討論範圍。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"if necessary","meaning":"如有需要","examples":[{"en":"The company reserves the right to take legal action if necessary.","zh":"公司保留如有需要時採取法律行動的權利。"},{"en":"If necessary means if it is needed because the situation requires it.","zh":"if necessary 指如果情況需要，或有實際需要時。"},{"en":"The nurse will call a doctor if necessary.","zh":"如有需要，護士會召喚醫生。"},{"en":"If necessary, the school may add extra classes before the public exam.","zh":"如有需要，學校可能會在公開考試前增加額外課堂。"},{"en":"This phrase shows that an action is possible, but will only happen when there is a real need.","zh":"這個短語顯示某行動有可能發生，但只會在真正有需要時才發生。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5},{"front":"issued by","meaning":"由……發出","examples":[{"en":"The press release was issued by LMB Tech Buddies.","zh":"該新聞稿由 LMB Tech Buddies 發出。"},{"en":"Issued by means officially sent out, published, or announced by a person or organisation.","zh":"issued by 指由某人或機構正式發出、發布或公布。"},{"en":"The notice was issued by the school office after the weather warning was raised.","zh":"天氣警告發出後，該通告由學校辦公室發出。"},{"en":"A statement issued by a company usually represents its official position.","zh":"由公司發出的聲明通常代表其官方立場。"},{"en":"This phrase is useful when identifying the source of a document, announcement, or warning.","zh":"當要指出文件、公告或警告的來源時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Press Release.pdf","sourcePage":5}],"dse/paper-3/practical-english-writing/practical-formats/proposal":[{"front":"proposal on","meaning":"關於……的建議書","examples":[{"en":"This is a proposal on the improvement of JD Hotel.","zh":"這是一份關於改善 JD Hotel 的建議書。"},{"en":"A proposal on something is a written plan that gives suggestions about that topic.","zh":"proposal on 某事是一份就該主題提出建議的書面計劃。"},{"en":"The student council wrote a proposal on improving the school canteen.","zh":"學生會寫了一份關於改善學校飯堂的建議書。"},{"en":"A proposal on hotel services can help managers decide what should be changed first.","zh":"關於酒店服務的建議書可以幫助管理層決定應先更改甚麼。"},{"en":"Before approving money for a project, a company may ask for a proposal on the expected benefits.","zh":"公司在批准項目撥款前，可能要求提交一份關於預期好處的建議書。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"the improvement of","meaning":"……的改善","examples":[{"en":"The proposal focuses on the improvement of JD Hotel.","zh":"這份建議書集中於 JD Hotel 的改善。"},{"en":"The improvement of something means making it better than before.","zh":"the improvement of 某事意思是令某事比以前更好。"},{"en":"The improvement of school facilities can make students feel safer and more comfortable.","zh":"學校設施的改善可以令學生感到更安全和舒適。"},{"en":"Regular feedback helps with the improvement of customer service.","zh":"定期意見回饋有助改善客戶服務。"},{"en":"The improvement of a hotel may include cleaner rooms, better lighting, and more helpful staff.","zh":"酒店的改善可能包括更乾淨的房間、更好的燈光和更樂於助人的員工。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"be intended to","meaning":"旨在；目的是","examples":[{"en":"This proposal is intended to summarise the suggested changes.","zh":"這份建議書旨在總結所建議的改動。"},{"en":"If something is intended to do something, that is its purpose.","zh":"如果某物 is intended to 做某事，意思是那就是它的目的。"},{"en":"This notice is intended to remind residents about the new recycling rules.","zh":"這張告示旨在提醒住戶新的回收規則。"},{"en":"A training session is intended to help new staff understand their duties.","zh":"培訓課程旨在幫助新員工了解自己的職責。"},{"en":"A plan may fail if it is not clear what it is intended to achieve.","zh":"如果計劃不清楚旨在達成甚麼，就可能失敗。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"summarise items","meaning":"總結項目","examples":[{"en":"The proposal summarises items to be added, removed, and changed.","zh":"這份建議書總結需要添加、移除和更改的項目。"},{"en":"To summarise items means to give a short list or explanation of the main points.","zh":"summarise items 意思是簡短列出或解釋主要項目。"},{"en":"The secretary summarised items from the meeting so everyone knew the next steps.","zh":"秘書總結了會議項目，讓所有人知道下一步。"},{"en":"Summarising items clearly can prevent people from missing important tasks.","zh":"清楚總結項目可以防止人們遺漏重要任務。"},{"en":"A report should summarise items briefly before giving detailed explanations.","zh":"報告應先簡短總結項目，然後再提供詳細解釋。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"items to be added","meaning":"需要添加的項目","examples":[{"en":"The first section lists the items to be added.","zh":"第一部分列出需要添加的項目。"},{"en":"Items to be added are things that should be included or put in later.","zh":"items to be added 是之後應包括或加入的東西。"},{"en":"The teacher wrote the items to be added to the classroom noticeboard.","zh":"老師寫下需要添加到課室告示板的項目。"},{"en":"A shopping list helps a family remember items to be added to the fridge.","zh":"購物清單幫助家庭記住需要添加到雪櫃的物品。"},{"en":"In a renovation plan, items to be added may include lights, chairs, signs, or safety equipment.","zh":"在翻新計劃中，需要添加的項目可能包括燈、椅子、標誌或安全設備。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"items to be removed","meaning":"需要移除的項目","examples":[{"en":"The second section lists the items to be removed.","zh":"第二部分列出需要移除的項目。"},{"en":"Items to be removed are things that should be taken away because they are unnecessary, unsuitable, or unsafe.","zh":"items to be removed 是因不必要、不合適或不安全而應被拿走的東西。"},{"en":"The office manager marked the old furniture as items to be removed.","zh":"辦公室經理把舊家具標記為需要移除的項目。"},{"en":"Listing items to be removed helps workers avoid throwing away the wrong things.","zh":"列出需要移除的項目，有助工人避免丟掉錯誤物品。"},{"en":"In a hotel, items to be removed may include damaged decorations or outdated notices.","zh":"在酒店中，需要移除的項目可能包括損壞裝飾或過時告示。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"items to be changed","meaning":"需要更改的項目","examples":[{"en":"The proposal also includes items to be changed.","zh":"這份建議書也包括需要更改的項目。"},{"en":"Items to be changed are things that should remain but need a different form, style, time, or arrangement.","zh":"items to be changed 是應保留但需要改變形式、風格、時間或安排的東西。"},{"en":"The timetable listed items to be changed after parents complained about late classes.","zh":"家長投訴課堂太晚後，時間表列出需要更改的項目。"},{"en":"Items to be changed should be clearly explained so staff know what new version is needed.","zh":"需要更改的項目應清楚說明，讓員工知道需要甚麼新版本。"},{"en":"A restaurant may keep its menu but mark prices and opening hours as items to be changed.","zh":"餐廳可能保留餐牌，但把價格和營業時間列為需要更改的項目。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"as well as","meaning":"以及","examples":[{"en":"The proposal covers changes as well as items for discussion.","zh":"這份建議書涵蓋改動以及需要討論的項目。"},{"en":"As well as means in addition to something else.","zh":"as well as 意思是除某事之外還有另一事。"},{"en":"The school library offers computers as well as printed books.","zh":"學校圖書館提供電腦以及印刷書籍。"},{"en":"A hotel must consider comfort as well as safety when improving its lobby.","zh":"酒店改善大堂時，必須考慮舒適度以及安全。"},{"en":"This phrase helps add another point without starting a completely new sentence.","zh":"這個片語有助加入另一個重點，而不用開始一個完全新的句子。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"items to be discussed","meaning":"需要討論的項目","examples":[{"en":"Several items are to be discussed in the next meeting.","zh":"幾個項目需要在下次會議中討論。"},{"en":"Items to be discussed are topics that people need to talk about before making a decision.","zh":"items to be discussed 是人們在作決定前需要討論的題目。"},{"en":"The class trip budget was one of the items to be discussed.","zh":"班級旅行預算是需要討論的項目之一。"},{"en":"Important items to be discussed should be placed clearly on the meeting agenda.","zh":"重要的討論項目應清楚放在會議議程上。"},{"en":"If items to be discussed are not prepared in advance, the meeting may waste time.","zh":"如果需要討論的項目沒有事先準備，會議可能浪費時間。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"in the next meeting","meaning":"在下次會議中","examples":[{"en":"The remaining issues will be discussed in the next meeting.","zh":"餘下問題會在下次會議中討論。"},{"en":"In the next meeting means during the following meeting, not the current one.","zh":"in the next meeting 意思是在下一次會議中，而不是本次會議。"},{"en":"We will confirm the activity date in the next meeting.","zh":"我們會在下次會議中確認活動日期。"},{"en":"If a problem is not urgent, it can be discussed in the next meeting.","zh":"如果問題不緊急，可以在下次會議中討論。"},{"en":"Writing down what to discuss in the next meeting helps the team remember unfinished business.","zh":"寫下下次會議要討論的內容，有助團隊記住未完成事項。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"Firstly","meaning":"首先","examples":[{"en":"Firstly, hand sanitisers should be placed at each entrance.","zh":"首先，應在每個入口放置搓手液。"},{"en":"Firstly is used to introduce the first point in a list or argument.","zh":"Firstly 用來引入清單或論點中的第一點。"},{"en":"Firstly, students should read the question carefully before writing.","zh":"首先，學生應在寫作前仔細閱讀題目。"},{"en":"Using firstly helps readers understand that more points will follow.","zh":"使用 firstly 可以幫助讀者明白後面還有更多重點。"},{"en":"In a formal proposal, firstly can make the structure clearer and easier to follow.","zh":"在正式建議書中，firstly 可以令結構更清晰、更容易跟隨。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":1},{"front":"it is suggested that","meaning":"建議……","examples":[{"en":"It is suggested that hand sanitisers be added at each entrance.","zh":"建議在每個入口添加搓手液。"},{"en":"It is suggested that is a formal way to introduce a recommendation.","zh":"it is suggested that 是正式提出建議的說法。"},{"en":"It is suggested that the school library stay open for one extra hour.","zh":"建議學校圖書館延長開放一小時。"},{"en":"This phrase makes advice sound polite and professional rather than personal.","zh":"這個片語令建議聽起來禮貌和專業，而不是純粹個人化。"},{"en":"In reports, it is suggested that is often followed by a change the writer wants people to consider.","zh":"在報告中，it is suggested that 後面常接作者希望人們考慮的改動。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"hand sanitisers","meaning":"搓手液；消毒搓手液","examples":[{"en":"Hand sanitisers should be placed at each entrance of the hotel.","zh":"酒店每個入口都應放置搓手液。"},{"en":"Hand sanitisers are liquids or gels used to clean hands and reduce germs.","zh":"hand sanitisers 是用來清潔雙手和減少細菌的液體或啫喱。"},{"en":"Schools often provide hand sanitisers near classrooms and toilets.","zh":"學校常在課室和洗手間附近提供消毒搓手液。"},{"en":"Hand sanitisers help improve hygiene when people cannot wash their hands immediately.","zh":"當人們不能立即洗手時，搓手液有助改善衛生。"},{"en":"In a hotel lobby, hand sanitisers can reassure guests that cleanliness is taken seriously.","zh":"在酒店大堂，搓手液可以讓住客放心，知道酒店重視清潔。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"be placed at","meaning":"放置於……","examples":[{"en":"Hand sanitisers should be placed at each entrance.","zh":"搓手液應放置於每個入口。"},{"en":"If something is placed at a location, it is put there for people to see or use.","zh":"如果某物 is placed at 某地，意思是它被放在那裏供人看見或使用。"},{"en":"A notice should be placed at the lift so residents can read it easily.","zh":"告示應放置於升降機旁，方便住戶閱讀。"},{"en":"Fire extinguishers are placed at visible points so people can find them in an emergency.","zh":"滅火筒放置於顯眼位置，讓人們在緊急時找到。"},{"en":"Items placed at entrances should not block people from walking through.","zh":"放置於入口的物品不應阻礙人們通行。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"each entrance","meaning":"每個入口","examples":[{"en":"Hand sanitisers should be added at each entrance of the hotel.","zh":"酒店每個入口都應添加搓手液。"},{"en":"Each entrance means every doorway or access point into a building or area.","zh":"each entrance 意思是進入建築物或區域的每一道門或通道。"},{"en":"Security staff checked tickets at each entrance of the concert hall.","zh":"保安員在演奏廳每個入口檢查門票。"},{"en":"Putting signs at each entrance helps visitors know where to go.","zh":"在每個入口放置指示牌，有助訪客知道應往哪裏走。"},{"en":"If only one entrance has information, guests using other entrances may miss it.","zh":"如果只有一個入口有資料，使用其他入口的客人可能會錯過。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"Secondly","meaning":"其次","examples":[{"en":"Secondly, two seven-seater sofas should be placed in the lobby.","zh":"其次，應在大堂放置兩張七人座梳化。"},{"en":"Secondly is used to introduce the second point in a list or argument.","zh":"Secondly 用來引入清單或論點中的第二點。"},{"en":"Firstly, check the date; secondly, check the room number.","zh":"首先，檢查日期；其次，檢查房號。"},{"en":"Using secondly helps the reader follow the order of your ideas.","zh":"使用 secondly 有助讀者跟隨你的想法次序。"},{"en":"In formal writing, secondly is useful when the writer has several connected suggestions.","zh":"在正式寫作中，當作者有幾個相關建議時，secondly 很有用。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"seven-seater sofas","meaning":"七人座梳化","examples":[{"en":"Two seven-seater sofas should be placed in the hotel lobby.","zh":"酒店大堂應放置兩張七人座梳化。"},{"en":"Seven-seater sofas are sofas large enough for seven people to sit on.","zh":"seven-seater sofas 是足夠七個人坐的梳化。"},{"en":"A waiting area may need seven-seater sofas if many visitors arrive together.","zh":"如果許多訪客一起到達，等候區可能需要七人座梳化。"},{"en":"Seven-seater sofas can make a lobby more comfortable, but they also require enough space.","zh":"七人座梳化可以令大堂更舒適，但也需要足夠空間。"},{"en":"Hotels should choose seven-seater sofas that are durable, easy to clean, and suitable for guests.","zh":"酒店應選擇耐用、容易清潔且適合客人的七人座梳化。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"hotel lobby","meaning":"酒店大堂","examples":[{"en":"The sofas should be placed in the hotel lobby.","zh":"梳化應放置在酒店大堂。"},{"en":"A hotel lobby is the main entrance area where guests arrive, wait, and speak to staff.","zh":"hotel lobby 是客人到達、等候和與員工交談的主要入口區域。"},{"en":"Guests often check in at the front desk in the hotel lobby.","zh":"客人通常在酒店大堂的前台辦理入住手續。"},{"en":"A clean and comfortable hotel lobby can create a good first impression.","zh":"乾淨舒適的酒店大堂可以留下良好第一印象。"},{"en":"The hotel lobby should have clear signs so guests can find lifts, toilets, and reception easily.","zh":"酒店大堂應有清晰指示牌，讓客人容易找到升降機、洗手間和接待處。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"Finally","meaning":"最後","examples":[{"en":"Finally, the painting should be displayed behind the front desk.","zh":"最後，畫作應展示在前台後方。"},{"en":"Finally is used to introduce the last point in a list or sequence.","zh":"Finally 用來引入清單或次序中的最後一點。"},{"en":"Finally, remember to save your work before closing the computer.","zh":"最後，關電腦前記得儲存你的工作。"},{"en":"Using finally tells the reader that the writer is reaching the final suggestion.","zh":"使用 finally 告訴讀者作者正到達最後一項建議。"},{"en":"In a proposal, finally can help finish a section neatly.","zh":"在建議書中，finally 可以幫助一個部分整齊收結。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"painting by","meaning":"由……創作的畫作","examples":[{"en":"The painting by Laurence Chak should be displayed behind the front desk.","zh":"由 Laurence Chak 創作的畫作應展示在前台後方。"},{"en":"A painting by someone is a painting created by that artist.","zh":"painting by someone 是由該藝術家創作的畫作。"},{"en":"The gallery bought a painting by a young local artist.","zh":"畫廊購買了一幅由年輕本地藝術家創作的畫作。"},{"en":"Naming the artist helps people understand who made the artwork.","zh":"說出藝術家名字有助人們明白作品由誰創作。"},{"en":"A hotel may display a painting by a local painter to show support for local culture.","zh":"酒店可能展示由本地畫家創作的畫作，以表示支持本地文化。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"be displayed on the wall","meaning":"展示在牆上","examples":[{"en":"The painting should be displayed on the wall behind the front desk.","zh":"畫作應展示在前台後方的牆上。"},{"en":"If something is displayed on the wall, it is placed there so people can see it.","zh":"如果某物 is displayed on the wall，意思是它被放在牆上讓人看見。"},{"en":"Student artwork was displayed on the wall outside the classroom.","zh":"學生作品展示在課室外的牆上。"},{"en":"Certificates displayed on the wall can make a clinic look more professional.","zh":"展示在牆上的證書可以令診所看起來更專業。"},{"en":"Items displayed on the wall should be placed at a height that people can view comfortably.","zh":"展示在牆上的物品應放在讓人能舒適觀看的高度。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"behind the front desk","meaning":"前台後方","examples":[{"en":"The painting should be placed behind the front desk.","zh":"畫作應放置在前台後方。"},{"en":"Behind the front desk means at the back of the reception counter or staff area.","zh":"behind the front desk 意思是在接待櫃檯或員工區域後面。"},{"en":"The hotel placed its logo behind the front desk so guests could see it when checking in.","zh":"酒店把標誌放在前台後方，讓客人辦理入住時看見。"},{"en":"Decorations behind the front desk can improve the appearance of the reception area.","zh":"前台後方的裝飾可以改善接待區外觀。"},{"en":"Items behind the front desk should not distract staff from serving guests.","zh":"前台後方的物品不應分散員工服務客人的注意力。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":2},{"front":"front desk","meaning":"前台","examples":[{"en":"The painting will be displayed near the front desk.","zh":"畫作將展示在前台附近。"},{"en":"The front desk is the reception counter where guests ask for help, check in, or receive information.","zh":"front desk 是客人求助、辦理入住或取得資料的接待櫃檯。"},{"en":"Please leave your room key at the front desk before going out.","zh":"外出前，請把房間鎖匙留在前台。"},{"en":"A helpful front desk can make hotel guests feel welcome.","zh":"服務周到的前台可以令酒店客人感到受歡迎。"},{"en":"The front desk should be easy to find when visitors enter the building.","zh":"訪客進入大樓時，前台應容易找到。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"in regard to","meaning":"關於……","examples":[{"en":"In regard to the white statues outside the hotel, three should be removed.","zh":"關於酒店外的白色雕像，應移除其中三座。"},{"en":"In regard to means about or concerning a particular topic.","zh":"in regard to 意思是關於某個特定主題。"},{"en":"In regard to the school trip, parents must return the reply slip by Friday.","zh":"關於學校旅行，家長必須在星期五前交回回條。"},{"en":"This phrase is often used in formal writing to introduce a specific matter.","zh":"這個片語常用於正式寫作，以引入具體事項。"},{"en":"In regard to a complaint, a clear reply should address the main problem directly.","zh":"關於投訴，清楚的回覆應直接處理主要問題。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"white statues","meaning":"白色雕像","examples":[{"en":"Three white statues outside the hotel should be removed.","zh":"酒店外的三座白色雕像應被移除。"},{"en":"White statues are sculptures or figures that are white in colour.","zh":"white statues 是白色的雕塑或人物像。"},{"en":"A garden may have white statues to create a classical look.","zh":"花園可能放置白色雕像，以營造古典外觀。"},{"en":"Too many white statues near an entrance may make the area look crowded.","zh":"入口附近太多白色雕像，可能令該區域看起來擠迫。"},{"en":"Hotels should keep white statues clean because dirt is easy to see on them.","zh":"酒店應保持白色雕像清潔，因為污漬在上面很容易看見。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"outside the hotel","meaning":"酒店外","examples":[{"en":"The white statues outside the hotel should be removed.","zh":"酒店外的白色雕像應被移除。"},{"en":"Outside the hotel means in the area just beyond the hotel building, not inside it.","zh":"outside the hotel 意思是在酒店建築物外面的區域，而不是室內。"},{"en":"Guests waited outside the hotel for the airport bus.","zh":"客人在酒店外等候機場巴士。"},{"en":"Clear lighting outside the hotel can help visitors feel safer at night.","zh":"酒店外清晰的照明可以幫助訪客在晚上感到更安全。"},{"en":"Decorations outside the hotel affect the first impression before guests enter.","zh":"酒店外的裝飾會在客人進入前影響第一印象。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"it is advised that","meaning":"建議……","examples":[{"en":"It is advised that three statues be removed from the area.","zh":"建議從該區域移除三座雕像。"},{"en":"It is advised that is a formal way to give advice or a recommendation.","zh":"it is advised that 是正式提出意見或建議的說法。"},{"en":"It is advised that students arrive ten minutes before the exam.","zh":"建議學生在考試前十分鐘到達。"},{"en":"This phrase sounds more formal and less personal than saying I advise you to.","zh":"這個片語比說 I advise you to 更正式，也較不個人化。"},{"en":"In a proposal, it is advised that can introduce a change politely but clearly.","zh":"在建議書中，it is advised that 可以禮貌而清楚地引入改動。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"be removed from","meaning":"從……移除","examples":[{"en":"Three statues should be removed from the area.","zh":"三座雕像應從該區域移除。"},{"en":"If something is removed from a place, it is taken away from that place.","zh":"如果某物 is removed from 某地，意思是它被從那個地方拿走。"},{"en":"Old notices should be removed from the classroom wall after the event.","zh":"活動結束後，舊告示應從課室牆上移除。"},{"en":"Broken chairs were removed from the hall to keep students safe.","zh":"損壞的椅子被從禮堂移除，以保障學生安全。"},{"en":"Items removed from a public area should be stored, repaired, or thrown away properly.","zh":"從公共區域移除的物品應妥善存放、維修或丟棄。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"from the area","meaning":"從該區域","examples":[{"en":"The statues should be removed from the area outside the hotel.","zh":"雕像應從酒店外該區域移除。"},{"en":"From the area means away from that particular place or space.","zh":"from the area 意思是從那個特定地方或空間移走。"},{"en":"Visitors were asked to move from the area because workers were cleaning the floor.","zh":"由於工人正在清潔地板，訪客被要求離開該區域。"},{"en":"Removing obstacles from the area can make it safer for people to walk.","zh":"從該區域移除障礙物，可以令行人更安全。"},{"en":"If furniture is moved from the area, staff should check where it will be stored.","zh":"如果家具從該區域移走，員工應確認它會存放在哪裏。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"concerning","meaning":"關於……","examples":[{"en":"Concerning the second chandelier, it should be removed.","zh":"關於第二盞吊燈，它應被移除。"},{"en":"Concerning means about or relating to a particular subject.","zh":"concerning 意思是關於或涉及某個特定主題。"},{"en":"Concerning the school uniform, students may give comments next week.","zh":"關於校服，學生可於下星期提出意見。"},{"en":"This word is often used to introduce the topic being discussed in a formal way.","zh":"這個字常用來以正式方式引入正在討論的主題。"},{"en":"Concerning can also mean worrying, but in this proposal it means about.","zh":"concerning 也可解作令人擔心，但在這份建議書中意思是關於。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"chandelier","meaning":"吊燈","examples":[{"en":"The second chandelier in the hotel lobby should be removed.","zh":"酒店大堂中的第二盞吊燈應被移除。"},{"en":"A chandelier is a large decorative light that usually hangs from the ceiling.","zh":"chandelier 是通常懸掛在天花板上的大型裝飾燈。"},{"en":"The restaurant installed a crystal chandelier above the dining area.","zh":"餐廳在用餐區上方安裝了一盞水晶吊燈。"},{"en":"A chandelier can make a room look elegant, but it may be expensive to clean and repair.","zh":"吊燈可以令房間看起來優雅，但清潔和維修可能昂貴。"},{"en":"If a chandelier is too large, it may make a lobby feel crowded or unsafe.","zh":"如果吊燈太大，可能令大堂感覺擠迫或不安全。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"be removed","meaning":"被移除","examples":[{"en":"The second chandelier should be removed.","zh":"第二盞吊燈應被移除。"},{"en":"If something should be removed, it should be taken away or no longer kept in that place.","zh":"如果某物 should be removed，意思是它應被拿走或不再留在該處。"},{"en":"The broken mirror should be removed before someone gets hurt.","zh":"破裂的鏡子應被移除，以免有人受傷。"},{"en":"Posters should be removed after the event so the wall looks tidy again.","zh":"活動結束後，海報應被移除，讓牆壁再次整潔。"},{"en":"Something may be removed because it is old, unsafe, unattractive, or unnecessary.","zh":"某物可能因為老舊、不安全、不吸引或不必要而被移除。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"as for","meaning":"至於……","examples":[{"en":"As for the pamphlets, they should be taken away.","zh":"至於小冊子，它們應被拿走。"},{"en":"As for is used to introduce a new topic related to what has already been discussed.","zh":"as for 用來引入與已討論內容相關的新主題。"},{"en":"The rooms are clean; as for the bathrooms, they need more attention.","zh":"房間很乾淨；至於浴室，則需要更多注意。"},{"en":"In a report, as for helps move smoothly from one item to another.","zh":"在報告中，as for 有助從一個項目順暢轉到另一個項目。"},{"en":"This phrase is useful when giving separate comments about several things.","zh":"當要分別評論幾件事時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":3},{"front":"pamphlets","meaning":"小冊子；宣傳單張","examples":[{"en":"The pamphlets on each side table should be taken away.","zh":"每張側桌上的小冊子應被拿走。"},{"en":"Pamphlets are small printed leaflets that give information or advertise something.","zh":"pamphlets 是提供資料或宣傳某事的小型印刷單張。"},{"en":"The clinic gave patients pamphlets about healthy eating.","zh":"診所向病人派發關於健康飲食的小冊子。"},{"en":"Too many pamphlets on a table can make a reception area look messy.","zh":"桌上太多宣傳單張會令接待區看起來凌亂。"},{"en":"Pamphlets should be updated regularly so visitors do not receive old information.","zh":"小冊子應定期更新，以免訪客收到舊資料。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"side table","meaning":"茶几；側桌","examples":[{"en":"The pamphlets on each side table should be removed.","zh":"每張側桌上的小冊子應被移除。"},{"en":"A side table is a small table placed beside a sofa, chair, or bed.","zh":"side table 是放在梳化、椅子或床旁邊的小桌子。"},{"en":"The hotel placed magazines on a side table near the lobby sofa.","zh":"酒店把雜誌放在大堂梳化旁的茶几上。"},{"en":"A side table is useful for holding drinks, lamps, books, or small decorations.","zh":"側桌可用來放飲品、燈、書或小裝飾。"},{"en":"If a side table is too crowded, guests may not have space to put their belongings.","zh":"如果茶几太擠，客人可能沒有空間放自己的物品。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"be taken away","meaning":"被拿走；被移走","examples":[{"en":"All the pamphlets should be taken away.","zh":"所有小冊子都應被拿走。"},{"en":"If something is taken away, it is removed from a place.","zh":"如果某物 is taken away，意思是它被從某處移走。"},{"en":"The empty plates were taken away after dinner.","zh":"晚飯後，空碟被拿走。"},{"en":"Old chairs were taken away because the school bought new ones.","zh":"舊椅子被移走，因為學校買了新的椅子。"},{"en":"Items should be taken away carefully if they may still be useful elsewhere.","zh":"如果物品在其他地方仍可能有用，就應小心移走。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"To begin with","meaning":"首先","examples":[{"en":"To begin with, the room fragrance should be changed.","zh":"首先，房間香氛應被更改。"},{"en":"To begin with is used to introduce the first point or first step.","zh":"To begin with 用來引入第一點或第一步。"},{"en":"To begin with, wash your hands before preparing food.","zh":"首先，在準備食物前洗手。"},{"en":"In a presentation, to begin with helps signal the start of your explanation.","zh":"在匯報中，to begin with 有助標示解釋的開始。"},{"en":"This phrase can also emphasise the first and most basic reason for something.","zh":"這個片語也可強調某事最基本的第一個原因。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"regarding","meaning":"關於……","examples":[{"en":"Regarding the room fragrance, the scent should be changed to vanilla.","zh":"關於房間香氛，香味應改為雲呢拿。"},{"en":"Regarding means about or in connection with a particular subject.","zh":"regarding 意思是關於或涉及某個特定主題。"},{"en":"Regarding the exam, students should bring their identity cards.","zh":"關於考試，學生應攜帶身份證。"},{"en":"This word is common in formal emails and reports when introducing a topic.","zh":"這個字常見於正式電郵和報告，用來引入主題。"},{"en":"Regarding should be followed by the matter you want to discuss.","zh":"regarding 後面應接你想討論的事項。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"room fragrance","meaning":"房間香氛；室內香氛","examples":[{"en":"The room fragrance on each floor should be changed to vanilla.","zh":"每一層的房間香氛應改為雲呢拿。"},{"en":"Room fragrance is the smell added to a room to make it feel pleasant.","zh":"room fragrance 是加入房間中，令人感覺舒適的香味。"},{"en":"A hotel may use room fragrance to make guests feel relaxed when they enter.","zh":"酒店可能使用室內香氛，令客人進入時感到放鬆。"},{"en":"Strong room fragrance can make some people uncomfortable or cause headaches.","zh":"太濃烈的房間香氛可能令人不舒服或頭痛。"},{"en":"A suitable room fragrance should match the hotel’s image and not be too heavy.","zh":"合適的室內香氛應配合酒店形象，而且不應太濃。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"on each floor","meaning":"在每一層","examples":[{"en":"The fragrance on each floor should be changed.","zh":"每一層的香氛都應更改。"},{"en":"On each floor means on every level of a building.","zh":"on each floor 意思是在建築物的每一層。"},{"en":"The school placed recycling bins on each floor.","zh":"學校在每一層放置回收箱。"},{"en":"Clear signs on each floor help visitors find classrooms, offices, and toilets.","zh":"每一層的清晰指示牌有助訪客找到課室、辦公室和洗手間。"},{"en":"If a hotel changes the fragrance on each floor, staff must check every level.","zh":"如果酒店更改每一層的香氛，員工必須檢查每個樓層。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"the scent should be changed to","meaning":"香味應改為……","examples":[{"en":"The scent should be changed to vanilla.","zh":"香味應改為雲呢拿。"},{"en":"The scent should be changed to something means the smell should be replaced with a different smell.","zh":"the scent should be changed to 某味道意思是原有氣味應被另一種氣味取代。"},{"en":"The scent in the spa should be changed to lavender to create a calmer mood.","zh":"水療中心的香味應改為薰衣草，以營造更平靜的氣氛。"},{"en":"Changing the scent can affect how comfortable guests feel in a room.","zh":"更改香味可以影響客人在房間中的舒適感。"},{"en":"If many guests dislike the current smell, the scent should be changed to a milder one.","zh":"如果很多客人不喜歡現時氣味，香味應改為較溫和的一種。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"vanilla","meaning":"雲呢拿；香草味","examples":[{"en":"The scent should be changed to vanilla.","zh":"香味應改為雲呢拿。"},{"en":"Vanilla is a sweet, warm smell or flavour often used in food, candles, and fragrance products.","zh":"vanilla 是一種甜暖的氣味或味道，常用於食物、蠟燭和香氛產品。"},{"en":"Many people like vanilla because it feels soft and familiar.","zh":"許多人喜歡香草味，因為它感覺柔和而熟悉。"},{"en":"Vanilla fragrance may make a hotel room feel warmer and more welcoming.","zh":"雲呢拿香氛可能令酒店房間感覺更溫暖和更受歡迎。"},{"en":"If vanilla is too strong, it can still feel unpleasant in a small room.","zh":"如果雲呢拿味太濃，在小房間中仍可能令人不舒服。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"Lastly","meaning":"最後","examples":[{"en":"Lastly, the washroom music should be changed.","zh":"最後，洗手間音樂應被更改。"},{"en":"Lastly is used to introduce the final point in a list.","zh":"Lastly 用來引入清單中的最後一點。"},{"en":"Lastly, check that all windows are closed before leaving.","zh":"最後，離開前檢查所有窗戶是否已關上。"},{"en":"Using lastly helps the reader understand that the list is ending.","zh":"使用 lastly 有助讀者明白清單即將結束。"},{"en":"In formal writing, lastly can neatly introduce the final recommendation.","zh":"在正式寫作中，lastly 可以整齊地引入最後一項建議。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"washroom music","meaning":"洗手間音樂","examples":[{"en":"The current washroom music should be changed to classical music.","zh":"現時的洗手間音樂應改為古典音樂。"},{"en":"Washroom music is music played in a washroom to create a certain atmosphere.","zh":"washroom music 是在洗手間播放，用來營造某種氣氛的音樂。"},{"en":"Some restaurants use washroom music so the space feels less silent and awkward.","zh":"有些餐廳使用洗手間音樂，令空間不那麼安靜和尷尬。"},{"en":"Washroom music that is too loud may disturb guests instead of relaxing them.","zh":"太大聲的洗手間音樂可能打擾客人，而不是令他們放鬆。"},{"en":"A hotel should choose washroom music that matches its image and feels comfortable.","zh":"酒店應選擇配合其形象並令人舒適的洗手間音樂。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":4},{"front":"current pop music","meaning":"現時播放的流行音樂","examples":[{"en":"The current pop music should be replaced with classical music.","zh":"現時播放的流行音樂應被古典音樂取代。"},{"en":"Current pop music means the popular music that is being played now.","zh":"current pop music 意思是現在正在播放的流行音樂。"},{"en":"The café changed its current pop music because customers wanted a calmer atmosphere.","zh":"咖啡店更改了現時播放的流行音樂，因為顧客想要更平靜的氣氛。"},{"en":"Current pop music may suit a youth event but not a quiet hotel washroom.","zh":"現時播放的流行音樂可能適合青年活動，但不適合安靜的酒店洗手間。"},{"en":"When choosing background music, managers should consider whether the current pop music matches the setting.","zh":"選擇背景音樂時，經理應考慮現時播放的流行音樂是否配合環境。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"be changed to","meaning":"改為……","examples":[{"en":"The washroom music should be changed to classical music.","zh":"洗手間音樂應改為古典音樂。"},{"en":"If something is changed to another thing, it is replaced by that new thing or form.","zh":"如果某物 is changed to 另一物，意思是它被新的事物或形式取代。"},{"en":"The meeting time was changed to three o’clock.","zh":"會議時間改為三點。"},{"en":"A menu item may be changed to a healthier version after customer feedback.","zh":"收到顧客意見後，餐牌項目可能改為較健康的版本。"},{"en":"When something is changed to a new option, people should be told clearly.","zh":"當某物改為新選項時，應清楚通知人們。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"classical music","meaning":"古典音樂","examples":[{"en":"The washroom music should be changed to classical music.","zh":"洗手間音樂應改為古典音樂。"},{"en":"Classical music is formal music from a long artistic tradition, often played by orchestras or on instruments such as the piano and violin.","zh":"classical music 是來自悠久藝術傳統的正式音樂，常由管弦樂團演奏，或以鋼琴、小提琴等樂器演奏。"},{"en":"Many people listen to classical music when they want a calm atmosphere.","zh":"許多人想要平靜氣氛時會聽古典音樂。"},{"en":"Classical music can make a hotel feel more elegant and peaceful.","zh":"古典音樂可以令酒店感覺更優雅和平靜。"},{"en":"However, classical music should not be played too loudly in a public space.","zh":"不過，在公共空間不應把古典音樂播放得太大聲。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"whether","meaning":"是否","examples":[{"en":"Whether cleaning services should be provided at eleven o’clock should be discussed.","zh":"是否應在十一點提供清潔服務，應予以討論。"},{"en":"Whether is used when there are two possibilities, such as yes or no.","zh":"whether 用於有兩種可能性時，例如是或否。"},{"en":"The teacher asked whether students wanted the test before or after lunch.","zh":"老師詢問學生是否想在午飯前或午飯後測驗。"},{"en":"A manager may discuss whether a service should continue if it costs too much.","zh":"如果某項服務成本太高，經理可能討論是否應繼續。"},{"en":"Whether helps introduce an issue that has not yet been decided.","zh":"whether 有助引入尚未決定的問題。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"cleaning services","meaning":"清潔服務","examples":[{"en":"The timing of the cleaning services should be discussed.","zh":"清潔服務的時間安排應予以討論。"},{"en":"Cleaning services are services that keep rooms, buildings, or public areas clean.","zh":"cleaning services 是保持房間、建築物或公共區域清潔的服務。"},{"en":"Hotels need cleaning services to prepare rooms for new guests.","zh":"酒店需要清潔服務為新客人準備房間。"},{"en":"Poor cleaning services can lead to complaints, bad smells, and health concerns.","zh":"差劣的清潔服務可能導致投訴、異味和衛生問題。"},{"en":"Good cleaning services should be regular, careful, and not too disruptive to guests.","zh":"良好的清潔服務應定期、仔細，而且不太打擾客人。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"be provided at","meaning":"於……提供","examples":[{"en":"Cleaning services may be provided at eleven o’clock.","zh":"清潔服務可能於十一點提供。"},{"en":"If a service is provided at a time or place, it is offered then or there.","zh":"如果服務 is provided at 某時間或地點，意思是服務在該時間或地點提供。"},{"en":"Breakfast is provided at the hotel restaurant from seven o’clock.","zh":"早餐於七點起在酒店餐廳提供。"},{"en":"Free Wi-Fi is provided at the library so students can study online.","zh":"圖書館提供免費 Wi-Fi，讓學生可以上網學習。"},{"en":"Services provided at inconvenient times may not be useful to guests.","zh":"於不方便時間提供的服務可能對客人沒有用。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"the colour of the wallpaper","meaning":"牆紙顏色","examples":[{"en":"The colour of the wallpaper should be discussed in the next meeting.","zh":"牆紙顏色應在下次會議中討論。"},{"en":"The colour of the wallpaper means the shade or colour used on the wall covering.","zh":"the colour of the wallpaper 意思是牆面覆蓋物所使用的色調或顏色。"},{"en":"The colour of the wallpaper can make a room feel bright, warm, calm, or crowded.","zh":"牆紙顏色可以令房間感覺明亮、溫暖、平靜或擠迫。"},{"en":"A hotel should choose the colour of the wallpaper carefully because guests notice it immediately.","zh":"酒店應謹慎選擇牆紙顏色，因為客人會立即注意到。"},{"en":"If the colour of the wallpaper is too dark, a small room may feel even smaller.","zh":"如果牆紙顏色太深，小房間可能感覺更小。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"the date of","meaning":"……的日期","examples":[{"en":"The date of the hotel’s opening ceremony should be confirmed.","zh":"酒店開幕典禮的日期應予以確認。"},{"en":"The date of an event is the exact day when it will happen.","zh":"the date of 活動意思是該活動舉行的確切日子。"},{"en":"Please write the date of the interview on your calendar.","zh":"請把面試日期寫在日曆上。"},{"en":"Confirming the date of a meeting helps people arrange transport and time off.","zh":"確認會議日期有助人們安排交通和休假。"},{"en":"If the date of an event changes, all guests should be informed quickly.","zh":"如果活動日期更改，應迅速通知所有客人。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"opening ceremony","meaning":"開幕典禮","examples":[{"en":"The hotel’s opening ceremony will be discussed in the next meeting.","zh":"酒店的開幕典禮會在下次會議中討論。"},{"en":"An opening ceremony is a formal event that marks the start of a new building, business, or activity.","zh":"opening ceremony 是標誌新建築、業務或活動開始的正式儀式。"},{"en":"The school invited parents to the opening ceremony of the new library.","zh":"學校邀請家長出席新圖書館的開幕典禮。"},{"en":"An opening ceremony can attract guests, media attention, and community support.","zh":"開幕典禮可以吸引嘉賓、媒體關注和社區支持。"},{"en":"A successful opening ceremony needs a clear schedule, speakers, seating, and decorations.","zh":"成功的開幕典禮需要清晰流程、講者、座位和裝飾。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"should be discussed","meaning":"應予以討論","examples":[{"en":"These items should be discussed in the next meeting.","zh":"這些項目應在下次會議中予以討論。"},{"en":"If something should be discussed, people need to talk about it before deciding what to do.","zh":"如果某事 should be discussed，意思是人們需要先討論它，再決定怎樣做。"},{"en":"The safety problem should be discussed before the school trip is approved.","zh":"安全問題應在學校旅行獲批准前予以討論。"},{"en":"Difficult topics should be discussed calmly so everyone understands the options.","zh":"困難題目應平靜地討論，讓所有人明白不同選項。"},{"en":"Items that affect cost, safety, or guests’ experience should be discussed carefully.","zh":"影響成本、安全或客人體驗的項目應仔細討論。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"It is hoped that","meaning":"希望……","examples":[{"en":"It is hoped that the above suggestions will be useful.","zh":"希望以上建議會有用。"},{"en":"It is hoped that is a formal way to express a wish or expectation.","zh":"It is hoped that 是正式表達願望或期望的說法。"},{"en":"It is hoped that the new timetable will reduce students’ stress.","zh":"希望新時間表能減少學生壓力。"},{"en":"This phrase is often used at the end of reports, letters, and proposals.","zh":"這個片語常用於報告、信件和建議書結尾。"},{"en":"It sounds polite because the writer does not force the reader to agree.","zh":"它聽起來有禮貌，因為作者沒有強迫讀者同意。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":5},{"front":"the above suggestions","meaning":"以上建議","examples":[{"en":"The above suggestions should be taken into consideration.","zh":"以上建議應被納入考慮。"},{"en":"The above suggestions are the recommendations mentioned earlier in the same document.","zh":"the above suggestions 是同一份文件前面已提及的建議。"},{"en":"The manager read the above suggestions before deciding which changes to approve.","zh":"經理在決定批准哪些改動前，閱讀了以上建議。"},{"en":"Referring to the above suggestions helps avoid repeating the whole list again.","zh":"提及以上建議有助避免再次重複整個清單。"},{"en":"In formal writing, the above suggestions usually points back to the ideas already presented.","zh":"在正式寫作中，the above suggestions 通常指回已提出的想法。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":6},{"front":"be found useful","meaning":"被認為有用","examples":[{"en":"It is hoped that the suggestions will be found useful.","zh":"希望這些建議會被認為有用。"},{"en":"If something is found useful, people consider it helpful after reading, using, or testing it.","zh":"如果某物 is found useful，意思是人們在閱讀、使用或測試後認為它有幫助。"},{"en":"The study guide was found useful by students preparing for the exam.","zh":"備考學生認為那份溫習指南有用。"},{"en":"Clear signs may be found useful by guests who are visiting a hotel for the first time.","zh":"第一次到訪酒店的客人可能會認為清晰指示牌有用。"},{"en":"A suggestion is more likely to be found useful when it solves a real problem.","zh":"當建議解決真正問題時，較可能被認為有用。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":6},{"front":"be taken into consideration","meaning":"被納入考慮","examples":[{"en":"The suggestions should be taken into consideration.","zh":"這些建議應被納入考慮。"},{"en":"If something is taken into consideration, it is thought about carefully before a decision is made.","zh":"如果某事 is taken into consideration，意思是在作決定前仔細考慮它。"},{"en":"Students’ safety should be taken into consideration when planning a school trip.","zh":"計劃學校旅行時，學生安全應被納入考慮。"},{"en":"Customer feedback was taken into consideration before the restaurant changed its menu.","zh":"餐廳更改餐牌前，顧客意見已被納入考慮。"},{"en":"A good decision takes cost, comfort, safety, and long-term effects into consideration.","zh":"好的決定會把成本、舒適度、安全和長遠影響納入考慮。"}],"source":"Flash Cards -實用文 - Proposal.pdf","sourcePage":6}],"dse/paper-3/practical-english-writing/practical-formats/report":[{"front":"report on","meaning":"關於……的報告","examples":[{"en":"This is a report on the development progress of the TDC Theme Park.","zh":"這是一份關於 TDC 主題公園發展進度的報告。"},{"en":"A report on something is a written document that gives information, findings, or recommendations about that topic.","zh":"report on something 指一份就某主題提供資料、調查結果或建議的書面文件。"},{"en":"A student may write a report on traffic problems near the school.","zh":"學生可能會寫一份關於學校附近交通問題的報告。"},{"en":"A report on safety can help managers understand what has gone wrong and what should be improved.","zh":"關於安全的報告可以幫助管理層了解出了甚麼問題，以及應如何改善。"},{"en":"A good report on a problem should be clear, factual, and useful for decision-making.","zh":"一份好的問題報告應清晰、基於事實，並有助作出決策。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"development progress","meaning":"發展進度","examples":[{"en":"The report summarises the development progress of the TDC Theme Park.","zh":"報告總結 TDC 主題公園的發展進度。"},{"en":"Development progress means how far a project has advanced and what stage it has reached.","zh":"development progress 指一個項目已推進到甚麼程度，以及已到達哪個階段。"},{"en":"A company may check the development progress of a new app every week.","zh":"公司可能每星期檢查新應用程式的發展進度。"},{"en":"Slow development progress can delay the opening of a building, website, or public facility.","zh":"發展進度緩慢可能會延誤建築物、網站或公共設施的啟用。"},{"en":"Reporting development progress helps people see what has been completed and what still needs work.","zh":"匯報發展進度有助人們了解甚麼已完成，以及甚麼仍需處理。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"aims to","meaning":"旨在；目的是","examples":[{"en":"This report aims to summarise the problems identified during construction.","zh":"本報告旨在總結工程期間發現的問題。"},{"en":"Aims to means has the purpose or intention of doing something.","zh":"aims to 指目的是做某事，或有意達成某目標。"},{"en":"This lesson aims to help students use formal email language correctly.","zh":"這堂課旨在幫助學生正確使用正式電郵語言。"},{"en":"A project that aims to improve road safety may add signs, lights, and crossings.","zh":"一個旨在改善道路安全的項目，可能會增加標誌、燈號和過路處。"},{"en":"When a report states what it aims to do, readers understand its purpose from the beginning.","zh":"當報告說明其目的時，讀者一開始便能理解它想達成甚麼。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"summarise the problems identified","meaning":"總結已發現的問題","examples":[{"en":"The report aims to summarise the problems identified during the construction of the theme park.","zh":"本報告旨在總結主題公園建造期間已發現的問題。"},{"en":"To summarise the problems identified means to give a short, organised account of the problems that have been found.","zh":"summarise the problems identified 指簡短而有條理地說明已被發現的問題。"},{"en":"After a school inspection, the principal may summarise the problems identified in classrooms and facilities.","zh":"學校巡查後，校長可能會總結課室和設施中已發現的問題。"},{"en":"Summarising the problems identified helps a team decide which issues are most urgent.","zh":"總結已發現的問題有助團隊判斷哪些問題最緊急。"},{"en":"This phrase is useful in reports because it focuses on confirmed problems, not rumours.","zh":"這個短語適合用於報告，因為它聚焦已確認的問題，而不是傳聞。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"during the construction of","meaning":"在……建造期間","examples":[{"en":"Several problems were identified during the construction of the TDC Theme Park.","zh":"在 TDC 主題公園建造期間，發現了幾個問題。"},{"en":"During the construction of something means while that building, structure, or project is being built.","zh":"during the construction of something 指在某建築物、結構或項目正在興建期間。"},{"en":"Noise complaints may increase during the construction of a new railway station.","zh":"在新鐵路站建造期間，噪音投訴可能會增加。"},{"en":"If safety checks are weak during the construction of a building, accidents may happen.","zh":"如果在建築物建造期間安全檢查不足，可能會發生意外。"},{"en":"This phrase gives the time period in which the problems or activities took place.","zh":"這個短語說明問題或活動發生的時間段。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"provide possible solutions","meaning":"提供可行解決方案","examples":[{"en":"The report provides possible solutions to the problems found on site.","zh":"報告為工地發現的問題提供可行解決方案。"},{"en":"To provide possible solutions means to offer practical ways that may solve a problem.","zh":"provide possible solutions 指提出可能解決問題的實際方法。"},{"en":"A teacher may provide possible solutions when students keep forgetting homework.","zh":"當學生經常忘記做功課，老師可能會提供可行解決方案。"},{"en":"Possible solutions help people move from complaining about a problem to fixing it.","zh":"可行解決方案幫助人們由抱怨問題轉向解決問題。"},{"en":"A report should provide possible solutions that match the causes of the problem.","zh":"報告應提供與問題成因相符的可行解決方案。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"suggest items to be added to","meaning":"建議加入……的項目","examples":[{"en":"The report suggests items to be added to the theme park.","zh":"報告建議加入主題公園的項目。"},{"en":"To suggest items to be added to a place means to recommend new things that should be included there.","zh":"suggest items to be added to a place 指建議在某處加入新的東西。"},{"en":"Students may suggest items to be added to the school library, such as comics or exam guides.","zh":"學生可能建議加入學校圖書館的項目，例如漫畫或考試指南。"},{"en":"Suggesting items to be added can improve a project if the new items meet real user needs.","zh":"如果新增項目符合真正使用者需要，建議加入項目可以改善計劃。"},{"en":"This phrase is useful when a place or plan is incomplete and needs extra features.","zh":"當某地方或計劃尚未完整、需要額外設施時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"findings of problems","meaning":"問題調查結果","examples":[{"en":"The findings of problems during construction are listed in the report.","zh":"施工期間的問題調查結果已列於報告中。"},{"en":"Findings of problems are the results of checking, investigating, or observing what has gone wrong.","zh":"findings of problems 指經檢查、調查或觀察後得出的問題結果。"},{"en":"The findings of problems in a hospital may include long waiting times and unclear signs.","zh":"醫院的問題調查結果可能包括輪候時間長和指示牌不清晰。"},{"en":"Clear findings of problems help managers understand the evidence before choosing solutions.","zh":"清晰的問題調查結果有助管理層在選擇解決方案前理解證據。"},{"en":"Without findings of problems, a report may sound like opinion rather than fact.","zh":"如果沒有問題調查結果，報告可能聽起來像意見，而不是事實。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"it was found that","meaning":"據發現","examples":[{"en":"It was found that construction signs were not displayed at the site.","zh":"據發現，工地沒有張貼工程告示牌。"},{"en":"It was found that is a formal phrase used to report what was discovered after checking or investigation.","zh":"it was found that 是正式用語，用來報告經檢查或調查後發現的事情。"},{"en":"It was found that several students had submitted the wrong form.","zh":"據發現，幾名學生提交了錯誤表格。"},{"en":"When it was found that the lift was unsafe, the building manager closed it immediately.","zh":"當發現升降機不安全時，大廈經理立即將其關閉。"},{"en":"This phrase is common in reports because it sounds factual and neutral.","zh":"這個短語常見於報告，因為語氣客觀中立。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"construction signs","meaning":"工程告示牌","examples":[{"en":"Construction signs should be displayed clearly at the entrance.","zh":"工程告示牌應清楚張貼在入口。"},{"en":"Construction signs are notices that warn people about building work, danger, restricted areas, or safety rules.","zh":"construction signs 指提醒人們有工程、危險、限制區域或安全規則的告示牌。"},{"en":"Roadworks usually need construction signs so drivers know to slow down.","zh":"道路工程通常需要工程告示牌，讓司機知道要減速。"},{"en":"Without construction signs, visitors may enter dangerous areas by mistake.","zh":"如果沒有工程告示牌，訪客可能會誤入危險區域。"},{"en":"Good construction signs should be large, clear, and placed where people can easily see them.","zh":"好的工程告示牌應夠大、清晰，並放在人們容易看見的位置。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"be displayed","meaning":"被展示；被張貼","examples":[{"en":"Construction signs should be displayed at the entrance every day.","zh":"工程告示牌應每天張貼在入口。"},{"en":"To be displayed means to be shown, placed, or presented where people can see it.","zh":"be displayed 指被展示、擺放或張貼在別人能看見的地方。"},{"en":"Exam results may be displayed on the school noticeboard.","zh":"考試結果可能會張貼在學校告示板上。"},{"en":"If safety rules are not displayed clearly, people may not know what to do.","zh":"如果安全規則沒有清楚張貼，人們可能不知道該怎樣做。"},{"en":"In public places, important information should be displayed in a visible position.","zh":"在公共場所，重要資訊應張貼在顯眼位置。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":1},{"front":"at the construction site","meaning":"在建築工地","examples":[{"en":"Safety problems were found at the construction site.","zh":"在建築工地發現了安全問題。"},{"en":"At the construction site means in the place where building work is taking place.","zh":"at the construction site 指在進行建築工程的地點。"},{"en":"Workers must wear helmets at the construction site.","zh":"工人在建築工地必須戴安全帽。"},{"en":"If tools are left everywhere at the construction site, people may trip and get hurt.","zh":"如果工具在建築工地四處亂放，人們可能會絆倒受傷。"},{"en":"This phrase identifies the exact location of work, checks, or safety problems.","zh":"這個短語指出工作、檢查或安全問題的確切地點。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"violate safety regulations","meaning":"違反安全規例","examples":[{"en":"Some construction workers were found to have violated safety regulations.","zh":"部分建築工人被發現違反安全規例。"},{"en":"To violate safety regulations means to break official rules designed to keep people safe.","zh":"violate safety regulations 指違反為保障人身安全而設的正式規則。"},{"en":"A driver may violate safety regulations by carrying too many passengers.","zh":"司機載客過多可能會違反安全規例。"},{"en":"Workers who violate safety regulations can create danger for themselves and others.","zh":"違反安全規例的工人可能會為自己和他人帶來危險。"},{"en":"This phrase is serious because it suggests rules were not just forgotten but broken.","zh":"這個短語語氣嚴重，因為它表示規則不只是被忘記，而是被違反。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"safety regulations","meaning":"安全規例","examples":[{"en":"All construction workers must follow safety regulations.","zh":"所有建築工人必須遵守安全規例。"},{"en":"Safety regulations are official rules that protect people from danger, injury, or accidents.","zh":"safety regulations 指保護人們免受危險、受傷或意外影響的正式規則。"},{"en":"Laboratories have safety regulations about chemicals, goggles, and emergency exits.","zh":"實驗室有關於化學品、護目鏡和緊急出口的安全規例。"},{"en":"If safety regulations are ignored, a small mistake can become a serious accident.","zh":"如果安全規例被忽視，小錯誤可能變成嚴重意外。"},{"en":"Safety regulations are important because they turn safe behaviour into clear requirements.","zh":"安全規例很重要，因為它把安全行為變成明確要求。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"key construction areas","meaning":"主要工程範圍","examples":[{"en":"Key construction areas were not covered with protective mats.","zh":"主要工程範圍沒有鋪上保護墊。"},{"en":"Key construction areas are the most important or risky parts of a building site where work is being done.","zh":"key construction areas 指建築工地中最重要或風險較高、正在施工的部分。"},{"en":"A supervisor may inspect key construction areas before workers leave.","zh":"主管可能會在工人離開前檢查主要工程範圍。"},{"en":"If key construction areas are not protected, equipment, surfaces, or people may be damaged or injured.","zh":"如果主要工程範圍沒有受到保護，設備、表面或人員可能受損或受傷。"},{"en":"This phrase focuses attention on the parts of the site that need special care.","zh":"這個短語把注意力集中在工地中特別需要照顧的部分。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"be covered with","meaning":"被……覆蓋","examples":[{"en":"The construction areas should be covered with protective mats.","zh":"工程範圍應被保護墊覆蓋。"},{"en":"To be covered with something means to have that thing placed over the surface.","zh":"be covered with something 指表面被某物蓋住。"},{"en":"A table may be covered with a cloth before dinner.","zh":"餐桌可能會在晚飯前被桌布覆蓋。"},{"en":"If a wet floor is covered with warning signs, people are less likely to slip.","zh":"如果濕滑地面被警告標誌覆蓋或圍住，人們較不容易滑倒。"},{"en":"This phrase usually shows what material or object is placed on top for protection or use.","zh":"這個短語通常說明有甚麼材料或物件被放在上方，以作保護或使用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"protective mats","meaning":"保護墊","examples":[{"en":"Protective mats should be placed over key construction areas.","zh":"保護墊應鋪在主要工程範圍上。"},{"en":"Protective mats are thick covers placed on floors or surfaces to prevent damage, slipping, or injury.","zh":"protective mats 指放在地面或表面上的厚墊，用來防止損壞、滑倒或受傷。"},{"en":"A gym uses protective mats so students do not hurt themselves when they fall.","zh":"體育館使用保護墊，讓學生跌倒時不會受傷。"},{"en":"Protective mats can reduce damage when heavy tools are used on a floor.","zh":"使用重型工具處理地面時，保護墊可以減少損壞。"},{"en":"In construction, protective mats help keep work areas safer and cleaner.","zh":"在工程中，保護墊有助令工作範圍更安全和整潔。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"after work had been completed","meaning":"工程完成後","examples":[{"en":"The areas were not covered with protective mats after work had been completed.","zh":"工程完成後，相關範圍沒有鋪上保護墊。"},{"en":"After work had been completed means after the task or construction activity was finished.","zh":"after work had been completed 指任務或工程活動完成之後。"},{"en":"After work had been completed, the cleaners checked every classroom.","zh":"工作完成後，清潔工檢查了每間課室。"},{"en":"If tools are not stored after work has been completed, the site may remain unsafe.","zh":"如果工程完成後工具沒有妥善存放，工地可能仍然不安全。"},{"en":"This phrase marks the time when follow-up checks or protective actions should happen.","zh":"這個短語標示應進行後續檢查或保護措施的時間。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"the security room","meaning":"保安室","examples":[{"en":"The security room at the construction site was found to be unlocked.","zh":"建築工地的保安室被發現沒有上鎖。"},{"en":"The security room is a room used by security staff to monitor cameras, keep records, or control access.","zh":"security room 指保安人員用來監察攝影機、保存紀錄或控制出入的房間。"},{"en":"A shopping mall may have a security room near the main entrance.","zh":"商場可能在正門附近設有保安室。"},{"en":"If the security room is left open, important keys or records may be at risk.","zh":"如果保安室沒有關好，重要鑰匙或紀錄可能有風險。"},{"en":"The security room should be controlled carefully because it supports the safety of the whole site.","zh":"保安室應受到謹慎管理，因為它支援整個場地的安全。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"be found to be unlocked","meaning":"被發現沒有上鎖","examples":[{"en":"The security room was found to be unlocked.","zh":"保安室被發現沒有上鎖。"},{"en":"To be found to be unlocked means that someone discovered a door, room, or container was not locked.","zh":"be found to be unlocked 指有人發現門、房間或容器沒有鎖上。"},{"en":"The classroom cupboard was found to be unlocked after school.","zh":"放學後，課室櫃被發現沒有上鎖。"},{"en":"If a medicine cabinet is found to be unlocked, children may be put in danger.","zh":"如果藥物櫃被發現沒有上鎖，兒童可能會有危險。"},{"en":"This phrase is often used in reports to record a security failure.","zh":"這個短語常用於報告中，用來記錄保安失誤。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"suggested solutions","meaning":"建議解決方案","examples":[{"en":"The report provides suggested solutions to the construction problems.","zh":"報告為工程問題提供建議解決方案。"},{"en":"Suggested solutions are proposed ways to solve or reduce the problems that have been found.","zh":"suggested solutions 指為解決或減少已發現問題而提出的方法。"},{"en":"A teacher may give suggested solutions for improving class discipline.","zh":"老師可能會提出改善課堂紀律的建議解決方案。"},{"en":"Suggested solutions are useful only if they are practical and match the real causes.","zh":"建議解決方案只有在實際可行並符合真正成因時才有用。"},{"en":"In a report, suggested solutions should follow naturally from the findings.","zh":"在報告中，建議解決方案應自然地由調查結果引出。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"It is suggested that","meaning":"建議……","examples":[{"en":"It is suggested that construction signs should be displayed every day.","zh":"建議每天張貼工程告示牌。"},{"en":"It is suggested that is a formal way to introduce a recommendation or proposed action.","zh":"It is suggested that 是引入建議或擬議行動的正式說法。"},{"en":"It is suggested that students arrive ten minutes early for the interview.","zh":"建議學生在面試前十分鐘到達。"},{"en":"It is suggested that broken equipment be reported immediately to prevent further danger.","zh":"建議損壞設備應立即報告，以防止進一步危險。"},{"en":"This phrase is common in reports because it sounds polite and professional.","zh":"這個短語常見於報告，因為語氣禮貌而專業。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":2},{"front":"at the entrance of","meaning":"在……入口","examples":[{"en":"Construction signs should be displayed at the entrance of the construction site.","zh":"工程告示牌應張貼在建築工地入口。"},{"en":"At the entrance of a place means at the point where people go in.","zh":"at the entrance of a place 指在某地方供人進入的位置。"},{"en":"Visitors usually buy tickets at the entrance of a museum.","zh":"訪客通常在博物館入口購買門票。"},{"en":"If safety notices are placed at the entrance of a site, people see them before entering.","zh":"如果安全告示放在場地入口，人們進入前便能看見。"},{"en":"This phrase is useful when giving clear location instructions.","zh":"這個短語適合用來提供清晰位置指示。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"every day","meaning":"每天","examples":[{"en":"Construction signs should be displayed every day.","zh":"工程告示牌應每天張貼。"},{"en":"Every day means on each day, not only sometimes or on special occasions.","zh":"every day 指每一日都如此，而不是有時或只在特別日子。"},{"en":"Students should check their school email every day during exam season.","zh":"學生在考試季節應每天查看學校電郵。"},{"en":"If safety checks are done every day, problems can be noticed earlier.","zh":"如果每天進行安全檢查，問題可以更早被發現。"},{"en":"This phrase shows regular action and leaves little room for gaps.","zh":"這個短語表示定期行動，較少留下空隙。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"daily safety briefings","meaning":"每日安全簡報","examples":[{"en":"Daily safety briefings should be conducted before construction begins.","zh":"每日安全簡報應在工程開始前舉行。"},{"en":"Daily safety briefings are short meetings held each day to remind workers about risks and rules.","zh":"daily safety briefings 指每天舉行的簡短會議，用來提醒工人注意風險和規則。"},{"en":"A factory may hold daily safety briefings before workers use heavy machines.","zh":"工廠可能在工人使用重型機器前舉行每日安全簡報。"},{"en":"Daily safety briefings can reduce accidents because workers know what to watch out for.","zh":"每日安全簡報可以減少意外，因為工人知道要注意甚麼。"},{"en":"These briefings are useful when work conditions change from day to day.","zh":"當工作情況每天都有變化時，這些簡報特別有用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"be conducted","meaning":"被進行；舉行","examples":[{"en":"Daily safety briefings should be conducted before construction begins.","zh":"每日安全簡報應在工程開始前舉行。"},{"en":"To be conducted means to be organised, carried out, or formally done.","zh":"be conducted 指被組織、執行或正式進行。"},{"en":"A survey may be conducted online to collect parents’ opinions.","zh":"問卷調查可能會在網上進行，以收集家長意見。"},{"en":"If training is conducted poorly, workers may still not understand the rules.","zh":"如果培訓進行得不好，工人可能仍然不明白規則。"},{"en":"This phrase is more formal than “done” and is common in reports.","zh":"這個短語比 done 更正式，常見於報告。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"before construction begins","meaning":"在工程開始前","examples":[{"en":"Daily safety briefings should be conducted before construction begins.","zh":"每日安全簡報應在工程開始前舉行。"},{"en":"Before construction begins means before building work starts for the day or for the project.","zh":"before construction begins 指在當天或整個項目的建築工程開始之前。"},{"en":"Workers should check their helmets before construction begins.","zh":"工人應在工程開始前檢查安全帽。"},{"en":"If risks are discussed before construction begins, accidents may be prevented.","zh":"如果在工程開始前討論風險，意外可能得以避免。"},{"en":"This phrase focuses on preparation before the actual work starts.","zh":"這個短語強調實際工作開始前的準備。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"It is recommended that","meaning":"建議……","examples":[{"en":"It is recommended that team leaders check the site before leaving.","zh":"建議小組組長在離開前檢查工地。"},{"en":"It is recommended that is a formal phrase used to present advice or a proposed action.","zh":"It is recommended that 是用來提出意見或建議行動的正式短語。"},{"en":"It is recommended that students save their work before closing the computer.","zh":"建議學生在關閉電腦前儲存功課。"},{"en":"It is recommended that visitors follow the marked route to avoid crowded areas.","zh":"建議訪客跟隨標示路線，以避開擠迫區域。"},{"en":"This phrase is common in reports because it sounds careful and objective.","zh":"這個短語常見於報告，因為語氣謹慎而客觀。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"team leaders","meaning":"小組組長；團隊負責人","examples":[{"en":"Team leaders should check whether construction areas are properly covered.","zh":"小組組長應檢查工程範圍是否已妥善覆蓋。"},{"en":"Team leaders are people responsible for guiding, checking, and organising the work of a group.","zh":"team leaders 指負責指導、檢查和組織小組工作的人。"},{"en":"A team leader in a restaurant may assign staff to serve tables, clean, and handle payments.","zh":"餐廳的團隊負責人可能會安排員工招待客人、清潔和處理付款。"},{"en":"If team leaders do not check work carefully, mistakes may spread across the whole team.","zh":"如果小組組長沒有仔細檢查工作，錯誤可能會擴散到整個團隊。"},{"en":"Team leaders are important because they connect managers’ instructions with workers’ actions.","zh":"小組組長很重要，因為他們把管理層指示與工人行動連接起來。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"each construction team","meaning":"每個工程團隊","examples":[{"en":"The leaders of each construction team should check the site before leaving.","zh":"每個工程團隊的負責人應在離開前檢查工地。"},{"en":"Each construction team means every separate group of workers responsible for a part of the building work.","zh":"each construction team 指每一個負責部分建築工作的獨立工人小組。"},{"en":"Each construction team may handle a different task, such as painting, wiring, or flooring.","zh":"每個工程團隊可能處理不同任務，例如油漆、電線或地板工程。"},{"en":"If each construction team checks its own area, fewer problems will be missed.","zh":"如果每個工程團隊檢查自己的範圍，較少問題會被遺漏。"},{"en":"This phrase makes responsibility clear because no team is excluded.","zh":"這個短語令責任清晰，因為沒有團隊被排除在外。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"check whether","meaning":"檢查是否","examples":[{"en":"Team leaders should check whether construction areas are properly covered.","zh":"小組組長應檢查工程範圍是否已妥善覆蓋。"},{"en":"To check whether something is true means to examine it and confirm if it is the case.","zh":"check whether something is true 指檢查並確認某事是否屬實。"},{"en":"Students should check whether they have written their names on the answer sheet.","zh":"學生應檢查是否已在答題紙上寫上姓名。"},{"en":"Checking whether doors are locked can prevent theft or unauthorised entry.","zh":"檢查門是否已上鎖，可以防止盜竊或未經授權進入。"},{"en":"This phrase is useful when the answer may be yes or no and needs confirmation.","zh":"當答案可能是「是」或「否」並需要確認時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"properly covered","meaning":"妥善覆蓋","examples":[{"en":"Construction areas should be properly covered before workers leave the site.","zh":"工人離開工地前，工程範圍應妥善覆蓋。"},{"en":"Properly covered means covered in the correct, complete, and safe way.","zh":"properly covered 指以正確、完整和安全的方式覆蓋。"},{"en":"Food should be properly covered in the fridge so it does not become dirty.","zh":"食物應在雪櫃中妥善覆蓋，以免弄污。"},{"en":"If dangerous surfaces are not properly covered, people may slip, cut themselves, or damage the floor.","zh":"如果危險表面沒有妥善覆蓋，人們可能會滑倒、割傷自己或損壞地板。"},{"en":"This phrase suggests that simply covering something is not enough; it must be done well.","zh":"這個短語表示只是覆蓋並不足夠；必須做得好。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"before leaving the site","meaning":"離開工地前","examples":[{"en":"Team leaders should check the construction areas before leaving the site.","zh":"小組組長應在離開工地前檢查工程範圍。"},{"en":"Before leaving the site means before workers or supervisors go away from the work location.","zh":"before leaving the site 指工人或主管離開工作地點之前。"},{"en":"A teacher should count all students before leaving the campsite.","zh":"老師應在離開營地前點算所有學生。"},{"en":"If workers check tools before leaving the site, missing equipment can be noticed early.","zh":"如果工人在離開工地前檢查工具，便能及早發現設備遺失。"},{"en":"This phrase marks the final moment for checking safety before people go home or move elsewhere.","zh":"這個短語標示人們回家或前往其他地方前檢查安全的最後時刻。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":3},{"front":"electronic locks","meaning":"電子門鎖","examples":[{"en":"Electronic locks should be installed on each door of the security room.","zh":"保安室每一道門都應安裝電子門鎖。"},{"en":"Electronic locks are locks that use cards, codes, fingerprints, or other digital systems instead of ordinary keys.","zh":"electronic locks 指使用卡、密碼、指紋或其他數碼系統，而不是普通鑰匙的門鎖。"},{"en":"Hotels often use electronic locks so guests can enter rooms with key cards.","zh":"酒店常使用電子門鎖，讓住客用房卡進入房間。"},{"en":"Electronic locks can record who enters a room, which helps improve security.","zh":"電子門鎖可以記錄誰進入房間，有助改善保安。"},{"en":"They are useful when access needs to be controlled carefully.","zh":"當出入需要受到嚴格控制時，電子門鎖很有用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"be installed on","meaning":"安裝在……上","examples":[{"en":"Electronic locks should be installed on each door of the security room.","zh":"電子門鎖應安裝在保安室的每一道門上。"},{"en":"To be installed on something means to be fixed, fitted, or set up on that surface or object.","zh":"be installed on something 指被固定、裝設或設置在某表面或物件上。"},{"en":"A camera may be installed on the wall outside the school office.","zh":"攝影機可能會安裝在學校辦公室外的牆上。"},{"en":"If safety equipment is installed on the wrong door, it may not protect the right area.","zh":"如果安全設備安裝在錯誤的門上，可能無法保護正確區域。"},{"en":"This phrase explains where a device or object should be placed for use.","zh":"這個短語說明設備或物件應放置在哪裡使用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"each door of","meaning":"……的每一道門","examples":[{"en":"Electronic locks should be installed on each door of the security room.","zh":"電子門鎖應安裝在保安室的每一道門上。"},{"en":"Each door of a room means every door belonging to that room, not just one of them.","zh":"each door of a room 指屬於該房間的每一道門，而不只是其中一道。"},{"en":"Each door of the laboratory should have a warning sign.","zh":"實驗室的每一道門都應有警告標誌。"},{"en":"If each door of a storage room is locked, unauthorised entry becomes less likely.","zh":"如果貯物室的每一道門都上鎖，未經授權進入的機會會較低。"},{"en":"This phrase is useful when complete coverage is important.","zh":"當完整覆蓋很重要時，這個短語很有用。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"It is hoped that","meaning":"希望……","examples":[{"en":"It is hoped that the suggestions will help address the problems identified.","zh":"希望這些建議有助處理已發現的問題。"},{"en":"It is hoped that is a formal phrase used to express a desired result politely.","zh":"It is hoped that 是正式短語，用來禮貌地表達期望中的結果。"},{"en":"It is hoped that the new timetable will reduce waiting time for students.","zh":"希望新時間表能減少學生輪候時間。"},{"en":"It is hoped that clearer signs will prevent visitors from getting lost.","zh":"希望更清晰的指示牌能防止訪客迷路。"},{"en":"This phrase is common at the end of reports because it presents a positive expectation.","zh":"這個短語常見於報告結尾，因為它呈現正面的期望。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"the above suggestions","meaning":"以上建議","examples":[{"en":"The above suggestions may help improve safety at the construction site.","zh":"以上建議可能有助改善建築工地的安全。"},{"en":"The above suggestions means the recommendations already mentioned earlier in the same text.","zh":"the above suggestions 指同一篇文章較早前已提及的建議。"},{"en":"The above suggestions should be discussed at the next staff meeting.","zh":"以上建議應在下一次職員會議中討論。"},{"en":"If the above suggestions are accepted, the school may have fewer safety complaints.","zh":"如果以上建議獲接納，學校可能會有較少安全投訴。"},{"en":"This phrase helps writers refer back to earlier points without repeating them all.","zh":"這個短語幫助作者回指前文要點，而不用全部重複。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"address the problems identified","meaning":"處理已發現的問題","examples":[{"en":"The suggestions will help address the problems identified during construction.","zh":"這些建議將有助處理施工期間已發現的問題。"},{"en":"To address the problems identified means to deal with the problems that have been found and take steps to reduce or solve them.","zh":"address the problems identified 指處理已被發現的問題，並採取措施減少或解決它們。"},{"en":"A school may address the problems identified in a survey by adding more support staff.","zh":"學校可能透過增加支援職員來處理問卷中已發現的問題。"},{"en":"If managers do not address the problems identified, the same mistakes may happen again.","zh":"如果管理層不處理已發現的問題，同樣錯誤可能會再次發生。"},{"en":"This phrase is useful because it connects findings with action.","zh":"這個短語很有用，因為它把調查結果與行動連繫起來。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4},{"front":"be taken into consideration","meaning":"被納入考慮","examples":[{"en":"It is hoped that the suggestions will be taken into consideration.","zh":"希望這些建議會被納入考慮。"},{"en":"To be taken into consideration means to be seriously thought about before a decision is made.","zh":"be taken into consideration 指在作出決定前被認真考慮。"},{"en":"Students’ opinions should be taken into consideration when the school changes lunch arrangements.","zh":"學校更改午膳安排時，學生意見應被納入考慮。"},{"en":"If safety concerns are not taken into consideration, a project may face accidents or complaints.","zh":"如果安全憂慮沒有被納入考慮，項目可能會面對意外或投訴。"},{"en":"This phrase is formal and polite when asking decision-makers to consider an idea.","zh":"這個短語在要求決策者考慮某想法時正式而禮貌。"}],"source":"Flash Cards -實用文 - Report.pdf","sourcePage":4}],"dse/paper-3/practical-english-writing/practical-formats/speech":[{"front":"Good evening, guests and staff members","meaning":"各位嘉賓及職員，晚上好","examples":[{"en":"Good evening, guests and staff members.","zh":"各位嘉賓及職員，晚上好。"},{"en":"Good evening, guests and staff members is a polite greeting used at the start of a formal evening event.","zh":"Good evening, guests and staff members 是在正式晚間活動開始時使用的禮貌問候語。"},{"en":"A hotel manager may say, “Good evening, guests and staff members,” before beginning an opening speech.","zh":"酒店經理在開始開幕演說前，可能會說：「各位嘉賓及職員，晚上好。」"},{"en":"This greeting helps welcome both visitors and workers in a respectful way.","zh":"這句問候語有助以尊重的方式歡迎訪客和員工。"},{"en":"It is more suitable for a ceremony than a casual greeting like “Hi everyone.”","zh":"它比「Hi everyone」這類隨意問候更適合典禮場合。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"First of all","meaning":"首先","examples":[{"en":"First of all, I would like to thank everyone for coming to the ceremony tonight.","zh":"首先，我想感謝大家今晚出席典禮。"},{"en":"First of all is used to introduce the first point before saying anything else.","zh":"First of all 用來在說其他事情之前引入第一點。"},{"en":"First of all, students should read the instructions carefully before answering.","zh":"首先，學生應在作答前仔細閱讀指示。"},{"en":"Using first of all helps listeners understand that the speaker is starting with an important opening point.","zh":"使用 first of all 有助聽眾明白講者正以重要開場重點開始。"},{"en":"In a speech, first of all often comes before thanks, background information, or the main purpose.","zh":"在演說中，first of all 常出現在致謝、背景資料或主要目的之前。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"I would like to thank everyone for","meaning":"我想感謝大家……","examples":[{"en":"I would like to thank everyone for coming to the ceremony tonight.","zh":"我想感謝大家今晚出席典禮。"},{"en":"I would like to thank everyone for is a polite way to show appreciation to a group of people.","zh":"I would like to thank everyone for 是禮貌地向一群人表達感謝的說法。"},{"en":"I would like to thank everyone for helping with the school fair.","zh":"我想感謝大家協助學校嘉年華。"},{"en":"This phrase makes a speech sound respectful because it recognises other people’s effort.","zh":"這個片語令演說聽起來有禮，因為它肯定了其他人的努力。"},{"en":"It is often followed by a noun or -ing form, such as “support” or “attending”.","zh":"它後面常接名詞或 -ing 形式，例如 support 或 attending。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"come to the ceremony","meaning":"出席典禮","examples":[{"en":"Thank you for coming to the ceremony tonight.","zh":"感謝你們今晚出席典禮。"},{"en":"To come to the ceremony means to attend a formal event or special occasion.","zh":"come to the ceremony 意思是出席正式活動或特別場合。"},{"en":"Parents came to the ceremony to watch their children receive awards.","zh":"家長出席典禮，觀看子女領獎。"},{"en":"When important guests come to the ceremony, organisers usually prepare seats and name tags.","zh":"當重要嘉賓出席典禮時，主辦方通常會準備座位和名牌。"},{"en":"This phrase is often used when thanking people for attending an event.","zh":"這個片語常用於感謝人們出席活動。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"be truly honoured to","meaning":"深感榮幸能夠……","examples":[{"en":"I am truly honoured to deliver a speech to all of you.","zh":"我深感榮幸能夠向在座各位發表演說。"},{"en":"To be truly honoured to do something means to feel deeply grateful and proud to have the chance to do it.","zh":"be truly honoured to do something 意思是因有機會做某事而深感感激和自豪。"},{"en":"The student was truly honoured to represent the school in the competition.","zh":"那名學生深感榮幸能夠代表學校參賽。"},{"en":"A speaker may use this phrase to show respect for the audience and the occasion.","zh":"講者可能用這個片語來表示對聽眾和場合的尊重。"},{"en":"It sounds more formal and sincere than simply saying “I am happy to”.","zh":"它比簡單說 “I am happy to” 更正式和真誠。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"deliver a speech","meaning":"發表演說","examples":[{"en":"I am truly honoured to deliver a speech to all of you.","zh":"我深感榮幸能夠向在座各位發表演說。"},{"en":"To deliver a speech means to give a formal talk to an audience.","zh":"deliver a speech 意思是向聽眾作正式講話。"},{"en":"The principal delivered a speech at the graduation ceremony.","zh":"校長在畢業典禮上發表演說。"},{"en":"A person who delivers a speech should speak clearly and organise ideas well.","zh":"發表演說的人應清楚說話並妥善組織想法。"},{"en":"Delivering a speech can be stressful, but preparation helps the speaker feel confident.","zh":"發表演說可能令人緊張，但準備能幫助講者建立信心。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"to all of you","meaning":"向在座各位","examples":[{"en":"I am truly honoured to speak to all of you tonight.","zh":"我深感榮幸今晚能夠向在座各位發言。"},{"en":"To all of you means to every person in the audience or group.","zh":"to all of you 意思是向聽眾或群體中的每一個人。"},{"en":"I would like to say thank you to all of you for your hard work.","zh":"我想向在座各位說聲謝謝，感謝你們的努力。"},{"en":"This phrase makes the message feel inclusive because nobody in the group is left out.","zh":"這個片語令訊息感覺更具包容性，因為群體中沒有人被遺漏。"},{"en":"In a ceremony, speakers often use to all of you when addressing the whole audience.","zh":"在典禮中，講者向全體聽眾發言時常用 to all of you。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"Before I begin","meaning":"在我開始之前","examples":[{"en":"Before I begin, I would like to express my most sincere gratitude to our customers and staff.","zh":"在我開始之前，我想向我們的顧客和職員表達最誠摯的謝意。"},{"en":"Before I begin is used before the main part of a speech or explanation starts.","zh":"Before I begin 用於演說或解釋的主要部分開始之前。"},{"en":"Before I begin, let me remind everyone to turn off their mobile phones.","zh":"在我開始之前，讓我提醒大家關掉手機。"},{"en":"This phrase helps a speaker add an important opening note before moving to the main topic.","zh":"這個片語有助講者在進入主題前加入重要開場說明。"},{"en":"It is useful when the speaker wants to thank people, give instructions, or explain the background first.","zh":"當講者想先致謝、給予指示或解釋背景時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"express my most sincere gratitude to","meaning":"向……表達最誠摯的謝意","examples":[{"en":"I would like to express my most sincere gratitude to all our customers and staff.","zh":"我想向我們所有顧客和職員表達最誠摯的謝意。"},{"en":"To express my most sincere gratitude to someone means to thank them in a very formal and heartfelt way.","zh":"express my most sincere gratitude to someone 意思是以非常正式和真心的方式感謝某人。"},{"en":"The charity director expressed her most sincere gratitude to the volunteers.","zh":"慈善機構主管向義工表達最誠摯的謝意。"},{"en":"This phrase is suitable when someone’s help has been important or meaningful.","zh":"當某人的幫助十分重要或有意義時，這個片語很適合。"},{"en":"It is stronger and more formal than simply saying “thank you”.","zh":"它比簡單說 “thank you” 更強烈和正式。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"customers and staff","meaning":"顧客與職員","examples":[{"en":"The company is grateful to all its customers and staff.","zh":"公司感謝所有顧客與職員。"},{"en":"Customers and staff means the people who buy from a company and the people who work for it.","zh":"customers and staff 意思是向公司購買產品或服務的人，以及為公司工作的人。"},{"en":"A hotel must listen to both customers and staff when improving its services.","zh":"酒店改善服務時，必須聆聽顧客與職員的意見。"},{"en":"If customers and staff are treated well, a business is more likely to succeed.","zh":"如果顧客與職員都受到良好對待，企業較可能成功。"},{"en":"This phrase is useful when a speech wants to recognise both outside support and internal effort.","zh":"當演說想同時肯定外部支持和內部努力時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"Without your help and support","meaning":"沒有你們的幫助和支持","examples":[{"en":"Without your help and support, the GF Smartphone would not have been possible.","zh":"沒有你們的幫助和支持，GF Smartphone 便不可能實現。"},{"en":"Without your help and support means that success depended on the assistance and encouragement of others.","zh":"Without your help and support 意思是成功有賴於他人的協助和鼓勵。"},{"en":"Without your help and support, our school charity sale could not have raised so much money.","zh":"沒有你們的幫助和支持，我們學校的慈善義賣不可能籌得這麼多錢。"},{"en":"This phrase shows humility because the speaker admits they did not succeed alone.","zh":"這個片語顯示謙遜，因為講者承認自己不是獨自成功。"},{"en":"It is often used in speeches, thank-you letters, and award ceremonies.","zh":"它常用於演說、感謝信和頒獎典禮。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":1},{"front":"would not have been possible","meaning":"便不可能實現","examples":[{"en":"Without your support, the GF Smartphone would not have been possible.","zh":"沒有你們的支持，GF Smartphone 便不可能實現。"},{"en":"Would not have been possible means something could not have happened without certain help or conditions.","zh":"would not have been possible 意思是沒有某些幫助或條件，某事便不能發生。"},{"en":"The trip would not have been possible without the teachers’ careful planning.","zh":"沒有老師仔細計劃，這次旅行便不可能實現。"},{"en":"This phrase is used to explain that a result depended on important support.","zh":"這個片語用來解釋某個結果有賴重要支持。"},{"en":"It is often used when thanking people for making a project or event happen.","zh":"它常用於感謝別人令項目或活動成事。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"be deeply indebted to","meaning":"對……深表感激","examples":[{"en":"I am also deeply indebted to Kevin Kim for his outstanding design.","zh":"我也對 Kevin Kim 的出色設計深表感激。"},{"en":"To be deeply indebted to someone means to feel very grateful because they helped you greatly.","zh":"be deeply indebted to someone 意思是因某人提供重大幫助而非常感激。"},{"en":"The school is deeply indebted to the volunteers who repaired the library.","zh":"學校對修復圖書館的義工深表感激。"},{"en":"This phrase is formal and shows stronger gratitude than ordinary thanks.","zh":"這個片語較正式，表達比普通感謝更強烈的感激。"},{"en":"It is suitable when someone’s contribution was essential to success.","zh":"當某人的貢獻對成功十分重要時，這個片語很適合。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"product designer","meaning":"產品設計師","examples":[{"en":"Kevin Kim is the company’s product designer.","zh":"Kevin Kim 是公司的產品設計師。"},{"en":"A product designer is a person who plans how a product looks, works, and feels to users.","zh":"product designer 是設計產品外觀、功能和用戶體驗的人。"},{"en":"A product designer may choose the shape, colour, buttons, and materials of a new phone.","zh":"產品設計師可能為新手機選擇形狀、顏色、按鈕和材料。"},{"en":"Good product designers help make products easier and more pleasant to use.","zh":"優秀的產品設計師幫助產品變得更易用和更令人喜歡。"},{"en":"A product designer must understand both customer needs and technical limits.","zh":"產品設計師必須理解顧客需要和技術限制。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"outstanding design","meaning":"出色的設計","examples":[{"en":"Kevin Kim contributed an outstanding design to the product.","zh":"Kevin Kim 為產品貢獻了出色的設計。"},{"en":"An outstanding design is a design that is excellent, impressive, and better than ordinary work.","zh":"outstanding design 是優秀、令人印象深刻，並比普通作品更好的設計。"},{"en":"The chair won an award because of its outstanding design and comfort.","zh":"那張椅子因出色的設計和舒適度而得獎。"},{"en":"Outstanding design can make a product easier to use and more attractive to customers.","zh":"出色的設計可以令產品更易用，也更吸引顧客。"},{"en":"A design is not outstanding only because it looks beautiful; it must also work well.","zh":"設計不只是外觀漂亮就是出色；它也必須實用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"I would like to begin by","meaning":"我想先由……開始","examples":[{"en":"I would like to begin by sharing why I founded GQ Tech Company.","zh":"我想先由分享我創立 GQ Tech Company 的原因開始。"},{"en":"I would like to begin by is a polite way to introduce the first action or topic in a speech.","zh":"I would like to begin by 是禮貌地引入演說中第一個行動或主題的說法。"},{"en":"I would like to begin by explaining the purpose of today’s meeting.","zh":"我想先由解釋今天會議的目的開始。"},{"en":"This phrase helps the speaker guide listeners into the first main part.","zh":"這個片語有助講者帶領聽眾進入第一個主要部分。"},{"en":"It is useful in formal presentations because it sounds organised and respectful.","zh":"它在正式匯報中很有用，因為聽起來有條理和有禮貌。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"share why","meaning":"分享……的原因","examples":[{"en":"I would like to share why I founded GQ Tech Company.","zh":"我想分享我創立 GQ Tech Company 的原因。"},{"en":"To share why means to explain the reason behind an action, choice, or feeling.","zh":"share why 意思是解釋某個行動、選擇或感受背後的原因。"},{"en":"The teacher shared why she became interested in education.","zh":"老師分享了她對教育產生興趣的原因。"},{"en":"Sharing why a decision was made can help people understand the purpose behind it.","zh":"分享作出某個決定的原因，可以幫助人理解背後目的。"},{"en":"This phrase is useful when a speaker wants to make a story more personal.","zh":"當講者想令故事更個人化時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"found a company","meaning":"創立公司","examples":[{"en":"I founded GQ Tech Company with my co-founder.","zh":"我和我的共同創辦人創立了 GQ Tech Company。"},{"en":"To found a company means to start and establish a new business.","zh":"found a company 意思是開辦和建立一間新企業。"},{"en":"Two friends founded a company after noticing that many students needed affordable tutoring.","zh":"兩位朋友注意到許多學生需要價格相宜的補習後，創立了一間公司。"},{"en":"Founding a company requires planning, money, risk-taking, and long-term commitment.","zh":"創立公司需要計劃、資金、承擔風險和長期投入。"},{"en":"A person who founds a company is often called a founder.","zh":"創立公司的人通常稱為 founder。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"develop an interest in","meaning":"培養對……的興趣","examples":[{"en":"I first developed an interest in inventing electronic products at the age of 17.","zh":"我最初在十七歲時培養出對發明電子產品的興趣。"},{"en":"To develop an interest in something means to gradually become curious about it or enjoy it.","zh":"develop an interest in 某事意思是逐漸對它感到好奇或喜歡它。"},{"en":"A child may develop an interest in science after doing simple experiments at school.","zh":"小朋友在學校做簡單實驗後，可能培養出對科學的興趣。"},{"en":"When people develop an interest in a subject, they often spend more time learning about it.","zh":"當人們培養出對某科目的興趣時，通常會花更多時間了解它。"},{"en":"This phrase shows that interest grows over time, not necessarily all at once.","zh":"這個片語顯示興趣是逐漸增長的，不一定突然出現。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"invent electronic products","meaning":"發明電子產品","examples":[{"en":"He developed an interest in inventing electronic products.","zh":"他培養出對發明電子產品的興趣。"},{"en":"To invent electronic products means to create new devices that use electricity or digital technology.","zh":"invent electronic products 意思是創造使用電力或數碼技術的新裝置。"},{"en":"Students may try inventing electronic products in a robotics club.","zh":"學生可能在機械人學會嘗試發明電子產品。"},{"en":"Inventing electronic products can solve daily problems, such as charging devices faster or saving energy.","zh":"發明電子產品可以解決日常問題，例如更快為裝置充電或節省能源。"},{"en":"Successful electronic products usually need creativity, testing, and user feedback.","zh":"成功的電子產品通常需要創意、測試和用戶意見。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"at the age of","meaning":"在……歲時","examples":[{"en":"He became interested in technology at the age of 17.","zh":"他在十七歲時對科技產生興趣。"},{"en":"At the age of means when someone was a particular age.","zh":"at the age of 意思是在某人某個年齡的時候。"},{"en":"She learned to play the piano at the age of six.","zh":"她在六歲時學彈鋼琴。"},{"en":"This phrase helps show when an important event happened in a person’s life.","zh":"這個片語有助顯示某個重要事件在人生中何時發生。"},{"en":"It is often used in biographies, speeches, and personal stories.","zh":"它常用於傳記、演說和個人故事。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"study at","meaning":"就讀於……","examples":[{"en":"I later studied at the University of Telza.","zh":"後來我就讀於 Telza 大學。"},{"en":"To study at a school or university means to be a student there.","zh":"study at 某學校或大學意思是在該處成為學生。"},{"en":"My cousin studied at a local college before working as a nurse.","zh":"我表姐在成為護士前，就讀於一間本地學院。"},{"en":"Where someone studies can shape their knowledge, friendships, and career choices.","zh":"一個人就讀的地方可以塑造其知識、友誼和職業選擇。"},{"en":"Use study at before the name of an institution, such as a school or university.","zh":"study at 用於學校或大學等機構名稱前。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":2},{"front":"co-founder","meaning":"共同創辦人","examples":[{"en":"I met our co-founder, Debby Tang, at university.","zh":"我在大學認識了我們的共同創辦人 Debby Tang。"},{"en":"A co-founder is one of the people who start a company or organisation together.","zh":"co-founder 是一起創立公司或組織的人之一。"},{"en":"The café has two co-founders who were classmates in secondary school.","zh":"那間咖啡店有兩位共同創辦人，他們是中學同學。"},{"en":"Co-founders often share early risks, decisions, and responsibilities.","zh":"共同創辦人通常共同承擔早期風險、決策和責任。"},{"en":"A strong relationship between co-founders can help a new company survive difficult years.","zh":"共同創辦人之間關係穩固，可以幫助新公司度過困難年份。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"study computer science","meaning":"修讀電腦科學","examples":[{"en":"We studied computer science together at university.","zh":"我們在大學一起修讀電腦科學。"},{"en":"To study computer science means to learn about computers, programming, data, and digital systems.","zh":"study computer science 意思是學習電腦、編程、數據和數碼系統。"},{"en":"Many students study computer science because they want to build apps or software.","zh":"許多學生修讀電腦科學，因為他們想開發應用程式或軟件。"},{"en":"Studying computer science can lead to careers in technology, finance, education, and design.","zh":"修讀電腦科學可以帶來科技、金融、教育和設計方面的職業機會。"},{"en":"Computer science is not only about coding; it also involves problem-solving and logical thinking.","zh":"電腦科學不只是編程；它也涉及解難和邏輯思維。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"after graduation","meaning":"畢業後","examples":[{"en":"After graduation, we worked at PZ Software Co.","zh":"畢業後，我們在 PZ Software Co. 工作。"},{"en":"After graduation means after someone finishes a school, college, or university programme.","zh":"after graduation 意思是在完成中學、學院或大學課程之後。"},{"en":"After graduation, many students look for jobs or continue studying.","zh":"畢業後，許多學生會找工作或繼續升學。"},{"en":"Plans after graduation can affect a student’s choice of courses and internships.","zh":"畢業後的計劃可以影響學生選擇課程和實習。"},{"en":"This phrase is often used when telling someone’s education and career story.","zh":"這個片語常用於講述一個人的教育和職業故事。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"work at","meaning":"在……工作","examples":[{"en":"After graduation, we worked at PZ Software Co.","zh":"畢業後，我們在 PZ Software Co. 工作。"},{"en":"To work at a company means to have a job in that company or organisation.","zh":"work at 某公司意思是在該公司或機構任職。"},{"en":"My brother works at a hospital as a laboratory assistant.","zh":"我哥哥在醫院任職實驗室助理。"},{"en":"Where people work at the beginning of their career can shape their skills and habits.","zh":"人們職業初期工作的地方可以塑造他們的技能和習慣。"},{"en":"Use work at before the name of a company, school, hospital, or other workplace.","zh":"work at 用於公司、學校、醫院或其他工作場所名稱前。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"ten years later","meaning":"十年後","examples":[{"en":"Ten years later, we founded GQ Tech Company.","zh":"十年後，我們創立了 GQ Tech Company。"},{"en":"Ten years later means after ten years had passed.","zh":"ten years later 意思是十年過去之後。"},{"en":"She left the village as a child; ten years later, she returned as a doctor.","zh":"她小時候離開村莊；十年後，她以醫生身份回來。"},{"en":"This phrase helps show a clear time gap between two events.","zh":"這個片語有助顯示兩件事之間清晰的時間距離。"},{"en":"In a life story, ten years later can signal growth, change, or a major decision.","zh":"在人生故事中，ten years later 可以表示成長、改變或重大決定。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"focus on","meaning":"專注於","examples":[{"en":"We wanted to focus on helping customers through innovative hardware solutions.","zh":"我們想專注於透過創新的硬件解決方案幫助顧客。"},{"en":"To focus on something means to give most of your attention, time, or effort to it.","zh":"focus on 某事意思是把大部分注意力、時間或努力放在該事上。"},{"en":"Students should focus on understanding the question before writing an answer.","zh":"學生應先專注於理解題目，然後才寫答案。"},{"en":"A company that focuses on customer needs can design better products.","zh":"專注於顧客需要的公司可以設計出更好的產品。"},{"en":"If you focus on too many things at once, your work may become less effective.","zh":"如果你同時專注太多事情，工作可能變得較低效。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"help customers through","meaning":"透過……幫助顧客","examples":[{"en":"The company aims to help customers through innovative hardware solutions.","zh":"公司旨在透過創新的硬件解決方案幫助顧客。"},{"en":"To help customers through something means to support them by using a particular method, tool, or service.","zh":"help customers through 某事意思是透過某種方法、工具或服務支援顧客。"},{"en":"A bank can help customers through online chat when branches are closed.","zh":"銀行可以在分行關門時透過網上聊天幫助顧客。"},{"en":"Helping customers through clear instructions can reduce confusion and complaints.","zh":"透過清晰指示幫助顧客，可以減少混亂和投訴。"},{"en":"This phrase shows both the people being helped and the way they are helped.","zh":"這個片語同時顯示被幫助的人和幫助的方法。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"innovative hardware solutions","meaning":"創新的硬件解決方案","examples":[{"en":"GQ Tech Company focuses on innovative hardware solutions.","zh":"GQ Tech Company 專注於創新的硬件解決方案。"},{"en":"Innovative hardware solutions are new and practical physical devices or equipment that solve problems.","zh":"innovative hardware solutions 是能解決問題的新穎而實用的實體裝置或設備。"},{"en":"A school may use innovative hardware solutions, such as smart boards, to improve lessons.","zh":"學校可能使用智能白板等創新的硬件解決方案來改善課堂。"},{"en":"Innovative hardware solutions can save time, reduce mistakes, or make daily tasks easier.","zh":"創新的硬件解決方案可以節省時間、減少錯誤或令日常任務更容易。"},{"en":"Good hardware solutions should be creative but also reliable and affordable.","zh":"好的硬件解決方案應有創意，同時可靠和價格相宜。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"undoubtedly","meaning":"毫無疑問","examples":[{"en":"It was undoubtedly one of the best decisions I have ever made.","zh":"毫無疑問，那是我作過最好的決定之一。"},{"en":"Undoubtedly means without doubt or certainly.","zh":"undoubtedly 意思是沒有疑問地或肯定地。"},{"en":"The new library is undoubtedly useful because more students now stay after school to read.","zh":"新圖書館毫無疑問很有用，因為現在更多學生放學後留下閱讀。"},{"en":"This word makes a statement sound strong and confident.","zh":"這個字令陳述聽起來強烈而有信心。"},{"en":"Use undoubtedly when the speaker believes the evidence or feeling is very clear.","zh":"當講者認為證據或感受十分清楚時，可以使用 undoubtedly。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"one of the best decisions I have ever made","meaning":"我作過最好的決定之一","examples":[{"en":"Founding the company was one of the best decisions I have ever made.","zh":"創立公司是我作過最好的決定之一。"},{"en":"One of the best decisions I have ever made means one of the choices in my life that brought the most positive results.","zh":"one of the best decisions I have ever made 意思是我人生中帶來最多正面結果的選擇之一。"},{"en":"Joining the reading club was one of the best decisions I have ever made because it improved my confidence.","zh":"加入閱讀學會是我作過最好的決定之一，因為它提升了我的信心。"},{"en":"People use this phrase when they look back and feel very satisfied with a past choice.","zh":"人們回望過去並對某個選擇非常滿意時，會使用這個片語。"},{"en":"It suggests that the decision had long-term value, not just a short-term benefit.","zh":"它暗示該決定有長遠價值，而不只是短期好處。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"Now, let me talk about","meaning":"現在，讓我談談……","examples":[{"en":"Now, let me talk about how we first developed the GF Smartphone.","zh":"現在，讓我談談我們最初如何開發 GF Smartphone。"},{"en":"Now, let me talk about is used to move to a new topic in a speech or presentation.","zh":"Now, let me talk about 用來在演說或匯報中轉到新主題。"},{"en":"Now, let me talk about the main problems we found in the survey.","zh":"現在，讓我談談我們在調查中發現的主要問題。"},{"en":"This phrase helps listeners follow the structure because it clearly signals a topic change.","zh":"這個片語清楚標示主題轉換，因此有助聽眾跟隨結構。"},{"en":"It is useful when a speaker wants to move from background information to details.","zh":"當講者想由背景資料轉到詳情時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":3},{"front":"first develop","meaning":"最初開發","examples":[{"en":"Let me explain how we first developed the GF Smartphone.","zh":"讓我解釋我們最初如何開發 GF Smartphone。"},{"en":"To first develop something means to create or improve it in its earliest stage.","zh":"first develop 某物意思是在最早階段創造或改進它。"},{"en":"The team first developed the app as a simple tool for taking notes.","zh":"團隊最初把這個應用程式開發成簡單的筆記工具。"},{"en":"Explaining how a product was first developed helps people understand its original purpose.","zh":"解釋產品最初如何開發，有助人們理解其原本目的。"},{"en":"A product may look very different from how it was first developed.","zh":"一項產品後來的樣子，可能與最初開發時很不同。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"have the idea of","meaning":"有……的想法","examples":[{"en":"Kevin and I had the idea of moving from traditional mobile phones to smartphones.","zh":"Kevin 和我有從傳統流動電話轉向智能手機的想法。"},{"en":"To have the idea of doing something means to think of a possible plan or new direction.","zh":"have the idea of doing something 意思是想到一個可能的計劃或新方向。"},{"en":"The teacher had the idea of using games to help students learn grammar.","zh":"老師有用遊戲幫助學生學文法的想法。"},{"en":"A good idea can lead to a new product, service, or way of working.","zh":"好想法可以帶來新產品、服務或工作方式。"},{"en":"This phrase often introduces the beginning of a plan before it becomes real.","zh":"這個片語常引入一個計劃成真之前的起點。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"transition from A to B","meaning":"從 A 過渡到 B","examples":[{"en":"We had the idea of transitioning from traditional mobile phones to smartphones.","zh":"我們有從傳統流動電話過渡到智能手機的想法。"},{"en":"To transition from A to B means to change gradually from one thing, stage, or system to another.","zh":"transition from A to B 意思是從一件事、一個階段或一套系統逐漸轉變到另一個。"},{"en":"Many schools transitioned from paper notices to online announcements.","zh":"許多學校從紙本通告過渡到網上公告。"},{"en":"A smooth transition from old systems to new ones requires training and patience.","zh":"從舊系統順利過渡到新系統需要培訓和耐性。"},{"en":"This phrase is useful when the change is not instant but happens step by step.","zh":"當改變不是即時發生，而是逐步出現時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"traditional mobile phones","meaning":"傳統流動電話","examples":[{"en":"The team wanted to move beyond traditional mobile phones.","zh":"團隊想超越傳統流動電話。"},{"en":"Traditional mobile phones are older-style phones mainly used for calling and texting.","zh":"traditional mobile phones 是較舊式的電話，主要用來通話和傳短訊。"},{"en":"Many people used traditional mobile phones before smartphones became common.","zh":"在智能手機普及前，許多人使用傳統流動電話。"},{"en":"Traditional mobile phones were simpler, but they could not support many modern apps.","zh":"傳統流動電話較簡單，但不能支援許多現代應用程式。"},{"en":"Comparing traditional mobile phones with smartphones helps show how technology has changed.","zh":"比較傳統流動電話與智能手機，有助顯示科技如何改變。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"offer greater convenience to","meaning":"為……帶來更大便利","examples":[{"en":"Smartphones could offer greater convenience to users.","zh":"智能手機可以為用戶帶來更大便利。"},{"en":"To offer greater convenience to someone means to make things easier, faster, or more comfortable for them.","zh":"offer greater convenience to someone 意思是令某人做事更容易、更快或更舒適。"},{"en":"Online booking can offer greater convenience to passengers who do not want to queue.","zh":"網上預訂可以為不想排隊的乘客帶來更大便利。"},{"en":"A product that offers greater convenience often saves users time and effort.","zh":"為用戶帶來更大便利的產品通常能節省時間和力氣。"},{"en":"Companies improve services when they think carefully about how to offer greater convenience to customers.","zh":"公司仔細思考如何為顧客帶來更大便利時，服務就會改善。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"the original colour","meaning":"原本的顏色","examples":[{"en":"The original colour of the phone was black.","zh":"這部電話原本的顏色是黑色。"},{"en":"The original colour means the colour something had at the beginning, before any changes were made.","zh":"the original colour 意思是某物一開始的顏色，即改變前的顏色。"},{"en":"The original colour of the classroom walls was white before they were painted blue.","zh":"課室牆壁在被油成藍色前，原本的顏色是白色。"},{"en":"Knowing the original colour can help designers explain how a product has changed.","zh":"知道原本的顏色，可以幫助設計師解釋產品如何改變。"},{"en":"A product’s original colour may be kept if customers strongly associate it with the brand.","zh":"如果顧客強烈把某種顏色與品牌聯繫起來，產品原本的顏色可能會被保留。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"introduce options","meaning":"推出選項","examples":[{"en":"We later introduced yellow and red options.","zh":"我們後來推出黃色和紅色選項。"},{"en":"To introduce options means to offer new choices to users or customers.","zh":"introduce options 意思是向用戶或顧客提供新的選擇。"},{"en":"The school introduced lunch options for vegetarian students.","zh":"學校為素食學生推出午餐選項。"},{"en":"Introducing more options can attract customers with different needs or tastes.","zh":"推出更多選項可以吸引有不同需要或品味的顧客。"},{"en":"However, too many options may make decisions harder for some people.","zh":"不過，太多選項可能令一些人更難作決定。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"yellow and red options","meaning":"黃色和紅色選項","examples":[{"en":"The company later introduced yellow and red options.","zh":"公司後來推出黃色和紅色選項。"},{"en":"Yellow and red options are choices that allow customers to select yellow or red versions of a product.","zh":"yellow and red options 是讓顧客選擇黃色或紅色版本產品的選項。"},{"en":"The shop sold the same backpack in yellow and red options.","zh":"商店以黃色和紅色選項出售同款背包。"},{"en":"Colour options can make a product feel more personal to customers.","zh":"顏色選項可以令產品對顧客來說更有個人感。"},{"en":"Yellow and red options may attract people who prefer brighter and more noticeable designs.","zh":"黃色和紅色選項可能吸引喜歡較鮮明和較顯眼設計的人。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"initially","meaning":"最初","examples":[{"en":"Initially, we hoped the smartphone would have five functions.","zh":"最初，我們希望智能手機有五項功能。"},{"en":"Initially means at the beginning or in the early stage.","zh":"initially 意思是在開始時或早期階段。"},{"en":"Initially, the club had only ten members, but it later became very popular.","zh":"最初，學會只有十名成員，但後來變得很受歡迎。"},{"en":"This word helps show how a situation changed from the start to a later stage.","zh":"這個字有助顯示情況如何由開始到後來階段改變。"},{"en":"It is useful when comparing an early plan with the final result.","zh":"當比較早期計劃與最終結果時，這個字很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"thanks to","meaning":"多虧；有賴於","examples":[{"en":"Thanks to the strong support and valuable feedback from our customers, the phone improved greatly.","zh":"多虧顧客的大力支持和寶貴意見，這部電話大大改進。"},{"en":"Thanks to means because of someone or something that helped create a positive result.","zh":"thanks to 意思是因為某人或某事帶來了正面結果。"},{"en":"Thanks to the teachers’ advice, the students improved their essays.","zh":"多虧老師的建議，學生改善了文章。"},{"en":"This phrase shows that a good result was made possible by helpful support or conditions.","zh":"這個片語顯示好結果是由有幫助的支持或條件促成。"},{"en":"It is usually used for positive causes, not for blaming someone.","zh":"它通常用於正面原因，而不是責怪某人。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"strong support","meaning":"大力支持","examples":[{"en":"The company received strong support from its customers.","zh":"公司得到顧客的大力支持。"},{"en":"Strong support means active, clear, and meaningful help or approval.","zh":"strong support 意思是積極、清楚而有意義的幫助或認同。"},{"en":"The charity event received strong support from parents and local shops.","zh":"慈善活動得到家長和本地商店的大力支持。"},{"en":"Strong support can give a team confidence to continue a difficult project.","zh":"大力支持可以給團隊信心，繼續推動困難項目。"},{"en":"Support is strong when people not only agree but also take action.","zh":"當人們不只是同意，還會採取行動時，支持就是強大的。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":4},{"front":"valuable feedback","meaning":"寶貴意見","examples":[{"en":"Customer feedback was extremely valuable to the development team.","zh":"顧客意見對開發團隊極為寶貴。"},{"en":"Valuable feedback is useful advice or comments that help improve something.","zh":"valuable feedback 是有助改善某事的有用建議或評論。"},{"en":"A teacher’s valuable feedback can help students correct repeated grammar mistakes.","zh":"老師的寶貴意見可以幫助學生改正常犯的文法錯誤。"},{"en":"Valuable feedback helps designers understand what users like, dislike, or find confusing.","zh":"寶貴意見幫助設計師了解用戶喜歡、不喜歡或覺得混亂的地方。"},{"en":"Feedback is valuable when it is specific, honest, and connected to improvement.","zh":"當意見具體、誠實並與改善有關時，就是寶貴的。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"evolve to include","meaning":"發展至包括","examples":[{"en":"The smartphone eventually evolved to include fifteen functions.","zh":"這部智能手機最終發展至包括十五項功能。"},{"en":"To evolve to include something means to gradually develop until that thing becomes part of it.","zh":"evolve to include 某物意思是逐漸發展，直到某物成為其中一部分。"},{"en":"The school website evolved to include online homework, notices, and booking forms.","zh":"學校網站發展至包括網上功課、通告和預約表格。"},{"en":"Products often evolve to include new features after users explain what they need.","zh":"產品常在用戶說明需要後，發展至包括新功能。"},{"en":"This phrase suggests gradual improvement rather than a sudden change.","zh":"這個片語暗示逐步改進，而不是突然改變。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"fifteen functions","meaning":"十五項功能","examples":[{"en":"The final smartphone included fifteen functions.","zh":"最終的智能手機包括十五項功能。"},{"en":"Fifteen functions means fifteen different tasks or features that a device can perform.","zh":"fifteen functions 意思是裝置可以執行的十五種不同任務或特色。"},{"en":"A calculator app may have fifteen functions, including addition, graphs, and unit conversion.","zh":"計算機應用程式可能有十五項功能，包括加法、圖表和單位換算。"},{"en":"More functions can make a product useful, but they must be easy to find and understand.","zh":"更多功能可以令產品有用，但它們必須易於尋找和理解。"},{"en":"Customers may prefer fifteen practical functions over many confusing ones.","zh":"顧客可能寧願要十五項實用功能，也不要許多令人混亂的功能。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"contribute tremendous effort to","meaning":"為……付出巨大努力","examples":[{"en":"Everyone in the company contributed tremendous effort to the development of this product.","zh":"公司每個人都為這項產品的開發付出巨大努力。"},{"en":"To contribute tremendous effort to something means to put a very large amount of work and energy into it.","zh":"contribute tremendous effort to 某事意思是為某事投入大量工作和精力。"},{"en":"Students contributed tremendous effort to preparing the school musical.","zh":"學生為準備學校音樂劇付出巨大努力。"},{"en":"A difficult project can succeed when many people contribute tremendous effort to it.","zh":"當許多人為困難項目付出巨大努力時，項目就可能成功。"},{"en":"This phrase recognises hard work, not only the final result.","zh":"這個片語肯定的是努力工作，而不只是最終結果。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"the development of this product","meaning":"這項產品的開發","examples":[{"en":"Staff contributed greatly to the development of this product.","zh":"職員為這項產品的開發作出重大貢獻。"},{"en":"The development of this product means the process of creating, testing, and improving this product.","zh":"the development of this product 意思是創造、測試和改進這項產品的過程。"},{"en":"Engineers, designers, and customer service staff may all help with the development of this product.","zh":"工程師、設計師和客戶服務員都可能協助這項產品的開發。"},{"en":"The development of a product can take months or years before it reaches customers.","zh":"一項產品的開發可能需要數月或數年才到達顧客手中。"},{"en":"Feedback, testing, and teamwork are important to the development of this product.","zh":"意見回饋、測試和團隊合作對這項產品的開發很重要。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"Last but not least","meaning":"最後但同樣重要的是","examples":[{"en":"Last but not least, I would like to share some exciting news.","zh":"最後但同樣重要的是，我想分享一些好消息。"},{"en":"Last but not least is used to introduce the final point while showing it is still important.","zh":"Last but not least 用來引入最後一點，同時表示它仍然重要。"},{"en":"Last but not least, remember to thank the volunteers after the event.","zh":"最後但同樣重要的是，活動後記得感謝義工。"},{"en":"This phrase prevents the final point from sounding less important just because it comes last.","zh":"這個片語避免最後一點因為排在最後而聽起來較不重要。"},{"en":"It is common in speeches, presentations, and formal announcements.","zh":"它常見於演說、匯報和正式公告。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"exciting news about","meaning":"關於……的好消息","examples":[{"en":"I would like to share some exciting news about our upcoming partnership.","zh":"我想分享一些關於我們即將建立合作關係的好消息。"},{"en":"Exciting news about something is good news that makes people interested, happy, or hopeful.","zh":"exciting news about 某事是令人感興趣、開心或充滿希望的好消息。"},{"en":"The principal shared exciting news about a new school library.","zh":"校長分享了關於新學校圖書館的好消息。"},{"en":"Exciting news about a company project can raise staff morale and public interest.","zh":"關於公司項目的好消息可以提升員工士氣和公眾興趣。"},{"en":"This phrase is often used before announcing a new plan, achievement, or opportunity.","zh":"這個片語常用於宣布新計劃、成就或機會之前。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"upcoming partnership with","meaning":"即將與……建立的合作關係","examples":[{"en":"The company announced an upcoming partnership with TF Media Company.","zh":"公司宣布即將與 TF Media Company 建立合作關係。"},{"en":"An upcoming partnership with another organisation is a planned cooperation that will begin soon.","zh":"upcoming partnership with 另一機構意思是即將開始的合作計劃。"},{"en":"The school announced an upcoming partnership with a local museum.","zh":"學校宣布即將與本地博物館建立合作關係。"},{"en":"An upcoming partnership can help both sides share skills, customers, or resources.","zh":"即將建立的合作關係可以幫助雙方分享技能、顧客或資源。"},{"en":"This phrase is useful when the cooperation has been planned but has not fully started yet.","zh":"當合作已計劃好但尚未完全開始時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"starting next year","meaning":"由明年開始","examples":[{"en":"Starting next year, the two companies will develop an online shopping platform together.","zh":"由明年開始，兩間公司將共同開發一個網上購物平台。"},{"en":"Starting next year means beginning from the next calendar year.","zh":"starting next year 意思是由下一個日曆年開始。"},{"en":"Starting next year, students will use a new online homework system.","zh":"由明年開始，學生將使用新的網上功課系統。"},{"en":"This phrase clearly tells people when a new plan or change will begin.","zh":"這個片語清楚告訴人們新計劃或改變何時開始。"},{"en":"It is useful in announcements because it connects a future action with a specific time.","zh":"它在公告中很有用，因為它把未來行動與具體時間連繫起來。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"develop an online shopping platform","meaning":"開發網上購物平台","examples":[{"en":"The two companies will develop an online shopping platform together.","zh":"兩間公司將共同開發網上購物平台。"},{"en":"To develop an online shopping platform means to build a website or app where people can buy products online.","zh":"develop an online shopping platform 意思是建立一個讓人可以網上購物的網站或應用程式。"},{"en":"A supermarket may develop an online shopping platform so customers can order groceries from home.","zh":"超級市場可能開發網上購物平台，讓顧客在家訂購雜貨。"},{"en":"Developing an online shopping platform requires payment systems, product pages, delivery arrangements, and customer support.","zh":"開發網上購物平台需要付款系統、產品頁面、送貨安排和客戶支援。"},{"en":"A good platform should be easy to search, safe to pay on, and reliable to use.","zh":"好的平台應容易搜尋、付款安全，而且使用可靠。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"be expected to","meaning":"預計會","examples":[{"en":"The platform is expected to offer more than 20,000 products.","zh":"這個平台預計會提供超過 20,000 件產品。"},{"en":"Be expected to means people believe or predict that something will happen.","zh":"be expected to 意思是人們相信或預測某事將會發生。"},{"en":"The new library is expected to open in September.","zh":"新圖書館預計會在九月開放。"},{"en":"This phrase is often used in formal announcements when the result is planned but not yet completed.","zh":"這個片語常用於正式公告，表示結果已計劃但尚未完成。"},{"en":"It sounds less certain than “will” because it leaves room for possible changes.","zh":"它比 “will” 聽起來較不絕對，因為仍留有可能變動的空間。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":5},{"front":"offer more than","meaning":"提供超過……","examples":[{"en":"The platform is expected to offer more than 20,000 products.","zh":"這個平台預計會提供超過 20,000 件產品。"},{"en":"To offer more than a number means to provide a quantity greater than that number.","zh":"offer more than 某數目意思是提供多於該數目的數量。"},{"en":"The library offers more than 5,000 e-books to students.","zh":"圖書館向學生提供超過 5,000 本電子書。"},{"en":"Offering more than one choice can help customers find what suits them best.","zh":"提供多於一個選擇，可以幫助顧客找到最適合自己的東西。"},{"en":"This phrase is useful when emphasising a large amount or wide selection.","zh":"當要強調大量或廣泛選擇時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"additional employees","meaning":"額外員工","examples":[{"en":"The company will hire 80 additional employees to operate the platform.","zh":"公司將聘請 80 名額外員工營運平台。"},{"en":"Additional employees are extra workers hired beyond the existing staff.","zh":"additional employees 是在現有員工以外額外聘請的工人。"},{"en":"A restaurant may hire additional employees during the busy holiday season.","zh":"餐廳可能在繁忙假期季節聘請額外員工。"},{"en":"Additional employees can reduce workload and help a new service run smoothly.","zh":"額外員工可以減輕工作量，並幫助新服務順利運作。"},{"en":"Hiring additional employees also increases training, salary, and management costs.","zh":"聘請額外員工也會增加培訓、薪金和管理成本。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"operate the platform","meaning":"營運平台","examples":[{"en":"The new employees will help operate the platform.","zh":"新員工將協助營運平台。"},{"en":"To operate the platform means to run, manage, and keep the online system working.","zh":"operate the platform 意思是運行、管理並維持網上系統運作。"},{"en":"Staff operate the platform by updating products, answering questions, and checking orders.","zh":"員工透過更新產品、回答問題和檢查訂單來營運平台。"},{"en":"If nobody operates the platform properly, customers may face delays or errors.","zh":"如果沒有人妥善營運平台，顧客可能遇到延誤或錯誤。"},{"en":"Operating a platform requires both technical support and customer service.","zh":"營運平台需要技術支援和客戶服務。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"core mission","meaning":"核心使命","examples":[{"en":"Our core mission is to make affordable electronics accessible to everyone.","zh":"我們的核心使命是讓每個人都能購買價格相宜的電子產品。"},{"en":"A core mission is the main purpose or most important goal of an organisation.","zh":"core mission 是一個機構的主要目的或最重要目標。"},{"en":"The school’s core mission is to help students learn with confidence and kindness.","zh":"學校的核心使命是幫助學生有信心和善意地學習。"},{"en":"A clear core mission helps staff decide what matters most when making choices.","zh":"清晰的核心使命有助員工作選擇時決定甚麼最重要。"},{"en":"If a company forgets its core mission, its services may lose direction.","zh":"如果公司忘記自己的核心使命，服務可能會失去方向。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"enable everyone to","meaning":"讓每個人都能夠……","examples":[{"en":"Our mission is to enable everyone to access affordable electronics.","zh":"我們的使命是讓每個人都能夠購買價格相宜的電子產品。"},{"en":"To enable everyone to do something means to make it possible for all people to do it.","zh":"enable everyone to do something 意思是令所有人都有可能做某事。"},{"en":"Public libraries enable everyone to borrow books without paying high prices.","zh":"公共圖書館讓每個人都能夠不用付高價就借閱書籍。"},{"en":"Technology can enable everyone to learn online if internet access is affordable.","zh":"如果網絡費用相宜，科技可以讓每個人都能夠網上學習。"},{"en":"This phrase often suggests fairness, access, and opportunity.","zh":"這個片語常暗示公平、可及性和機會。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"access affordable electronics","meaning":"購買價格相宜的電子產品","examples":[{"en":"The company wants everyone to access affordable electronics from around the world.","zh":"公司希望每個人都能購買來自世界各地、價格相宜的電子產品。"},{"en":"To access affordable electronics means to be able to buy or use electronic products at reasonable prices.","zh":"access affordable electronics 意思是能夠以合理價格購買或使用電子產品。"},{"en":"Students need to access affordable electronics so they can study online.","zh":"學生需要購買價格相宜的電子產品，才能網上學習。"},{"en":"If people cannot access affordable electronics, the gap between rich and poor users may grow.","zh":"如果人們無法取得價格相宜的電子產品，貧富用戶之間的差距可能擴大。"},{"en":"This phrase is about both availability and price, not just technology itself.","zh":"這個片語關乎供應和價格，而不只是科技本身。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"from around the world","meaning":"來自世界各地","examples":[{"en":"The platform will offer products from around the world.","zh":"這個平台將提供來自世界各地的產品。"},{"en":"From around the world means from many different countries or places globally.","zh":"from around the world 意思是來自全球許多不同國家或地方。"},{"en":"The food fair sold snacks from around the world.","zh":"美食節售賣來自世界各地的小食。"},{"en":"Products from around the world can give customers more variety and choice.","zh":"來自世界各地的產品可以給顧客更多種類和選擇。"},{"en":"This phrase is useful when showing that something is international, diverse, or widely sourced.","zh":"當要顯示某事具國際性、多樣性或來源廣泛時，這個片語很有用。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"look forward to","meaning":"期待","examples":[{"en":"We are truly looking forward to this new venture.","zh":"我們真的很期待這項新業務。"},{"en":"To look forward to something means to feel pleased and excited about something that will happen in the future.","zh":"look forward to 某事意思是對未來將發生的事感到高興和期待。"},{"en":"Students look forward to the school picnic after weeks of exams.","zh":"經過數星期考試後，學生期待學校野餐。"},{"en":"This phrase shows positive expectation and hope.","zh":"這個片語表達正面的期望和希望。"},{"en":"Remember that look forward to is followed by a noun or an -ing form, such as “meeting you”.","zh":"請記住 look forward to 後面接名詞或 -ing 形式，例如 “meeting you”。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"new venture","meaning":"新業務；新計劃","examples":[{"en":"The online shopping platform is an exciting new venture.","zh":"網上購物平台是一項令人興奮的新業務。"},{"en":"A new venture is a new business activity, project, or risky plan.","zh":"new venture 是新的商業活動、項目或帶風險的計劃。"},{"en":"Opening a small bakery was my aunt’s first new venture after leaving her office job.","zh":"我姨姨離開辦公室工作後，開小麵包店是她第一項新業務。"},{"en":"A new venture can bring growth, but it also requires money, planning, and patience.","zh":"新業務可以帶來增長，但也需要資金、計劃和耐性。"},{"en":"Companies often call a project a new venture when it explores a fresh opportunity.","zh":"當公司探索新機會時，常稱該項目為 new venture。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"conclude my speech","meaning":"結束我的演說","examples":[{"en":"I will conclude my speech here.","zh":"我將在此結束我的演說。"},{"en":"To conclude my speech means to bring my speech to an end.","zh":"conclude my speech 意思是結束我的演說。"},{"en":"The student concluded her speech by thanking the audience.","zh":"那名學生以感謝聽眾來結束她的演說。"},{"en":"A clear ending helps listeners remember the main message of a speech.","zh":"清晰的結尾有助聽眾記住演說的主要訊息。"},{"en":"Speakers often conclude a speech with thanks, a wish, or a final reminder.","zh":"講者常以致謝、祝願或最後提醒來結束演說。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"once again","meaning":"再一次","examples":[{"en":"Once again, thank you all for attending the ceremony.","zh":"再一次，感謝各位出席典禮。"},{"en":"Once again means one more time, often used when repeating thanks or an important point.","zh":"once again 意思是再一次，常用於重複感謝或重要重點。"},{"en":"Once again, please remember to submit the form by Friday.","zh":"再一次，請記得在星期五前提交表格。"},{"en":"This phrase helps emphasise a message before the speaker finishes.","zh":"這個片語有助講者在結束前強調訊息。"},{"en":"In speeches, once again often introduces a final expression of gratitude.","zh":"在演說中，once again 常引入最後一次致謝。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":6},{"front":"thank you all for attending","meaning":"感謝各位出席","examples":[{"en":"Thank you all for attending the ceremony.","zh":"感謝各位出席典禮。"},{"en":"Thank you all for attending is a polite way to thank a group for coming to an event.","zh":"thank you all for attending 是禮貌地感謝一群人出席活動的說法。"},{"en":"Thank you all for attending the parents’ meeting this evening.","zh":"感謝各位今晚出席家長會。"},{"en":"This phrase recognises that people spent time and effort to be present.","zh":"這個片語肯定人們花時間和心力到場。"},{"en":"It is suitable at the beginning or end of formal events.","zh":"它適合用於正式活動的開始或結尾。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":7},{"front":"enjoy the evening","meaning":"享受今晚的活動","examples":[{"en":"I hope everyone enjoys the evening.","zh":"我希望大家享受今晚的活動。"},{"en":"To enjoy the evening means to have a pleasant time during the event or night.","zh":"enjoy the evening 意思是在活動或晚上度過愉快時光。"},{"en":"After the speech, guests were invited to enjoy the evening with food and music.","zh":"演說結束後，嘉賓獲邀享受有食物和音樂的晚間活動。"},{"en":"This phrase creates a warm ending because it wishes the audience a good experience.","zh":"這個片語營造溫暖結尾，因為它祝願聽眾有美好體驗。"},{"en":"It is often used at ceremonies, dinners, parties, and company events.","zh":"它常用於典禮、晚宴、派對和公司活動。"}],"source":"Flash Cards -實用文 - Speech.pdf","sourcePage":7}]};
